// Quotations extracted from the user-provided PDF: Citations_du_monde.pdf
// Source duplicates are intentionally preserved.
const QUOTE_DATASET = {
  "dataset": "Citations du monde",
  "source": "Citations_du_monde.pdf",
  "total": 2508,
  "quotes": [
    {
      "id": 1,
      "text": "Les conneries c'est comme les impôts, on finit toujours par les payer.",
      "author": "Michel Audiard",
      "sourcePage": 1
    },
    {
      "id": 2,
      "text": "La statistique est la première des sciences inexactes.",
      "author": "Edmond et Jules de Goncourt",
      "sourcePage": 1
    },
    {
      "id": 3,
      "text": "La curiosité mène à tout : parfois à écouter aux portes, parfois à découvrir l'Amérique.",
      "author": "J. M. Eca de Queiros",
      "sourcePage": 1
    },
    {
      "id": 4,
      "text": "Le chien a son sourire dans sa queue.",
      "author": "Victor Hugo",
      "sourcePage": 1
    },
    {
      "id": 5,
      "text": "Je travaille à être heureux : c'est le plus beau des métiers.",
      "author": "Roland de Lassus",
      "sourcePage": 1
    },
    {
      "id": 6,
      "text": "Un savant est un homme qui sait beaucoup de choses qu'il faudrait connaître mieux que lui pour savoir s'il n'est pas une âne.",
      "author": "Hector Talvart",
      "sourcePage": 1
    },
    {
      "id": 7,
      "text": "Je n'aimerais guère vivre dans la Lune. Ça m'embêterait, de changer de quartier, tous les neuf jours.",
      "author": "Francis Blanche",
      "sourcePage": 1
    },
    {
      "id": 8,
      "text": "Verser de l'eau dans du cognac, c'est gâcher deux bonnes choses.",
      "author": "Charles Lamb",
      "sourcePage": 1
    },
    {
      "id": 9,
      "text": "Quand on voit ce qu'on voit et que l'on entend ce qu'on entend, on a bien raison de penser ce qu'on pense.",
      "author": "Guy Bedos",
      "sourcePage": 1
    },
    {
      "id": 10,
      "text": "Les absents ont toujours tort de revenir.",
      "author": "Jules Renard",
      "sourcePage": 1
    },
    {
      "id": 11,
      "text": "La semaine du travailleur a sept jours, la semaine du paresseux a sept demains.",
      "author": "proverbe français",
      "sourcePage": 1
    },
    {
      "id": 12,
      "text": "Si j'ai l'occasion, j'aimerais mieux mourir de mon vivant !",
      "author": "Coluche",
      "sourcePage": 1
    },
    {
      "id": 13,
      "text": "Ce qu'il y a de meilleur dans le dimanche, c'est encore le samedi soir.",
      "author": "Gilbert Cesbron",
      "sourcePage": 1
    },
    {
      "id": 14,
      "text": "De toutes les aberrations sexuelles, la pire est la chasteté.",
      "author": "Anatole France",
      "sourcePage": 1
    },
    {
      "id": 15,
      "text": "Le prélèvement d'impôts au-delà du strict nécessaire constitue un vol légalisé.",
      "author": "Calvin Coolidge",
      "sourcePage": 1
    },
    {
      "id": 16,
      "text": "L'argent n'a pas d'odeur, mais à partir d'un million il commence à se faire sentir.",
      "author": "Tristan Bernard",
      "sourcePage": 1
    },
    {
      "id": 17,
      "text": "La culture, c'est comme la confiture, moins on en a, plus on l'étale.",
      "author": "Françoise Sagan",
      "sourcePage": 1
    },
    {
      "id": 18,
      "text": "L'Internet serait une toile comme les autres si elle n'avait ses millions d'araignées...",
      "author": "Maxime Allain",
      "sourcePage": 1
    },
    {
      "id": 19,
      "text": "Je regarde la carte des vins pour éviter les bouchons.",
      "author": "Raymond Devos",
      "sourcePage": 1
    },
    {
      "id": 20,
      "text": "L'amour... il y a ceux qui en parlent et il y a ceux qui le font. A partir de quoi il m'apparaît urgent de me taire.",
      "author": "Pierre Desproges",
      "sourcePage": 1
    },
    {
      "id": 21,
      "text": "Si l'administration militaire était bien faite, il n'y aurait pas de soldat inconnu.",
      "author": "Louis Jouvet",
      "sourcePage": 1
    },
    {
      "id": 22,
      "text": "Le printemps est venu : comment, nul ne l'a su.",
      "author": "Antonio Machado",
      "sourcePage": 1
    },
    {
      "id": 23,
      "text": "La trace d'un rêve n'est pas moins réelle que celle d'un pas.",
      "author": "Georges Duby",
      "sourcePage": 1
    },
    {
      "id": 24,
      "text": "Je sais enfin ce qui distingue l'homme de la bête : ce sont les ennuis d'argent !",
      "author": "Jules Renard",
      "sourcePage": 1
    },
    {
      "id": 25,
      "text": "L'habitude nous réconcilie avec tout.",
      "author": "Edmund Burke",
      "sourcePage": 1
    },
    {
      "id": 26,
      "text": "Je voudrais connaître la musique dont la queue de mon chien bat la mesure.",
      "author": "Yvan Audouard",
      "sourcePage": 1
    },
    {
      "id": 27,
      "text": "Si vous ne voulez pas qu'on le sache, mieux vaut encore ne pas le faire.",
      "author": "proverbe chinois",
      "sourcePage": 1
    },
    {
      "id": 28,
      "text": "L'architecture, c'est de la musique figée.",
      "author": "Goethe",
      "sourcePage": 1
    },
    {
      "id": 29,
      "text": "Un secret consiste à ne le répéter qu'à une seule personne à la fois.",
      "author": "Michel Audiard",
      "sourcePage": 1
    },
    {
      "id": 30,
      "text": "Conscience collective : somme des inconsciences individuelles.",
      "author": "Georges Elgozy",
      "sourcePage": 1
    },
    {
      "id": 31,
      "text": "Aussi grand que soit un trou, il y a toujours quelque chose autour.",
      "author": "François Cavanna",
      "sourcePage": 1
    },
    {
      "id": 32,
      "text": "Le temps porte conseil : en général celui de ne rien faire.",
      "author": "Claude Roy",
      "sourcePage": 1
    },
    {
      "id": 33,
      "text": "Pour dire oui, il faut pouvoir dire non.",
      "author": "François Mitterand",
      "sourcePage": 1
    },
    {
      "id": 34,
      "text": "Une fois qu'on a donné son opinion, il serait logique qu'on ne l'ait plus.",
      "author": "Albert Brie",
      "sourcePage": 1
    },
    {
      "id": 35,
      "text": "Nous ne savons pas où nous allons. Si nous le savions, nous n'irions peut-être pas.",
      "author": "Anonyme",
      "sourcePage": 1
    },
    {
      "id": 36,
      "text": "J'adore la télévision. En fermant les yeux, c'est presque aussi bien que la radio.",
      "author": "Pierre-Jean Vaillard",
      "sourcePage": 1
    },
    {
      "id": 37,
      "text": "Le voisin est un animal nuisible assez proche de l'homme.",
      "author": "Pierre Desproges",
      "sourcePage": 1
    },
    {
      "id": 38,
      "text": "Neuf personnes sur dix aiment le chocolat ; la dixième ment.",
      "author": "Anonyme",
      "sourcePage": 1
    },
    {
      "id": 39,
      "text": "Si la matière grise était plus rose, le monde aurait moins les idées noires.",
      "author": "Pierre Dac",
      "sourcePage": 1
    },
    {
      "id": 40,
      "text": "A quoi bon soulever des montagnes quand il est si simple de passer par dessus ?",
      "author": "Boris Vian",
      "sourcePage": 1
    },
    {
      "id": 41,
      "text": "Repartie : ce qui nous vient à l'esprit quand notre interlocuteur est parti.",
      "author": "Dan Bennet",
      "sourcePage": 1
    },
    {
      "id": 42,
      "text": "Le cheveu rare, ça donne l'air intellectuel, à défaut d'être intelligent.",
      "author": "Anne Roumanoff",
      "sourcePage": 1
    },
    {
      "id": 43,
      "text": "Qui aime un chat aime tous les chats. Qui aime son chien n'aime pas les autres.",
      "author": "Roland Topor",
      "sourcePage": 1
    },
    {
      "id": 44,
      "text": "L'espérance est un risque à courir.",
      "author": "Georges Bernanos",
      "sourcePage": 1
    },
    {
      "id": 45,
      "text": "Il y a des gens qui disent qu'ils peuvent ; d'autres qu'ils ne peuvent pas. En général, ils ont tous raison.",
      "author": "Henry Ford",
      "sourcePage": 1
    },
    {
      "id": 46,
      "text": "L'ennui avec la ponctualité, c'est que personne n'est jamais là pour l'apprécier.",
      "author": "Harold Rome",
      "sourcePage": 1
    },
    {
      "id": 47,
      "text": "J'ai passe une excellente soirée... mais ça n'était pas celle-ci.",
      "author": "Groucho Marx",
      "sourcePage": 1
    },
    {
      "id": 48,
      "text": "La vérité n'est jamais amusante sinon tout le monde la dirait.",
      "author": "Michel Audiard",
      "sourcePage": 1
    },
    {
      "id": 49,
      "text": "Un bienfait n'est jamais perdu. C'est peut-être pour ça qu'on n'en trouve jamais !",
      "author": "Pierre-Jean Vaillard",
      "sourcePage": 1
    },
    {
      "id": 50,
      "text": "La vie, c'est comme une bicyclette, il faut avancer pour ne pas perdre l'équilibre.",
      "author": "Albert Einstein",
      "sourcePage": 1
    },
    {
      "id": 51,
      "text": "Souris. Animal dont le chemin est jonché de femmes évanouies.",
      "author": "Ambrose Bierce",
      "sourcePage": 1
    },
    {
      "id": 52,
      "text": "Ce qu'il y a d'admirable dans le bonheur des autres, c'est qu'on y croit.",
      "author": "Marcel Proust",
      "sourcePage": 2
    },
    {
      "id": 53,
      "text": "Qui vole un bœuf est vachement muscle !",
      "author": "Chaval",
      "sourcePage": 2
    },
    {
      "id": 54,
      "text": "La beauté du neuf, tout de même, c'est d'être propre.",
      "author": "Jules Renard",
      "sourcePage": 2
    },
    {
      "id": 55,
      "text": "Notre tête est ronde pour permettre à la pensée de changer de direction.",
      "author": "Francis Picabia",
      "sourcePage": 2
    },
    {
      "id": 56,
      "text": "C'est le coq qui chante, mais c'est la poule qui pond les œufs.",
      "author": "Margaret Thatcher",
      "sourcePage": 2
    },
    {
      "id": 57,
      "text": "Un exemple n'est pas forcement un exemple à suivre.",
      "author": "Albert Camus",
      "sourcePage": 2
    },
    {
      "id": 58,
      "text": "Les nuits de la semaine restent à baptiser.",
      "author": "Roland Topor",
      "sourcePage": 2
    },
    {
      "id": 59,
      "text": "Il importe peu de descendre du singe ; l'essentiel est de ne pas y remonter.",
      "author": "Richard Wagner",
      "sourcePage": 2
    },
    {
      "id": 60,
      "text": "Une fortune est plus à l'abri dans une tête que dans un sac.",
      "author": "Félix Leclerc",
      "sourcePage": 2
    },
    {
      "id": 61,
      "text": "Aujourd'hui, j'ai permis au soleil de se lever plus tôt que moi.",
      "author": "Georg Christoph Lichtenberg",
      "sourcePage": 2
    },
    {
      "id": 62,
      "text": "On n'a jamais autant besoin de vacances que lorsqu'on en revient.",
      "author": "Ann Landers",
      "sourcePage": 2
    },
    {
      "id": 63,
      "text": "Le bonheur est une petite chose que l'on grignote, assis par terre, au soleil.",
      "author": "Jean Giraudoux",
      "sourcePage": 2
    },
    {
      "id": 64,
      "text": "Qui rit vendredi, c'est toujours ça de pris. Qui pleure vendredi, dimanche ne saura quoi faire.",
      "author": "François Cavanna",
      "sourcePage": 2
    },
    {
      "id": 65,
      "text": "L'argent n'a pas d'idée.",
      "author": "Jean-Paul Sartre",
      "sourcePage": 2
    },
    {
      "id": 66,
      "text": "Nous avons besoin d'hommes qui savent rêver à des choses inédites.",
      "author": "John Fitzgerald Kennedy",
      "sourcePage": 2
    },
    {
      "id": 67,
      "text": "Savoir si l'on aimerait mieux mourir de faim ou de soif est une question qui apparemment plaît toujours.",
      "author": "Pierre Daninos",
      "sourcePage": 2
    },
    {
      "id": 68,
      "text": "Je n'ai jamais compris pourquoi les gens se disent \"au revoir\" au téléphone.",
      "author": "Albert Willemetz",
      "sourcePage": 2
    },
    {
      "id": 69,
      "text": "Il n'y a jamais eu de bonne guerre ni de mauvaise paix.",
      "author": "Benjamin Franklin",
      "sourcePage": 2
    },
    {
      "id": 70,
      "text": "Bien mal acquis profite toujours à quelqu'un.",
      "author": "Paul Léautaud",
      "sourcePage": 2
    },
    {
      "id": 71,
      "text": "La seule façon d'être suivi, c'est de courir plus vite que les autres.",
      "author": "Francis Picabia",
      "sourcePage": 2
    },
    {
      "id": 72,
      "text": "Le tact dans l'audace, c'est de savoir jusqu'ou on peut aller trop loin.",
      "author": "Jean Cocteau",
      "sourcePage": 2
    },
    {
      "id": 73,
      "text": "Quand on apporte une mauvaise nouvelle, personne ne pense à vous offrir à boire.",
      "author": "Marcel Pagnol",
      "sourcePage": 2
    },
    {
      "id": 74,
      "text": "La poubelle est le meilleur des accessoires de rangement.",
      "author": "San Antonio",
      "sourcePage": 2
    },
    {
      "id": 75,
      "text": "Arsenic : arme adroite pour faire passer l'arme à gauche.",
      "author": "Martial Villemin",
      "sourcePage": 2
    },
    {
      "id": 76,
      "text": "Verre d'eau - Quantité de liquide dans laquelle les autres se noient.",
      "author": "Pierre Daninos",
      "sourcePage": 2
    },
    {
      "id": 77,
      "text": "Celui qui dit que le bonheur ne s'achète pas a oublié qu'il y a les petits chiots.",
      "author": "Gene Hill",
      "sourcePage": 2
    },
    {
      "id": 78,
      "text": "Il ne faut pas de tout pour faire un monde. Il faut du bonheur, et rien d'autre.",
      "author": "Paul Eluard",
      "sourcePage": 2
    },
    {
      "id": 79,
      "text": "Les miroirs feraient bien de réfléchir un peu plus avant de renvoyer les images.",
      "author": "Jean Cocteau",
      "sourcePage": 2
    },
    {
      "id": 80,
      "text": "On ne ment jamais autant qu'avant les élections, pendant la guerre et après la chasse.",
      "author": "Georges Clemenceau",
      "sourcePage": 2
    },
    {
      "id": 81,
      "text": "Ne faites jamais l'amour le samedi soir, car s'il pleut le dimanche, vous ne saurez plus quoi faire.",
      "author": "Sacha Guitry",
      "sourcePage": 2
    },
    {
      "id": 82,
      "text": "Les cinéastes sont les conteurs d'aujourd'hui.",
      "author": "George Lucas",
      "sourcePage": 2
    },
    {
      "id": 83,
      "text": "Boire du café empêche de dormir. Par contre, dormir empêche de boire du café.",
      "author": "Philippe Geluck",
      "sourcePage": 2
    },
    {
      "id": 84,
      "text": "Alunissage : Procède technique consistant à déposer des imbéciles sur un rêve enfantin.",
      "author": "Pierre Desproges",
      "sourcePage": 2
    },
    {
      "id": 85,
      "text": "A force d'aller au fond des choses, on y reste.",
      "author": "Jean Cocteau",
      "sourcePage": 2
    },
    {
      "id": 86,
      "text": "Les passionnes soulèvent le monde, et les sceptiques le laissent retomber.",
      "author": "Albert Guinon",
      "sourcePage": 2
    },
    {
      "id": 87,
      "text": "Je hais la prudence, elle ne vous amène à rien.",
      "author": "Jacques Brel",
      "sourcePage": 2
    },
    {
      "id": 88,
      "text": "Les bouteilles à la mer ne ramènent pas souvent les réponses.",
      "author": "Antoine Blondin",
      "sourcePage": 2
    },
    {
      "id": 89,
      "text": "Il faut savoir profiter des mamans propices.",
      "author": "Roland Topor",
      "sourcePage": 2
    },
    {
      "id": 90,
      "text": "A quarante ans, on est riche ou on n'est rien.",
      "author": "Daniel Pennac",
      "sourcePage": 2
    },
    {
      "id": 91,
      "text": "Rien n'est moins sûr que l'incertain.",
      "author": "Pierre Dac",
      "sourcePage": 2
    },
    {
      "id": 92,
      "text": "Etant philosophe, j'ai un problème pour chaque solution.",
      "author": "Robert Zend",
      "sourcePage": 2
    },
    {
      "id": 93,
      "text": "Si vous voulez que vos rêves se réalisent, ne dormez pas.",
      "author": "proverbe juif",
      "sourcePage": 2
    },
    {
      "id": 94,
      "text": "Si haut qu'on monte, on finit toujours par des cendres.",
      "author": "Henri Rochefort",
      "sourcePage": 2
    },
    {
      "id": 95,
      "text": "Une fois qu'on a passé les bornes, il n'y a plus de limites.",
      "author": "Alphonse Allais",
      "sourcePage": 2
    },
    {
      "id": 96,
      "text": "Il faut toujours se réserver le droit de rire le lendemain de ses idées de la veille.",
      "author": "Napoléon Bonaparte",
      "sourcePage": 2
    },
    {
      "id": 97,
      "text": "Le nom du plus grand des inventeurs : accident.",
      "author": "Mark Twain",
      "sourcePage": 2
    },
    {
      "id": 98,
      "text": "C'est la différence d'opinion qui fait les courses de chevaux.",
      "author": "Mark Twain",
      "sourcePage": 2
    },
    {
      "id": 99,
      "text": "Tout le monde a des idées : la preuve, c'est qu'il y en a de mauvaises.",
      "author": "Coluche",
      "sourcePage": 2
    },
    {
      "id": 100,
      "text": "Un conducteur dangereux, c'est celui qui vous dépasse malgré tous vos efforts pour l'en empêcher.",
      "author": "Woody Allen",
      "sourcePage": 2
    },
    {
      "id": 101,
      "text": "Le café est un breuvage qui fait dormir quand on n'en prend pas.",
      "author": "Alphonse Allais",
      "sourcePage": 2
    },
    {
      "id": 102,
      "text": "Quand je mange des glaces, cela me fait réfléchir.",
      "author": "Louis Auguste Commerson",
      "sourcePage": 2
    },
    {
      "id": 103,
      "text": "J'aime mieux les méchants que les imbéciles, parce qu'ils se reposent.",
      "author": "Alexandre Dumas",
      "sourcePage": 2
    },
    {
      "id": 104,
      "text": "La campagne n'a de charme que pour ceux qui ne sont pas obligés d'y habiter.",
      "author": "Edouard Manet",
      "sourcePage": 2
    },
    {
      "id": 105,
      "text": "Fait curieux : personne n'a jamais le mal de mer à terre.",
      "author": "Jerome K. Jerome",
      "sourcePage": 2
    },
    {
      "id": 106,
      "text": "Le bac, c'est comme la lessive : on mouille, on sèche... et on repasse.",
      "author": "Henri Troyat",
      "sourcePage": 2
    },
    {
      "id": 107,
      "text": "Idée de génie : mettre la pomme de Newton dans la brouette de Pascal.",
      "author": "Roland Bacri",
      "sourcePage": 3
    },
    {
      "id": 108,
      "text": "Ronfler, c'est dormir tout haut.",
      "author": "Jules Renard",
      "sourcePage": 3
    },
    {
      "id": 109,
      "text": "La fête des pères est comme la fête des mères, sauf pour le cadeau qui coûte moins cher.",
      "author": "Georges Herbert",
      "sourcePage": 3
    },
    {
      "id": 110,
      "text": "Comme tous les verseaux, je ne crois pas a l'horoscope.",
      "author": "Anonyme",
      "sourcePage": 3
    },
    {
      "id": 111,
      "text": "On cesse toujours d'être le numéro un mais on ne cesse jamais d'avoir été le premier.",
      "author": "San Antonio",
      "sourcePage": 3
    },
    {
      "id": 112,
      "text": "Entre presque oui et oui, il y a tout un monde.",
      "author": "Alfred de Musset",
      "sourcePage": 3
    },
    {
      "id": 113,
      "text": "La moindre chose contient un peu d'inconnu. Trouvons-le.",
      "author": "Guy de Maupassant",
      "sourcePage": 3
    },
    {
      "id": 114,
      "text": "Les lettres anonymes ont le grand avantage qu'on n'est pas forcé d'y répondre.",
      "author": "Alexandre Dumas, fils",
      "sourcePage": 3
    },
    {
      "id": 115,
      "text": "Toute l'intelligence du monde est impuissante contre une idiotie à la mode.",
      "author": "Anonyme",
      "sourcePage": 3
    },
    {
      "id": 116,
      "text": "La logique mène à tout... à condition d'en sortir.",
      "author": "Alphonse Allais",
      "sourcePage": 3
    },
    {
      "id": 117,
      "text": "Vous n'aurez jamais une deuxième chance de faire une bonne première impression.",
      "author": "David Swanson",
      "sourcePage": 3
    },
    {
      "id": 118,
      "text": "Les principales manifestations sportives ont lieu pendant les examens.",
      "author": "Anonyme",
      "sourcePage": 3
    },
    {
      "id": 119,
      "text": "Il est singulier de songer qu'amour n'est féminin qu'au pluriel.",
      "author": "Albert Willemetz",
      "sourcePage": 3
    },
    {
      "id": 120,
      "text": "Les Français sont si fiers de leurs vins qu'ils ont donné à certaines de leurs villes le nom d'un grand cru.",
      "author": "Oscar Wilde",
      "sourcePage": 3
    },
    {
      "id": 121,
      "text": "Tout ce qui a son prix est de peu de valeur.",
      "author": "Friedrich Nietzsche",
      "sourcePage": 3
    },
    {
      "id": 122,
      "text": "Ne rien faire n'est vraiment agréable que si l'on a beaucoup de travail en retard.",
      "author": "Jerome K. Jerome",
      "sourcePage": 3
    },
    {
      "id": 123,
      "text": "La vie c'est comme le football, seul le résultat compte !",
      "author": "Anonyme",
      "sourcePage": 3
    },
    {
      "id": 124,
      "text": "L'amour, c'est de la physique, le mariage c'est de la chimie.",
      "author": "Alexandre Dumas, fils",
      "sourcePage": 3
    },
    {
      "id": 125,
      "text": "Les privilèges dont on ne bénéficie pas sont absolument inadmissibles.",
      "author": "Yvan Audouard",
      "sourcePage": 3
    },
    {
      "id": 126,
      "text": "Celui qui n'a jamais perdu la tête, c'est qu'il n'avait pas de tête à perdre.",
      "author": "Marcel Achard",
      "sourcePage": 3
    },
    {
      "id": 127,
      "text": "Le taxi est comme le prêt bancaire. Très difficile à trouver quand on en a besoin.",
      "author": "José Artur",
      "sourcePage": 3
    },
    {
      "id": 128,
      "text": "Ce qui est nouveau est rarement vrai ; ce qui est vrai est rarement nouveau.",
      "author": "Georg Christoph Lichtenberg",
      "sourcePage": 3
    },
    {
      "id": 129,
      "text": "Il faut faire aujourd'hui ce que tout le monde fera demain.",
      "author": "Jean Cocteau",
      "sourcePage": 3
    },
    {
      "id": 130,
      "text": "Les deux mots les plus beaux de notre vocabulaire sont 'cheque joint'.",
      "author": "Dorothy Parker",
      "sourcePage": 3
    },
    {
      "id": 131,
      "text": "Je fais un nœud à mon mouchoir pour me rappeler que j'existe.",
      "author": "Alexandre Arnoux",
      "sourcePage": 3
    },
    {
      "id": 132,
      "text": "J'ai tout donné au soleil, tout, sauf mon ombre.",
      "author": "Guillaume Apollinaire",
      "sourcePage": 3
    },
    {
      "id": 133,
      "text": "Présage. Signe que quelque chose arrivera si rien ne se passe.",
      "author": "Ambrose Bierce",
      "sourcePage": 3
    },
    {
      "id": 134,
      "text": "On n'a quand même pas pris la Bastille pour en faire un opéra !",
      "author": "Pierre Desproges",
      "sourcePage": 3
    },
    {
      "id": 135,
      "text": "Pourquoi n'entend-on jamais parler de l'imbécile malheureux ?",
      "author": "Jean Dion",
      "sourcePage": 3
    },
    {
      "id": 136,
      "text": "Certains croient que le génie est héréditaire. Les autres n'ont pas d'enfants.",
      "author": "Marcel Achard",
      "sourcePage": 3
    },
    {
      "id": 137,
      "text": "Et si vous n'avez rien à dire, ce n'est pas la peine de le faire savoir à tout le monde !",
      "author": "Francis Blanche",
      "sourcePage": 3
    },
    {
      "id": 138,
      "text": "Ne remets jamais au lendemain ce que tu peux ne pas faire du tout.",
      "author": "Ambrose Bierce",
      "sourcePage": 3
    },
    {
      "id": 139,
      "text": "La véritable discipline, c'est de ramasser des fraises sans en manger une seule.",
      "author": "Doug Larson",
      "sourcePage": 3
    },
    {
      "id": 140,
      "text": "On ne perd rien à être poli sauf sa place dans le métro.",
      "author": "Tristan Bernard",
      "sourcePage": 3
    },
    {
      "id": 141,
      "text": "En amour, écrire est dangereux, sans compter que c'est inutile.",
      "author": "Alexandre Dumas, fils",
      "sourcePage": 3
    },
    {
      "id": 142,
      "text": "Je ne pense jamais, cela me fatigue ; ou si je pense, je ne pense à rien.",
      "author": "Georges Courteline",
      "sourcePage": 3
    },
    {
      "id": 143,
      "text": "L'âge ne compte pas, à moins d'être un fromage.",
      "author": "Billie Burke",
      "sourcePage": 3
    },
    {
      "id": 144,
      "text": "Le Tour de France, il serait moins dur à faire sans le vélo que sans le dopage. Et encore, il faudrait qu'il fasse beau !",
      "author": "Coluche",
      "sourcePage": 3
    },
    {
      "id": 145,
      "text": "Avec le talent, on fait ce qu'on veut. Avec le génie, on fait ce qu'on peut.",
      "author": "Jean-Auguste Ingres",
      "sourcePage": 3
    },
    {
      "id": 146,
      "text": "Etre dans le vent : une ambition de feuille morte...",
      "author": "Gustave Thibon",
      "sourcePage": 3
    },
    {
      "id": 147,
      "text": "On ne demande conseil que pour raconter ses ennuis.",
      "author": "Jules Renard",
      "sourcePage": 3
    },
    {
      "id": 148,
      "text": "Il ne sert de rien à l'homme de gagner la Lune s'il vient à perdre la Terre.",
      "author": "François Mauriac",
      "sourcePage": 3
    },
    {
      "id": 149,
      "text": "Le meilleur moyen de ne pas être dérangé au téléphone, c'est d'être en dérangement.",
      "author": "Fernand Raynaud",
      "sourcePage": 3
    },
    {
      "id": 150,
      "text": "L'homme est intelligent parce qu'il a une main.",
      "author": "Anaxagore",
      "sourcePage": 3
    },
    {
      "id": 151,
      "text": "Cheval : le seul animal dans lequel on puisse planter des clous.",
      "author": "Jules Renard",
      "sourcePage": 3
    },
    {
      "id": 152,
      "text": "Le poisson est un animal susceptible : en présence du pêcheur, il prend facilement la mouche.",
      "author": "Noctuel",
      "sourcePage": 3
    },
    {
      "id": 153,
      "text": "La preuve que l'homme descend du singe, c'est que, lorsqu'il se sent perdu, il se raccroche à toutes les branches.",
      "author": "Antoine Préault",
      "sourcePage": 3
    },
    {
      "id": 154,
      "text": "Les conseils qui valent de l'or rapportent rarement de l'argent.",
      "author": "Jacques Sternberg",
      "sourcePage": 3
    },
    {
      "id": 155,
      "text": "La bouillabaisse, c'est du poisson avec du soleil.",
      "author": "Alfred Capus",
      "sourcePage": 3
    },
    {
      "id": 156,
      "text": "Je chante faux, mais j'entends juste.",
      "author": "Marcel Achard",
      "sourcePage": 3
    },
    {
      "id": 157,
      "text": "Il est plus facile de résister au premier de ses désirs qu'à tous ceux qui le suivent.",
      "author": "Benjamin Franklin",
      "sourcePage": 4
    },
    {
      "id": 158,
      "text": "Les obstacles ne sont que ce qu'il faut surmonter.",
      "author": "Samuel Gridley Howe",
      "sourcePage": 4
    },
    {
      "id": 159,
      "text": "Ou l'on fait appel au talent, c'est que l'imagination fait défaut.",
      "author": "Georges Braque",
      "sourcePage": 4
    },
    {
      "id": 160,
      "text": "Ni Dieu ni maître, même nageur !",
      "author": "Jean Yanne",
      "sourcePage": 4
    },
    {
      "id": 161,
      "text": "Cherchez le ridicule en tout, vous le trouverez.",
      "author": "Jules Renard",
      "sourcePage": 4
    },
    {
      "id": 162,
      "text": "Parfois je pense ; et parfois je suis.",
      "author": "Paul Valery",
      "sourcePage": 4
    },
    {
      "id": 163,
      "text": "La lune est pleine et on ne sait pas qui l'a mise dans cet état.",
      "author": "Alphonse Allais",
      "sourcePage": 4
    },
    {
      "id": 164,
      "text": "Quel homme a jamais pu être sûr de ce qui se passe derrière son dos ?",
      "author": "Julien Green",
      "sourcePage": 4
    },
    {
      "id": 165,
      "text": "Ce que le tableau représente ? Cela dépend de celui qui le regarde.",
      "author": "James Whistler",
      "sourcePage": 4
    },
    {
      "id": 166,
      "text": "Faire un malheur au théâtre, c'est faire plein de petits bonheurs.",
      "author": "Coluche",
      "sourcePage": 4
    },
    {
      "id": 167,
      "text": "Les gens qui envoient des baisers sont de sacres paresseux.",
      "author": "Bob Hope",
      "sourcePage": 4
    },
    {
      "id": 168,
      "text": "Je vous céderais bien ma place, mais elle est occupée.",
      "author": "Groucho Marx",
      "sourcePage": 4
    },
    {
      "id": 169,
      "text": "L'avenir, c'est du passe en préparation.",
      "author": "Pierre Dac",
      "sourcePage": 4
    },
    {
      "id": 170,
      "text": "Ça marche toujours lorsqu'on sait ce qu'on fait.",
      "author": "Richard Bach",
      "sourcePage": 4
    },
    {
      "id": 171,
      "text": "Il est bien plus beau de savoir quelque chose de tout que de savoir tout d'une chose.",
      "author": "Blaise Pascal",
      "sourcePage": 4
    },
    {
      "id": 172,
      "text": "Quand les hommes ne peuvent changer les choses, ils changent les mots.",
      "author": "Jean Jaures",
      "sourcePage": 4
    },
    {
      "id": 173,
      "text": "La Joconde sourit parce que tous ceux qui lui ont dessiné des moustaches sont morts.",
      "author": "André Malraux",
      "sourcePage": 4
    },
    {
      "id": 174,
      "text": "Les enfants seuls savent ce qu'ils cherchent.",
      "author": "Antoine de Saint-Exupéry",
      "sourcePage": 4
    },
    {
      "id": 175,
      "text": "L'insouciance tue... les autres.",
      "author": "Stanislaw Jerzy Lec",
      "sourcePage": 4
    },
    {
      "id": 176,
      "text": "La mode est ce que l'on porte. Ce qui est démodé, c'est ce que portent les autres.",
      "author": "Oscar Wilde",
      "sourcePage": 4
    },
    {
      "id": 177,
      "text": "A quoi servirait l'intelligence si l'imbécillité n'existait pas ?",
      "author": "Pierre Dac",
      "sourcePage": 4
    },
    {
      "id": 178,
      "text": "Gagner sa vie en jouant du piano, c'est savoir compter sur ses doigts.",
      "author": "Darry Cowl",
      "sourcePage": 4
    },
    {
      "id": 179,
      "text": "Il n'y a pas d'opinions, mais des gens qui donnent la leur.",
      "author": "Miguel de Unamuno",
      "sourcePage": 4
    },
    {
      "id": 180,
      "text": "Les absurdités d'hier sont les vérités d'aujourd'hui et les banalités de demain.",
      "author": "A. Marandotti",
      "sourcePage": 4
    },
    {
      "id": 181,
      "text": "Rien n'est petit pour un grand esprit.",
      "author": "Arthur Conan Doyle",
      "sourcePage": 4
    },
    {
      "id": 182,
      "text": "J'ai assez d'idées pour qu'on puisse me voler sans me nuire.",
      "author": "André Malraux",
      "sourcePage": 4
    },
    {
      "id": 183,
      "text": "Il n'y a aucun mal à changer d'avis. Pourvu que ce soit dans le bon sens.",
      "author": "Winston Churchill",
      "sourcePage": 4
    },
    {
      "id": 184,
      "text": "Un homme compétent est un homme qui se trompe selon les règles.",
      "author": "Paul Valery",
      "sourcePage": 4
    },
    {
      "id": 185,
      "text": "Moustique : plus dangereux que n'importe quelle bête féroce.",
      "author": "Gustave Flaubert",
      "sourcePage": 4
    },
    {
      "id": 186,
      "text": "C'est dur, hein, d'avoir un cerveau...",
      "author": "Jean Yanne",
      "sourcePage": 4
    },
    {
      "id": 187,
      "text": "Ne rien risquer est un risque encore plus grand !",
      "author": "Erica Jong",
      "sourcePage": 4
    },
    {
      "id": 188,
      "text": "L'exactitude est la politesse des montres.",
      "author": "Jean Dutourd",
      "sourcePage": 4
    },
    {
      "id": 189,
      "text": "Quarante années durant, j'ai vu. Aujourd'hui je regarde.",
      "author": "Pierre Daninos",
      "sourcePage": 4
    },
    {
      "id": 190,
      "text": "Tout s'explique, rien ne se justifie.",
      "author": "Alfred Capus",
      "sourcePage": 4
    },
    {
      "id": 191,
      "text": "Une pensée est une chose aussi réelle qu'un boulet de canon.",
      "author": "Joseph Joubert",
      "sourcePage": 4
    },
    {
      "id": 192,
      "text": "Droit devant soi, on ne peut pas aller bien loin.",
      "author": "Antoine de Saint-Exupéry",
      "sourcePage": 4
    },
    {
      "id": 193,
      "text": "Pourquoi dit-on que les murs ont des oreilles, alors que c'est aux portes qu'on écoute ?",
      "author": "La Robertie",
      "sourcePage": 4
    },
    {
      "id": 194,
      "text": "Le savant sait qu'il ignore.",
      "author": "Victor Hugo",
      "sourcePage": 4
    },
    {
      "id": 195,
      "text": "Si l'important n'est pas de gagner, pourquoi compte-t-on les points ?",
      "author": "Vince Lombardi",
      "sourcePage": 4
    },
    {
      "id": 196,
      "text": "Plus nombreux sont les problèmes auxquels on réfléchit, plus on risque de n'en comprendre aucun.",
      "author": "Jan Amos Comenius",
      "sourcePage": 4
    },
    {
      "id": 197,
      "text": "Du sublime au ridicule, il n'y a qu'un pas.",
      "author": "Napoléon Bonaparte",
      "sourcePage": 4
    },
    {
      "id": 198,
      "text": "La vie a plus d'imagination que n'en portent nos rêves.",
      "author": "Ridley Scott",
      "sourcePage": 4
    },
    {
      "id": 199,
      "text": "L'opinion publique, c'est la sottise en action.",
      "author": "Julien Green",
      "sourcePage": 4
    },
    {
      "id": 200,
      "text": "La connaissance parle, mais la sagesse écoute.",
      "author": "Jimi Hendrix",
      "sourcePage": 4
    },
    {
      "id": 201,
      "text": "Il vaut mieux dater d'un siècle que d'une saison.",
      "author": "Alfred Capus",
      "sourcePage": 4
    },
    {
      "id": 202,
      "text": "Notre vie vaut ce qu'elle nous a coûté d'efforts.",
      "author": "François Mauriac",
      "sourcePage": 4
    },
    {
      "id": 203,
      "text": "Les rêves donnent du travail.",
      "author": "Paulo Coelho",
      "sourcePage": 4
    },
    {
      "id": 204,
      "text": "Faites des bêtises, mais faites-les avec enthousiasme.",
      "author": "Colette",
      "sourcePage": 4
    },
    {
      "id": 205,
      "text": "Le talent, c'est une question d'amour.",
      "author": "Romy Schneider",
      "sourcePage": 4
    },
    {
      "id": 206,
      "text": "Comme il faut travailler pour être naturel !",
      "author": "Louis Jouvet",
      "sourcePage": 4
    },
    {
      "id": 207,
      "text": "Ce qui compte, c'est d'avoir toujours quelque chose à attendre.",
      "author": "Didier van Cauwelaert",
      "sourcePage": 4
    },
    {
      "id": 208,
      "text": "Le meilleur moyen de s'endormir est de s'imaginer qu'il est l'heure de se lever.",
      "author": "Groucho Marx",
      "sourcePage": 4
    },
    {
      "id": 209,
      "text": "Dans le monde, il n'est pas défendu d'avoir l'air franc mais de l'être.",
      "author": "Marguerite Grepon",
      "sourcePage": 4
    },
    {
      "id": 210,
      "text": "Le hasard dans certains cas, c'est la volonté des autres.",
      "author": "Alfred Capus",
      "sourcePage": 4
    },
    {
      "id": 211,
      "text": "Savoir où l'on veut aller, c'est très bien ; mais il faut encore montrer qu'on y va.",
      "author": "Emile Zola",
      "sourcePage": 4
    },
    {
      "id": 212,
      "text": "Avez-vous remarqué comme on est bête, quand on est beaucoup ?",
      "author": "George Sand",
      "sourcePage": 4
    },
    {
      "id": 213,
      "text": "J'ai toujours été surpris qu'un record battu ne se soit jamais plaint.",
      "author": "Pierre Dac",
      "sourcePage": 4
    },
    {
      "id": 214,
      "text": "Tout est permis en dedans.",
      "author": "Louis-Ferdinand Céline",
      "sourcePage": 5
    },
    {
      "id": 215,
      "text": "Les idées reçues sont des maladies contagieuses.",
      "author": "Esther Rochon",
      "sourcePage": 5
    },
    {
      "id": 216,
      "text": "Un remords vaut mieux qu'une hésitation qui se prolonge.",
      "author": "Henry de Montherlant",
      "sourcePage": 5
    },
    {
      "id": 217,
      "text": "On peut feindre d'avoir du cœur, pas d'avoir de l'esprit.",
      "author": "Paul Morand",
      "sourcePage": 5
    },
    {
      "id": 218,
      "text": "Pourquoi faire part de nos opinions ? Demain, nous en aurons changé.",
      "author": "Paul Leautaud",
      "sourcePage": 5
    },
    {
      "id": 219,
      "text": "Sous prétexte que la perfection n'est pas de ce monde, ne gardez pas soigneusement tous vos défauts.",
      "author": "Jules Renard",
      "sourcePage": 5
    },
    {
      "id": 220,
      "text": "Un homme est heureux tant qu'il décide de l'être, et nul ne peut l'en empêcher.",
      "author": "Alexandre Soljenitsyne",
      "sourcePage": 5
    },
    {
      "id": 221,
      "text": "Imaginer, c'est choisir.",
      "author": "Jean Giono",
      "sourcePage": 5
    },
    {
      "id": 222,
      "text": "Le futur a été crée pour être changé.",
      "author": "Paulo Coelho",
      "sourcePage": 5
    },
    {
      "id": 223,
      "text": "Le hasard, c'est Dieu qui se promène incognito.",
      "author": "Albert Einstein",
      "sourcePage": 5
    },
    {
      "id": 224,
      "text": "On ne peut apprendre au crabe à marcher droit.",
      "author": "Aristophane",
      "sourcePage": 5
    },
    {
      "id": 225,
      "text": "L'homme est fait pour attendre, et la femme pour être inattendue.",
      "author": "Gérard de Rohan Chabot",
      "sourcePage": 5
    },
    {
      "id": 226,
      "text": "Créer, c'est penser plus fortement.",
      "author": "Pierre Reverdy",
      "sourcePage": 5
    },
    {
      "id": 227,
      "text": "Le chauffeur est, de loin, la partie la plus dangereuse de l'automobile.",
      "author": "Léo Campion",
      "sourcePage": 5
    },
    {
      "id": 228,
      "text": "Le neuf suscite la colère des habitudes.",
      "author": "Jacques Attali",
      "sourcePage": 5
    },
    {
      "id": 229,
      "text": "Pourquoi lave-t-on une injure alors qu'on essuie un affront ?",
      "author": "Alphonse Allais",
      "sourcePage": 5
    },
    {
      "id": 230,
      "text": "Ne pas se faire de bien, c'est une manière de se faire du mal.",
      "author": "Lisa Carducci",
      "sourcePage": 5
    },
    {
      "id": 231,
      "text": "Ça ne sert à rien d'être le meilleur, ce qui est important c'est d'être bon.",
      "author": "Christophe Malavoy",
      "sourcePage": 5
    },
    {
      "id": 232,
      "text": "Se passionner pour tout et ne tenir à rien.",
      "author": "Jean-Louis Barrault",
      "sourcePage": 5
    },
    {
      "id": 233,
      "text": "Le superflu, cette chose si nécessaire.",
      "author": "Voltaire",
      "sourcePage": 5
    },
    {
      "id": 234,
      "text": "Une journée nuageuse ne peut rien contre un tempérament radieux.",
      "author": "William Arthur Ward",
      "sourcePage": 5
    },
    {
      "id": 235,
      "text": "Il y a tellement de choses qu'on voudrait avoir faites hier et si peu qu'on a envie de faire aujourd'hui.",
      "author": "Mignon MacLaughlin",
      "sourcePage": 5
    },
    {
      "id": 236,
      "text": "Les singes sont bien trop bons pour que l'homme puisse descendre d'eux.",
      "author": "Friedrich Nietzsche",
      "sourcePage": 5
    },
    {
      "id": 237,
      "text": "Dieu a inventé la calvitie pour rendre les hommes plus humbles.",
      "author": "Bruce Willis",
      "sourcePage": 5
    },
    {
      "id": 238,
      "text": "Je ne connais pas la clé du succès mais celle de l'échec est d'essayer de plaire à tout le monde.",
      "author": "Bill Cosby",
      "sourcePage": 5
    },
    {
      "id": 239,
      "text": "Les problèmes d'aujourd'hui viennent des solutions d'hier.",
      "author": "Peter Senge",
      "sourcePage": 5
    },
    {
      "id": 240,
      "text": "La perfection d'une pendule n'est pas d'aller vite, mais d'être réglée.",
      "author": "Vauvenargues",
      "sourcePage": 5
    },
    {
      "id": 241,
      "text": "Pas besoin d'intérêt pour mentir. Le plaisir suffit.",
      "author": "Amélie Nothomb",
      "sourcePage": 5
    },
    {
      "id": 242,
      "text": "Ne pas se faire de bien, c'est une manière de se faire du mal.",
      "author": "Lisa Carducci",
      "sourcePage": 5
    },
    {
      "id": 243,
      "text": "Il est bien peu de monstres qui méritent la peur que nous en avons.",
      "author": "André Gide",
      "sourcePage": 5
    },
    {
      "id": 244,
      "text": "La Toussaint est le jour où les morts de demain vont rendre visite à ceux d'hier.",
      "author": "Henri Duvernois",
      "sourcePage": 5
    },
    {
      "id": 245,
      "text": "Ce ne sont pas les heures qui sont précieuses, ce sont les minutes.",
      "author": "Bernard Shaw",
      "sourcePage": 5
    },
    {
      "id": 246,
      "text": "Les murs ont des oreilles. Vos oreilles ont des murs.",
      "author": "slogan de mai 68",
      "sourcePage": 5
    },
    {
      "id": 247,
      "text": "Les grandes choses peuvent se manifester par de petits signes.",
      "author": "Sigmund Freud",
      "sourcePage": 5
    },
    {
      "id": 248,
      "text": "On peut toujours plus que ce que l'on croit pouvoir.",
      "author": "Joseph Kessel",
      "sourcePage": 5
    },
    {
      "id": 249,
      "text": "Les déceptions ne tuent pas et les espérances font vivre.",
      "author": "George Sand",
      "sourcePage": 5
    },
    {
      "id": 250,
      "text": "Pour la plupart des hommes, se corriger consiste à changer de défauts.",
      "author": "Voltaire",
      "sourcePage": 5
    },
    {
      "id": 251,
      "text": "Qu'appelle-t-on sens commun ? Le sens que chacun de nous pense avoir tout seul.",
      "author": "Alfred Bougeard",
      "sourcePage": 5
    },
    {
      "id": 252,
      "text": "Si on respecte toutes les règles, on gâche tout le plaisir.",
      "author": "Katharine Hepburn",
      "sourcePage": 5
    },
    {
      "id": 253,
      "text": "Il faut rêver très haut pour ne pas réaliser trop bas.",
      "author": "Alfred Capus",
      "sourcePage": 5
    },
    {
      "id": 254,
      "text": "Qui prête à rire n'est jamais sûr d'être remboursé.",
      "author": "Raymond Devos",
      "sourcePage": 5
    },
    {
      "id": 255,
      "text": "La faiblesse de la force est de ne croire qu'à la force.",
      "author": "Paul Valery",
      "sourcePage": 5
    },
    {
      "id": 256,
      "text": "Où serait le mérite, si les héros n'avaient jamais peur ?",
      "author": "Alphonse Daudet",
      "sourcePage": 5
    },
    {
      "id": 257,
      "text": "Il ne faut pas avoir peur du bonheur. C'est seulement un bon moment à passer.",
      "author": "Romain Gary",
      "sourcePage": 5
    },
    {
      "id": 258,
      "text": "Il faut s'efforcer d'être jeune comme un beaujolais et de vieillir comme un bourgogne.",
      "author": "Robert Sabatier",
      "sourcePage": 5
    },
    {
      "id": 259,
      "text": "C'est quand on a raison qu'il est difficile de prouver qu'on n'a pas tort.",
      "author": "Pierre Dac",
      "sourcePage": 5
    },
    {
      "id": 260,
      "text": "On n'arrête pas le progrès dit-on. La bêtise non plus.",
      "author": "Yves Courrière",
      "sourcePage": 5
    },
    {
      "id": 261,
      "text": "Rien n'est moins raisonnable que de vouloir que les enfants le soient.",
      "author": "Madame de Maintenon",
      "sourcePage": 5
    },
    {
      "id": 262,
      "text": "Le trop de quelque chose est un manque de quelque chose.",
      "author": "proverbe arabe",
      "sourcePage": 5
    },
    {
      "id": 263,
      "text": "Entre deux maux, je choisis toujours celui que je n'ai jamais essayé.",
      "author": "Mae West",
      "sourcePage": 5
    },
    {
      "id": 264,
      "text": "On agit plus avec un homme qu'avec une idée.",
      "author": "Alfred Capus",
      "sourcePage": 5
    },
    {
      "id": 265,
      "text": "Il n'y a rien de nouveau sous le soleil, mais il y a aussi tout un tas de vieux trucs que nous ignorons.",
      "author": "Ambrose Bierce",
      "sourcePage": 5
    },
    {
      "id": 266,
      "text": "Voilà ce qui fait le bon commerçant. Il vous fait acheter ce qu'il a besoin de vendre.",
      "author": "James Joyce",
      "sourcePage": 5
    },
    {
      "id": 267,
      "text": "La découverte d'un mets nouveau fait plus pour le genre humain que la découverte d'une étoile.",
      "author": "Anthelme Brillat-Savarin",
      "sourcePage": 5
    },
    {
      "id": 268,
      "text": "Avec nos pensées, nous créons le monde.",
      "author": "Bouddha",
      "sourcePage": 6
    },
    {
      "id": 269,
      "text": "Si les pêches faisaient souffrir quand on les fait, nous serions tous des saints.",
      "author": "Marcel Pagnol",
      "sourcePage": 6
    },
    {
      "id": 270,
      "text": "A quoi bon apprendre ce qui est dans les livres, puisque ça y est ?",
      "author": "Sacha Guitry",
      "sourcePage": 6
    },
    {
      "id": 271,
      "text": "Je peux résister à tout, sauf à la tentation.",
      "author": "Oscar Wilde",
      "sourcePage": 6
    },
    {
      "id": 272,
      "text": "Le meilleur moyen de tenir sa parole est de ne jamais la donner.",
      "author": "Napoléon Bonaparte",
      "sourcePage": 6
    },
    {
      "id": 273,
      "text": "On n'a rien inventé de mieux que la bêtise pour se croire intelligent.",
      "author": "Amélie Nothomb",
      "sourcePage": 6
    },
    {
      "id": 274,
      "text": "Je suis pessimiste par l'intelligence mais optimiste par la volonté.",
      "author": "Antonio Gramsci",
      "sourcePage": 6
    },
    {
      "id": 275,
      "text": "Il ne suffit pas d'avoir du talent. Il faut encore savoir s'en servir.",
      "author": "Alphonse Allais",
      "sourcePage": 6
    },
    {
      "id": 276,
      "text": "Un peu d'inexactitude peut parfois éviter de nombreuses explications.",
      "author": "Saki",
      "sourcePage": 6
    },
    {
      "id": 277,
      "text": "Mieux vaut un mauvais caractère que pas de caractère du tout.",
      "author": "Georges Bernanos",
      "sourcePage": 6
    },
    {
      "id": 278,
      "text": "Pourquoi l'argent n'aurait-il pas d'odeur, lui qui peut tout avoir ?",
      "author": "Erik Satie",
      "sourcePage": 6
    },
    {
      "id": 279,
      "text": "Qui est en bonne santé est riche sans le savoir.",
      "author": "Proverbe français",
      "sourcePage": 6
    },
    {
      "id": 280,
      "text": "Il est souvent plus facile de commencer quelque chose que d'y mettre fin.",
      "author": "Agnes Allen",
      "sourcePage": 6
    },
    {
      "id": 281,
      "text": "La liberté consiste à faire tout ce qui ne nuit pas à autrui.",
      "author": "Anonyme",
      "sourcePage": 6
    },
    {
      "id": 282,
      "text": "Il faut collectionner les pierres qu'on vous jette. C'est le début d'un piédestal.",
      "author": "Hector Berlioz",
      "sourcePage": 6
    },
    {
      "id": 283,
      "text": "Tous les moyens sont bons quand ils sont efficaces.",
      "author": "Jean-Paul Sartre",
      "sourcePage": 6
    },
    {
      "id": 284,
      "text": "En ce monde, on vit mieux en disant la bonne aventure qu'en disant la vérité.",
      "author": "Georg Christoph Lichtenberg",
      "sourcePage": 6
    },
    {
      "id": 285,
      "text": "Il faut toujours abuser de sa liberté.",
      "author": "Paul Eluard",
      "sourcePage": 6
    },
    {
      "id": 286,
      "text": "Si vous ne dites rien, on ne vous demandera pas de le répéter.",
      "author": "Calvin Coolidge",
      "sourcePage": 6
    },
    {
      "id": 287,
      "text": "La gourmandise commence quand on n'a plus faim.",
      "author": "Alphonse Daudet",
      "sourcePage": 6
    },
    {
      "id": 288,
      "text": "Si deux hommes sont d'accord sur tout, c'est qu'un seul des deux pense.",
      "author": "Lyndon B. Johnson",
      "sourcePage": 6
    },
    {
      "id": 289,
      "text": "Il faut toujours un coup de folie pour bâtir un destin.",
      "author": "Marguerite Yourcenar",
      "sourcePage": 6
    },
    {
      "id": 290,
      "text": "Entreprenez l'impossible, l'impossible fera le reste.",
      "author": "François Caries",
      "sourcePage": 6
    },
    {
      "id": 291,
      "text": "Les huîtres sont des mollusques qui passent les fêtes de fin d'année dans des huttes appelées bourriches.",
      "author": "Claude Pieplu",
      "sourcePage": 6
    },
    {
      "id": 292,
      "text": "Je vous offrirais bien un parachute... si j'étais sur qu'il ne s'ouvre pas !",
      "author": "Groucho Marx",
      "sourcePage": 6
    },
    {
      "id": 293,
      "text": "Il y a des moments où l'absence d'ogres se fait cruellement sentir.",
      "author": "Alphonse Allais",
      "sourcePage": 6
    },
    {
      "id": 294,
      "text": "Treize à table n'est à craindre qu'autant qu'il n'y aurait à manger que pour douze.",
      "author": "Grimod de la Reynière",
      "sourcePage": 6
    },
    {
      "id": 295,
      "text": "Noël, c'est la veille, c'est l'attente.",
      "author": "Georges Dor",
      "sourcePage": 6
    },
    {
      "id": 296,
      "text": "Le Père Noël ne fait jamais de réveillon dans sa maison, car il rentre au mois de mai ; ce n'est plus la saison.",
      "author": "Francis Blanche",
      "sourcePage": 6
    },
    {
      "id": 297,
      "text": "Le chocolat plonge des êtres par ailleurs normaux dans d'étranges états extatiques.",
      "author": "John West",
      "sourcePage": 6
    },
    {
      "id": 298,
      "text": "Une huître, c'est un poisson fait comme une noix.",
      "author": "Jean-Charles",
      "sourcePage": 6
    },
    {
      "id": 299,
      "text": "La table est le seul endroit où l'on ne s'ennuie jamais pendant la première heure.",
      "author": "Anthelme Brillat- Savarin",
      "sourcePage": 6
    },
    {
      "id": 300,
      "text": "Les gens ne mangeraient pas de caviar s'il était bon marché.",
      "author": "Groucho Marx",
      "sourcePage": 6
    },
    {
      "id": 301,
      "text": "Quand mon verre est vide, je le plains ; quand mon verre est plein, je le vide.",
      "author": "Raoul Ponchon",
      "sourcePage": 6
    },
    {
      "id": 302,
      "text": "Mon Dieu, que votre volonté soit fête !",
      "author": "Frédéric Dard",
      "sourcePage": 6
    },
    {
      "id": 303,
      "text": "Le premier janvier est le seul jour de l'année où les femmes oublient notre passé grâce à notre présent.",
      "author": "Sacha Guitry",
      "sourcePage": 6
    },
    {
      "id": 304,
      "text": "Je me suis mis au régime : en quatorze jours, j'ai perdu deux semaines.",
      "author": "Joe Lewis",
      "sourcePage": 6
    },
    {
      "id": 305,
      "text": "On oublie, dans le classement des grands événements ayant marqué le millénaire, d'inclure la vogue des classements.",
      "author": "Jean Dion",
      "sourcePage": 6
    },
    {
      "id": 306,
      "text": "Janvier est le mois où l'on offre ses meilleurs vœux à ses amis. Les autres mois sont ceux où ils ne se réaliseront pas.",
      "author": "Georg Christoph Lichtenberg",
      "sourcePage": 6
    },
    {
      "id": 307,
      "text": "Pour bien mentir il faut beaucoup de sincérité !",
      "author": "Jean Giono",
      "sourcePage": 6
    },
    {
      "id": 308,
      "text": "C'est en copiant qu'on invente.",
      "author": "Paul Valery",
      "sourcePage": 6
    },
    {
      "id": 309,
      "text": "L'imagination est plus importante que le savoir.",
      "author": "Albert Einstein",
      "sourcePage": 6
    },
    {
      "id": 310,
      "text": "Le possible n'est pas loin du nécessaire.",
      "author": "Pythagore",
      "sourcePage": 6
    },
    {
      "id": 311,
      "text": "Quand le sage désigne la lune, l'idiot regarde le doigt.",
      "author": "Proverbe chinois",
      "sourcePage": 6
    },
    {
      "id": 312,
      "text": "La mode se démode, le style jamais.",
      "author": "Coco Chanel",
      "sourcePage": 6
    },
    {
      "id": 313,
      "text": "C'est avoir tort que d'avoir raison trop tôt.",
      "author": "Marguerite Yourcenar",
      "sourcePage": 6
    },
    {
      "id": 314,
      "text": "Ne pas prévoir, c'est déjà gémir.",
      "author": "Léonard de Vinci",
      "sourcePage": 6
    },
    {
      "id": 315,
      "text": "Pour sauver un arbre, mangez un castor !",
      "author": "Prades",
      "sourcePage": 6
    },
    {
      "id": 316,
      "text": "Rien n'est jamais perdu tant qu'il reste quelque chose à trouver.",
      "author": "Pierre Dac",
      "sourcePage": 6
    },
    {
      "id": 317,
      "text": "Il n'est pas de problème dont une absence de solution ne finisse par venir à bout.",
      "author": "Henri Queuille",
      "sourcePage": 6
    },
    {
      "id": 318,
      "text": "On ne peut oublier le temps qu'en s'en servant.",
      "author": "Charles Baudelaire",
      "sourcePage": 6
    },
    {
      "id": 319,
      "text": "La meilleure façons d'imposer une idée aux autres, c'est de leur faire croire qu'elle vient d'eux.",
      "author": "Alphonse Daudet",
      "sourcePage": 6
    },
    {
      "id": 320,
      "text": "Il n'y a rien de plus inutile que de faire avec efficacité quelque chose qui ne doit pas du tout être fait.",
      "author": "Peter Drücker",
      "sourcePage": 7
    },
    {
      "id": 321,
      "text": "Ce que l'amour peut faire, l'amour ose le tenter.",
      "author": "William Shakespeare",
      "sourcePage": 7
    },
    {
      "id": 322,
      "text": "La mode, c'est ce qui se démode.",
      "author": "Jean Cocteau",
      "sourcePage": 7
    },
    {
      "id": 323,
      "text": "C'est dans ce que les hommes ont de plus commun qu'ils se différencient le plus.",
      "author": "Blaise Cendrars",
      "sourcePage": 7
    },
    {
      "id": 324,
      "text": "On passe presque toute sa vie déguisé en adulte.",
      "author": "Monique Corriveau",
      "sourcePage": 7
    },
    {
      "id": 325,
      "text": "S'accrocher au connu, c'est rester prisonnier de l'ignorance.",
      "author": "Yvon Rivard",
      "sourcePage": 7
    },
    {
      "id": 326,
      "text": "Le danger que l'on pressent, mais que l'on ne voit pas, est celui qui trouble le plus.",
      "author": "Jules César",
      "sourcePage": 7
    },
    {
      "id": 327,
      "text": "La seule chose que nous ayons à craindre, c'est que le ciel nous tombe sur la tête !",
      "author": "René Goscinny",
      "sourcePage": 7
    },
    {
      "id": 328,
      "text": "L'humour est l'ombre d'un doute sur les choses.",
      "author": "Roch Carrier",
      "sourcePage": 7
    },
    {
      "id": 329,
      "text": "Dans le vocabulaire des couturiers seulement, patron est synonyme de modèle.",
      "author": "Aymond d'Alost",
      "sourcePage": 7
    },
    {
      "id": 330,
      "text": "Le commencement est la moitié de tout.",
      "author": "Pythagore",
      "sourcePage": 7
    },
    {
      "id": 331,
      "text": "La puissance ne consiste pas à frapper fort ou souvent, mais à frapper juste.",
      "author": "Honoré de Balzac",
      "sourcePage": 7
    },
    {
      "id": 332,
      "text": "Il n'est jamais trop tard pour devenir ce que nous aurions pu être.",
      "author": "George Eliot",
      "sourcePage": 7
    },
    {
      "id": 333,
      "text": "Si tu n'obtiens pas ce que tu veux avec de l'argent, tu peux l'obtenir avec beaucoup d'argent !",
      "author": "Emir Kusturica",
      "sourcePage": 7
    },
    {
      "id": 334,
      "text": "L'important, c'est de savoir ce qu'il faut observer.",
      "author": "Edgar Allen Poe",
      "sourcePage": 7
    },
    {
      "id": 335,
      "text": "Très peu de cause peut avoir beaucoup d'effet.",
      "author": "Bernard Werber",
      "sourcePage": 7
    },
    {
      "id": 336,
      "text": "La joie est dans le risque à faire du neuf.",
      "author": "Marilyn Ferguson",
      "sourcePage": 7
    },
    {
      "id": 337,
      "text": "Beaucoup d'hommes ont une idée derrière la tête. Très loin derrière, presque toujours.",
      "author": "Jacques Sternberg",
      "sourcePage": 7
    },
    {
      "id": 338,
      "text": "La connaissance de l'homme est à la base de tout succès.",
      "author": "Charles Chaplin",
      "sourcePage": 7
    },
    {
      "id": 339,
      "text": "La modestie n'est pas une vertu, seulement de la prudence.",
      "author": "Bernard Shaw",
      "sourcePage": 7
    },
    {
      "id": 340,
      "text": "Il n'y a pas de vérités, pas de mensonges. Tout est une histoire d'opinions.",
      "author": "Terry Giliam",
      "sourcePage": 7
    },
    {
      "id": 341,
      "text": "En bonne arithmétique, un plus un égale tout et deux moins un égale rien.",
      "author": "Ninon de Lenclos",
      "sourcePage": 7
    },
    {
      "id": 342,
      "text": "Il n'y a pas d'amour, il n'y a que des preuves d'amour.",
      "author": "Pierre Reverdy",
      "sourcePage": 7
    },
    {
      "id": 343,
      "text": "Un baiser légal ne vaut jamais un baiser volé.",
      "author": "Guy de Maupassant",
      "sourcePage": 7
    },
    {
      "id": 344,
      "text": "Quand on aime quelqu'un, c'est effrayant comme on pense peu aux autres...",
      "author": "Marcel Pagnol",
      "sourcePage": 7
    },
    {
      "id": 345,
      "text": "Les déclarations d'amour pour toujours ne sont jamais ridicules quand elles s'accompagnent d'émeraudes.",
      "author": "Somerset Maugham",
      "sourcePage": 7
    },
    {
      "id": 346,
      "text": "Aimer, ce n'est pas se regarder l'un l'autre, c'est regarder ensemble dans la même direction.",
      "author": "Antoine de Saint-Exupéry",
      "sourcePage": 7
    },
    {
      "id": 347,
      "text": "La courbe de tes yeux fait le tour de mon cœur.",
      "author": "Paul Eluard",
      "sourcePage": 7
    },
    {
      "id": 348,
      "text": "L'impossible, nous ne l'atteignons pas, mais il nous sert de lanterne.",
      "author": "René Char",
      "sourcePage": 7
    },
    {
      "id": 349,
      "text": "La liberté c'est de ne jamais avoir à dire qu'on est désolé.",
      "author": "Sidney Lumet",
      "sourcePage": 7
    },
    {
      "id": 350,
      "text": "Les folies sont les seules choses qu'on ne regrette jamais.",
      "author": "Oscar Wilde",
      "sourcePage": 7
    },
    {
      "id": 351,
      "text": "Ceux qui emploient mal leur temps sont les premiers à se plaindre de sa brièveté.",
      "author": "Jean de La Bruyère",
      "sourcePage": 7
    },
    {
      "id": 352,
      "text": "Les fautes des autres, c'est toujours réjouissant.",
      "author": "André Gide",
      "sourcePage": 7
    },
    {
      "id": 353,
      "text": "Il faut se lever, se laver, se vêtir et ne plus chanter si l'on n'a plus rien à dire.",
      "author": "Charles Trenet",
      "sourcePage": 7
    },
    {
      "id": 354,
      "text": "Si l'on jugeait les choses sur les apparences, personne n'aurait jamais voulu manger un oursin.",
      "author": "Marcel Pagnol",
      "sourcePage": 7
    },
    {
      "id": 355,
      "text": "Rien ne nous rend aussi grands qu'une paire d'échasses.",
      "author": "Professeur Choron",
      "sourcePage": 7
    },
    {
      "id": 356,
      "text": "Notre pays est la seule nation au monde où il y a autant de problèmes qu'ailleurs.",
      "author": "Bernard Shaw",
      "sourcePage": 7
    },
    {
      "id": 357,
      "text": "Le plus dur, c'est pas d'arriver au sommet, c'est d'y être.",
      "author": "Coluche",
      "sourcePage": 7
    },
    {
      "id": 358,
      "text": "Sur le plan spirituel, toute douleur est une chance ; sur le plan spirituel seulement.",
      "author": "Emil Michel Cioran",
      "sourcePage": 7
    },
    {
      "id": 359,
      "text": "Il est grand temps de rallumer les étoiles.",
      "author": "Guillaume Apollinaire",
      "sourcePage": 7
    },
    {
      "id": 360,
      "text": "Il faut oser ou se résigner à tout.",
      "author": "Tite-Live",
      "sourcePage": 7
    },
    {
      "id": 361,
      "text": "Quand un homme ne parle que de ce qu'il sait, il a toujours l'air plus savant que nous.",
      "author": "Jules Renard",
      "sourcePage": 7
    },
    {
      "id": 362,
      "text": "Il faut creuser les puits aujourd’hui pour étancher les soifs de demain.",
      "author": "Proverbe peul",
      "sourcePage": 7
    },
    {
      "id": 363,
      "text": "Mieux vaut ne penser à rien que ne pas penser du tout.",
      "author": "Serge Gainsbourg",
      "sourcePage": 7
    },
    {
      "id": 364,
      "text": "Une maman formidable donne toujours une grand-mère exceptionnelle.",
      "author": "Jean Gastaldi",
      "sourcePage": 7
    },
    {
      "id": 365,
      "text": "Le beaucoup savoir apporte l'occasion de plus douter.",
      "author": "Montaigne",
      "sourcePage": 7
    },
    {
      "id": 366,
      "text": "J'aime qu'on m'aime comme je m'aime !",
      "author": "Alain Delon",
      "sourcePage": 7
    },
    {
      "id": 367,
      "text": "Rien ne concourt davantage à la paix de l'âme que de n'avoir point d'opinion.",
      "author": "Georg Christoph Lichtenberg",
      "sourcePage": 7
    },
    {
      "id": 368,
      "text": "La femme est tout ce que l'homme appelle et tout ce qu'il n'atteint pas.",
      "author": "Simone de Beauvoir",
      "sourcePage": 7
    },
    {
      "id": 369,
      "text": "Toutes choses sont dites déjà ; mais comme personne n'écoute, il faut toujours recommencer.",
      "author": "André Gide",
      "sourcePage": 7
    },
    {
      "id": 370,
      "text": "Puisque le peuple vote contre le Gouvernement, il faut dissoudre le peuple.",
      "author": "Bertolt Brecht",
      "sourcePage": 8
    },
    {
      "id": 371,
      "text": "La majorité a toujours raison, mais la raison a bien rarement la majorité aux élections.",
      "author": "Jean Mistler",
      "sourcePage": 8
    },
    {
      "id": 372,
      "text": "On ne voit bien qu'avec le cœur. L'essentiel est invisible pour les yeux.",
      "author": "Antoine de Saint-Exupéry",
      "sourcePage": 8
    },
    {
      "id": 373,
      "text": "Agir en primitif et prévoir en stratège.",
      "author": "René Char",
      "sourcePage": 8
    },
    {
      "id": 374,
      "text": "Si les Romains avaient dû d'abord apprendre le latin, ils n'auraient jamais eu le temps de conquérir le monde.",
      "author": "Albert Willemetz",
      "sourcePage": 8
    },
    {
      "id": 375,
      "text": "Il vaut mieux débattre d'une question sans la régler que la régler sans en avoir débattu.",
      "author": "Joseph Joubert",
      "sourcePage": 8
    },
    {
      "id": 376,
      "text": "Certains livres se lisent à la cuisine, d'autres au salon. Un vrai bon livre se lit n'importe où.",
      "author": "Thomas Chandler Haliburton",
      "sourcePage": 8
    },
    {
      "id": 377,
      "text": "Tout le monde voudrait vivre longtemps, mais personne ne voudrait être vieux.",
      "author": "Jonathan Swift",
      "sourcePage": 8
    },
    {
      "id": 378,
      "text": "Il n'y a pas le pouvoir. Il y a l'abus de pouvoir, rien d'autre.",
      "author": "Henry de Montherlant",
      "sourcePage": 8
    },
    {
      "id": 379,
      "text": "Dans la vie il y a des hauts et des bas. Il faut surmonter les hauts et repriser les bas.",
      "author": "Jacques Chirac",
      "sourcePage": 8
    },
    {
      "id": 380,
      "text": "Une erreur ne devient une faute que lorsqu'on ne veut pas en démordre.",
      "author": "Ernst Jünger",
      "sourcePage": 8
    },
    {
      "id": 381,
      "text": "La fantaisie est un perpétuel printemps.",
      "author": "Friedrich von Schiller",
      "sourcePage": 8
    },
    {
      "id": 382,
      "text": "Un idéaliste est une personne qui aide les autres à prospérer.",
      "author": "Henry Ford",
      "sourcePage": 8
    },
    {
      "id": 383,
      "text": "Rien de grand ne s'est accompli dans le monde sans passion.",
      "author": "Friedrich Hegel",
      "sourcePage": 8
    },
    {
      "id": 384,
      "text": "Ce qui est juste peut bien être dit même deux fois.",
      "author": "Empédocle",
      "sourcePage": 8
    },
    {
      "id": 385,
      "text": "Le cinéma est fait pour tous ceux dont la curiosité est le plus grand défaut.",
      "author": "Claude Lelouch",
      "sourcePage": 8
    },
    {
      "id": 386,
      "text": "La poésie c'est le plus joli surnom qu'on donne à la vie.",
      "author": "Jacques Prévert",
      "sourcePage": 8
    },
    {
      "id": 387,
      "text": "Un jour par an, le Mardi gras par exemple, les hommes devraient retirer leur masque des autres jours.",
      "author": "Claude Aveline",
      "sourcePage": 8
    },
    {
      "id": 388,
      "text": "C'est toujours le plus idiot des deux qui s'en prend à l'autre.",
      "author": "Herman Melville",
      "sourcePage": 8
    },
    {
      "id": 389,
      "text": "Il faut demander plus à l'impôt et moins aux contribuables.",
      "author": "Alphonse Allais",
      "sourcePage": 8
    },
    {
      "id": 390,
      "text": "Je me presse de rire de tout, de peur d'être obligé d'en pleurer.",
      "author": "Beaumarchais",
      "sourcePage": 8
    },
    {
      "id": 391,
      "text": "La musique, c'est du bruit qui pense.",
      "author": "Victor Hugo",
      "sourcePage": 8
    },
    {
      "id": 392,
      "text": "Qui voit le ciel dans l'eau voit les poissons dans les arbres.",
      "author": "Proverbe chinois",
      "sourcePage": 8
    },
    {
      "id": 393,
      "text": "Un millionnaire est un milliardaire qui vient de payer ses impôts.",
      "author": "Jean Rigaux",
      "sourcePage": 8
    },
    {
      "id": 394,
      "text": "Ce qu'on ne voit pas, on peut l'ignorer.",
      "author": "Graham Greene",
      "sourcePage": 8
    },
    {
      "id": 395,
      "text": "Je ne fais rien du tout quand je pense tout faire.",
      "author": "Pierre Corneille",
      "sourcePage": 8
    },
    {
      "id": 396,
      "text": "Impose ta chance, serre ton bonheur et va vers ton risque.",
      "author": "René Char",
      "sourcePage": 8
    },
    {
      "id": 397,
      "text": "Il est plus facile de faire sortir le dentifrice du tube que de l'y faire rentrer.",
      "author": "Pierre Dac",
      "sourcePage": 8
    },
    {
      "id": 398,
      "text": "Soyons optimistes : la médecine a découvert beaucoup plus de remèdes qu'il n'y a de maux.",
      "author": "Alfred Capus",
      "sourcePage": 8
    },
    {
      "id": 399,
      "text": "Rien ne sert de courir, il suffit d'arriver.",
      "author": "Henri Dreysse",
      "sourcePage": 8
    },
    {
      "id": 400,
      "text": "Les sages émettent des idées nouvelles, les sots les répandent.",
      "author": "Heinrich Heine",
      "sourcePage": 8
    },
    {
      "id": 401,
      "text": "’On pourrait presque...’ C'est bon, la vie au conditionnel.",
      "author": "Philippe Delerm",
      "sourcePage": 8
    },
    {
      "id": 402,
      "text": "On ne va jamais si loin que lorsque l'on ne sait pas où l'on va.",
      "author": "Oliver Cromwell",
      "sourcePage": 8
    },
    {
      "id": 403,
      "text": "Dieu n'existe pas, je ne l'ai pas rencontré.",
      "author": "Iouri Gagarine",
      "sourcePage": 8
    },
    {
      "id": 404,
      "text": "La psychanalyse est un remède contre l'ignorance. Elle est sans effet sur la connerie.",
      "author": "Jacques Lacan",
      "sourcePage": 8
    },
    {
      "id": 405,
      "text": "Où se posaient les hirondelles avant l'invention du téléphone ?",
      "author": "Grégoire Lacroix",
      "sourcePage": 8
    },
    {
      "id": 406,
      "text": "La force c'est de pouvoir casser une barre de chocolat en quatre et de n'en manger qu'un carré.",
      "author": "Judith Viorst",
      "sourcePage": 8
    },
    {
      "id": 407,
      "text": "Pour être le meilleur, il suffit parfois que les autres soient moins bons.",
      "author": "Philippe Geluck",
      "sourcePage": 8
    },
    {
      "id": 408,
      "text": "Je ne connais absolument rien à la musique. Pour ce que je fais, je n'en ai pas besoin !",
      "author": "Elvis Presley",
      "sourcePage": 8
    },
    {
      "id": 409,
      "text": "Nous sommes tous dans le caniveau, mais certains d'entre nous regardent les étoiles.",
      "author": "Oscar Wilde",
      "sourcePage": 8
    },
    {
      "id": 410,
      "text": "L'inefficacité des patrons est bien souvent camouflée par l'efficacité des employés.",
      "author": "Yvon Deveault",
      "sourcePage": 8
    },
    {
      "id": 411,
      "text": "Il y a des gens sur qui on peut compter. Ce sont généralement des gens dont on n'a pas besoin.",
      "author": "Sacha Guitry",
      "sourcePage": 8
    },
    {
      "id": 412,
      "text": "L'interminable est la spécialité des indécis.",
      "author": "Emil Michel Cioran",
      "sourcePage": 8
    },
    {
      "id": 413,
      "text": "Que serait la vie sans l'imparfait du subjonctif... ?",
      "author": "Alexandre Vialatte",
      "sourcePage": 8
    },
    {
      "id": 414,
      "text": "Le temps de la réflexion est une économie de temps.",
      "author": "Publius Syrus",
      "sourcePage": 8
    },
    {
      "id": 415,
      "text": "Le monde aurait pu être simple comme le ciel et la mer.",
      "author": "André Malraux",
      "sourcePage": 8
    },
    {
      "id": 416,
      "text": "Si cela va sans dire, ça ira encore mieux en le disant.",
      "author": "Talleyrand",
      "sourcePage": 8
    },
    {
      "id": 417,
      "text": "L'activité fait plus de fortunes que la prudence.",
      "author": "Vauvenargues",
      "sourcePage": 8
    },
    {
      "id": 418,
      "text": "Un sot ne dit pas de choses intelligentes, mais un homme intelligent dit beaucoup de bêtises.",
      "author": "Garabet Ibraileanu",
      "sourcePage": 8
    },
    {
      "id": 419,
      "text": "Le meilleur moyen pour ralentir un cheval est de parier sur lui.",
      "author": "Loi de Murphy",
      "sourcePage": 9
    },
    {
      "id": 420,
      "text": "Que le soleil se lèvera demain est une hypothèse.",
      "author": "Ludwig Wittgenstein",
      "sourcePage": 9
    },
    {
      "id": 421,
      "text": "Ne remets pas à demain ce que tu peux faire après-demain.",
      "author": "Alphonse Allais",
      "sourcePage": 9
    },
    {
      "id": 422,
      "text": "Le travail c'est la santé ; ne rien faire, c'est la conserver.",
      "author": "Henri Salvador",
      "sourcePage": 9
    },
    {
      "id": 423,
      "text": "Chaque année, la nature nous offre le mois de mai pour se faire pardonner février.",
      "author": "Bill Tammeus",
      "sourcePage": 9
    },
    {
      "id": 424,
      "text": "La liberté de la presse présente des inconvénients. Mais moins que l'absence de liberté.",
      "author": "Francois Mitterrand",
      "sourcePage": 9
    },
    {
      "id": 425,
      "text": "Il y a bien moins de difficulté à résoudre un problème qu'à le poser.",
      "author": "Joseph de Maistre",
      "sourcePage": 9
    },
    {
      "id": 426,
      "text": "Avant de changer d'idée, s'assurer qu'on en a déjà une.",
      "author": "Albert Brie",
      "sourcePage": 9
    },
    {
      "id": 427,
      "text": "Visez toujours la lune. Même si vous ratez, vous atterrirez parmi les étoiles.",
      "author": "Les Brown",
      "sourcePage": 9
    },
    {
      "id": 428,
      "text": "Faire du théâtre, l'unique manière de ne pas s'y ennuyer.",
      "author": "Roland Topor",
      "sourcePage": 9
    },
    {
      "id": 429,
      "text": "Combattre pour la paix, il parait que c'est de bonne guerre.",
      "author": "Roland Bacri",
      "sourcePage": 9
    },
    {
      "id": 430,
      "text": "Cannes, c'est d'abord un escalier : un escalier facile à monter... difficile à descendre.",
      "author": "Claude Lelouch",
      "sourcePage": 9
    },
    {
      "id": 431,
      "text": "L'imagination n'est fertile que lorsqu'elle est futile.",
      "author": "Vladimir Nabokov",
      "sourcePage": 9
    },
    {
      "id": 432,
      "text": "Essayer, c'est le meilleur moyen de se planter...",
      "author": "Homer Simpson",
      "sourcePage": 9
    },
    {
      "id": 433,
      "text": "Un petit chez soi vaut mieux qu'un grand chez les autres.",
      "author": "Proverbe français",
      "sourcePage": 9
    },
    {
      "id": 434,
      "text": "Je suis inculte parce que je n'en pratique aucun, et insecte parce que je me méfie de toutes.",
      "author": "Raymond Queneau",
      "sourcePage": 9
    },
    {
      "id": 435,
      "text": "L'hésitation est source de complications.",
      "author": "John Grisham",
      "sourcePage": 9
    },
    {
      "id": 436,
      "text": "Il vaut mieux prêter à sourire que donner à réfléchir.",
      "author": "Les Nuls",
      "sourcePage": 9
    },
    {
      "id": 437,
      "text": "L'euro a été inventé pour rendre le salaire des riches six fois moins indécent.",
      "author": "Frédéric Beigbeder",
      "sourcePage": 9
    },
    {
      "id": 438,
      "text": "Une petite inexactitude économise parfois une tonne d'explications.",
      "author": "Hecto Hugh Munro",
      "sourcePage": 9
    },
    {
      "id": 439,
      "text": "Tout avantage a ses inconvénients et réciproquement.",
      "author": "Les shadoks",
      "sourcePage": 9
    },
    {
      "id": 440,
      "text": "Le jour où vos chiffres sortiront au loto, ce sera la seule fois où vous ne les aurez pas joués.",
      "author": "Loi de Murphy",
      "sourcePage": 9
    },
    {
      "id": 441,
      "text": "Dans chaque Français, il y a deux hommes : celui qui ne veut pas d'histoires et celui qui a de grandes idées.",
      "author": "Georges Wolinski",
      "sourcePage": 9
    },
    {
      "id": 442,
      "text": "A quoi sert Internet. A part à aller sur Internet...",
      "author": "Jacob Berger",
      "sourcePage": 9
    },
    {
      "id": 443,
      "text": "Ce n'est pas parce qu'il y a un trou qu'il y a un écureuil dedans.",
      "author": "Proverbe américain",
      "sourcePage": 9
    },
    {
      "id": 444,
      "text": "Le problème avec la vie, c'est que l'on ne sait vraiment pas du tout ce qui se passe.",
      "author": "Philip Roth",
      "sourcePage": 9
    },
    {
      "id": 445,
      "text": "Si Dieu n'existait pas, il faudrait l'inventer.",
      "author": "Voltaire",
      "sourcePage": 9
    },
    {
      "id": 446,
      "text": "Le cinéma, c'est l'écriture moderne dont l'encre est la lumière.",
      "author": "Jean Cocteau",
      "sourcePage": 9
    },
    {
      "id": 447,
      "text": "L'ennui, c'est que nous négligeons le football au profit de l'éducation.",
      "author": "Groucho Marx",
      "sourcePage": 9
    },
    {
      "id": 448,
      "text": "On n'est jamais si bien servi que par sa mère.",
      "author": "Jacques Pater",
      "sourcePage": 9
    },
    {
      "id": 449,
      "text": "Tant qu'il reste un homme en prison, je ne suis pas libre.",
      "author": "Eugene Debs",
      "sourcePage": 9
    },
    {
      "id": 450,
      "text": "Le tennis c'est comme le ping-pong, sauf qu'au tennis, les joueurs sont debout sur la table.",
      "author": "Coluche",
      "sourcePage": 9
    },
    {
      "id": 451,
      "text": "J'ai décidé d'affronter la réalité, alors des qu'elle se présente bien, prévenez-moi.",
      "author": "Quino",
      "sourcePage": 9
    },
    {
      "id": 452,
      "text": "Vous avez parfaitement le droit de dire à un fumeur qu'il fume trop s'il fume votre tabac.",
      "author": "Sacha Guitry",
      "sourcePage": 9
    },
    {
      "id": 453,
      "text": "Un rayon de soleil vaut tous les livres du monde.",
      "author": "Christian Bobin",
      "sourcePage": 9
    },
    {
      "id": 454,
      "text": "Dieu n'existe pas, mais il faut faire semblant d'y croire. Cela Lui fait tellement plaisir...",
      "author": "Philippe Bouvard",
      "sourcePage": 9
    },
    {
      "id": 455,
      "text": "Le pessimisme est d'humeur ; l'optimisme est de volonté.",
      "author": "Alain",
      "sourcePage": 9
    },
    {
      "id": 456,
      "text": "Celui qui dit qu'il est arrivé, c'est qu'il n'est pas allé bien loin.",
      "author": "Jean Carmet",
      "sourcePage": 9
    },
    {
      "id": 457,
      "text": "Nous n'héritons pas de la terre de nos parents, nous l'empruntons à nos enfants.",
      "author": "Léopold Sedar Senghor",
      "sourcePage": 9
    },
    {
      "id": 458,
      "text": "Dans la vie, il faut choisir : être riche ou bachelier.",
      "author": "San-Antonio",
      "sourcePage": 9
    },
    {
      "id": 459,
      "text": "Ce que beurre et whisky ne peuvent soigner est incurable.",
      "author": "Proverbe irlandais",
      "sourcePage": 9
    },
    {
      "id": 460,
      "text": "Il y a des fleurs partout pour qui veut bien les voir.",
      "author": "Henri Matisse",
      "sourcePage": 9
    },
    {
      "id": 461,
      "text": "Apres 40 ans une femme doit choisir entre sa silhouette et son visage. Choisissez le visage et restez assise !",
      "author": "Barbara Cartland",
      "sourcePage": 9
    },
    {
      "id": 462,
      "text": "Si on n'est pas prêt à tout, on n'est prêt à rien.",
      "author": "Paul Auster",
      "sourcePage": 9
    },
    {
      "id": 463,
      "text": "Etudiants, étudiantes, ne vous présentez plus au bac : prenez le Pont de Tancarville !",
      "author": "Francis Blanche",
      "sourcePage": 9
    },
    {
      "id": 464,
      "text": "La grande supériorité de l'examinateur est de se trouver du bon côté de la table.",
      "author": "Edouard Herriot",
      "sourcePage": 9
    },
    {
      "id": 465,
      "text": "Comment le temps fait-il pour tourner rond dans des horloges carrées ?",
      "author": "Quino",
      "sourcePage": 9
    },
    {
      "id": 466,
      "text": "Le problème avec le sens de l'humour, c'est la facilité avec laquelle chacun prétend en être pourvu.",
      "author": "Alain de Botton",
      "sourcePage": 9
    },
    {
      "id": 467,
      "text": "Je n'ai jamais rien appris d'une personne qui était d'accord avec moi.",
      "author": "Dudley Field Malone",
      "sourcePage": 9
    },
    {
      "id": 468,
      "text": "Si j'étais né avant mon père, j'aurais pu être le sien.",
      "author": "Louis Auguste Commerson",
      "sourcePage": 9
    },
    {
      "id": 469,
      "text": "L'exemple, c'est tout ce qu'un père peut faire pour ses enfants.",
      "author": "Thomas Mann",
      "sourcePage": 10
    },
    {
      "id": 470,
      "text": "Le 17 juin 1940, personne ne savait qu'un nomme Charles de Gaulle parlerait le 18.",
      "author": "Alexandre Sanguinetti",
      "sourcePage": 10
    },
    {
      "id": 471,
      "text": "Si vous avez besoin de quelque chose, appelez-moi. Je vous dirai comment vous en passer.",
      "author": "Coluche",
      "sourcePage": 10
    },
    {
      "id": 472,
      "text": "Ne craignez pas d'être lent, craignez seulement d'être à l'arrêt.",
      "author": "Proverbe chinois",
      "sourcePage": 10
    },
    {
      "id": 473,
      "text": "La fête de la musique est une grande réussite puisqu'elle garantit trois cent soixante-quatre jours de silence par an.",
      "author": "Philippe Bouvard",
      "sourcePage": 10
    },
    {
      "id": 474,
      "text": "Je vais bien. Et si tout le monde allait aussi bien que moi, j'irais beaucoup mieux.",
      "author": "Guy Bedos",
      "sourcePage": 10
    },
    {
      "id": 475,
      "text": "Observer attentivement, c'est se rappeler distinctement.",
      "author": "Edgar Allen Poe",
      "sourcePage": 10
    },
    {
      "id": 476,
      "text": "Je plains ceux qui ont l'air intelligent ; c'est une promesse qu'on ne peut tenir.",
      "author": "Alain",
      "sourcePage": 10
    },
    {
      "id": 477,
      "text": "La meilleure façon de prédire l'avenir, c'est de le créer.",
      "author": "Peter Drucker",
      "sourcePage": 10
    },
    {
      "id": 478,
      "text": "Cannabis : parmi ceux qui n'ont jamais commencé, il n'y en a aucun qui a continué.",
      "author": "Gérard Miller",
      "sourcePage": 10
    },
    {
      "id": 479,
      "text": "Pourquoi appelle-t-on une chanson à succès un \"tube\" ? Sans doute parce qu'il est creux.",
      "author": "André Birabeau",
      "sourcePage": 10
    },
    {
      "id": 480,
      "text": "La vacance des grandes valeurs n'enlève rien à la valeur des grandes vacances.",
      "author": "Henri Weber",
      "sourcePage": 10
    },
    {
      "id": 481,
      "text": "Il en est de la culture à la télévision comme des habitants des villes : rejetée à la périphérie.",
      "author": "Bernard Pivot",
      "sourcePage": 10
    },
    {
      "id": 482,
      "text": "Les pensées qui nous viennent valent mieux que celles que nous trouvons.",
      "author": "Joseph Joubert",
      "sourcePage": 10
    },
    {
      "id": 483,
      "text": "Quand on va au cinéma, on lève la tête. Quand on regarde la télévision, on la baisse.",
      "author": "Jean-Luc Godard",
      "sourcePage": 10
    },
    {
      "id": 484,
      "text": "Un homme, ça peut-être détruit, mais pas vaincu.",
      "author": "Ernest Hemingway",
      "sourcePage": 10
    },
    {
      "id": 485,
      "text": "Celui qui contrôle les médias contrôle les esprits.",
      "author": "Jim Morrison",
      "sourcePage": 10
    },
    {
      "id": 486,
      "text": "Si ma chaussure est étroite, que m'importe que le monde soit vaste.",
      "author": "Proverbe turc",
      "sourcePage": 10
    },
    {
      "id": 487,
      "text": "Un jour où l'on est très satisfait de soi est un jour où l'on n'a pas été paresseux.",
      "author": "Margaret Thatcher",
      "sourcePage": 10
    },
    {
      "id": 488,
      "text": "Le théâtre c'est la poésie qui sort du livre pour descendre dans la rue.",
      "author": "Federico Garcia Lorca",
      "sourcePage": 10
    },
    {
      "id": 489,
      "text": "Seul un imbécile s'attend à être toujours heureux.",
      "author": "Robertson Davies",
      "sourcePage": 10
    },
    {
      "id": 490,
      "text": "Sans l'invention de la roue, les coureurs du Tour de France seraient condamnés à porter leur bicyclette sur le dos.",
      "author": "Pierre Dac",
      "sourcePage": 10
    },
    {
      "id": 491,
      "text": "Connais-toi toi-même et n'en dis rien à personne.",
      "author": "Franklin Jones",
      "sourcePage": 10
    },
    {
      "id": 492,
      "text": "Il faut vivre comme l'on pense, autrement l'on finit par penser comme l'on vit !",
      "author": "Paul Bourget",
      "sourcePage": 10
    },
    {
      "id": 493,
      "text": "Vaincre sans péril est peut-être la seule chance de triompher sans péril.",
      "author": "Gilbert Cesbron",
      "sourcePage": 10
    },
    {
      "id": 494,
      "text": "Quand tout est fichu, il y a encore le courage.",
      "author": "Daniel Pennac",
      "sourcePage": 10
    },
    {
      "id": 495,
      "text": "Il est exact que ça porte malheur de se marier un vendredi 13, car il n'y a pas de raison pour que ce jour fasse exception.",
      "author": "Georges Courteline",
      "sourcePage": 10
    },
    {
      "id": 496,
      "text": "Personne n'a jamais vu un 14 juillet raté. Sauf le premier, naturellement...",
      "author": "Claire Gallois",
      "sourcePage": 10
    },
    {
      "id": 497,
      "text": "De temps en temps, il faut se reposer de ne rien faire.",
      "author": "Jean Cocteau",
      "sourcePage": 10
    },
    {
      "id": 498,
      "text": "Se donner du mal pour les petites choses, c'est parvenir aux grandes, avec le temps.",
      "author": "Samuel Beckett",
      "sourcePage": 10
    },
    {
      "id": 499,
      "text": "On résiste à l'invasion des armées, on ne résiste pas à l'invasion des idées.",
      "author": "Victor Hugo",
      "sourcePage": 10
    },
    {
      "id": 500,
      "text": "Le parfait est ce qui n'est plus à refaire...",
      "author": "André Gide",
      "sourcePage": 10
    },
    {
      "id": 501,
      "text": "Là où tant d'hommes ont échoue, une femme peut réussir.",
      "author": "Talleyrand",
      "sourcePage": 10
    },
    {
      "id": 502,
      "text": "Rien ne contribue davantage à la sérénité de l'âme que de n'avoir aucune opinion.",
      "author": "Georg Christoph Lichtenberg",
      "sourcePage": 10
    },
    {
      "id": 503,
      "text": "Chassez le naturiste, il revient au bungalow.",
      "author": "Jean-Paul Grousset",
      "sourcePage": 10
    },
    {
      "id": 504,
      "text": "Le bonheur, c'est avoir une bonne santé et une mauvaise mémoire.",
      "author": "Ingrid Bergman",
      "sourcePage": 10
    },
    {
      "id": 505,
      "text": "C'est déjà bien ennuyeux de ne pas avoir d'argent ; s'il fallait encore s'en priver.",
      "author": "Paul Morand",
      "sourcePage": 10
    },
    {
      "id": 506,
      "text": "Les idées, c'est comme les gosses. Il ne suffit pas de les avoir, il faut les élever.",
      "author": "Daniel Picouly",
      "sourcePage": 10
    },
    {
      "id": 507,
      "text": "Trop de repos n'a jamais fait mourir personne.",
      "author": "Tristan Bernard",
      "sourcePage": 10
    },
    {
      "id": 508,
      "text": "En Provence, le soleil se lève deux fois, le matin et après la sieste.",
      "author": "Yvan Audouard",
      "sourcePage": 10
    },
    {
      "id": 509,
      "text": "Si Noé avait vraiment été un sage, il aurait tapé sur ces deux mouches.",
      "author": "Helen Castle",
      "sourcePage": 10
    },
    {
      "id": 510,
      "text": "Quand la prudence est partout, le courage n'est nulle part.",
      "author": "Cardinal Mercier",
      "sourcePage": 10
    },
    {
      "id": 511,
      "text": "Sur la route, j'ai deux grands principes : prudence, prudence.",
      "author": "Philippe Geluck",
      "sourcePage": 10
    },
    {
      "id": 512,
      "text": "Tout corps plongé dans un liquide éprouve une bonne satisfaction.",
      "author": "Maurice Fombeure",
      "sourcePage": 10
    },
    {
      "id": 513,
      "text": "Peindre n'est pas teindre.",
      "author": "Jean Dubuffet",
      "sourcePage": 10
    },
    {
      "id": 514,
      "text": "Tout bonheur commence par un petit-déjeuner tranquille.",
      "author": "Somerset Maugham",
      "sourcePage": 10
    },
    {
      "id": 515,
      "text": "Voici l'été, épousez une femme ombrageuse !",
      "author": "Jules Jouy",
      "sourcePage": 10
    },
    {
      "id": 516,
      "text": "Que les sportifs arrêtent le doping... On aura l'air malin devant nos téléviseurs en attendant qu'ils battent les records.",
      "author": "Coluche",
      "sourcePage": 10
    },
    {
      "id": 517,
      "text": "Le rang ne confère ni privilège, ni pouvoir. Il impose des responsabilités.",
      "author": "Louis Armstrong",
      "sourcePage": 10
    },
    {
      "id": 518,
      "text": "On peut toujours faire quelque chose avec ce qu'on a, mais pas forcement ce qu'on veut...",
      "author": "Julien Lorcy",
      "sourcePage": 11
    },
    {
      "id": 519,
      "text": "Personne n'est plus redoutable que celui qui n'a jamais de doutes.",
      "author": "Jacques Sternberg",
      "sourcePage": 11
    },
    {
      "id": 520,
      "text": "Certaines questions ne sont difficiles que parce qu'on les pose.",
      "author": "André Frossard",
      "sourcePage": 11
    },
    {
      "id": 521,
      "text": "Le secret d'une culture intelligente, c'est de savoir sur quel rayon de la bibliothèque se tient le Larousse.",
      "author": "Sacha Guitry",
      "sourcePage": 11
    },
    {
      "id": 522,
      "text": "Je ne suis pas allé partout, mais je suis revenu de tout.",
      "author": "Coluche",
      "sourcePage": 11
    },
    {
      "id": 523,
      "text": "Il faut de l'esprit pour bien parler, de l'intelligence suffit pour bien écouter.",
      "author": "André Gide",
      "sourcePage": 11
    },
    {
      "id": 524,
      "text": "La santé, c'est ce qui sert à ne pas mourir chaque fois qu'on est gravement malade.",
      "author": "Georges Perros",
      "sourcePage": 11
    },
    {
      "id": 525,
      "text": "Il vaut mieux gâcher sa jeunesse que de n'en rien faire du tout.",
      "author": "Georges Courteline",
      "sourcePage": 11
    },
    {
      "id": 526,
      "text": "La vie, c'est ce qui arrive quand on a d'autres projets.",
      "author": "John Lennon",
      "sourcePage": 11
    },
    {
      "id": 527,
      "text": "Quand on ne sait rien faire, il faut avoir de l'ambition.",
      "author": "Georges Wolinski",
      "sourcePage": 11
    },
    {
      "id": 528,
      "text": "On atteint plus vite le ciel en partant d'une chaumière que d'un palais.",
      "author": "Saint François d'Assise",
      "sourcePage": 11
    },
    {
      "id": 529,
      "text": "A partir de quarante ans, tant vaut l'homme, tant vaut l'acteur.",
      "author": "Louis Jouvet",
      "sourcePage": 11
    },
    {
      "id": 530,
      "text": "Il est bon de n'avoir pas de vices et mauvais de n'avoir pas de tentations.",
      "author": "Walter Bagehot",
      "sourcePage": 11
    },
    {
      "id": 531,
      "text": "La liberté est le meilleur des aphrodisiaques.",
      "author": "Bjork",
      "sourcePage": 11
    },
    {
      "id": 532,
      "text": "Il y a des bêtises que j'ai faites, uniquement pour avoir le plaisir de les raconter.",
      "author": "Sacha Guitry",
      "sourcePage": 11
    },
    {
      "id": 533,
      "text": "La conscience, comme l'appendice, ne sert à rien, sauf à rendre l'homme malade.",
      "author": "Alexandre Vialatte",
      "sourcePage": 11
    },
    {
      "id": 534,
      "text": "Le fait que j'existe prouve que le monde n'a pas de sens.",
      "author": "Emil Michel Cioran",
      "sourcePage": 11
    },
    {
      "id": 535,
      "text": "Les jours sont peut-être égaux pour une horloge, mais pas pour un homme.",
      "author": "Marcel Proust",
      "sourcePage": 11
    },
    {
      "id": 536,
      "text": "Le passé m'effraie, l'avenir me fait peur. Heureusement qu'il y a le présent.",
      "author": "Philippe Geluck",
      "sourcePage": 11
    },
    {
      "id": 537,
      "text": "On ne peut poser les pieds sur le sol tant qu'on a pas touché le ciel.",
      "author": "Paul Auster",
      "sourcePage": 11
    },
    {
      "id": 538,
      "text": "Il faut garder quelques sourires pour se moquer des jours sans joie.",
      "author": "Charles Trenet",
      "sourcePage": 11
    },
    {
      "id": 539,
      "text": "Un oignon suffit à faire pleurer les gens, mais on n'a pas encore inventé le légume qui les ferait rire.",
      "author": "Will Rogers",
      "sourcePage": 11
    },
    {
      "id": 540,
      "text": "Soyez indulgents pour les autres et sévères pour vous.",
      "author": "Adam Mickiewicz",
      "sourcePage": 11
    },
    {
      "id": 541,
      "text": "Seule la chaussure sait si la chaussette a des trous.",
      "author": "Proverbe créole",
      "sourcePage": 11
    },
    {
      "id": 542,
      "text": "Bienheureux celui qui a appris à rire de lui-même : il n'a pas fini de s'amuser !",
      "author": "Joseph Folliet",
      "sourcePage": 11
    },
    {
      "id": 543,
      "text": "Ce qui va de soi c'est ce qui va mal.",
      "author": "Alain",
      "sourcePage": 11
    },
    {
      "id": 544,
      "text": "Mieux vaut être optimiste et se tromper que pessimiste et avoir raison.",
      "author": "Jack Penn",
      "sourcePage": 11
    },
    {
      "id": 545,
      "text": "L'intelligence artificielle se définit comme le contraire de la bêtise naturelle.",
      "author": "Woody Allen",
      "sourcePage": 11
    },
    {
      "id": 546,
      "text": "Il ne suffit pas de parler, il faut parler juste.",
      "author": "William Shakespeare",
      "sourcePage": 11
    },
    {
      "id": 547,
      "text": "N'abusons de rien, sauf de la modération.",
      "author": "Jean Dion",
      "sourcePage": 11
    },
    {
      "id": 548,
      "text": "A une juste guerre, préférons une injuste paix !",
      "author": "Samuel Butler",
      "sourcePage": 11
    },
    {
      "id": 549,
      "text": "Ne vous dérangez pas, le temps ne fait que passer.",
      "author": "Vassilis Alexakis",
      "sourcePage": 11
    },
    {
      "id": 550,
      "text": "La seule véritable erreur est celle dont on ne retire aucun enseignement.",
      "author": "John Powell",
      "sourcePage": 11
    },
    {
      "id": 551,
      "text": "Il n'y a point de génie sans un grain de folie.",
      "author": "Aristote",
      "sourcePage": 11
    },
    {
      "id": 552,
      "text": "Que de temps perdu à gagner du temps !",
      "author": "Paul Morand",
      "sourcePage": 11
    },
    {
      "id": 553,
      "text": "A chaque sommet on est toujours au bord d'un précipice.",
      "author": "Stanislaw Jerzy Lec",
      "sourcePage": 11
    },
    {
      "id": 554,
      "text": "Le plus beau sommeil ne vaut pas le moment où l'on se réveille.",
      "author": "André Gide",
      "sourcePage": 11
    },
    {
      "id": 555,
      "text": "Pourquoi payer ses impôts sur le revenu ? Il vaut mieux attendre qu'ils repartent.",
      "author": "Pierre Dac",
      "sourcePage": 11
    },
    {
      "id": 556,
      "text": "Le mal de la télévision, ce n'est pas dans la télévision qu'il est, c'est dans le monde.",
      "author": "Christian Bobin",
      "sourcePage": 11
    },
    {
      "id": 557,
      "text": "Mourir pour ses idées ne prouve pas qu'elles soient bonnes.",
      "author": "Yvan Audouard",
      "sourcePage": 11
    },
    {
      "id": 558,
      "text": "Dieu ne pouvait être partout, alors il a créé la mère.",
      "author": "Proverbe juif",
      "sourcePage": 11
    },
    {
      "id": 559,
      "text": "Une explication, qu'elle qu'elle soit, ne peut être qu'en trop face à la présence des choses.",
      "author": "Alain Robbe-Grillet",
      "sourcePage": 11
    },
    {
      "id": 560,
      "text": "Je n'ai pas les moyens de perdre mon temps à gagner de l'argent.",
      "author": "Louis Agassiz",
      "sourcePage": 11
    },
    {
      "id": 561,
      "text": "L'automne est le printemps de l'hiver.",
      "author": "Henri de Toulouse-Lautrec",
      "sourcePage": 11
    },
    {
      "id": 562,
      "text": "On jugerait bien plus sûrement un homme d'après ce qu'il rêve que d'après ce qu'il pense.",
      "author": "Victor Hugo",
      "sourcePage": 11
    },
    {
      "id": 563,
      "text": "Découvrir consiste à voir comme tout le monde et à réfléchir comme personne.",
      "author": "Albert Szent Gyorgyi",
      "sourcePage": 11
    },
    {
      "id": 564,
      "text": "Tout s'arrangerait parfaitement bien si l'on pouvait faire les choses deux fois.",
      "author": "Goethe",
      "sourcePage": 11
    },
    {
      "id": 565,
      "text": "Pourquoi jouer tant de notes alors qu'il suffit de jouer les meilleures ?",
      "author": "Miles Davis",
      "sourcePage": 11
    },
    {
      "id": 566,
      "text": "Si vous ne pouvez les convaincre, semez le doute dans leur esprit.",
      "author": "Harry Truman",
      "sourcePage": 11
    },
    {
      "id": 567,
      "text": "Il n'y a pas de plus grand cœur au monde que le cœur qui pardonne.",
      "author": "Benoît Lacroix",
      "sourcePage": 11
    },
    {
      "id": 568,
      "text": "Rien ne sert de penser, il faut réfléchir avant.",
      "author": "Pierre Dac",
      "sourcePage": 11
    },
    {
      "id": 569,
      "text": "Dieu a créé la mer et il l'a peinte en bleu pour qu'on soit bien dessus.",
      "author": "Bernard Moitessier",
      "sourcePage": 11
    },
    {
      "id": 570,
      "text": "Vivre sans lecture c'est dangereux, il faut se contenter de la vie, ça peut amener à prendre des risques.",
      "author": "Michel Houellebecq",
      "sourcePage": 12
    },
    {
      "id": 571,
      "text": "Découvrir consiste à voir comme tout le monde et à réfléchir comme personne.",
      "author": "Albert Szent Gyorgyi",
      "sourcePage": 12
    },
    {
      "id": 572,
      "text": "La planète fourmille de criminels qui fuient leur châtiment.",
      "author": "Amélie Nothomb - Cosmétique de l'ennemi",
      "sourcePage": 12
    },
    {
      "id": 573,
      "text": "Pour voir loin, il faut y regarder de près.",
      "author": "Pierre Dac",
      "sourcePage": 12
    },
    {
      "id": 574,
      "text": "Nul n'ira jusqu'au fond du rire d'un enfant.",
      "author": "Victor Hugo",
      "sourcePage": 12
    },
    {
      "id": 575,
      "text": "Il y a de l'esprit ailleurs que dans la pensée des hommes.",
      "author": "Jean d'Ormesson - Voyez comme on danse",
      "sourcePage": 12
    },
    {
      "id": 576,
      "text": "Paresse : habitude prise de se reposer avant la fatigue.",
      "author": "Jules Renard",
      "sourcePage": 12
    },
    {
      "id": 577,
      "text": "L'intelligence est presque inutile à celui qui ne possède qu'elle.",
      "author": "Alexis Carrel - Prix Nobel de Médecine 1912",
      "sourcePage": 12
    },
    {
      "id": 578,
      "text": "Il est plus difficile de désagréger un préjugé qu'un atome.",
      "author": "Albert Einstein",
      "sourcePage": 12
    },
    {
      "id": 579,
      "text": "On travaille pour épater, ou bien on se répète.",
      "author": "Alberto Giacometti",
      "sourcePage": 12
    },
    {
      "id": 580,
      "text": "La violence est injuste d'où qu'elle vienne.",
      "author": "Jean-Paul Sartre",
      "sourcePage": 12
    },
    {
      "id": 581,
      "text": "Ceux qui ne connaissent pas leur histoire s'exposent à ce qu'elle recommence...",
      "author": "Elie Wiesel - Prix Nobel de la Paix 1986",
      "sourcePage": 12
    },
    {
      "id": 582,
      "text": "Il ne peut pas y avoir de crise la semaine prochaine : mon agenda est déjà plein.",
      "author": "Henry Kissinger",
      "sourcePage": 12
    },
    {
      "id": 583,
      "text": "Dans le passé, il y avait plus de futur que maintenant.",
      "author": "Philippe Geluck",
      "sourcePage": 12
    },
    {
      "id": 584,
      "text": "La vie est comme le chocolat, c'est l'amer qui fait apprécier le sucre.",
      "author": "Xavier Brebion",
      "sourcePage": 12
    },
    {
      "id": 585,
      "text": "Le plus beau cadeau que puisse offrir une femme à un homme, c'est la tranquillité.",
      "author": "Helen Fielding",
      "sourcePage": 12
    },
    {
      "id": 586,
      "text": "Rien au monde, après l'espérance, n'est plus trompeur que l'apparence.",
      "author": "Charles Perrault",
      "sourcePage": 12
    },
    {
      "id": 587,
      "text": "Toute opinion est transitoire et toute œuvre est permanente.",
      "author": "Man Ray",
      "sourcePage": 12
    },
    {
      "id": 588,
      "text": "Il semble que le goût des livres croisse avec l'intelligence.",
      "author": "Marcel Proust",
      "sourcePage": 12
    },
    {
      "id": 589,
      "text": "L'art de lire, c'est l'art de penser avec un peu d'aide.",
      "author": "Emile Faguet",
      "sourcePage": 12
    },
    {
      "id": 590,
      "text": "Tout bon livre doit savoir provoquer l'attente : lire, c'est attendre la suite !",
      "author": "Frédéric Beigbeder",
      "sourcePage": 12
    },
    {
      "id": 591,
      "text": "L'informatique est géniale : les e-mails, même si vous n'y répondez pas, ça ne prend pas de place.",
      "author": "Alain Remond",
      "sourcePage": 12
    },
    {
      "id": 592,
      "text": "L'Histoire est une interaction de peuples divers, il n'en a jamais été autrement.",
      "author": "V. S. Naipaul - Nobel de littérature 2001",
      "sourcePage": 12
    },
    {
      "id": 593,
      "text": "Le monde se définit non seulement par ce 'pour quoi', mais aussi par ce 'contre quoi' et 'contre qui' il agit.",
      "author": "Kofi Annan - Prix Nobel de la Paix 2001",
      "sourcePage": 12
    },
    {
      "id": 594,
      "text": "Lire et être curieux, c'est la même chose.",
      "author": "Pascal Quignard",
      "sourcePage": 12
    },
    {
      "id": 595,
      "text": "Le seul mauvais choix est l'absence de choix.",
      "author": "Amélie Nothomb",
      "sourcePage": 12
    },
    {
      "id": 596,
      "text": "La télévision n'est pas faite pour être regardée mais pour qu'on y passe.",
      "author": "Noël Coward",
      "sourcePage": 12
    },
    {
      "id": 597,
      "text": "Vienne la nuit sonne l'heure - les jours s'en vont je demeure.",
      "author": "Guillaume Apollinaire - Le Pont Mirabeau",
      "sourcePage": 12
    },
    {
      "id": 598,
      "text": "Pour reconnaître que l'on n'est pas intelligent, il faudrait l'être.",
      "author": "Georges Brassens",
      "sourcePage": 12
    },
    {
      "id": 599,
      "text": "On s'étonne trop de ce qu'on voit rarement et pas assez de ce qu'on voit tous les jours.",
      "author": "Madame de Genlis",
      "sourcePage": 12
    },
    {
      "id": 600,
      "text": "Il y a le peureux qui regarde sous son lit, et le peureux qui n'ose même pas regarder sous son lit.",
      "author": "Jules Renard",
      "sourcePage": 12
    },
    {
      "id": 601,
      "text": "Notre existence se trouve entre deux éternités.",
      "author": "Timée",
      "sourcePage": 12
    },
    {
      "id": 602,
      "text": "Quand on ne travaillera plus les lendemains des jours de repos, la fatigue sera vaincue.",
      "author": "Alphonse Allais",
      "sourcePage": 12
    },
    {
      "id": 603,
      "text": "Il n'y a pas de héros sans auditoire.",
      "author": "André Malraux",
      "sourcePage": 12
    },
    {
      "id": 604,
      "text": "Ne désespérez jamais. Faites infuser davantage.",
      "author": "Henri Michaux",
      "sourcePage": 12
    },
    {
      "id": 605,
      "text": "Quand on donne le Goncourt à un écrivain, est-ce qu'il est obligé de le lire ?",
      "author": "Laurent Ruquier",
      "sourcePage": 12
    },
    {
      "id": 606,
      "text": "Quand trop de choses sont là, plus de place pour les rêves.",
      "author": "Jean-Jacques Schuhl",
      "sourcePage": 12
    },
    {
      "id": 607,
      "text": "Les gens compliquent tout pour avoir l'impression de vivre.",
      "author": "Patrick Rambaud",
      "sourcePage": 12
    },
    {
      "id": 608,
      "text": "Le secret du bonheur en amour, ce n'est pas d'être aveugle mais de savoir fermer les yeux quand il le faut.",
      "author": "Simone Signoret",
      "sourcePage": 12
    },
    {
      "id": 609,
      "text": "Il n'y a pas de précurseurs, il n'existe que des retardataires.",
      "author": "Jean Cocteau",
      "sourcePage": 12
    },
    {
      "id": 610,
      "text": "La paix à n'importe quel prix, ce n'est plus la paix.",
      "author": "Eve Curie",
      "sourcePage": 12
    },
    {
      "id": 611,
      "text": "Ce que je redoute le plus avec l'Euro, c'est qu'il sera environ 6,5 fois plus dur d'être millionnaire.",
      "author": "Maxime Landron",
      "sourcePage": 12
    },
    {
      "id": 612,
      "text": "Les pères ne savent jamais rien de leurs fils. Ni les fils de leurs pères.",
      "author": "Patrick Poivre d'Arvor",
      "sourcePage": 12
    },
    {
      "id": 613,
      "text": "Toute angoisse est imaginaire ; le réel est son antidote.",
      "author": "André Comte-Sponville",
      "sourcePage": 12
    },
    {
      "id": 614,
      "text": "Lyon est une ville arrosée par trois grands fleuves : le Rhône, la Saône et le Beaujolais.",
      "author": "Léon Daudet",
      "sourcePage": 12
    },
    {
      "id": 615,
      "text": "N'ayez d'intolérance que vis-à-vis de l'intolérance.",
      "author": "Hippolyte Taine",
      "sourcePage": 12
    },
    {
      "id": 616,
      "text": "Se cogner à la réalité ne peut pas faire de mal.",
      "author": "Smain",
      "sourcePage": 13
    },
    {
      "id": 617,
      "text": "Le passé est soldé, le présent vous échappe, songez à l'avenir.",
      "author": "Duc de Levis",
      "sourcePage": 13
    },
    {
      "id": 618,
      "text": "Plus d'une chose insignifiante a pris de l'ampleur grâce à une bonne publicité.",
      "author": "Mark Twain",
      "sourcePage": 13
    },
    {
      "id": 619,
      "text": "On est de son enfance comme on est d'un pays.",
      "author": "Antoine de Saint-Exupéry",
      "sourcePage": 13
    },
    {
      "id": 620,
      "text": "Le peu qu'on peut faire, le très peu qu'on peut faire, il faut le faire, pour l'honneur, mais sans illusion.",
      "author": "Théodore Monod",
      "sourcePage": 13
    },
    {
      "id": 621,
      "text": "La Terre n'appartient pas à l'homme, c'est l'homme qui appartient à la Terre.",
      "author": "Sitting Bull - Chef indien",
      "sourcePage": 13
    },
    {
      "id": 622,
      "text": "La nature donne le génie ; la société, l'esprit ; les études, le goût.",
      "author": "Charles-Augustin Sainte-Beuve",
      "sourcePage": 13
    },
    {
      "id": 623,
      "text": "Les femmes sont faites pour être mariées et les hommes pour être célibataires. De là vient tout le mal.",
      "author": "Sacha Guitry",
      "sourcePage": 13
    },
    {
      "id": 624,
      "text": "Mieux vaut ne penser à rien que ne pas penser du tout.",
      "author": "Serge Gainsbourg",
      "sourcePage": 13
    },
    {
      "id": 625,
      "text": "Ce que je vous demande, c'est d'ouvrir votre esprit, non de croire.",
      "author": "Krishnamurti",
      "sourcePage": 13
    },
    {
      "id": 626,
      "text": "Qui cherche l'infini n'a qu'à fermer les yeux.",
      "author": "Milan Kundera",
      "sourcePage": 13
    },
    {
      "id": 627,
      "text": "C'est peut-être l'enfance qui approche le plus de la 'vraie vie'.",
      "author": "André Breton",
      "sourcePage": 13
    },
    {
      "id": 628,
      "text": "Les lois ne font plus les hommes, mais quelques hommes font la loi.",
      "author": "Daniel Balavoine",
      "sourcePage": 13
    },
    {
      "id": 629,
      "text": "La santé dépend plus des précautions que des médecins.",
      "author": "Bossuet",
      "sourcePage": 13
    },
    {
      "id": 630,
      "text": "Dire oui à tout et à tout le monde, c'est comme si on n'existait pas.",
      "author": "Tahar Ben Jelloun",
      "sourcePage": 13
    },
    {
      "id": 631,
      "text": "Le monde fleurit par ceux qui cèdent à la tentation.",
      "author": "Julien Gracq",
      "sourcePage": 13
    },
    {
      "id": 632,
      "text": "Les mots en ont toujours un pour rire.",
      "author": "Bernard Pivot",
      "sourcePage": 13
    },
    {
      "id": 633,
      "text": "Les humains ont un don pour désirer ce qui leur fait le plus de mal.",
      "author": "J. K. Rowling",
      "sourcePage": 13
    },
    {
      "id": 634,
      "text": "Ce ne sont pas ceux qui courent le plus vite qui sont les plus pressés.",
      "author": "Coluche",
      "sourcePage": 13
    },
    {
      "id": 635,
      "text": "L'homme généreux invente même des raisons de donner.",
      "author": "Publius Syrus",
      "sourcePage": 13
    },
    {
      "id": 636,
      "text": "Comme pour l'esprit rien n'est trop grand, pour la bonté rien n'est trop petit.",
      "author": "Jean-Paul II",
      "sourcePage": 13
    },
    {
      "id": 637,
      "text": "Qui n'a pas d'imagination n'a pas d'ailes.",
      "author": "Mohammed Ali",
      "sourcePage": 13
    },
    {
      "id": 638,
      "text": "Aucun homme n'a reçu de la nature le droit de commander aux autres.",
      "author": "Denis Diderot",
      "sourcePage": 13
    },
    {
      "id": 639,
      "text": "L'homme n'est heureux que de vouloir et d'inventer.",
      "author": "Alain",
      "sourcePage": 13
    },
    {
      "id": 640,
      "text": "On ne force pas une curiosité, on l'éveille.",
      "author": "Daniel Pennac",
      "sourcePage": 13
    },
    {
      "id": 641,
      "text": "A défaut d'autre chose, on peut toujours acquérir de l'expérience.",
      "author": "Dan Stanford",
      "sourcePage": 13
    },
    {
      "id": 642,
      "text": "Un homme qui hésite, c'est un homme qu'on peut tenter.",
      "author": "Lionel Groulx",
      "sourcePage": 13
    },
    {
      "id": 643,
      "text": "Si vous ne venez pas à l'euro, c'est l'euro qui vient vers vous !",
      "author": "Annie-Claire Poisson",
      "sourcePage": 13
    },
    {
      "id": 644,
      "text": "Dieu nous donne des mains, mais il ne bâtit pas les ponts.",
      "author": "Proverbe arabe",
      "sourcePage": 13
    },
    {
      "id": 645,
      "text": "En vérité, le chemin importe peu, la volonté d'arriver suffit à tout.",
      "author": "Albert Camus",
      "sourcePage": 13
    },
    {
      "id": 646,
      "text": "Noël n'est pas un jour ni une saison, c'est un état d'esprit.",
      "author": "Calvin Coolidge",
      "sourcePage": 13
    },
    {
      "id": 647,
      "text": "On a tous besoin de quelqu'un, de quelque chose ou d'un ailleurs que l'on n'a pas...",
      "author": "Gilbert Bécaud",
      "sourcePage": 13
    },
    {
      "id": 648,
      "text": "Celui qui brise une chose pour apprendre ce qu'elle est, a quitté les chemins de la raison.",
      "author": "J. R. R. Tolkien",
      "sourcePage": 13
    },
    {
      "id": 649,
      "text": "Quelle flamme pourrait égaler le rayon de soleil d'un jour d'hiver ?",
      "author": "Henry David Thoreau",
      "sourcePage": 13
    },
    {
      "id": 650,
      "text": "Le plaisir le plus délicat est de faire celui d'autrui.",
      "author": "Jean de La Bruyère",
      "sourcePage": 13
    },
    {
      "id": 651,
      "text": "C'est la nuit qu'il est beau de croire à la lumière.",
      "author": "Edmond Rostand",
      "sourcePage": 13
    },
    {
      "id": 652,
      "text": "Les parents du Père Noël auraient aussi souhaité que leur fils existe vraiment.",
      "author": "Jean-Michel Serveaux",
      "sourcePage": 13
    },
    {
      "id": 653,
      "text": "L'enfance c'est de croire qu'avec le sapin de Noël et trois flocons de neige toute la terre est changée.",
      "author": "André Laurendeau",
      "sourcePage": 13
    },
    {
      "id": 654,
      "text": "J'ai rêvé d'un monde de soleil dans la fraternité de mes frères aux yeux bleus.",
      "author": "Léopold Sedar Senghor",
      "sourcePage": 13
    },
    {
      "id": 655,
      "text": "La neige n'est plus un don du ciel. Elle tombe exactement aux endroits marqués par les stations d'hiver.",
      "author": "Jean Baudrillard",
      "sourcePage": 13
    },
    {
      "id": 656,
      "text": "Ce qui embellit le désert c'est qu'il cache un puits quelque part...",
      "author": "Antoine de Saint-Exupéry",
      "sourcePage": 13
    },
    {
      "id": 657,
      "text": "Le futur appartient à ceux qui croient à la beauté de leurs rêves.",
      "author": "Eleanor Roosevelt",
      "sourcePage": 13
    },
    {
      "id": 658,
      "text": "Tout le bonheur des hommes est dans l'imagination.",
      "author": "Marquis de Sade",
      "sourcePage": 13
    },
    {
      "id": 659,
      "text": "Celui-là a eu du courage, qui a été le premier à manger une huître.",
      "author": "Jonathan Swift",
      "sourcePage": 13
    },
    {
      "id": 660,
      "text": "- Je vous apporte mes vœux. - Merci, je tacherai d'en faire quelque chose.",
      "author": "Jules Renard",
      "sourcePage": 13
    },
    {
      "id": 661,
      "text": "La résistance au changement n'est que le refus de la croissance.",
      "author": "Alexander Ruperti",
      "sourcePage": 13
    },
    {
      "id": 662,
      "text": "Si on ne construit rien sur des regrets, par contre on bâtit sur des résolutions.",
      "author": "Anne Bernard",
      "sourcePage": 13
    },
    {
      "id": 663,
      "text": "Si les femmes n'existaient pas, tout l'argent du monde ne servirait à rien.",
      "author": "Aristote Onassis",
      "sourcePage": 13
    },
    {
      "id": 664,
      "text": "Plus on prend de la hauteur et plus on voit loin.",
      "author": "Proverbe chinois",
      "sourcePage": 13
    },
    {
      "id": 665,
      "text": "C'est toujours le chauve qui trouve le peigne dans la galette des rois.",
      "author": "Professeur Choron",
      "sourcePage": 13
    },
    {
      "id": 666,
      "text": "La meilleure façons de ne pas avancer est de suivre une idée fixe.",
      "author": "Jacques Prévert",
      "sourcePage": 13
    },
    {
      "id": 667,
      "text": "On n'a encore rien trouvé de mieux que la force pour résister à la violence.",
      "author": "Christophe Donner",
      "sourcePage": 13
    },
    {
      "id": 668,
      "text": "L'angoisse du temps qui passe nous fait parler du temps qu'il fait.",
      "author": "Jean-Pierre Jeunet",
      "sourcePage": 13
    },
    {
      "id": 669,
      "text": "Les leçons ne servent généralement qu'à ceux qui les donnent.",
      "author": "Pierre Dac",
      "sourcePage": 14
    },
    {
      "id": 670,
      "text": "Un optimiste, c'est un homme qui plante deux glands et qui s'achète un hamac.",
      "author": "Jean de Lattre de Tassigny",
      "sourcePage": 14
    },
    {
      "id": 671,
      "text": "A la liberté de provocation, répond la liberté d'objection.",
      "author": "Bernard Pivot",
      "sourcePage": 14
    },
    {
      "id": 672,
      "text": "Les hommes mettent dans leur voiture autant d'amour-propre que d'essence.",
      "author": "Pierre Daninos",
      "sourcePage": 14
    },
    {
      "id": 673,
      "text": "Nous ne voyons jamais qu'un seul côté des choses.",
      "author": "Victor Hugo - Les Contemplations",
      "sourcePage": 14
    },
    {
      "id": 674,
      "text": "Il faut plus de force et de talent pour conserver que pour acquérir.",
      "author": "Jean Pucelle",
      "sourcePage": 14
    },
    {
      "id": 675,
      "text": "On ne se doit qu'à l'enfant qu'on a été.",
      "author": "Alexandre Jardin",
      "sourcePage": 14
    },
    {
      "id": 676,
      "text": "Les grands bonheurs viennent du ciel, les petits bonheurs viennent de l'effort.",
      "author": "Proverbe chinois",
      "sourcePage": 14
    },
    {
      "id": 677,
      "text": "Il faut tenir à une résolution parce qu'elle est bonne, et non parce qu'on l'a prise.",
      "author": "La Rochefoucauld",
      "sourcePage": 14
    },
    {
      "id": 678,
      "text": "L'amour, c'est offrir à quelqu'un qui n'en veut pas quelque chose que l'on n'a pas.",
      "author": "Jacques Lacan",
      "sourcePage": 14
    },
    {
      "id": 679,
      "text": "Ca ne sert à rien d'avoir raison, si l'on n'a convaincu personne !",
      "author": "Richard Weltz",
      "sourcePage": 14
    },
    {
      "id": 680,
      "text": "Ce qui reste à faire est plus important que ce qui a déjà été fait.",
      "author": "Michel Conte",
      "sourcePage": 14
    },
    {
      "id": 681,
      "text": "Ne pas avoir de but est aussi un but.",
      "author": "Gao Xingjian - Nobel de littérature 2000",
      "sourcePage": 14
    },
    {
      "id": 682,
      "text": "Tant de mains pour transformer ce monde, et si peu de regards pour le contempler !",
      "author": "Julien Gracq",
      "sourcePage": 14
    },
    {
      "id": 683,
      "text": "Il y a ceux qui écrivent l'histoire et ceux qui ont besoin de lunettes pour la lire.",
      "author": "Greg - Extrait d'Achille Talon",
      "sourcePage": 14
    },
    {
      "id": 684,
      "text": "On a peur seulement quand on n'est pas d'accord avec soi-même.",
      "author": "Luis Fernandez",
      "sourcePage": 14
    },
    {
      "id": 685,
      "text": "Allons au fond de l'inconnu pour trouver du nouveau.",
      "author": "Charles Baudelaire",
      "sourcePage": 14
    },
    {
      "id": 686,
      "text": "La fleur de l'illusion produit le fruit de la réalité.",
      "author": "Paul Claudel",
      "sourcePage": 14
    },
    {
      "id": 687,
      "text": "Tout le bonheur du monde est dans l'inattendu.",
      "author": "Jean d'Ormesson",
      "sourcePage": 14
    },
    {
      "id": 688,
      "text": "A vaincre sans péril, on évite des ennuis !",
      "author": "René Goscinny - Extrait d'Astérix chez les Bretons",
      "sourcePage": 14
    },
    {
      "id": 689,
      "text": "La culture ne s'hérite pas, elle se conquiert.",
      "author": "André Malraux",
      "sourcePage": 14
    },
    {
      "id": 690,
      "text": "L'esprit... à quel âge il commence à avoir besoin de maquillage ?",
      "author": "Quino",
      "sourcePage": 14
    },
    {
      "id": 691,
      "text": "La confiture n'est bonne que s'il faut monter sur une chaise pour attraper le pot dans le placard.",
      "author": "Alexandre Vialatte",
      "sourcePage": 14
    },
    {
      "id": 692,
      "text": "Réfléchir, c'est déranger ses pensées.",
      "author": "Jean Rostand",
      "sourcePage": 14
    },
    {
      "id": 693,
      "text": "Pour 'changer la vie', il faudrait commencer par changer la vie politique.",
      "author": "Pierre Bourdieu - Sociologue français",
      "sourcePage": 14
    },
    {
      "id": 694,
      "text": "L'amour est à réinventer.",
      "author": "Arthur Rimbaud",
      "sourcePage": 14
    },
    {
      "id": 695,
      "text": "Le cinéma, c'est un œil ouvert sur le monde.",
      "author": "Joseph Bédier",
      "sourcePage": 14
    },
    {
      "id": 696,
      "text": "Un secret a toujours la forme d'une oreille.",
      "author": "Jean Cocteau",
      "sourcePage": 14
    },
    {
      "id": 697,
      "text": "La victoire va à celui qui prend le plus de risques.",
      "author": "Jean-Claude Killy",
      "sourcePage": 14
    },
    {
      "id": 698,
      "text": "Le cœur n'a pas de rides.",
      "author": "Madame de Sévigné",
      "sourcePage": 14
    },
    {
      "id": 699,
      "text": "En un baiser partons vers un monde inconnu.",
      "author": "Alfred de Musset",
      "sourcePage": 14
    },
    {
      "id": 700,
      "text": "Le peu que je sais, c'est à mon ignorance que je le dois.",
      "author": "Sacha Guitry",
      "sourcePage": 14
    },
    {
      "id": 701,
      "text": "L'enfance est ce que le monde abandonne pour continuer d'être monde.",
      "author": "Christian Bobin",
      "sourcePage": 14
    },
    {
      "id": 702,
      "text": "Il faut rajouter de la vie aux années et non des années à la vie.",
      "author": "Proverbe chinois",
      "sourcePage": 14
    },
    {
      "id": 703,
      "text": "Aimer, c'est perdre le contrôle.",
      "author": "Paulo Coelho",
      "sourcePage": 14
    },
    {
      "id": 704,
      "text": "Faites donc ce que vous voulez - mais soyez d'abord de ceux qui peuvent vouloir !",
      "author": "Friedrich Nietzsche",
      "sourcePage": 14
    },
    {
      "id": 705,
      "text": "Il n'y a personne qui soit née sous une mauvaise étoile, il n'y a que des gens qui ne savent pas lire le ciel.",
      "author": "Dalai Lama",
      "sourcePage": 14
    },
    {
      "id": 706,
      "text": "Dans la vie il faut être franc, et par les temps qui courent un franc c'est un franc.",
      "author": "Smain",
      "sourcePage": 14
    },
    {
      "id": 707,
      "text": "Pour ce qui est de l'avenir, il ne s'agit pas de le prévoir, mais de le rendre possible.",
      "author": "Antoine de Saint-Exupéry",
      "sourcePage": 14
    },
    {
      "id": 708,
      "text": "Un grain de poésie suffit à parfumer tout un siècle.",
      "author": "José Marti",
      "sourcePage": 14
    },
    {
      "id": 709,
      "text": "Les hommes ne voient la nécessité que dans la crise.",
      "author": "Jean Monnet",
      "sourcePage": 14
    },
    {
      "id": 710,
      "text": "De petites occasions sont souvent à l'origine de grandes entreprises.",
      "author": "Démosthène",
      "sourcePage": 14
    },
    {
      "id": 711,
      "text": "La culture... ce qui a fait de l'homme autre chose qu'un accident de l'univers.",
      "author": "André Malraux",
      "sourcePage": 14
    },
    {
      "id": 712,
      "text": "Dans un grain de sable voir un monde, dans chaque fleur des champs le Paradis.",
      "author": "William Blake",
      "sourcePage": 14
    },
    {
      "id": 713,
      "text": "Si, au lieu de gagner beaucoup d'argent pour vivre, nous tachions de vivre avec peu d'argent ?",
      "author": "Jules Renard",
      "sourcePage": 14
    },
    {
      "id": 714,
      "text": "Quand mille personnes prennent la route, il en faut une pour prendre la tête.",
      "author": "Proverbe chinois",
      "sourcePage": 14
    },
    {
      "id": 715,
      "text": "N'imitez rien ni personne. Un lion qui copie un lion devient un singe.",
      "author": "Victor Hugo - Tas de pierres",
      "sourcePage": 14
    },
    {
      "id": 716,
      "text": "L'âge que nous vivons est dangereux ; comme il serait ennuyeux s'il ne l'était pas.",
      "author": "John Steinbeck",
      "sourcePage": 14
    },
    {
      "id": 717,
      "text": "Qui a la même vision du monde à vingt ans qu'à cinquante, a perdu trente ans de sa vie.",
      "author": "Mohammed Ali",
      "sourcePage": 14
    },
    {
      "id": 718,
      "text": "Penser contre a toujours été la façon la moins difficile de penser.",
      "author": "Jacques de Bourbon-Busset",
      "sourcePage": 14
    },
    {
      "id": 719,
      "text": "La chance, c'est ce qu'on croit toujours qu'on n'a pas.",
      "author": "Patrice Leconte",
      "sourcePage": 14
    },
    {
      "id": 720,
      "text": "Une maman formidable donne toujours une grand-mère exceptionnelle.",
      "author": "Jean Gastaldi",
      "sourcePage": 15
    },
    {
      "id": 721,
      "text": "Choisir, c'est se priver du reste.",
      "author": "André Gide",
      "sourcePage": 15
    },
    {
      "id": 722,
      "text": "Le bonheur n'est pas le but mais le moyen de la vie.",
      "author": "Paul Claudel",
      "sourcePage": 15
    },
    {
      "id": 723,
      "text": "L'intelligence, c'est de prévoir celle de l'autre.",
      "author": "Georges Perros",
      "sourcePage": 15
    },
    {
      "id": 724,
      "text": "Les hommes créent souvent des modes aberrantes pour se venger des femmes.",
      "author": "Roland Barthes",
      "sourcePage": 15
    },
    {
      "id": 725,
      "text": "La vraie république : aux hommes leurs droits et rien de plus, aux femmes leurs droits et rien de moins.",
      "author": "Susan Anthony",
      "sourcePage": 15
    },
    {
      "id": 726,
      "text": "Une erreur originale vaut mieux qu'une vérité banale.",
      "author": "Fiodor Dostoïevski",
      "sourcePage": 15
    },
    {
      "id": 727,
      "text": "Il n'est rien de si absent que la présence d'esprit.",
      "author": "Rivarol",
      "sourcePage": 15
    },
    {
      "id": 728,
      "text": "Un poète est un monde enfermé dans un homme.",
      "author": "Victor Hugo",
      "sourcePage": 15
    },
    {
      "id": 729,
      "text": "Les gens heureux n'ont pas besoin de beaucoup pour être heureux.",
      "author": "Phil Bosmans",
      "sourcePage": 15
    },
    {
      "id": 730,
      "text": "La vérité est une ligne tracée entre les erreurs.",
      "author": "Franz Anton Mesmer",
      "sourcePage": 15
    },
    {
      "id": 731,
      "text": "La persuasion n'annule pas définitivement le doute.",
      "author": "Denis Guedj",
      "sourcePage": 15
    },
    {
      "id": 732,
      "text": "Dieu lui-même croit à la publicité : il a mis des cloches dans les églises.",
      "author": "Aurélien Scholl",
      "sourcePage": 15
    },
    {
      "id": 733,
      "text": "Tant qu'il y aura des dictatures, je n'aurai pas le cœur à critiquer une démocratie.",
      "author": "Jean Rostand",
      "sourcePage": 15
    },
    {
      "id": 734,
      "text": "Y penser sans cesse ne labourera pas le champ.",
      "author": "Proverbe irlandais",
      "sourcePage": 15
    },
    {
      "id": 735,
      "text": "Chaque langue voit le monde d'une manière différente.",
      "author": "Federico Fellini",
      "sourcePage": 15
    },
    {
      "id": 736,
      "text": "Un film doit être comme un caillou dans une chaussure.",
      "author": "Lars von Trier",
      "sourcePage": 15
    },
    {
      "id": 737,
      "text": "C'est en croyant aux roses qu'on les fait éclore.",
      "author": "Anatole France",
      "sourcePage": 15
    },
    {
      "id": 738,
      "text": "Election : opération par laquelle des citoyens libres se choisissent des maîtres.",
      "author": "Timon de Paris",
      "sourcePage": 15
    },
    {
      "id": 739,
      "text": "A l'échelle cosmique, l'eau est plus rare que l'or.",
      "author": "Hubert Reeves",
      "sourcePage": 15
    },
    {
      "id": 740,
      "text": "A l'envers des nuages, il y a toujours un ciel.",
      "author": "Muhammad Al-Faytury",
      "sourcePage": 15
    },
    {
      "id": 741,
      "text": "Lire est le propre de l'homme.",
      "author": "Madeleine Chapsal",
      "sourcePage": 15
    },
    {
      "id": 742,
      "text": "On ne fait pas ce qu'on veut et cependant on est responsable de ce qu'on est.",
      "author": "Jean-Paul Sartre",
      "sourcePage": 15
    },
    {
      "id": 743,
      "text": "Il faut être prudent, mais non pas timide.",
      "author": "Voltaire",
      "sourcePage": 15
    },
    {
      "id": 744,
      "text": "L'avenir, c'est ce qui dépasse la main tendue.",
      "author": "Louis Aragon",
      "sourcePage": 15
    },
    {
      "id": 745,
      "text": "Les idées fausses ne sont pas toutes mauvaises.",
      "author": "Marcel Ayme",
      "sourcePage": 15
    },
    {
      "id": 746,
      "text": "Faites confiance à votre instinct. Il vaut mieux que les erreurs soient les vôtres, plutôt que celles de quelqu'un d'autre.",
      "author": "Billy Wilder",
      "sourcePage": 15
    },
    {
      "id": 747,
      "text": "Le Parisien adore qu'on lui dise que sa vie n'est pas une vie. Il se flatte de son endurance.",
      "author": "Alain Schifres",
      "sourcePage": 15
    },
    {
      "id": 748,
      "text": "Ce n'est pas la girouette qui tourne, c'est le vent.",
      "author": "Edgar Faure",
      "sourcePage": 15
    },
    {
      "id": 749,
      "text": "Nous sommes entrés dans l'ère de l'espace. Un candidat pourra promettre la lune et la donner.",
      "author": "David Brinkley",
      "sourcePage": 15
    },
    {
      "id": 750,
      "text": "Je ne fais rien du tout quand je pense tout faire.",
      "author": "Pierre Corneille",
      "sourcePage": 15
    },
    {
      "id": 751,
      "text": "Pour moi, être aimé n'est rien, c'est être préféré que je désire.",
      "author": "André Gide",
      "sourcePage": 15
    },
    {
      "id": 752,
      "text": "Pour réussir, il ne suffit pas de prévoir. Il faut aussi savoir improviser.",
      "author": "Isaac Asimov",
      "sourcePage": 15
    },
    {
      "id": 753,
      "text": "J'ai décidé d'être heureux parce que c'est bon pour la santé.",
      "author": "Voltaire",
      "sourcePage": 15
    },
    {
      "id": 754,
      "text": "L'avenir n'est interdit à personne.",
      "author": "Léon Gambetta",
      "sourcePage": 15
    },
    {
      "id": 755,
      "text": "Je ne suis pas un homme de parti, mais je défends des causes.",
      "author": "Théodore Monod",
      "sourcePage": 15
    },
    {
      "id": 756,
      "text": "Sans la musique, la vie serait une erreur.",
      "author": "Friedrich Nietzsche",
      "sourcePage": 15
    },
    {
      "id": 757,
      "text": "Quand la vérité n'est pas libre, la liberté n'est pas vraie.",
      "author": "Jacques Prévert",
      "sourcePage": 15
    },
    {
      "id": 758,
      "text": "Pourquoi un homme ne pourrait-il pas avoir plus d'une vie ?",
      "author": "John Grisham",
      "sourcePage": 15
    },
    {
      "id": 759,
      "text": "L'esprit libre et curieux de l'homme est ce qui a le plus de prix au monde.",
      "author": "John Steinbeck",
      "sourcePage": 15
    },
    {
      "id": 760,
      "text": "Les hommes politiques feraient bien d'écouter nos voix, avant de les compter.",
      "author": "Claude Frisoni",
      "sourcePage": 15
    },
    {
      "id": 761,
      "text": "Qui ne doute pas acquiert peu.",
      "author": "Léonard de Vinci",
      "sourcePage": 15
    },
    {
      "id": 762,
      "text": "Il faut tout prendre au sérieux, mais rien au tragique.",
      "author": "Adolphe Thiers",
      "sourcePage": 15
    },
    {
      "id": 763,
      "text": "L'initiative est chose individuelle.",
      "author": "Marcelin Berthelot",
      "sourcePage": 15
    },
    {
      "id": 764,
      "text": "La veille de la fête des Secrétaires, il y a sûrement de nombreux patrons qui ont dit à la leur : 'Nicole, vous penserez demain à vous acheter un bouquet de fleurs.'",
      "author": "Laurent Ruquier",
      "sourcePage": 15
    },
    {
      "id": 765,
      "text": "Qu'il faut donc aimer quelqu'un pour le préférer à son absence !",
      "author": "Jean Rostand",
      "sourcePage": 15
    },
    {
      "id": 766,
      "text": "L'entreprise ne peut exiger la loyauté de ses salaries : elle doit la mériter.",
      "author": "Charles Handy",
      "sourcePage": 15
    },
    {
      "id": 767,
      "text": "Un bulletin de vote est plus fort qu'une balle de fusil.",
      "author": "Abraham Lincoln",
      "sourcePage": 15
    },
    {
      "id": 768,
      "text": "On ne peut atteindre les limites de l'art.",
      "author": "Ptahhotep",
      "sourcePage": 15
    },
    {
      "id": 769,
      "text": "Le paradis, à n'en pas douter, n'est qu'une immense bibliothèque.",
      "author": "Gaston Bachelard",
      "sourcePage": 15
    },
    {
      "id": 770,
      "text": "Il faudrait essayer d'être heureux, ne serait-ce que pour donner l'exemple.",
      "author": "Jacques Prévert",
      "sourcePage": 15
    },
    {
      "id": 771,
      "text": "Avec le mot 'si' on peut faire tout ce qu'on ne peut pas faire.",
      "author": "Pierre Dac",
      "sourcePage": 15
    },
    {
      "id": 772,
      "text": "Rien n'est plus dangereux qu'une idée quand on n'en a qu'une.",
      "author": "Paul Claudel",
      "sourcePage": 15
    },
    {
      "id": 773,
      "text": "Penser, c'est dire 'non'.",
      "author": "Alain",
      "sourcePage": 15
    },
    {
      "id": 774,
      "text": "La liberté appartient à ceux qui l'ont conquise.",
      "author": "André Malraux",
      "sourcePage": 15
    },
    {
      "id": 775,
      "text": "Nous devons apprendre à vivre ensemble comme des frères, sinon nous allons mourir tous ensemble comme des idiots.",
      "author": "Martin Luther King",
      "sourcePage": 15
    },
    {
      "id": 776,
      "text": "Pour connaître les hommes, il faut les voir agir.",
      "author": "Jean-Jacques Rousseau",
      "sourcePage": 16
    },
    {
      "id": 777,
      "text": "Bien informés, les hommes sont des citoyens ; mal informés, ils deviennent des sujets.",
      "author": "Alfred Sauvy",
      "sourcePage": 16
    },
    {
      "id": 778,
      "text": "La pire des démocraties est de loin préférable à la meilleure des dictatures.",
      "author": "Ruy Barbosa",
      "sourcePage": 16
    },
    {
      "id": 779,
      "text": "Le droit de vote, ce n'est pas l'expression d'une humeur, c'est une décision à l'égard de son pays, à l'égard de ses enfants.",
      "author": "Jacques Chirac",
      "sourcePage": 16
    },
    {
      "id": 780,
      "text": "L'amour de la démocratie est celui de l'égalité.",
      "author": "Montesquieu",
      "sourcePage": 16
    },
    {
      "id": 781,
      "text": "Le progrès avance en permanence grâce à l'expérience des autres.",
      "author": "Bruno Peyron",
      "sourcePage": 16
    },
    {
      "id": 782,
      "text": "La mémoire est l'avenir du passé.",
      "author": "Paul Valery",
      "sourcePage": 16
    },
    {
      "id": 783,
      "text": "Jésus, de retour sur terre, s'étonnerait qu'on le commente tant et qu'on essaie si peu de l'imiter.",
      "author": "Jacques de Bourbon-Busset",
      "sourcePage": 16
    },
    {
      "id": 784,
      "text": "Dans la vie, rien n'est à craindre, tout est à comprendre.",
      "author": "Marie Curie",
      "sourcePage": 16
    },
    {
      "id": 785,
      "text": "Mal pense qui ne repense.",
      "author": "Jean II Le Bon",
      "sourcePage": 16
    },
    {
      "id": 786,
      "text": "Je préfère quand le spectateur sort avec des questions plutôt qu'avec des réponses.",
      "author": "Louis Malle",
      "sourcePage": 16
    },
    {
      "id": 787,
      "text": "On ne peut donner que deux choses à ses enfants : des racines et des ailes.",
      "author": "Proverbe juif",
      "sourcePage": 16
    },
    {
      "id": 788,
      "text": "Rien ne vaut une douce maman.",
      "author": "Léon Tolstoï",
      "sourcePage": 16
    },
    {
      "id": 789,
      "text": "La passion fournit les arguments incontestables pour contourner les obstacles.",
      "author": "Antoine Riboud",
      "sourcePage": 16
    },
    {
      "id": 790,
      "text": "Imité, assimilé, et ensuite innové...",
      "author": "Clark Terry",
      "sourcePage": 16
    },
    {
      "id": 791,
      "text": "Pour voir le futur, il faut regarder derrière soi.",
      "author": "La Bible",
      "sourcePage": 16
    },
    {
      "id": 792,
      "text": "La réalité est une chose au-dessus de laquelle il faut s'élever.",
      "author": "Liza Minnelli",
      "sourcePage": 16
    },
    {
      "id": 793,
      "text": "La liberté de pensée est absolue ou elle n'est rien.",
      "author": "Luc Ferry",
      "sourcePage": 16
    },
    {
      "id": 794,
      "text": "On ne peut pas être heureux à tort ; on ne peut pas avoir tort d'être heureux.",
      "author": "Henri Petit",
      "sourcePage": 16
    },
    {
      "id": 795,
      "text": "La prudence dans les entreprises, la fermeté dans l'exécution, et l'intrépidité dans les périls.",
      "author": "Chevalier de Mère",
      "sourcePage": 16
    },
    {
      "id": 796,
      "text": "L'art sauvera le monde.",
      "author": "Fiodor Dostoïevski",
      "sourcePage": 16
    },
    {
      "id": 797,
      "text": "Là où on s'aime, il ne fait jamais nuit.",
      "author": "Proverbe africain",
      "sourcePage": 16
    },
    {
      "id": 798,
      "text": "La fête des mères est un prétexte, car on fête toute l'année sa maman.",
      "author": "Jean Gastaldi",
      "sourcePage": 16
    },
    {
      "id": 799,
      "text": "Si vous gagnez sans progresser, vous ne serez jamais champion.",
      "author": "John McEnroe",
      "sourcePage": 16
    },
    {
      "id": 800,
      "text": "Il ne faut pas toujours avoir raison pour plaire.",
      "author": "Prince de Ligne",
      "sourcePage": 16
    },
    {
      "id": 801,
      "text": "Les performances individuelles, ce n'est pas le plus important. On gagne et on perd en équipe.",
      "author": "Zinédine Zidane",
      "sourcePage": 16
    },
    {
      "id": 802,
      "text": "La cigarette est la prière de notre temps.",
      "author": "Annie Leclerc",
      "sourcePage": 16
    },
    {
      "id": 803,
      "text": "Dieu a créé l'homme. Et ensuite, pour le remercier, l'homme a créé Dieu.",
      "author": "Philippe Geluck",
      "sourcePage": 16
    },
    {
      "id": 804,
      "text": "L'homme libre est celui qui n'a pas peur d'aller jusqu'au bout de sa pensée.",
      "author": "Léon Blum",
      "sourcePage": 16
    },
    {
      "id": 805,
      "text": "Pour être soi-même, il faut être quelqu'un.",
      "author": "Stanislaw Jerzy Lec",
      "sourcePage": 16
    },
    {
      "id": 806,
      "text": "Un père vaut plus qu'une centaine de maîtres d'école.",
      "author": "George Herbert",
      "sourcePage": 16
    },
    {
      "id": 807,
      "text": "La nature, pour être commandée, doit être obéie.",
      "author": "Francis Bacon",
      "sourcePage": 16
    },
    {
      "id": 808,
      "text": "Un cœur de père est le chef-d’œuvre de la nature.",
      "author": "Abbé Prévost",
      "sourcePage": 16
    },
    {
      "id": 809,
      "text": "L'intelligence, c'est comme un sous-vêtement. Il faut en avoir mais ne pas l'exhiber.",
      "author": "James Dent",
      "sourcePage": 16
    },
    {
      "id": 810,
      "text": "Il faut se méfier des comiques, parce que quelquefois ils disent des choses pour plaisanter.",
      "author": "Coluche",
      "sourcePage": 16
    },
    {
      "id": 811,
      "text": "Les sondages ne votent pas, ce sont les gens qui votent.",
      "author": "Hillary Clinton",
      "sourcePage": 16
    },
    {
      "id": 812,
      "text": "Quand les enfants ne font rien, ils font des bêtises.",
      "author": "Henry Fielding",
      "sourcePage": 16
    },
    {
      "id": 813,
      "text": "Le bruit ne fait pas de bien, et le bien ne fait pas de bruit.",
      "author": "Saint Vincent de Paul",
      "sourcePage": 16
    },
    {
      "id": 814,
      "text": "L'homme est un être raisonnable, mais les hommes le sont-ils ?",
      "author": "Raymond Aron",
      "sourcePage": 16
    },
    {
      "id": 815,
      "text": "A mesure qu'on est plus éclairé, on a moins de lumière.",
      "author": "Prince de Ligne",
      "sourcePage": 16
    },
    {
      "id": 816,
      "text": "Tous les hommes font la même erreur, de s'imaginer que bonheur veut dire que tous les vœux se réalisent.",
      "author": "Léon Tolstoï",
      "sourcePage": 16
    },
    {
      "id": 817,
      "text": "Voter c'est écrire l'Histoire.",
      "author": "Alex le Gall",
      "sourcePage": 16
    },
    {
      "id": 818,
      "text": "Etre père, c'est prétendre que le cadeau qu'on préfère c'est un cendrier en terre cuite.",
      "author": "Bill Cosby",
      "sourcePage": 16
    },
    {
      "id": 819,
      "text": "Souvent, au lieu de penser, on se fait des idées.",
      "author": "Louis Scutenaire",
      "sourcePage": 16
    },
    {
      "id": 820,
      "text": "Tout travail est noblesse que l'on accroche à une étoile.",
      "author": "Raoul Follereau",
      "sourcePage": 16
    },
    {
      "id": 821,
      "text": "Il est bon de suivre sa pente, pourvu que ce soit en montant.",
      "author": "André Gide",
      "sourcePage": 16
    },
    {
      "id": 822,
      "text": "Entre une pratique sans tête et une théorie sans jambes, il n'y aura jamais à choisir.",
      "author": "Régis Debray",
      "sourcePage": 16
    },
    {
      "id": 823,
      "text": "A quoi sert la lumière du soleil, si on a les yeux fermés.",
      "author": "Proverbe arabe",
      "sourcePage": 16
    },
    {
      "id": 824,
      "text": "C'est par le bien-faire que se crée le bien-être.",
      "author": "Proverbe chinois",
      "sourcePage": 16
    },
    {
      "id": 825,
      "text": "Les grandes joies ne sont pas les plus importantes ; ce qui compte c'est de savourer les petites.",
      "author": "Jean Webster",
      "sourcePage": 16
    },
    {
      "id": 826,
      "text": "Ce n'est pas la réalité qui compte dans un film, mais ce que l'imagination peut en faire.",
      "author": "Charlie Chaplin",
      "sourcePage": 16
    },
    {
      "id": 827,
      "text": "Le véritable talent, c'est de réagir de la même façon devant la victoire et la défaite.",
      "author": "Chris Evert",
      "sourcePage": 16
    },
    {
      "id": 828,
      "text": "Le succès est un mauvais professeur. Il pousse les gens intelligents à croire qu'ils sont infaillibles.",
      "author": "Bill Gates",
      "sourcePage": 17
    },
    {
      "id": 829,
      "text": "Dans tout homme, il y a un peu de tous les hommes.",
      "author": "Georg Christoph Lichtenberg",
      "sourcePage": 17
    },
    {
      "id": 830,
      "text": "L'important n'est pas d'être connue, mais d'être reconnue.",
      "author": "Monica Bellucci",
      "sourcePage": 17
    },
    {
      "id": 831,
      "text": "Allons ! Vive l'amour que l'ivresse accompagne !",
      "author": "Alfred De Musset",
      "sourcePage": 17
    },
    {
      "id": 832,
      "text": "Le sport consiste à déléguer au corps quelques-unes des vertus les plus fortes de l'âme.",
      "author": "Jean Giraudoux",
      "sourcePage": 17
    },
    {
      "id": 833,
      "text": "La liberté commence où l'ignorance finit.",
      "author": "Victor Hugo",
      "sourcePage": 17
    },
    {
      "id": 834,
      "text": "Plus on prête attention aux coïncidences, plus elles se produisent.",
      "author": "Vladimir Nabokov",
      "sourcePage": 17
    },
    {
      "id": 835,
      "text": "Dans une avalanche, aucun flocon ne se sent jamais responsable.",
      "author": "Stanislaw Jerzy Lec",
      "sourcePage": 17
    },
    {
      "id": 836,
      "text": "Aujourd'hui on ne sait plus parler, parce qu'on ne sait plus écouter.",
      "author": "Jules Renard",
      "sourcePage": 17
    },
    {
      "id": 837,
      "text": "Le plus simple écolier sait maintenant des vérités pour lesquelles Archimède eut sacrifié sa vie.",
      "author": "Ernest Renan",
      "sourcePage": 17
    },
    {
      "id": 838,
      "text": "La musique donne une âme à nos cœurs et des ailes à la pensée.",
      "author": "Platon",
      "sourcePage": 17
    },
    {
      "id": 839,
      "text": "Une baguette est facile à casser, dix baguettes sont dures comme fer.",
      "author": "Proverbe chinois",
      "sourcePage": 17
    },
    {
      "id": 840,
      "text": "Le cinéma, c'est comme un père, ça fait rêver. Le théâtre, c'est comme une mère, on y revient toujours...",
      "author": "Valérie Lemercier",
      "sourcePage": 17
    },
    {
      "id": 841,
      "text": "C'est une erreur de ne pas croire et une faute de tout croire.",
      "author": "Fernando de Rojas",
      "sourcePage": 17
    },
    {
      "id": 842,
      "text": "Dans la vie il faut savoir compter... mais pas sur les autres.",
      "author": "Paul-Jean Toulet",
      "sourcePage": 17
    },
    {
      "id": 843,
      "text": "La Terre promise est toujours de l'autre côté du désert.",
      "author": "Henry Havelock Ellis",
      "sourcePage": 17
    },
    {
      "id": 844,
      "text": "Une petite flamme de folie, si on savait comme la vie s'en éclaire !",
      "author": "Henry de Montherlant",
      "sourcePage": 17
    },
    {
      "id": 845,
      "text": "Le seul homme qui peut changer d'idée est celui qui en a une.",
      "author": "Edwards Noyes Westcott",
      "sourcePage": 17
    },
    {
      "id": 846,
      "text": "Quiconque a semé des privilèges doit recueillir des révolutions.",
      "author": "Claude Tillier",
      "sourcePage": 17
    },
    {
      "id": 847,
      "text": "La joie est en tout ; il faut savoir l'extraire.",
      "author": "Confucius",
      "sourcePage": 17
    },
    {
      "id": 848,
      "text": "Une suite de petites volontés fait un gros résultat.",
      "author": "Charles Baudelaire",
      "sourcePage": 17
    },
    {
      "id": 849,
      "text": "Il faut éteindre la démesure plus encore que l'incendie.",
      "author": "Héraclite d'Ephèse",
      "sourcePage": 17
    },
    {
      "id": 850,
      "text": "L'ivresse de la jeunesse est plus forte que l'ivresse du vin.",
      "author": "Proverbe persan",
      "sourcePage": 17
    },
    {
      "id": 851,
      "text": "Nous sommes peu à penser trop, trop à penser peu.",
      "author": "Françoise Sagan",
      "sourcePage": 17
    },
    {
      "id": 852,
      "text": "Les vacances, c'est tout un travail de repos très difficile.",
      "author": "Vincent Gury",
      "sourcePage": 17
    },
    {
      "id": 853,
      "text": "Quelqu'un s'assoit à l'ombre aujourd'hui parce que quelqu'un d'autre a planté un arbre il y a longtemps.",
      "author": "Warren Buffet",
      "sourcePage": 17
    },
    {
      "id": 854,
      "text": "On met longtemps à devenir jeune.",
      "author": "Pablo Picasso",
      "sourcePage": 17
    },
    {
      "id": 855,
      "text": "Les faits ne cessent pas d'exister parce qu'on les ignore.",
      "author": "Aldous Huxley",
      "sourcePage": 17
    },
    {
      "id": 856,
      "text": "On ne vit pas de ce que l'on mange, mais de ce que l'on digère.",
      "author": "Alexandre Dumas",
      "sourcePage": 17
    },
    {
      "id": 857,
      "text": "L'hésitation est le propre de l'intelligence.",
      "author": "Henry de Montherlant",
      "sourcePage": 17
    },
    {
      "id": 858,
      "text": "Il vaut mieux se tromper avec tout le monde que d'être intelligent tout seul.",
      "author": "Marcel Achard",
      "sourcePage": 17
    },
    {
      "id": 859,
      "text": "Si vous voulez obtenir quelque chose, adressez-vous à quelqu'un de très occupé : les autres n'ont pas le temps.",
      "author": "Pierre Daninos",
      "sourcePage": 17
    },
    {
      "id": 860,
      "text": "Quand tourne le vent on accuse les girouettes.",
      "author": "Paul-Jean Toulet",
      "sourcePage": 17
    },
    {
      "id": 861,
      "text": "Mieux vaut allumer une bougie que maudire les ténèbres.",
      "author": "Lao-Tseu",
      "sourcePage": 17
    },
    {
      "id": 862,
      "text": "C'est à l'endroit où l'eau est la plus profonde qu'elle est le plus calme.",
      "author": "William Shakespeare",
      "sourcePage": 17
    },
    {
      "id": 863,
      "text": "Etre en vacances c'est n'avoir rien à faire et avoir toute la journée pour le faire.",
      "author": "Robert Orben",
      "sourcePage": 17
    },
    {
      "id": 864,
      "text": "Comment des années si courtes se fabriquent-elles avec des journées si longues ?",
      "author": "Vladimir Jankelevitch",
      "sourcePage": 17
    },
    {
      "id": 865,
      "text": "Et pour quelles raisons étranges les gens qui pensent autrement, ça nous dérange ?",
      "author": "Michel Berger",
      "sourcePage": 17
    },
    {
      "id": 866,
      "text": "Changer d'air, c'est salutaire !",
      "author": "Jean-Pierre Jeunet",
      "sourcePage": 17
    },
    {
      "id": 867,
      "text": "L'autre rive est toujours plus belle. Elle se trouve toujours plus loin.",
      "author": "Phil Bosmans",
      "sourcePage": 17
    },
    {
      "id": 868,
      "text": "Ne cherchez pas une raison. Cherchez une issue.",
      "author": "Vincenzo Natali",
      "sourcePage": 17
    },
    {
      "id": 869,
      "text": "Pour croire avec certitude, il faut commencer par douter.",
      "author": "Proverbe polonais",
      "sourcePage": 17
    },
    {
      "id": 870,
      "text": "Devant l'impossibilité de tout savoir, la plupart ont choisi de ne savoir rien.",
      "author": "Louis Scutenaire",
      "sourcePage": 17
    },
    {
      "id": 871,
      "text": "Aidez-moi, j'aiderai le ciel.",
      "author": "Jacques Rigaut",
      "sourcePage": 17
    },
    {
      "id": 872,
      "text": "Le secret de la jeunesse est d'être honnête, de manger lentement, et de mentir sur son age.",
      "author": "Lucille Ball",
      "sourcePage": 17
    },
    {
      "id": 873,
      "text": "Quand le soleil s'éclipse on en voit la grandeur.",
      "author": "Sénèque",
      "sourcePage": 17
    },
    {
      "id": 874,
      "text": "On est riche surtout de l'or qu'on a donné.",
      "author": "Emile Deschamps",
      "sourcePage": 17
    },
    {
      "id": 875,
      "text": "Si j'étais roi, je me méfierais des As.",
      "author": "Tristan Bernard",
      "sourcePage": 17
    },
    {
      "id": 876,
      "text": "Ce n'est pas le but qui est intéressant, ce sont les moyens pour y parvenir.",
      "author": "Georges Braque",
      "sourcePage": 17
    },
    {
      "id": 877,
      "text": "Je n'oublie jamais un visage, mais pour vous je ferai une exception.",
      "author": "Groucho Marx",
      "sourcePage": 17
    },
    {
      "id": 878,
      "text": "Le soleil accepte bien de passer par de petites fenêtres.",
      "author": "Frederick van Eeden",
      "sourcePage": 17
    },
    {
      "id": 879,
      "text": "Est heureux qui croit l'être.",
      "author": "Proverbe français",
      "sourcePage": 17
    },
    {
      "id": 880,
      "text": "Bonheur : faire ce que l'on veut et vouloir ce que l'on fait.",
      "author": "Françoise Giroud",
      "sourcePage": 17
    },
    {
      "id": 881,
      "text": "Vivez si m'en croyez, n'attendez à demain. Cueillez dès aujourd'hui les roses de la vie.",
      "author": "Pierre de Ronsard",
      "sourcePage": 18
    },
    {
      "id": 882,
      "text": "Si, nous ne trouvons pas des choses agréables, nous trouverons du moins des choses nouvelles.",
      "author": "Voltaire",
      "sourcePage": 18
    },
    {
      "id": 883,
      "text": "Le difficile c'est ce qui peut-être fait tout de suite. L'impossible, c'est ce qui prend un peu plus de temps.",
      "author": "George Santayana",
      "sourcePage": 18
    },
    {
      "id": 884,
      "text": "Serai-je sur la terre quand la justice et l'égalité règneront parmi les hommes ?",
      "author": "Pierre Leroux",
      "sourcePage": 18
    },
    {
      "id": 885,
      "text": "Le soleil est nouveau tous les jours.",
      "author": "Héraclite d'Ephèse",
      "sourcePage": 18
    },
    {
      "id": 886,
      "text": "Il n'y a que deux conduites avec la vie : ou on la rêve ou on l'accomplit.",
      "author": "René Char",
      "sourcePage": 18
    },
    {
      "id": 887,
      "text": "Croire au soleil quand tombe l'eau.",
      "author": "Louis Aragon",
      "sourcePage": 18
    },
    {
      "id": 888,
      "text": "Sachons éviter les offenses, puisque nous ne savons pas les supporter.",
      "author": "Sénèque",
      "sourcePage": 18
    },
    {
      "id": 889,
      "text": "La rigueur vient toujours à bout de l'obstacle.",
      "author": "Léonard de Vinci",
      "sourcePage": 18
    },
    {
      "id": 890,
      "text": "On commence à vieillir quand on finit d'apprendre.",
      "author": "Proverbe japonais",
      "sourcePage": 18
    },
    {
      "id": 891,
      "text": "A force de prévoir l'avenir, on nous le rend aussi fastidieux qu'un passé.",
      "author": "Jean Rostand",
      "sourcePage": 18
    },
    {
      "id": 892,
      "text": "Lorsqu'un mur va s'écrouler, tout le monde le pousse.",
      "author": "Jiang Zilong",
      "sourcePage": 18
    },
    {
      "id": 893,
      "text": "Sans imagination, l'amour n'a aucune chance.",
      "author": "Romain Gary",
      "sourcePage": 18
    },
    {
      "id": 894,
      "text": "La richesse est un instrument dont on use, et non un dieu que l'on vénère.",
      "author": "Calvin Coolidge",
      "sourcePage": 18
    },
    {
      "id": 895,
      "text": "Je ne suis jamais entré dans un bureau sans me demander comment m'en échapper.",
      "author": "Jacques Sternberg",
      "sourcePage": 18
    },
    {
      "id": 896,
      "text": "Le bonheur qu'on veut avoir gâte celui qu'on a déjà.",
      "author": "Jacques Deval",
      "sourcePage": 18
    },
    {
      "id": 897,
      "text": "Mourir pour une cause ne fait pas que cette cause soit juste.",
      "author": "Henry de Montherlant",
      "sourcePage": 18
    },
    {
      "id": 898,
      "text": "La vérité n'est pas dans un seul rêve, mais dans beaucoup de rêves.",
      "author": "Pier Paolo Pasolini",
      "sourcePage": 18
    },
    {
      "id": 899,
      "text": "Le grand talent accepte les critiques.",
      "author": "Marin Karmitz",
      "sourcePage": 18
    },
    {
      "id": 900,
      "text": "Il est des sentiments si intraduisibles qu'il faut la musique pour les suggérer.",
      "author": "André Esparcieux",
      "sourcePage": 18
    },
    {
      "id": 901,
      "text": "Le lendemain s'instruit aux leçons de la veille.",
      "author": "Publius Syrus",
      "sourcePage": 18
    },
    {
      "id": 902,
      "text": "Le monde appartient aux optimistes, les pessimistes ne sont que des spectateurs.",
      "author": "François Guizot",
      "sourcePage": 18
    },
    {
      "id": 903,
      "text": "Quand on n'a pas de mémoire, on se répète : quand on en a, on répète les autres.",
      "author": "Albert Brie",
      "sourcePage": 18
    },
    {
      "id": 904,
      "text": "Le bonheur, c'est de continuer à désirer ce qu'on possède.",
      "author": "Saint Augustin",
      "sourcePage": 18
    },
    {
      "id": 905,
      "text": "L'homme a ce choix : laisser entrer la lumière ou garder les volets fermés.",
      "author": "Henry Miller",
      "sourcePage": 18
    },
    {
      "id": 906,
      "text": "Celui qui marche droit trouve toujours la route assez large.",
      "author": "Proverbe breton",
      "sourcePage": 18
    },
    {
      "id": 907,
      "text": "C'est quand on a tout que le reste vous manque.",
      "author": "Ylipe",
      "sourcePage": 18
    },
    {
      "id": 908,
      "text": "Il y a des gens dans le monde qui n'ont de succès que par leurs défauts.",
      "author": "Madame de Genlis",
      "sourcePage": 18
    },
    {
      "id": 909,
      "text": "Rien n'est jamais joué si l'on se refuse à subir.",
      "author": "Françoise Giroud",
      "sourcePage": 18
    },
    {
      "id": 910,
      "text": "C'est toujours l'impatience de gagner qui fait perdre.",
      "author": "Louis XIV",
      "sourcePage": 18
    },
    {
      "id": 911,
      "text": "Quand on me contrarie, on éveille mon attention, non pas ma colère.",
      "author": "Montaigne",
      "sourcePage": 18
    },
    {
      "id": 912,
      "text": "On ne saurait aller trop loin dans la connaissance de l'homme.",
      "author": "Emile Zola",
      "sourcePage": 18
    },
    {
      "id": 913,
      "text": "Une vie ne vaut rien, mais rien ne vaut une vie.",
      "author": "André Malraux",
      "sourcePage": 18
    },
    {
      "id": 914,
      "text": "Vieillir ensemble, ce n'est pas ajouter des années à la vie, mais de la vie aux années.",
      "author": "Jacques Salomé",
      "sourcePage": 18
    },
    {
      "id": 915,
      "text": "Le secret de la liberté, c'est la librairie.",
      "author": "Bernard Werber",
      "sourcePage": 18
    },
    {
      "id": 916,
      "text": "Il arrive souvent de ne rien obtenir parce que l'on ne tente rien.",
      "author": "Jacques Deval",
      "sourcePage": 18
    },
    {
      "id": 917,
      "text": "On ne peut répondre de son courage quand on n'a jamais été dans le péril.",
      "author": "La Rochefoucauld",
      "sourcePage": 18
    },
    {
      "id": 918,
      "text": "On gagne à être connu. On perd à être trop connu.",
      "author": "Jules Renard",
      "sourcePage": 18
    },
    {
      "id": 919,
      "text": "Une mauvaise idée vaut toujours mieux que pas d'idée du tout.",
      "author": "Alphonse Allais",
      "sourcePage": 18
    },
    {
      "id": 920,
      "text": "La source désapprouve presque toujours l'itinéraire du fleuve.",
      "author": "Jean Cocteau",
      "sourcePage": 18
    },
    {
      "id": 921,
      "text": "Pour qui n'ambitionne rien, le monde est à portée de la main.",
      "author": "José Maria Peman",
      "sourcePage": 18
    },
    {
      "id": 922,
      "text": "Les apparences suffisent largement à faire un monde.",
      "author": "Jean Anouilh",
      "sourcePage": 18
    },
    {
      "id": 923,
      "text": "Aujourd'hui, je suis reine. Autrefois, j'étais libre.",
      "author": "Victor Hugo",
      "sourcePage": 18
    },
    {
      "id": 924,
      "text": "La folie, c'est se comporter de la même manière et s'attendre à un résultat différent.",
      "author": "Albert Einstein",
      "sourcePage": 18
    },
    {
      "id": 925,
      "text": "Quoi d'imprévu pour qui n'a rien prévu ?",
      "author": "Paul Valery",
      "sourcePage": 18
    },
    {
      "id": 926,
      "text": "Un homme est bien fort quand il s'avoue sa faiblesse.",
      "author": "Honore de Balzac",
      "sourcePage": 18
    },
    {
      "id": 927,
      "text": "Hâtons-nous de succomber à la tentation, avant qu'elle ne s'éloigne.",
      "author": "Epicure",
      "sourcePage": 18
    },
    {
      "id": 928,
      "text": "Il faut rire avant d'être heureux, de peur de mourir sans avoir ri.",
      "author": "Jean de La Bruyère",
      "sourcePage": 18
    },
    {
      "id": 929,
      "text": "Les enfants ont plus besoin de modèles que de critiques.",
      "author": "Joseph Joubert",
      "sourcePage": 18
    },
    {
      "id": 930,
      "text": "Nous devons accepter le changement mais conserver nos principes.",
      "author": "Jimmy Carter",
      "sourcePage": 18
    },
    {
      "id": 931,
      "text": "Derrière chaque livre il y a un homme.",
      "author": "Ray Bradbury",
      "sourcePage": 18
    },
    {
      "id": 932,
      "text": "J'ai accompli de délicieux voyages, embarqué sur un mot...",
      "author": "Honore de Balzac",
      "sourcePage": 18
    },
    {
      "id": 933,
      "text": "La science n'a pas de patrie.",
      "author": "Louis Pasteur",
      "sourcePage": 18
    },
    {
      "id": 934,
      "text": "On ne consulte que l'oreille parce qu'on manque de cœur.",
      "author": "Blaise Pascal",
      "sourcePage": 18
    },
    {
      "id": 935,
      "text": "Mieux vaut transmettre un art à son fils que de lui léguer mille pièces d'or.",
      "author": "Proverbe chinois",
      "sourcePage": 18
    },
    {
      "id": 936,
      "text": "Après le pain, l'éducation est le premier besoin d'un peuple.",
      "author": "Georges Jacques Danton",
      "sourcePage": 19
    },
    {
      "id": 937,
      "text": "La moitié du monde ne sait comment l'autre vit.",
      "author": "François Rabelais",
      "sourcePage": 19
    },
    {
      "id": 938,
      "text": "Le jour a des yeux, la nuit a des oreilles.",
      "author": "Proverbe persan",
      "sourcePage": 19
    },
    {
      "id": 939,
      "text": "Comment penser le monde si on ne sait pas le rêver ?",
      "author": "Denis Roche",
      "sourcePage": 19
    },
    {
      "id": 940,
      "text": "Un peu de folie est nécessaire pour faire un pas de plus.",
      "author": "Paulo Coelho",
      "sourcePage": 19
    },
    {
      "id": 941,
      "text": "Il faut faire vite ce qui ne presse pas pour pouvoir faire lentement ce qui presse.",
      "author": "Proverbe chinois",
      "sourcePage": 19
    },
    {
      "id": 942,
      "text": "Il faut avoir déjà beaucoup appris de choses pour savoir demander ce qu'on ne sait pas.",
      "author": "Jean- Jacques Rousseau",
      "sourcePage": 19
    },
    {
      "id": 943,
      "text": "Les cœurs les plus proches ne sont pas ceux qui se touchent.",
      "author": "Proverbe chinois",
      "sourcePage": 19
    },
    {
      "id": 944,
      "text": "Ne rien livrer au hasard, c'est économiser du travail.",
      "author": "Antoine Albalat",
      "sourcePage": 19
    },
    {
      "id": 945,
      "text": "Rien ne sert de courir si l'on n'est pas pressé.",
      "author": "Pierre Dac",
      "sourcePage": 19
    },
    {
      "id": 946,
      "text": "Un homme n'est que ce qu'il sait.",
      "author": "Francis Bacon",
      "sourcePage": 19
    },
    {
      "id": 947,
      "text": "On ne fait jamais attention à ce qui a été fait ; on ne voit que ce qui reste à faire.",
      "author": "Marie Curie",
      "sourcePage": 19
    },
    {
      "id": 948,
      "text": "Croyez pour être forts. Aimez pour être heureux.",
      "author": "Victor Hugo",
      "sourcePage": 19
    },
    {
      "id": 949,
      "text": "Rien n'est jamais acquis à l'homme.",
      "author": "Louis Aragon",
      "sourcePage": 19
    },
    {
      "id": 950,
      "text": "Ce que chacun fait, il le décide.",
      "author": "Virginie Despentes",
      "sourcePage": 19
    },
    {
      "id": 951,
      "text": "En buvant l'eau du puits, n'oubliez pas ceux qui l'ont creusé.",
      "author": "Proverbe chinois",
      "sourcePage": 19
    },
    {
      "id": 952,
      "text": "Les bonnes résolutions ne gagnent pas à être différées.",
      "author": "Jules Romains",
      "sourcePage": 19
    },
    {
      "id": 953,
      "text": "Les peuples qui n'ont plus de voix n'en ont pas moins de la mémoire.",
      "author": "Benjamin Constant",
      "sourcePage": 19
    },
    {
      "id": 954,
      "text": "Vivre, c'est changer du temps en expérience.",
      "author": "Caleb Gattegno",
      "sourcePage": 19
    },
    {
      "id": 955,
      "text": "Un lac réfléchit mieux les étoiles qu'une rivière.",
      "author": "Théodore Jouffroy",
      "sourcePage": 19
    },
    {
      "id": 956,
      "text": "Un changement en prépare un autre.",
      "author": "Nicolas Machiavel",
      "sourcePage": 19
    },
    {
      "id": 957,
      "text": "C'est presque tout que de savoir lire.",
      "author": "Alain",
      "sourcePage": 19
    },
    {
      "id": 958,
      "text": "Notre vraie nationalité est l'humanité.",
      "author": "Herbert George Wells",
      "sourcePage": 19
    },
    {
      "id": 959,
      "text": "Il est extrêmement rare que la montagne soit abrupte de tous côtés.",
      "author": "André Gide",
      "sourcePage": 19
    },
    {
      "id": 960,
      "text": "Il y a un autre monde mais il est dans celui-ci.",
      "author": "Paul Eluard",
      "sourcePage": 19
    },
    {
      "id": 961,
      "text": "Nos enfants, c'est notre éternité.",
      "author": "Robert Debré",
      "sourcePage": 19
    },
    {
      "id": 962,
      "text": "Les détails font la perfection, et la perfection n'est pas un détail.",
      "author": "Léonard de Vinci",
      "sourcePage": 19
    },
    {
      "id": 963,
      "text": "C'est peut-être au dehors que l'on guette, mais c'est toujours au fond de soi que l'on attend.",
      "author": "Jérôme Touzalin",
      "sourcePage": 19
    },
    {
      "id": 964,
      "text": "Ce n'est pas parce qu'un problème n'a pas été résolu qu'il est impossible à résoudre.",
      "author": "Agatha Christie",
      "sourcePage": 19
    },
    {
      "id": 965,
      "text": "Un rêve est la moitié d'une réalité.",
      "author": "Joseph Joubert",
      "sourcePage": 19
    },
    {
      "id": 966,
      "text": "Il n'y a que les montagnes qui ne se rencontrent jamais.",
      "author": "Proverbe français",
      "sourcePage": 19
    },
    {
      "id": 967,
      "text": "L'obstacle nous fait grands.",
      "author": "André de Chénier",
      "sourcePage": 19
    },
    {
      "id": 968,
      "text": "Un livre est une fenêtre par laquelle on s'évade.",
      "author": "Julien Green",
      "sourcePage": 19
    },
    {
      "id": 969,
      "text": "La gaieté, la santé changent l'hiver en été.",
      "author": "Antoine Désaugiers",
      "sourcePage": 19
    },
    {
      "id": 970,
      "text": "Le lève du soleil ne dure pas toute la matinée.",
      "author": "George Harrison",
      "sourcePage": 19
    },
    {
      "id": 971,
      "text": "Tous pour un, un pour tous !",
      "author": "Alexandre Dumas",
      "sourcePage": 19
    },
    {
      "id": 972,
      "text": "Le véritable trésor, c'est de pouvoir compter sur les autres.",
      "author": "Massa Makan Diabaté",
      "sourcePage": 19
    },
    {
      "id": 973,
      "text": "Tout ce qui se ressemble n'est pas identique.",
      "author": "William Shakespeare",
      "sourcePage": 19
    },
    {
      "id": 974,
      "text": "Qu'importe aux cœurs unis ce qui change autour d'eux ?",
      "author": "Alphonse de Lamartine",
      "sourcePage": 19
    },
    {
      "id": 975,
      "text": "La barbe ne fait pas le philosophe.",
      "author": "Plutarque",
      "sourcePage": 19
    },
    {
      "id": 976,
      "text": "Il faut casser le noyau pour avoir l'amande.",
      "author": "Plaute",
      "sourcePage": 19
    },
    {
      "id": 977,
      "text": "Une âme est plus grande qu'un monde.",
      "author": "Victor Hugo",
      "sourcePage": 19
    },
    {
      "id": 978,
      "text": "Un grain de gaieté assaisonne tout.",
      "author": "Baltasar Gracian Y Morales",
      "sourcePage": 19
    },
    {
      "id": 979,
      "text": "Qu'est-ce que je me serais ennuyé si je n'avais pas été là.",
      "author": "Jules Renard",
      "sourcePage": 19
    },
    {
      "id": 980,
      "text": "Les hommes construisent trop de murs et pas assez de ponts.",
      "author": "Isaac Newton",
      "sourcePage": 19
    },
    {
      "id": 981,
      "text": "Les hommes ne peuvent être s'ils ne sont pas libres.",
      "author": "Salvador Espriu",
      "sourcePage": 19
    },
    {
      "id": 982,
      "text": "Les bonnes idées n'ont pas d'âge, elles ont seulement de l'avenir.",
      "author": "Robert Mallet",
      "sourcePage": 19
    },
    {
      "id": 983,
      "text": "Le monde progresse grâce aux choses impossibles qui ont été réalisées.",
      "author": "André Maurois",
      "sourcePage": 19
    },
    {
      "id": 984,
      "text": "Le destin est ce que la vie fait de nos désirs.",
      "author": "Gustave Parking",
      "sourcePage": 19
    },
    {
      "id": 985,
      "text": "Il faut savoir résister au pessimisme des autres.",
      "author": "Guy Bedos",
      "sourcePage": 19
    },
    {
      "id": 986,
      "text": "Certains sentent la pluie à l'avance : d'autres se contentent d'être mouillés.",
      "author": "Henry Miller",
      "sourcePage": 19
    },
    {
      "id": 987,
      "text": "On ne peut admirer en même temps la lune, la neige et les fleurs.",
      "author": "Proverbe japonais",
      "sourcePage": 19
    },
    {
      "id": 988,
      "text": "Le bonheur, c'est quand le temps s'arrête.",
      "author": "Gilbert Cesbron",
      "sourcePage": 19
    },
    {
      "id": 989,
      "text": "Une vie sans chocolat est une vie à laquelle manque l'essentiel.",
      "author": "Marcia Colman et Frederic Morton",
      "sourcePage": 19
    },
    {
      "id": 990,
      "text": "A chaque enfant qui naît, le monde recommence.",
      "author": "Gilbert Bécaud",
      "sourcePage": 19
    },
    {
      "id": 991,
      "text": "La porte la mieux fermée est celle qu'on peut laisser ouverte.",
      "author": "Proverbe chinois",
      "sourcePage": 19
    },
    {
      "id": 992,
      "text": "Ce qu'on risque révèle ce qu'on vaut.",
      "author": "Jeanette Winterson",
      "sourcePage": 19
    },
    {
      "id": 993,
      "text": "Les querelles ne dureraient pas longtemps si le tort n'était que d'un côté.",
      "author": "La Rochefoucauld",
      "sourcePage": 19
    },
    {
      "id": 994,
      "text": "La grandeur d'un destin se fait de ce qu'on refuse plus que de ce qu'on obtient.",
      "author": "Françoise Chandernagor",
      "sourcePage": 20
    },
    {
      "id": 995,
      "text": "Un réveil d'enfants, c'est une ouverture de fleurs.",
      "author": "Victor Hugo",
      "sourcePage": 20
    },
    {
      "id": 996,
      "text": "Il n'est pas d'hiver sans neige, de printemps sans soleil, et de joie sans être partagée.",
      "author": "Proverbe serbe",
      "sourcePage": 20
    },
    {
      "id": 997,
      "text": "Mon idée du ciel : manger du foie gras au son des trompettes.",
      "author": "Sydney Smith",
      "sourcePage": 20
    },
    {
      "id": 998,
      "text": "La joie est pareille à un fleuve : rien n'arrête son cours.",
      "author": "Henry Miller",
      "sourcePage": 20
    },
    {
      "id": 999,
      "text": "C'est surtout quand les journées paraissent longues que les années passent vite.",
      "author": "Alfred Capus",
      "sourcePage": 20
    },
    {
      "id": 1000,
      "text": "Nul ne peut atteindre l'aube sans passer par le chemin de la nuit.",
      "author": "Khalil Gibran",
      "sourcePage": 20
    },
    {
      "id": 1001,
      "text": "Il n'y a pas de fin. Il n'y a pas de début. Il n'y a que la passion infinie de la vie.",
      "author": "Federico Fellini",
      "sourcePage": 20
    },
    {
      "id": 1002,
      "text": "- Je vous apporte mes vœux. - Merci, je tacherai d'en faire quelque chose.",
      "author": "Jules Renard",
      "sourcePage": 20
    },
    {
      "id": 1003,
      "text": "Il n'est aucune chose qui aille plus vite que les années.",
      "author": "Léonard de Vinci",
      "sourcePage": 20
    },
    {
      "id": 1004,
      "text": "Le monde est à la volonté bien plus qu'à la sagesse.",
      "author": "Henri-Frédéric Amiel",
      "sourcePage": 20
    },
    {
      "id": 1005,
      "text": "La joie des autres est une grande part de la nôtre.",
      "author": "Ernest Renan",
      "sourcePage": 20
    },
    {
      "id": 1006,
      "text": "Les esprits sont comme les parachutes. Ils ne fonctionnent que quand ils sont ouverts.",
      "author": "Louis Pauwels",
      "sourcePage": 20
    },
    {
      "id": 1007,
      "text": "Il vaut mieux reverdir que d'être toujours vert.",
      "author": "Madame de Sévigné",
      "sourcePage": 20
    },
    {
      "id": 1008,
      "text": "Ce n'est pas seulement le monde qu'il s'agit de changer ; mais l'homme.",
      "author": "André Gide",
      "sourcePage": 20
    },
    {
      "id": 1009,
      "text": "Il vaut mieux ne pas faire le voyage que s'arrêter en chemin.",
      "author": "Michel Polac",
      "sourcePage": 20
    },
    {
      "id": 1010,
      "text": "Le bonheur, c'est d'être heureux ; ce n'est pas de faire croire aux autres qu'on l'est.",
      "author": "Jules Renard",
      "sourcePage": 20
    },
    {
      "id": 1011,
      "text": "L'homme n'est pas son propre présent. Il est son propre avenir.",
      "author": "Constantin Noica",
      "sourcePage": 20
    },
    {
      "id": 1012,
      "text": "Mettez tous vos œufs dans le même panier - et surveillez le panier.",
      "author": "Mark Twain",
      "sourcePage": 20
    },
    {
      "id": 1013,
      "text": "Un bon conseil vaut mieux que de le suivre.",
      "author": "Ambrose Bierce",
      "sourcePage": 20
    },
    {
      "id": 1014,
      "text": "Ce n'est pas l'abondance, mais l'excellence qui est richesse.",
      "author": "Joseph Joubert",
      "sourcePage": 20
    },
    {
      "id": 1015,
      "text": "Le fleuve le plus large, on le passe à la source.",
      "author": "Publius Syrus",
      "sourcePage": 20
    },
    {
      "id": 1016,
      "text": "Ce qui compte c'est d'être vivant et le savoir.",
      "author": "Robert Lalonde",
      "sourcePage": 20
    },
    {
      "id": 1017,
      "text": "Ne faut-il pas avoir perdu du temps pour en apprécier la valeur ?",
      "author": "Jacques Lamarche",
      "sourcePage": 20
    },
    {
      "id": 1018,
      "text": "Il s'agit moins de penser davantage que de penser autrement.",
      "author": "Jean-Marie Domenach",
      "sourcePage": 20
    },
    {
      "id": 1019,
      "text": "Le seul moment où une femme réussit à changer un homme, c'est quand il est bébé.",
      "author": "Natalie Wood",
      "sourcePage": 20
    },
    {
      "id": 1020,
      "text": "Les résolutions sont comme les anguilles ; on les prend aisément. Le diable est de les tenir.",
      "author": "Alexandre Dumas, fils",
      "sourcePage": 20
    },
    {
      "id": 1021,
      "text": "L'événement à venir projette son ombre.",
      "author": "Thomas Campbell",
      "sourcePage": 20
    },
    {
      "id": 1022,
      "text": "Lorsque deux forces sont jointes, leur efficacité est double.",
      "author": "Isaac Newton",
      "sourcePage": 20
    },
    {
      "id": 1023,
      "text": "Il faut agir en homme de pensée et penser en homme d'action.",
      "author": "Henri Bergson",
      "sourcePage": 20
    },
    {
      "id": 1024,
      "text": "Quelqu'un qui ne laisse pas la réalité déranger ses rêves est un sage.",
      "author": "Christiane Singer",
      "sourcePage": 20
    },
    {
      "id": 1025,
      "text": "Il vaut mieux fortifier ses points forts que combler ses points faibles.",
      "author": "Bernard Werber",
      "sourcePage": 20
    },
    {
      "id": 1026,
      "text": "L'amour est comme la rougeole, plus on l'attrape tard, plus le mal est sérieux.",
      "author": "Douglas Jerrold",
      "sourcePage": 20
    },
    {
      "id": 1027,
      "text": "Les épines que j'ai recueillies viennent de l'arbre que j'ai planté.",
      "author": "Lord Byron",
      "sourcePage": 20
    },
    {
      "id": 1028,
      "text": "Ce qui est maintenant prouvé ne fut jadis qu'imaginé.",
      "author": "William Blake",
      "sourcePage": 20
    },
    {
      "id": 1029,
      "text": "On perd ce que l'on tient quant on veut gagner tout.",
      "author": "Jean-Pierre Florian",
      "sourcePage": 20
    },
    {
      "id": 1030,
      "text": "L'indifférence est une infirmité de l'esprit et du cœur.",
      "author": "Françoise Giroud",
      "sourcePage": 20
    },
    {
      "id": 1031,
      "text": "La perle est sans valeur dans sa propre coquille.",
      "author": "Proverbe indien",
      "sourcePage": 20
    },
    {
      "id": 1032,
      "text": "Les sentiers battus n'offrent guère de richesse ; les autres en sont pleins.",
      "author": "Jean Giono",
      "sourcePage": 20
    },
    {
      "id": 1033,
      "text": "Le fond du cœur est plus loin que le bout du monde.",
      "author": "Proverbe chinois",
      "sourcePage": 20
    },
    {
      "id": 1034,
      "text": "Etre intelligent, c'est être méfiant, même à l'égard de soi-même.",
      "author": "Paul Léautaud",
      "sourcePage": 20
    },
    {
      "id": 1035,
      "text": "La nature fait les hommes semblables, la vie les rend différents.",
      "author": "Confucius",
      "sourcePage": 20
    },
    {
      "id": 1036,
      "text": "Il y a des miroirs pour le visage, il n'y en a pas pour l'esprit.",
      "author": "Baltasar Gracian Y Morales",
      "sourcePage": 20
    },
    {
      "id": 1037,
      "text": "L'homme est fait pour attendre, et la femme pour être inattendue.",
      "author": "Gérard de Rohan Chabot",
      "sourcePage": 20
    },
    {
      "id": 1038,
      "text": "Ce n'est pas le gouffre qui sépare, mais la différence de niveau.",
      "author": "Stanislaw Jerzy Lec",
      "sourcePage": 20
    },
    {
      "id": 1039,
      "text": "Aimer, c'est se surpasser.",
      "author": "Oscar Wilde",
      "sourcePage": 20
    },
    {
      "id": 1040,
      "text": "Mais que peuvent contre la destinée les plus fermes résolutions ?",
      "author": "Catulle Mendès",
      "sourcePage": 20
    },
    {
      "id": 1041,
      "text": "Punir l'échec est le meilleur moyen pour que personne n'ose.",
      "author": "Jack Welch",
      "sourcePage": 20
    },
    {
      "id": 1042,
      "text": "L'éponge absorbe, mais il faut la presser pour qu'elle s'exprime.",
      "author": "Proverbe allemand",
      "sourcePage": 20
    },
    {
      "id": 1043,
      "text": "En toute chose, l'on ne reçoit qu'en raison de ce que l'on donne.",
      "author": "Honoré de Balzac",
      "sourcePage": 20
    },
    {
      "id": 1044,
      "text": "Tant d'énergie est dépensée pour que tout soit bien immobile.",
      "author": "Bernard Werber",
      "sourcePage": 20
    },
    {
      "id": 1045,
      "text": "La patience vient mieux à bout des entreprises que la force.",
      "author": "Plutarque",
      "sourcePage": 20
    },
    {
      "id": 1046,
      "text": "Je suis venu pour te voler cent millions de baisers.",
      "author": "Serge Gainsbourg",
      "sourcePage": 20
    },
    {
      "id": 1047,
      "text": "Mieux vaut réfléchir avant d'agir que regretter après avoir agi.",
      "author": "Démocrite",
      "sourcePage": 20
    },
    {
      "id": 1048,
      "text": "La vie est trop courte pour être petite.",
      "author": "Benjamin Disraeli",
      "sourcePage": 20
    },
    {
      "id": 1049,
      "text": "Qui veut changer trouvera toujours une bonne raison pour changer.",
      "author": "André Maurois",
      "sourcePage": 20
    },
    {
      "id": 1050,
      "text": "Le moment présent a un avantage sur tous les autres : il nous appartient.",
      "author": "Charles Caleb Colton",
      "sourcePage": 20
    },
    {
      "id": 1051,
      "text": "Le premier signe de l'ignorance, c'est de présumer que l'on sait.",
      "author": "Baltasar Gracian Y Morales",
      "sourcePage": 21
    },
    {
      "id": 1052,
      "text": "Il fait bon partout où l'on respire l'air de la liberté.",
      "author": "Emile Leclercq",
      "sourcePage": 21
    },
    {
      "id": 1053,
      "text": "Les esprits mobiles ne sont pas garantis contre les idées fixes.",
      "author": "Aymond d'Alost",
      "sourcePage": 21
    },
    {
      "id": 1054,
      "text": "Le travail, c'est bon pour ceux qui n'ont rien à faire.",
      "author": "Henri Jeanson",
      "sourcePage": 21
    },
    {
      "id": 1055,
      "text": "Ne vous mettez pas en avant, mais ne restez pas en arrière.",
      "author": "Proverbe chinois",
      "sourcePage": 21
    },
    {
      "id": 1056,
      "text": "On ne se découvre qu'en se tournant vers ce que l'on n'est pas.",
      "author": "Paul Auster",
      "sourcePage": 21
    },
    {
      "id": 1057,
      "text": "Ce sont les folles idées qui bâtissent le monde.",
      "author": "Paul Boudreau",
      "sourcePage": 21
    },
    {
      "id": 1058,
      "text": "C'est toujours ce qui éclaire qui demeure dans l'ombre.",
      "author": "Edgar Morin",
      "sourcePage": 21
    },
    {
      "id": 1059,
      "text": "Sur les chemins sans risques on n'envoie que les faibles.",
      "author": "Hermann Hesse",
      "sourcePage": 21
    },
    {
      "id": 1060,
      "text": "La vérité est le meilleur argument.",
      "author": "Hazrat Ali",
      "sourcePage": 21
    },
    {
      "id": 1061,
      "text": "Ou on tire les ficelles, ou on essaie de s'en débarrasser.",
      "author": "Paul Newman",
      "sourcePage": 21
    },
    {
      "id": 1062,
      "text": "Les succès personnels sont le but des âmes inférieures.",
      "author": "Louis Lafferre",
      "sourcePage": 21
    },
    {
      "id": 1063,
      "text": "Ne désirer que ce qu'on a, c'est avoir tout ce qu'on désire.",
      "author": "Jean Chardin",
      "sourcePage": 21
    },
    {
      "id": 1064,
      "text": "Il y a une différence entre vivre et exister.",
      "author": "Peggy Boucher",
      "sourcePage": 21
    },
    {
      "id": 1065,
      "text": "La vraie république : aux hommes leurs droits et rien de plus, aux femmes leurs droits et rien de moins.",
      "author": "Susan Anthony",
      "sourcePage": 21
    },
    {
      "id": 1066,
      "text": "Il fait froid, parce que l'on regarde là où il n'y a pas de chaleur.",
      "author": "Alexandra David-Neel",
      "sourcePage": 21
    },
    {
      "id": 1067,
      "text": "Nous trouverons un chemin... ou nous en créerons un.",
      "author": "Hannibal",
      "sourcePage": 21
    },
    {
      "id": 1068,
      "text": "S'éloigner de tout rapproche un peu de l'essentiel.",
      "author": "Loick Peyron",
      "sourcePage": 21
    },
    {
      "id": 1069,
      "text": "Vous devez être le changement que vous voulez voir dans ce monde.",
      "author": "Gandhi",
      "sourcePage": 21
    },
    {
      "id": 1070,
      "text": "On fait tout pour gagner un cœur et bien peu pour le garder.",
      "author": "Jacques Deval",
      "sourcePage": 21
    },
    {
      "id": 1071,
      "text": "Un mot aimable est comme un jour de printemps.",
      "author": "Proverbe russe",
      "sourcePage": 21
    },
    {
      "id": 1072,
      "text": "Internet. On ne sait pas ce qu'on y cherche mais on trouve tout ce qu'on ne cherche pas.",
      "author": "Anne Roumanoff",
      "sourcePage": 21
    },
    {
      "id": 1073,
      "text": "Quand un peuple n'ose plus défendre sa langue, il est mur pour l'esclavage.",
      "author": "Remy de Gourmont",
      "sourcePage": 21
    },
    {
      "id": 1074,
      "text": "Demain est moins à découvrir qu'à inventer.",
      "author": "Gaston Berger",
      "sourcePage": 21
    },
    {
      "id": 1075,
      "text": "On risque autant à croire trop qu'à croire trop peu.",
      "author": "Denis Diderot",
      "sourcePage": 21
    },
    {
      "id": 1076,
      "text": "Quand je pense à tous les livres qu'il me reste à lire, j'ai la certitude d'être encore heureux.",
      "author": "Jules Renard",
      "sourcePage": 21
    },
    {
      "id": 1077,
      "text": "Si vous fermez la porte à toutes les erreurs, la vérité restera dehors.",
      "author": "Rabindranath Tagore",
      "sourcePage": 21
    },
    {
      "id": 1078,
      "text": "Le goéland qui voit le plus loin vole le plus haut.",
      "author": "Richard Bach",
      "sourcePage": 21
    },
    {
      "id": 1079,
      "text": "Nous leur demandons seulement d'aimer leur prochain autant que leur voiture.",
      "author": "Gilbert Cesbron",
      "sourcePage": 21
    },
    {
      "id": 1080,
      "text": "Il vaut mieux suivre le bon chemin en boitant que le mauvais d'un pas ferme.",
      "author": "Saint Augustin",
      "sourcePage": 21
    },
    {
      "id": 1081,
      "text": "La vie, ça se fabrique avec les moyens du bord.",
      "author": "Hervé Bazin",
      "sourcePage": 21
    },
    {
      "id": 1082,
      "text": "Le travail de la jeunesse fait le repos de la vieillesse.",
      "author": "Proverbe grec antique",
      "sourcePage": 21
    },
    {
      "id": 1083,
      "text": "La vie qui aurait pu être est cachée dans la vie qui est.",
      "author": "Njabulo S. Ndebele",
      "sourcePage": 21
    },
    {
      "id": 1084,
      "text": "Si tu n'as jamais marché sur les pieds de quelqu'un, tu n'es jamais allé te promener.",
      "author": "Barbara Kingsolver",
      "sourcePage": 21
    },
    {
      "id": 1085,
      "text": "Quand on ne sait où l'on va, qu'on sache d'où l'on vient.",
      "author": "Ahmadou Kourouma",
      "sourcePage": 21
    },
    {
      "id": 1086,
      "text": "Un seul trou suffit pour faire une passoire.",
      "author": "Ylipe",
      "sourcePage": 21
    },
    {
      "id": 1087,
      "text": "Les hommes ont tout perfectionné, sauf les hommes.",
      "author": "Proverbe américain",
      "sourcePage": 21
    },
    {
      "id": 1088,
      "text": "Si vous voulez vraiment rêver, réveillez-vous...",
      "author": "Daniel Pennac",
      "sourcePage": 21
    },
    {
      "id": 1089,
      "text": "Rien de tel que d'aller au bout du monde pour trouver des gens qui vont encore plus loin.",
      "author": "Pierre Daninos",
      "sourcePage": 21
    },
    {
      "id": 1090,
      "text": "L'humanité devra mettre un terme à la guerre, ou la guerre mettra un terme à l'humanité.",
      "author": "John Fitzgerald Kennedy",
      "sourcePage": 21
    },
    {
      "id": 1091,
      "text": "Je ne veux pas prier d'être protégé des dangers, mais de pouvoir les affronter.",
      "author": "Rabindranath Tagore",
      "sourcePage": 21
    },
    {
      "id": 1092,
      "text": "On n'a pas besoin de gravir une montagne pour savoir si elle est élevée.",
      "author": "Paulo Coelho",
      "sourcePage": 21
    },
    {
      "id": 1093,
      "text": "Moins on a de vrais problèmes, plus on en a de faux.",
      "author": "Paul Carvel",
      "sourcePage": 21
    },
    {
      "id": 1094,
      "text": "On t'accompagnera si tu trouves ta route.",
      "author": "Eugène Guillevic",
      "sourcePage": 21
    },
    {
      "id": 1095,
      "text": "On ne paie jamais trop cher le privilège d'être son propre maître.",
      "author": "Rudyard Kipling",
      "sourcePage": 21
    },
    {
      "id": 1096,
      "text": "Quand on ne pense pas à ce que l'on dit, c'est qu'on dit ce que l'on pense.",
      "author": "Jacinto Benavente",
      "sourcePage": 21
    },
    {
      "id": 1097,
      "text": "Il se noie plus de gens dans les verres que dans les rivières.",
      "author": "Georg Christoph Lichtenberg",
      "sourcePage": 21
    },
    {
      "id": 1098,
      "text": "L'indépendance, ce n'est pas une récompense, c'est une responsabilité.",
      "author": "Pierre Bourgault",
      "sourcePage": 21
    },
    {
      "id": 1099,
      "text": "Ne soyez pas si pressé de croire tout ce qu'on vous raconte.",
      "author": "Lewis Carroll",
      "sourcePage": 21
    },
    {
      "id": 1100,
      "text": "Il faudrait essayer d'être heureux, ne serait-ce que pour donner l'exemple.",
      "author": "Jacques Prévert",
      "sourcePage": 21
    },
    {
      "id": 1101,
      "text": "Tout âge porte ses fruits, il faut savoir les cueillir.",
      "author": "Raymond Radiguet",
      "sourcePage": 21
    },
    {
      "id": 1102,
      "text": "Les mères font les hommes.",
      "author": "Thomas Jefferson",
      "sourcePage": 21
    },
    {
      "id": 1103,
      "text": "Savoir partager son temps, c'est savoir jouir de la vie.",
      "author": "Baltasar Gracian Y Morales",
      "sourcePage": 21
    },
    {
      "id": 1104,
      "text": "Tes yeux sont si profonds que j'y perds la mémoire.",
      "author": "Louis Aragon",
      "sourcePage": 21
    },
    {
      "id": 1105,
      "text": "Je ne peux pas me marier. Je suis trop riche pour ça.",
      "author": "Eddie Murphy",
      "sourcePage": 21
    },
    {
      "id": 1106,
      "text": "Je me cite souvent, cela apporte du piment à ma conversation.",
      "author": "Bernard Shaw",
      "sourcePage": 22
    },
    {
      "id": 1107,
      "text": "De tous les droits de la femme, le plus grand est celui d'être mère.",
      "author": "Lin Yutang",
      "sourcePage": 22
    },
    {
      "id": 1108,
      "text": "Mon Dieu, que votre volonté soit fête !",
      "author": "Frédéric Dard",
      "sourcePage": 22
    },
    {
      "id": 1109,
      "text": "Il faut se fixer des buts avant de pouvoir les atteindre.",
      "author": "Michael Jordan",
      "sourcePage": 22
    },
    {
      "id": 1110,
      "text": "L'amour n'est pas un sentiment, c'est un art.",
      "author": "Paul Morand",
      "sourcePage": 22
    },
    {
      "id": 1111,
      "text": "L'Homme a besoin de passion pour exister.",
      "author": "Eric Tabarly",
      "sourcePage": 22
    },
    {
      "id": 1112,
      "text": "Il ne s'agit pas de beaucoup lire, mais de bien lire.",
      "author": "Aristippe",
      "sourcePage": 22
    },
    {
      "id": 1113,
      "text": "C'est l'esprit qui mène le monde et non l'intelligence.",
      "author": "Antoine de Saint-Exupéry",
      "sourcePage": 22
    },
    {
      "id": 1114,
      "text": "Pensez faux, s'il vous plaît, mais surtout pensez par vous-même.",
      "author": "Doris Lessing",
      "sourcePage": 22
    },
    {
      "id": 1115,
      "text": "Cœur insouciant vit longtemps.",
      "author": "William Shakespeare",
      "sourcePage": 22
    },
    {
      "id": 1116,
      "text": "Vous aimez la liberté ? Elle habite la campagne.",
      "author": "Andres Bello",
      "sourcePage": 22
    },
    {
      "id": 1117,
      "text": "Comment vivre sans inconnu devant soi ?",
      "author": "René Char",
      "sourcePage": 22
    },
    {
      "id": 1118,
      "text": "On voyage pour changer, non de lieu, mais d'idées.",
      "author": "Hippolyte Taine",
      "sourcePage": 22
    },
    {
      "id": 1119,
      "text": "Il faut regarder la vie en farce.",
      "author": "Louis Scutenaire",
      "sourcePage": 22
    },
    {
      "id": 1120,
      "text": "Nul ne s'est jamais perdu dans le droit chemin.",
      "author": "Goethe",
      "sourcePage": 22
    },
    {
      "id": 1121,
      "text": "L'habituel défaut de l'homme est de ne pas prévoir l'orage par beau temps.",
      "author": "Nicolas Machiavel",
      "sourcePage": 22
    },
    {
      "id": 1122,
      "text": "A deux, nul versant n'est trop raide.",
      "author": "Henrik Ibsen",
      "sourcePage": 22
    },
    {
      "id": 1123,
      "text": "Il faut souffler sur quelques lueurs pour faire de la bonne lumière.",
      "author": "René Char",
      "sourcePage": 22
    },
    {
      "id": 1124,
      "text": "La joie n'est pas dans les choses, elle est en nous.",
      "author": "Richard Wagner",
      "sourcePage": 22
    },
    {
      "id": 1125,
      "text": "Une fois, c'est une erreur, deux fois, c'est une mauvaise habitude.",
      "author": "Proverbe québécois",
      "sourcePage": 22
    },
    {
      "id": 1126,
      "text": "On ne dit jamais rien parce qu'on parle tout le temps.",
      "author": "Eric-Emmanuel Schmitt",
      "sourcePage": 22
    },
    {
      "id": 1127,
      "text": "L'intéressant, ce n'est pas de savoir d'où vient le monde, mais où il va.",
      "author": "Quino",
      "sourcePage": 22
    },
    {
      "id": 1128,
      "text": "L'homme moderne perd son temps à essayer de le gagner.",
      "author": "Noël Mamère",
      "sourcePage": 22
    },
    {
      "id": 1129,
      "text": "L'aventure c'est le trésor que l'on découvre à chaque matin.",
      "author": "Jacques Brel",
      "sourcePage": 22
    },
    {
      "id": 1130,
      "text": "La pire décision de toutes est celle que l'on n'a pas prise.",
      "author": "Zig Ziglar",
      "sourcePage": 22
    },
    {
      "id": 1131,
      "text": "Le monde du partage devra remplacer le partage du monde.",
      "author": "Claude Lelouch",
      "sourcePage": 22
    },
    {
      "id": 1132,
      "text": "Le chemin se construit en marchant.",
      "author": "Antonio Machado",
      "sourcePage": 22
    },
    {
      "id": 1133,
      "text": "Beaucoup des choses que l'on fait ne le sont que pour faire plaisir aux autres.",
      "author": "Bjork",
      "sourcePage": 22
    },
    {
      "id": 1134,
      "text": "L'amour, c'est comme si jamais on n'avait respiré.",
      "author": "Georges Perros",
      "sourcePage": 22
    },
    {
      "id": 1135,
      "text": "Les désirs ne peuvent s'étendre à ce que l'on ne connaît pas.",
      "author": "Ovide",
      "sourcePage": 22
    },
    {
      "id": 1136,
      "text": "En faisant scintiller notre lumière, nous offrons aux autres la possibilité d'en faire autant.",
      "author": "Nelson Mandela",
      "sourcePage": 22
    },
    {
      "id": 1137,
      "text": "Si vous possédez une bibliothèque et un jardin, vous avez tout ce qu'il vous faut.",
      "author": "Cicéron",
      "sourcePage": 22
    },
    {
      "id": 1138,
      "text": "J'ai trouvé le chaînon manquant entre le singe et l'Homme : c'est nous !",
      "author": "Konrad Lorenz",
      "sourcePage": 22
    },
    {
      "id": 1139,
      "text": "Le monde est un spectacle à regarder et non un problème à résoudre.",
      "author": "Jules de Gaultier",
      "sourcePage": 22
    },
    {
      "id": 1140,
      "text": "Les destins conduisent celui qui veut, ils traînent celui qui ne veut pas.",
      "author": "Sénèque",
      "sourcePage": 22
    },
    {
      "id": 1141,
      "text": "Vis comme si tu devais mourir demain. Apprends comme si tu devais vivre toujours.",
      "author": "Gandhi",
      "sourcePage": 22
    },
    {
      "id": 1142,
      "text": "Les roses poussent parmi les épines.",
      "author": "Proverbe latin",
      "sourcePage": 22
    },
    {
      "id": 1143,
      "text": "Si vous allez trop loin, vous n'irez nulle part.",
      "author": "Jacques Monod",
      "sourcePage": 22
    },
    {
      "id": 1144,
      "text": "Ceux qui rient beaucoup sont plus heureux que ceux qui rient peu.",
      "author": "Giovanni Casanova",
      "sourcePage": 22
    },
    {
      "id": 1145,
      "text": "Je t'aime, tu t'aimes, on sème.",
      "author": "Maurice Chapelan",
      "sourcePage": 22
    },
    {
      "id": 1146,
      "text": "Les bonnes habitudes sont beaucoup plus faciles à perdre que les mauvaises.",
      "author": "Somerset Maugham",
      "sourcePage": 22
    },
    {
      "id": 1147,
      "text": "Il faut que le hasard renverse la fourmi pour qu'elle voit le ciel.",
      "author": "Proverbe arabe",
      "sourcePage": 22
    },
    {
      "id": 1148,
      "text": "Les hommes gagnent des diplômes et perdent leur instinct.",
      "author": "Francis Picabia",
      "sourcePage": 22
    },
    {
      "id": 1149,
      "text": "On ne mordra jamais assez dans son propre cerveau.",
      "author": "Tristan Tzara",
      "sourcePage": 22
    },
    {
      "id": 1150,
      "text": "Les petites fantaisies font les grandes carrières.",
      "author": "Theodore Fraenkel",
      "sourcePage": 22
    },
    {
      "id": 1151,
      "text": "Le cœur découvre, la tête invente.",
      "author": "Arthur Cravan",
      "sourcePage": 22
    },
    {
      "id": 1152,
      "text": "Moins on a de pouvoir, plus on aime à en user.",
      "author": "Jules Petit-Senn",
      "sourcePage": 22
    },
    {
      "id": 1153,
      "text": "Aucun chemin de fleurs ne conduit à la gloire.",
      "author": "Jean de La Fontaine",
      "sourcePage": 22
    },
    {
      "id": 1154,
      "text": "Quiconque sauve une vie sauve le monde entier.",
      "author": "Steven Spielberg",
      "sourcePage": 22
    },
    {
      "id": 1155,
      "text": "La vie se goûte à l'appétit de tous les jours.",
      "author": "Marc Levy",
      "sourcePage": 22
    },
    {
      "id": 1156,
      "text": "Au pays du rêve, nul n'est interdit de séjour.",
      "author": "Julos Beaucarne",
      "sourcePage": 22
    },
    {
      "id": 1157,
      "text": "La seule liberté, c'est de choisir son destin.",
      "author": "Claire de Lamirande",
      "sourcePage": 22
    },
    {
      "id": 1158,
      "text": "Il n'y a que l'argent qui aide à oublier qu'on n'est pas riche.",
      "author": "Philippe Bouvard",
      "sourcePage": 22
    },
    {
      "id": 1159,
      "text": "Les enfants trouvent tout d'un rien, les hommes ne trouvent rien dans tout.",
      "author": "Giacomo Leopardi",
      "sourcePage": 22
    },
    {
      "id": 1160,
      "text": "Tous les voyages commencent chez soi.",
      "author": "Allan Gurganus",
      "sourcePage": 22
    },
    {
      "id": 1161,
      "text": "Qui ne demande rien, c'est qu'il attend tout.",
      "author": "Jean Rostand",
      "sourcePage": 22
    },
    {
      "id": 1162,
      "text": "Il ne faut jamais croire ce qu'on est disposé à croire.",
      "author": "Eric-Emmanuel Schmitt",
      "sourcePage": 22
    },
    {
      "id": 1163,
      "text": "Se pencher sur son passé, c'est risquer de tomber dans l'oubli.",
      "author": "Coluche",
      "sourcePage": 22
    },
    {
      "id": 1164,
      "text": "La vie est courte mais très large.",
      "author": "Jim Harrison",
      "sourcePage": 22
    },
    {
      "id": 1165,
      "text": "Plus on plaît, plus on déplaît.",
      "author": "Francis Picabia",
      "sourcePage": 22
    },
    {
      "id": 1166,
      "text": "Deux manières de briller : rejeter la lumière ou la produire.",
      "author": "Paul Claudel",
      "sourcePage": 23
    },
    {
      "id": 1167,
      "text": "Je trouve mes plus grands bonheurs dans les petits plaisirs.",
      "author": "Françoise Chandernagor",
      "sourcePage": 23
    },
    {
      "id": 1168,
      "text": "La nécessité est la mère de l'invention.",
      "author": "Platon",
      "sourcePage": 23
    },
    {
      "id": 1169,
      "text": "Je ne perds jamais de vue que le seul fait d'exister est une chance.",
      "author": "Katharine Hepburn",
      "sourcePage": 23
    },
    {
      "id": 1170,
      "text": "On ne fait jamais rien pour une seule raison.",
      "author": "Samuel Taylor Coleridge",
      "sourcePage": 23
    },
    {
      "id": 1171,
      "text": "Il y a toujours un rêve qui veille.",
      "author": "Paul Eluard",
      "sourcePage": 23
    },
    {
      "id": 1172,
      "text": "Tout le monde a un secret désir d'étonner les autres.",
      "author": "Rose Tremain",
      "sourcePage": 23
    },
    {
      "id": 1173,
      "text": "Ne pas pouvoir revenir en arrière est une forme de progression.",
      "author": "Frédéric Dard",
      "sourcePage": 23
    },
    {
      "id": 1174,
      "text": "Il faut apprendre partout où c'est possible.",
      "author": "Vaclav Havel",
      "sourcePage": 23
    },
    {
      "id": 1175,
      "text": "Personne n'est plus sourd que celui qui ne veut pas entendre.",
      "author": "Proverbe australien",
      "sourcePage": 23
    },
    {
      "id": 1176,
      "text": "Rien ne vaut les encouragements d'un ami.",
      "author": "Katherine Butler Hathaway",
      "sourcePage": 23
    },
    {
      "id": 1177,
      "text": "On peut toujours faire quelque chose de ce qu'on a fait de nous.",
      "author": "Jean-Paul Sartre",
      "sourcePage": 23
    },
    {
      "id": 1178,
      "text": "Le soleil ne sait rien de l'ombre.",
      "author": "Eugène Guillevic",
      "sourcePage": 23
    },
    {
      "id": 1179,
      "text": "La vie, c'est très drôle, si on prend le temps de regarder.",
      "author": "Jacques Tati",
      "sourcePage": 23
    },
    {
      "id": 1180,
      "text": "Celui qui ne veut pas se hasarder ne doit pas songer à s'élever.",
      "author": "Chevalier de Méré",
      "sourcePage": 23
    },
    {
      "id": 1181,
      "text": "Car le feu qui me brûle est celui qui m'éclaire.",
      "author": "La Boétie",
      "sourcePage": 23
    },
    {
      "id": 1182,
      "text": "Le femme nous rend poète ; l'enfant nous rend philosophe.",
      "author": "Malcolm de Chazal",
      "sourcePage": 23
    },
    {
      "id": 1183,
      "text": "Il faut exiger de chacun ce que chacun peut donner.",
      "author": "Antoine de Saint-Exupéry",
      "sourcePage": 23
    },
    {
      "id": 1184,
      "text": "Une mauvaise herbe est une plante dont on n'a pas encore trouvé les vertus.",
      "author": "Ralph Waldo Emerson",
      "sourcePage": 23
    },
    {
      "id": 1185,
      "text": "Si vous ne partez pas, vous êtes sûr de ne pas arriver.",
      "author": "Robert Anthony",
      "sourcePage": 23
    },
    {
      "id": 1186,
      "text": "La civilisation crée plus de besoin qu'elle n'en comble.",
      "author": "Bernard Grasset",
      "sourcePage": 23
    },
    {
      "id": 1187,
      "text": "L'art de la réussite consiste à savoir s'entourer des meilleurs.",
      "author": "John Fitzgerald Kennedy",
      "sourcePage": 23
    },
    {
      "id": 1188,
      "text": "Nos désirs sont comme les enfants : plus on leur cède, plus ils deviennent exigeants.",
      "author": "Proverbe chinois",
      "sourcePage": 23
    },
    {
      "id": 1189,
      "text": "Ce qui noie quelqu'un, ce n'est pas le plongeon, mais le fait de rester sous l'eau.",
      "author": "Paulo Coelho",
      "sourcePage": 23
    },
    {
      "id": 1190,
      "text": "On naît. On meurt. C'est mieux si entre les deux on a fait quelque chose.",
      "author": "Francis Bacon",
      "sourcePage": 23
    },
    {
      "id": 1191,
      "text": "Je veux être tout ce que je suis capable de devenir.",
      "author": "Katherine Mansfield",
      "sourcePage": 23
    },
    {
      "id": 1192,
      "text": "On n'est jamais si malheureux qu'on croit, ni si heureux qu'on l'avait espéré.",
      "author": "La Rochefoucauld",
      "sourcePage": 23
    },
    {
      "id": 1193,
      "text": "Détruire la concurrence, c'est tuer l'intelligence.",
      "author": "Frédéric Bastiat",
      "sourcePage": 23
    },
    {
      "id": 1194,
      "text": "Les raisons d'aimer et de vivre varient comme font les saisons.",
      "author": "Louis Aragon",
      "sourcePage": 23
    },
    {
      "id": 1195,
      "text": "Si élevé que soit l'arbre, ses feuilles tombent toujours à terre.",
      "author": "Proverbe chinois",
      "sourcePage": 23
    },
    {
      "id": 1196,
      "text": "Si un arc-en-ciel dure un quart d'heure, on ne le regarde plus.",
      "author": "Goethe",
      "sourcePage": 23
    },
    {
      "id": 1197,
      "text": "Suffit-il de n'être jamais injuste pour être toujours innocent ?",
      "author": "Jean-Jacques Rousseau",
      "sourcePage": 23
    },
    {
      "id": 1198,
      "text": "Quand on fait ce qu'on peut, on fait ce qu'on doit.",
      "author": "Madeleine de Scudéry",
      "sourcePage": 23
    },
    {
      "id": 1199,
      "text": "A-t-on déjà vu quelqu'un embrasser l'instant qui passe ?",
      "author": "François Poirié",
      "sourcePage": 23
    },
    {
      "id": 1200,
      "text": "On regarde en l'air et l'on ne voit pas ce que l'on a à ses pieds.",
      "author": "Lucien",
      "sourcePage": 23
    },
    {
      "id": 1201,
      "text": "Il faut oser d'abord, doser ensuite.",
      "author": "Karin Viard",
      "sourcePage": 23
    },
    {
      "id": 1202,
      "text": "Le même soleil fait fondre la cire et sécher l'argile.",
      "author": "Clément d'Alexandrie",
      "sourcePage": 23
    },
    {
      "id": 1203,
      "text": "Il y a en permanence un cinquième des gens qui sont contre.",
      "author": "Robert Fitzgerald Kennedy",
      "sourcePage": 23
    },
    {
      "id": 1204,
      "text": "Les crocodiles vivent cent ans ; les roses trois jours. Et pourtant, on offre des roses.",
      "author": "Michel Chrestien",
      "sourcePage": 23
    },
    {
      "id": 1205,
      "text": "Si vous ne voulez pas qu'on le sache, mieux vaut encore ne pas le faire.",
      "author": "Proverbe chinois",
      "sourcePage": 23
    },
    {
      "id": 1206,
      "text": "Le monde appartient à ceux qui n'ont pas d'heure fixe pour les repas.",
      "author": "Anne Jules de Noailles",
      "sourcePage": 23
    },
    {
      "id": 1207,
      "text": "Toutes les soifs n'ont pas à être apaisées.",
      "author": "Stephen King",
      "sourcePage": 23
    },
    {
      "id": 1208,
      "text": "Je travaille à être heureux : c'est le plus beau des métiers.",
      "author": "Roland de Lassus",
      "sourcePage": 23
    },
    {
      "id": 1209,
      "text": "On n'aime que ce qu'on ne possède pas tout entier.",
      "author": "Marcel Proust",
      "sourcePage": 23
    },
    {
      "id": 1210,
      "text": "L'enfant n'est pas un vase qu'on emplit, mais un feu qu'on allume.",
      "author": "Cécile B. Loupan",
      "sourcePage": 23
    },
    {
      "id": 1211,
      "text": "Le seul homme à ne jamais faire d'erreurs est celui qui ne fait rien.",
      "author": "Theodore Roosevelt",
      "sourcePage": 23
    },
    {
      "id": 1212,
      "text": "Le meilleur moyen de tenir sa parole est de ne jamais la donner.",
      "author": "Napoléon Bonaparte",
      "sourcePage": 23
    },
    {
      "id": 1213,
      "text": "L'arbre est deux fois plus utile que les fruits.",
      "author": "Cicéron",
      "sourcePage": 23
    },
    {
      "id": 1214,
      "text": "Les erreurs sont les portes de la découverte.",
      "author": "James Joyce",
      "sourcePage": 23
    },
    {
      "id": 1215,
      "text": "Les folies sont les seules choses qu'on ne regrette jamais.",
      "author": "Oscar Wilde",
      "sourcePage": 23
    },
    {
      "id": 1216,
      "text": "Le péril s'évanouit quand on ose le regarder.",
      "author": "Chateaubriand",
      "sourcePage": 23
    },
    {
      "id": 1217,
      "text": "On ne jouit bien que de ce qu'on partage.",
      "author": "Madame de Genlis",
      "sourcePage": 23
    },
    {
      "id": 1218,
      "text": "Il vaut mieux gâcher sa jeunesse que de n'en rien faire du tout.",
      "author": "Georges Courteline",
      "sourcePage": 23
    },
    {
      "id": 1219,
      "text": "C'est au pied du mur que l'on voit le mieux le mur.",
      "author": "Jean-Marie Bigard",
      "sourcePage": 23
    },
    {
      "id": 1220,
      "text": "Si l'homme descend du singe, il peut aussi y remonter.",
      "author": "Buster Keaton",
      "sourcePage": 23
    },
    {
      "id": 1221,
      "text": "Un bon archer atteint la cible avant même d'avoir tiré.",
      "author": "Zhao Buzhi",
      "sourcePage": 23
    },
    {
      "id": 1222,
      "text": "Pour avoir du talent, il faut être convaincu qu'on en possède.",
      "author": "Gustave Flaubert",
      "sourcePage": 23
    },
    {
      "id": 1223,
      "text": "Prenez un peu de repos, afin de finir plus vite.",
      "author": "George Herbert",
      "sourcePage": 23
    },
    {
      "id": 1224,
      "text": "L'homme a du génie lorsqu'il rêve.",
      "author": "Akira Kurosawa",
      "sourcePage": 23
    },
    {
      "id": 1225,
      "text": "Les conséquences de ce qu'on ne fait pas sont les plus graves.",
      "author": "Marcel Marien",
      "sourcePage": 24
    },
    {
      "id": 1226,
      "text": "Pour chanter le rossignol n'ouvre qu'un petit bec.",
      "author": "Buson Yosa",
      "sourcePage": 24
    },
    {
      "id": 1227,
      "text": "Un problème prévu est un problème en moins.",
      "author": "Maurice Dantec",
      "sourcePage": 24
    },
    {
      "id": 1228,
      "text": "Il faut compter ses richesses par les moyens qu'on a de satisfaire ses désirs.",
      "author": "Abbé Prévost",
      "sourcePage": 24
    },
    {
      "id": 1229,
      "text": "Le bonheur le plus doux est celui qu'on partage.",
      "author": "Jacques Delille",
      "sourcePage": 24
    },
    {
      "id": 1230,
      "text": "Qui parle sème ; qui écoute récolte.",
      "author": "Pythagore",
      "sourcePage": 24
    },
    {
      "id": 1231,
      "text": "Ce qui n'est point utile à l'essaim, n'est point utile à l'abeille.",
      "author": "Montesquieu",
      "sourcePage": 24
    },
    {
      "id": 1232,
      "text": "Une chose ne vaut que par l'importance qu'on lui donne.",
      "author": "André Gide",
      "sourcePage": 24
    },
    {
      "id": 1233,
      "text": "Tout homme a deux mères : la nature et les circonstances.",
      "author": "José Marti",
      "sourcePage": 24
    },
    {
      "id": 1234,
      "text": "Vous oubliez que les fruits sont à tous et que la terre n'est à personne.",
      "author": "Jean-Jacques Rousseau",
      "sourcePage": 24
    },
    {
      "id": 1235,
      "text": "Ce n'est pas tant d'être riche qui fait le bonheur, c'est de le devenir.",
      "author": "Stendhal",
      "sourcePage": 24
    },
    {
      "id": 1236,
      "text": "N'est grave que ce qu'on veut bien considérer comme tel.",
      "author": "Xavier Patier",
      "sourcePage": 24
    },
    {
      "id": 1237,
      "text": "Plus on veut, mieux on veut.",
      "author": "Charles Baudelaire",
      "sourcePage": 24
    },
    {
      "id": 1238,
      "text": "Faites que le rêve dévore votre vie afin que la vie ne dévore pas votre rêve.",
      "author": "Antoine de Saint- Exupéry",
      "sourcePage": 24
    },
    {
      "id": 1239,
      "text": "Sa vie, on ne la refait pas, on la poursuit.",
      "author": "Françoise Chandernagor",
      "sourcePage": 24
    },
    {
      "id": 1240,
      "text": "La sérénité et l'oubli vont parfois de pair.",
      "author": "Allan Gurganus",
      "sourcePage": 24
    },
    {
      "id": 1241,
      "text": "Il y a deux manières de prendre une femme : par la taille et par le sentiment.",
      "author": "Henri Bataille",
      "sourcePage": 24
    },
    {
      "id": 1242,
      "text": "Choisir, c'est se priver du reste.",
      "author": "André Gide",
      "sourcePage": 24
    },
    {
      "id": 1243,
      "text": "On ne décide pas bien tout seul.",
      "author": "Daniel Jouve",
      "sourcePage": 24
    },
    {
      "id": 1244,
      "text": "Ne désespérez jamais. Faites infuser davantage.",
      "author": "Henri Michaux",
      "sourcePage": 24
    },
    {
      "id": 1245,
      "text": "On s'étonne trop de ce qu'on voit rarement et pas assez de ce qu'on voit tous les jours.",
      "author": "Madame de Genlis",
      "sourcePage": 24
    },
    {
      "id": 1246,
      "text": "Innover, ce n'est pas avoir une nouvelle idée mais arrêter d'avoir une vieille idée.",
      "author": "Edwin Herbert Land",
      "sourcePage": 24
    },
    {
      "id": 1247,
      "text": "Se donner du mal pour les petites choses, c'est parvenir aux grandes, avec le temps.",
      "author": "Samuel Beckett",
      "sourcePage": 24
    },
    {
      "id": 1248,
      "text": "Allons au fond de l'inconnu pour trouver du nouveau.",
      "author": "Charles Baudelaire",
      "sourcePage": 24
    },
    {
      "id": 1249,
      "text": "Le monde fleurit par ceux qui cèdent à la tentation.",
      "author": "Julien Gracq",
      "sourcePage": 24
    },
    {
      "id": 1250,
      "text": "Nous avons besoin d'hommes qui sachent rêver à des choses inédites.",
      "author": "John Fitzgerald Kennedy",
      "sourcePage": 24
    },
    {
      "id": 1251,
      "text": "Le moment présent est la piste désignée à tout nouveau départ.",
      "author": "Louis-Marie Parent",
      "sourcePage": 24
    },
    {
      "id": 1252,
      "text": "La culture ne s'hérite pas, elle se conquiert.",
      "author": "André Malraux",
      "sourcePage": 24
    },
    {
      "id": 1253,
      "text": "Nous ne pouvons pas toujours changer le monde, mais nous pouvons changer d'idée.",
      "author": "Gérald Jampolsky",
      "sourcePage": 24
    },
    {
      "id": 1254,
      "text": "Il faut aussi rêver sa révolution, pas seulement la construire.",
      "author": "Pierre Boulez",
      "sourcePage": 24
    },
    {
      "id": 1255,
      "text": "La joie est dans le risque à faire du neuf.",
      "author": "Marilyn Ferguson",
      "sourcePage": 24
    },
    {
      "id": 1256,
      "text": "Je n'ai jamais eu de chagrin qu'une heure de lecture n'ait dissipé.",
      "author": "Montesquieu",
      "sourcePage": 24
    },
    {
      "id": 1257,
      "text": "Si vous voulez que vos rêves se réalisent, ne dormez-pas.",
      "author": "Proverbe juif",
      "sourcePage": 24
    },
    {
      "id": 1258,
      "text": "Le pessimisme est d'humeur ; l'optimisme est de volonté.",
      "author": "Alain",
      "sourcePage": 24
    },
    {
      "id": 1259,
      "text": "Il y a des fleurs partout pour qui veut bien les voir.",
      "author": "Henri Matisse",
      "sourcePage": 24
    },
    {
      "id": 1260,
      "text": "Ce qui nous manque nous instruit.",
      "author": "Proverbe allemand",
      "sourcePage": 24
    },
    {
      "id": 1261,
      "text": "Peu importe le succès, il s'agit d'être grand, non de le paraître.",
      "author": "Romain Rolland",
      "sourcePage": 24
    },
    {
      "id": 1262,
      "text": "On ne trouve de bon dans la vie que ce qui la fait oublier.",
      "author": "Madame de Staël",
      "sourcePage": 24
    },
    {
      "id": 1263,
      "text": "Il n'y a pas de lumière sans ombre.",
      "author": "Louis Aragon",
      "sourcePage": 24
    },
    {
      "id": 1264,
      "text": "Tous les trésors de la terre ne valent pas le bonheur d'être aimé.",
      "author": "Calderon",
      "sourcePage": 24
    },
    {
      "id": 1265,
      "text": "L'erreur n'annule pas la valeur de l'effort accompli.",
      "author": "Proverbe africain",
      "sourcePage": 24
    },
    {
      "id": 1266,
      "text": "Un problème sans solution est un problème mal posé.",
      "author": "Albert Einstein",
      "sourcePage": 24
    },
    {
      "id": 1267,
      "text": "Le plus beau sommeil ne vaut pas le moment où l'on se réveille.",
      "author": "André Gide",
      "sourcePage": 24
    },
    {
      "id": 1268,
      "text": "Nous avons une raison de vivre : apprendre, découvrir, être libres !",
      "author": "Richard Bach",
      "sourcePage": 24
    },
    {
      "id": 1269,
      "text": "Une bonne parole éteint mieux qu'un seau d'eau.",
      "author": "Miguel de Cervantès, extrait de \"Nouvelles exemplaires\"",
      "sourcePage": 24
    },
    {
      "id": 1270,
      "text": "N'a de convictions que celui qui n'a rien approfondi.\"",
      "author": "Emil Michel Cioran, extrait de \"L'inconvénient d'être né\"",
      "sourcePage": 24
    },
    {
      "id": 1271,
      "text": "Ce qui embellit le désert c'est qu'il cache un puits quelque part.",
      "author": "Antoine de Saint-Exupéry, extrait de \"Le petit prince\"",
      "sourcePage": 24
    },
    {
      "id": 1272,
      "text": "Un remords vaut mieux qu'une hésitation qui se prolonge.",
      "author": "Henry de Montherlant, extrait de \"La reine morte\"",
      "sourcePage": 24
    },
    {
      "id": 1273,
      "text": "C'est quand il y a quelque chose au-dessus de la vie que la vie devient belle.",
      "author": "Jean d'Ormesson",
      "sourcePage": 24
    },
    {
      "id": 1274,
      "text": "La vraie générosité envers l'avenir consiste à tout donner au présent.",
      "author": "Albert Camus, extrait de \"L'homme révolté\"",
      "sourcePage": 24
    },
    {
      "id": 1275,
      "text": "Je crois que Dieu, ce sont les hommes et qu'ils ne le savent pas.",
      "author": "Jacques Brel",
      "sourcePage": 24
    },
    {
      "id": 1276,
      "text": "La vie fleurit par le travail.",
      "author": "Arthur Rimbaud, extrait d' \"Une saison en enfer\"",
      "sourcePage": 24
    },
    {
      "id": 1277,
      "text": "Ne pas avoir de but est aussi un but.",
      "author": "Gao Xingjian, extrait de \"La montagne de l'âme\"",
      "sourcePage": 25
    },
    {
      "id": 1278,
      "text": "On ne force pas une curiosité, on l'éveille.",
      "author": "Daniel Pennac, extrait de \"Comme un roman\"",
      "sourcePage": 25
    },
    {
      "id": 1279,
      "text": "Au milieu de l'hiver, j'ai découvert en moi un invincible été.",
      "author": "Albert Camus",
      "sourcePage": 25
    },
    {
      "id": 1280,
      "text": "Les grands embrasements naissent de petites étincelles.",
      "author": "Cardinal de Richelieu, extrait de \"Testament politique\"",
      "sourcePage": 25
    },
    {
      "id": 1281,
      "text": "On ne naît pas femme : on le devient.",
      "author": "Simone de Beauvoir, extrait de \"Le deuxième sexe\"",
      "sourcePage": 25
    },
    {
      "id": 1282,
      "text": "Il n'y a pas de réussite facile ni d'échecs définitifs.",
      "author": "Marcel Proust",
      "sourcePage": 25
    },
    {
      "id": 1283,
      "text": "Les jours sont des fruits et notre rôle est de les manger.",
      "author": "Jean Giono",
      "sourcePage": 25
    },
    {
      "id": 1284,
      "text": "La fatalité, c'est l'excuse des âmes sans volonté.",
      "author": "Romain Rolland",
      "sourcePage": 25
    },
    {
      "id": 1285,
      "text": "Si vous voulez être heureux, soyez-le !",
      "author": "Léon Tolstoï",
      "sourcePage": 25
    },
    {
      "id": 1286,
      "text": "Etre conscient de la difficulté permet de l'éviter.",
      "author": "Lao-Tseu, extrait du \"Tao Te King\"",
      "sourcePage": 25
    },
    {
      "id": 1287,
      "text": "Le patient use toujours l'impatient.",
      "author": "Paul Morand, extrait de \"L'homme pressé\"",
      "sourcePage": 25
    },
    {
      "id": 1288,
      "text": "Les hommes pratiquent le stress comme si c'était un sport.",
      "author": "Madeleine Ferron, extrait de \"Le chemin des dames\"",
      "sourcePage": 25
    },
    {
      "id": 1289,
      "text": "Il n'importe pas qu'un être soit croyant ou non : il est plus important qu'il soit bon.",
      "author": "Dalaï Lama, extrait de \"Sagesse ancienne, monde moderne\"",
      "sourcePage": 25
    },
    {
      "id": 1290,
      "text": "Il vaut mieux se faire aimer que se faire craindre.",
      "author": "Pythagore",
      "sourcePage": 25
    },
    {
      "id": 1291,
      "text": "Moins on a de connaissances, plus on a de convictions.",
      "author": "Boris Cyrulnik, extrait de \"Un merveilleux malheur\"",
      "sourcePage": 25
    },
    {
      "id": 1292,
      "text": "Vieillir ensemble, ce n'est pas ajouter des années à la vie, mais de la vie aux années.",
      "author": "Jacques Salomé, extrait de \"Si je m'écoutais, je m'entendrais\"",
      "sourcePage": 25
    },
    {
      "id": 1293,
      "text": "Le temps mène la vie dure à ceux qui veulent le tuer.",
      "author": "Jacques Prévert, extrait de \"Fatras\"",
      "sourcePage": 25
    },
    {
      "id": 1294,
      "text": "La vraie vie est si souvent celle qu'on ne vit pas.",
      "author": "Oscar Wilde, extrait de \"Rose-leaf and apple-leaf\"",
      "sourcePage": 25
    },
    {
      "id": 1295,
      "text": "Il faut se garder de vouloir uniformiser les mentalités.",
      "author": "Alexandra David-Neel",
      "sourcePage": 25
    },
    {
      "id": 1296,
      "text": "La victoire sur soi est la plus grande des victoires.",
      "author": "Platon",
      "sourcePage": 25
    },
    {
      "id": 1297,
      "text": "Toutes nos passions reflètent les étoiles.",
      "author": "Victor Hugo, extrait de \"La légende des siècles\"",
      "sourcePage": 25
    },
    {
      "id": 1298,
      "text": "Un voyage de mille lieues commence toujours par un premier pas.",
      "author": "Lao-Tseu, extrait du \"Tao Te King\"",
      "sourcePage": 25
    },
    {
      "id": 1299,
      "text": "La nature, pour être commandée, doit être obéie.",
      "author": "Francis Bacon, extrait de \"Novum Organum\"",
      "sourcePage": 25
    },
    {
      "id": 1300,
      "text": "Une petite flamme de folie, si on savait comme la vie s'en éclaire !",
      "author": "Henry de Montherlant, extrait de \"Malatesta\"",
      "sourcePage": 25
    },
    {
      "id": 1301,
      "text": "La meilleure façon de ne pas avancer est de suivre une idée fixe.",
      "author": "Jacques Prévert",
      "sourcePage": 25
    },
    {
      "id": 1302,
      "text": "Il faut avoir beaucoup de patience pour apprendre à être patient.",
      "author": "Stanislaw Jerzy Lec, extrait des \"Nouvelles pensées échevelées\"",
      "sourcePage": 25
    },
    {
      "id": 1303,
      "text": "S'il n'y a pas de solution c'est qu'il n'y a pas de problème.",
      "author": "Jacques Rouxel, extrait du dessin animé \"Les shadoks\"",
      "sourcePage": 25
    },
    {
      "id": 1304,
      "text": "La réalité est une chose au-dessus de laquelle il faut s'élever.",
      "author": "Liza Minnelli",
      "sourcePage": 25
    },
    {
      "id": 1305,
      "text": "Qui n'a pas d'imagination n'a pas d'ailes.",
      "author": "Mohammed Ali",
      "sourcePage": 25
    },
    {
      "id": 1306,
      "text": "Ce que je vous demande, c'est d'ouvrir votre esprit, non de croire.",
      "author": "Krishnamurti, extrait de \"De l'éducation\"",
      "sourcePage": 25
    },
    {
      "id": 1307,
      "text": "Les gens compliquent tout pour avoir l'impression de vivre.",
      "author": "Patrick Rambaud, extrait du journal \"Libération - 18 Novembre 1997\"",
      "sourcePage": 25
    },
    {
      "id": 1308,
      "text": "L'avenir, c'est ce qui dépasse la main tendue.",
      "author": "Louis Aragon",
      "sourcePage": 25
    },
    {
      "id": 1309,
      "text": "Bonheur : faire ce que l'on veut et vouloir ce que l'on fait.",
      "author": "Françoise Giroud, extrait de \"Ce que je crois\"",
      "sourcePage": 25
    },
    {
      "id": 1310,
      "text": "La trace d'un rêve n'est pas moins réelle que celle d'un pas.",
      "author": "Georges Duby",
      "sourcePage": 25
    },
    {
      "id": 1311,
      "text": "Une journée nuageuse ne peut rien contre un tempérament radieux.",
      "author": "William Arthur Ward",
      "sourcePage": 25
    },
    {
      "id": 1312,
      "text": "Je préfère un futur imprévisible à un futur imposteur.",
      "author": "Maurice Schumann",
      "sourcePage": 25
    },
    {
      "id": 1313,
      "text": "Mieux vaut allumer une bougie que maudire les ténèbres.",
      "author": "Lao-Tseu",
      "sourcePage": 25
    },
    {
      "id": 1314,
      "text": "L'espérance est un risque à courir.",
      "author": "Georges Bernanos",
      "sourcePage": 25
    },
    {
      "id": 1315,
      "text": "Dans la vie, rien n'est à craindre, tout est à comprendre.",
      "author": "Marie Curie",
      "sourcePage": 25
    },
    {
      "id": 1316,
      "text": "J'aime les gens qui se battent, même contre l'évidence.",
      "author": "Jacqueline Rémy, extrait de \"Je meurs d'envie\"",
      "sourcePage": 25
    },
    {
      "id": 1317,
      "text": "A qui sait bien aimer, il n'est rien d'impossible.",
      "author": "Pierre Corneille, extrait de \"Médée\"",
      "sourcePage": 25
    },
    {
      "id": 1318,
      "text": "Le plaisir le plus délicat est de faire celui d'autrui.",
      "author": "Jean de La Bruyère",
      "sourcePage": 25
    },
    {
      "id": 1319,
      "text": "Là où tant d'hommes ont échoué, une femme peut réussir.",
      "author": "Talleyrand",
      "sourcePage": 25
    },
    {
      "id": 1320,
      "text": "Dans la vie il faut savoir compter... mais pas sur les autres.",
      "author": "Paul-Jean Toulet",
      "sourcePage": 25
    },
    {
      "id": 1321,
      "text": "Quand on est jeune, c'est pour la vie.",
      "author": "Georges Clemenceau",
      "sourcePage": 25
    },
    {
      "id": 1322,
      "text": "Pour vivre heureux, vivons caché.",
      "author": "Jean-Pierre Florian, extrait des \"Fables\"",
      "sourcePage": 25
    },
    {
      "id": 1323,
      "text": "Un père vaut plus qu'une centaine de maîtres d'école.",
      "author": "George Herbert, extrait de \"Jacula Prudentum\"",
      "sourcePage": 25
    },
    {
      "id": 1324,
      "text": "Tout est trop cher quand on n'en a pas besoin.",
      "author": "James Joyce, extrait de \"Ulysse\"",
      "sourcePage": 26
    },
    {
      "id": 1325,
      "text": "A qui peut se vaincre soi-même, il est peu de chose qui puisse résister.",
      "author": "Louis XIV, extrait de ses \"Mémoires\"",
      "sourcePage": 26
    },
    {
      "id": 1326,
      "text": "L'avenir est quelque chose qui se surmonte. On ne subit pas l'avenir, on le fait.",
      "author": "Georges Bernanos, extrait de \"La liberté pour quoi faire ?\"",
      "sourcePage": 26
    },
    {
      "id": 1327,
      "text": "Le bonheur qu'on veut avoir gâte celui qu'on a déjà.",
      "author": "Jacques Deval, extrait d' \"Afin de vivre bel et bien\"",
      "sourcePage": 26
    },
    {
      "id": 1328,
      "text": "Rien ne développe l'intelligence comme les voyages.",
      "author": "Emile Zola, extrait des \"Aventures du grand Sidoine et du petit Médéric\"",
      "sourcePage": 26
    },
    {
      "id": 1329,
      "text": "Droit devant soi, on ne peut pas aller bien loin.",
      "author": "Antoine de Saint-Exupéry, extrait de \"Le petit prince\"",
      "sourcePage": 26
    },
    {
      "id": 1330,
      "text": "Visez toujours la lune. Même si vous la manquez, vous atterrirez parmi les étoiles.",
      "author": "Les Brown",
      "sourcePage": 26
    },
    {
      "id": 1331,
      "text": "Il n'y a pas de plus grande joie que celle qu'on n'attend pas.",
      "author": "Sophocle",
      "sourcePage": 26
    },
    {
      "id": 1332,
      "text": "Pour préparer un arbre de Noël, il faut trois choses, outre les ornements et l'arbre, la foi dans les beaux jours à venir.",
      "author": "Zahrad, extrait de \"Un arbre de Noël\"",
      "sourcePage": 26
    },
    {
      "id": 1333,
      "text": "Ferme les yeux, et le monde devient celui que tu veux.",
      "author": "Alain Berliner, dialogue du film \"Ma vie en rose\"",
      "sourcePage": 26
    },
    {
      "id": 1334,
      "text": "Quand le feu dans l'âtre brille, il fait bon fêter la famille.",
      "author": "Dicton français",
      "sourcePage": 26
    },
    {
      "id": 1335,
      "text": "Celui qui n'a pas Noël dans le cœur ne le trouvera jamais au pied d'un arbre.",
      "author": "Roy L. Smith",
      "sourcePage": 26
    },
    {
      "id": 1336,
      "text": "Où peut-on être mieux qu'au sein de sa famille ?",
      "author": "Jean-François Marmontel",
      "sourcePage": 26
    },
    {
      "id": 1337,
      "text": "Que la lumière soif... Et la lumière but.",
      "author": "André Beucler",
      "sourcePage": 26
    },
    {
      "id": 1338,
      "text": "La beauté plaît aux yeux, la douceur charme l'âme.",
      "author": "Voltaire",
      "sourcePage": 26
    },
    {
      "id": 1339,
      "text": "Les émotions sont faites pour être partagées.",
      "author": "Marc Levy, extrait de \"Et si c'était vrai...\"",
      "sourcePage": 26
    },
    {
      "id": 1340,
      "text": "Quel vin est aussi pétillant, savoureux, enivrant, que l'infini des possibles !",
      "author": "Sören Kierkegaard",
      "sourcePage": 26
    },
    {
      "id": 1341,
      "text": "Petite chère et grand accueil font joyeux festin.",
      "author": "William Shakespeare, extrait de \"La comédie des erreurs\"",
      "sourcePage": 26
    },
    {
      "id": 1342,
      "text": "Accroche ton chariot à une étoile.",
      "author": "Ralph Waldo Emerson",
      "sourcePage": 26
    },
    {
      "id": 1343,
      "text": "Il faut rajouter de la vie aux années et non des années à la vie.",
      "author": "Proverbe chinois",
      "sourcePage": 26
    },
    {
      "id": 1344,
      "text": "Le bonheur le plus doux est celui qu'on partage.",
      "author": "Jacques Delille",
      "sourcePage": 26
    },
    {
      "id": 1345,
      "text": "La joie prolonge la vie.",
      "author": "Ben Sira",
      "sourcePage": 26
    },
    {
      "id": 1346,
      "text": "Tes destins sont d'un homme, et tes vœux sont d'un Dieu.",
      "author": "Voltaire, extrait du \"Discours en vers sur l'homme\"",
      "sourcePage": 26
    },
    {
      "id": 1347,
      "text": "Il ne dépend pas de toi d'être riche, mais il dépend de toi d'être heureux.",
      "author": "Epictète",
      "sourcePage": 26
    },
    {
      "id": 1348,
      "text": "La gaieté, la santé changent l'hiver en été.",
      "author": "Antoine Désaugiers, extrait de \"Le dîner de Madelon\"",
      "sourcePage": 26
    },
    {
      "id": 1349,
      "text": "Que la santé immortelle descende du ciel pour avoir soin de tous vos jours !",
      "author": "Voltaire, extrait de \"Zadig ou la destinée\"",
      "sourcePage": 26
    },
    {
      "id": 1350,
      "text": "Qu'importent les trésors ! Plutôt qu'argent entasser, mieux vaut amis posséder.",
      "author": "Nikolaï Gogol, extrait de \"Les âmes mortes\"",
      "sourcePage": 26
    },
    {
      "id": 1351,
      "text": "On ne doit se résigner qu'au bonheur.",
      "author": "Alfred Capus",
      "sourcePage": 26
    },
    {
      "id": 1352,
      "text": "Sous prétexte que la perfection n'est pas de ce monde, ne gardez pas soigneusement tous vos défauts.",
      "author": "Jules Renard, extrait de son \"Journal\"",
      "sourcePage": 26
    },
    {
      "id": 1353,
      "text": "Ce qui compte, c'est d'avoir toujours quelque chose à attendre.",
      "author": "Didier van Cauwelaert, extrait de \"La vie interdite\"",
      "sourcePage": 26
    },
    {
      "id": 1354,
      "text": "Le bruit ne fait pas de bien, et le bien ne fait pas de bruit.",
      "author": "Saint François de Sales",
      "sourcePage": 26
    },
    {
      "id": 1355,
      "text": "La violence est le dernier refuge de l'incompétence.",
      "author": "Isaac Asimov, extrait de \"Fondation\"",
      "sourcePage": 26
    },
    {
      "id": 1356,
      "text": "Il vaut mieux se perdre dans sa passion que perdre sa passion.",
      "author": "Denis Robert, extrait de \"Le bonheur\"",
      "sourcePage": 26
    },
    {
      "id": 1357,
      "text": "N'oublions pas que les enfants suivent les exemples mieux qu'ils n'écoutent les conseils.",
      "author": "Roy L. Smith",
      "sourcePage": 26
    },
    {
      "id": 1358,
      "text": "La chance, c'est ce qu'on croit toujours qu'on n'a pas.",
      "author": "Patrice Leconte, dialogue du film \"La fille sur le pont\"",
      "sourcePage": 26
    },
    {
      "id": 1359,
      "text": "Les choses les plus précieuses sont plus légères que l'air.",
      "author": "Paul Auster",
      "sourcePage": 26
    },
    {
      "id": 1360,
      "text": "Les deux grands secrets du bonheur : le plaisir et l'oubli.",
      "author": "Alfred de Musset, extrait de \"La nuit vénitienne\"",
      "sourcePage": 26
    },
    {
      "id": 1361,
      "text": "Quand la prudence est partout, le courage n'est nulle part.",
      "author": "Cardinal Mercier",
      "sourcePage": 26
    },
    {
      "id": 1362,
      "text": "Pourquoi faudrait-il aimer rarement pour aimer beaucoup ?",
      "author": "Albert Camus, extrait de \"Le mythe de Sisyphe\"",
      "sourcePage": 26
    },
    {
      "id": 1363,
      "text": "Nous avons plus de paresse dans l'esprit que dans le corps.",
      "author": "La Rochefoucauld, extrait de \"Maximes\"",
      "sourcePage": 26
    },
    {
      "id": 1364,
      "text": "C'est un devoir aussi envers les autres que d'être heureux.",
      "author": "Alain, extrait des \"Propos sur le bonheur\"",
      "sourcePage": 26
    },
    {
      "id": 1365,
      "text": "L'homme est un être raisonnable, mais les hommes le sont-ils ?",
      "author": "Raymond Aron",
      "sourcePage": 26
    },
    {
      "id": 1366,
      "text": "Ce n'est pas la girouette qui tourne, c'est le vent.",
      "author": "Edgar Faure",
      "sourcePage": 27
    },
    {
      "id": 1367,
      "text": "Le succès c'est d'aller d'échec en échec sans perdre son enthousiasme.",
      "author": "Winston Churchill",
      "sourcePage": 27
    },
    {
      "id": 1368,
      "text": "La recherche du bonheur rend les gens tellement malheureux.",
      "author": "Georges Raby, extrait de \"Les dents longues\"",
      "sourcePage": 27
    },
    {
      "id": 1369,
      "text": "Tout semble impossible à ceux qui n'ont jamais rien essayé.",
      "author": "Jean-Louis Etienne",
      "sourcePage": 27
    },
    {
      "id": 1370,
      "text": "Dans le désert, on peut toujours tomber sur une oasis.",
      "author": "Fatou Diome, extrait de \"Le ventre de l'Atlantique\"",
      "sourcePage": 27
    },
    {
      "id": 1371,
      "text": "Ce n'est jamais gagné tant que ce n'est pas gagné.",
      "author": "Ron Dennis, extrait d'une \"Interview - 29 Avril 2001\"",
      "sourcePage": 27
    },
    {
      "id": 1372,
      "text": "Les hommes construisent trop de murs et pas assez de ponts.",
      "author": "Isaac Newton",
      "sourcePage": 27
    },
    {
      "id": 1373,
      "text": "Il ne suffit pas d'être heureux, encore faut-il savoir qu'on l'est.",
      "author": "Jean Dion, extrait du journal québécois \"Le Devoir de Montréal - 10 mai 2001\"",
      "sourcePage": 27
    },
    {
      "id": 1374,
      "text": "Le mal de la télévision, ce n'est pas dans la télévision qu'il est, c'est dans le monde.",
      "author": "Christian Bobin, extrait de \"L'inespérée\"",
      "sourcePage": 27
    },
    {
      "id": 1375,
      "text": "L'homme de génie est celui qui m'en donne.",
      "author": "Paul Valéry",
      "sourcePage": 27
    },
    {
      "id": 1376,
      "text": "La vie est courte, même pour ceux qui passent leur temps à la trouver longue.",
      "author": "André Maurois",
      "sourcePage": 27
    },
    {
      "id": 1377,
      "text": "La difficulté n'est pas de comprendre les idées nouvelles, mais d'échapper aux idées anciennes.",
      "author": "John Maynard Keynes",
      "sourcePage": 27
    },
    {
      "id": 1378,
      "text": "On peut toujours plus que ce que l'on croit pouvoir.",
      "author": "Joseph Kessel",
      "sourcePage": 27
    },
    {
      "id": 1379,
      "text": "Nous sommes peu à penser trop, trop à penser peu.",
      "author": "Françoise Sagan",
      "sourcePage": 27
    },
    {
      "id": 1380,
      "text": "Etre aimé, c'est plus qu'être riche, car c'est être heureux.",
      "author": "Claude Tillier, extrait de \"Mon oncle Benjamin\"",
      "sourcePage": 27
    },
    {
      "id": 1381,
      "text": "Attendre d'en savoir assez pour agir en toute lumière, c'est se condamner à l'inaction.",
      "author": "Jean Rostand, extrait des \"Inquiétudes d'un biologiste\"",
      "sourcePage": 27
    },
    {
      "id": 1382,
      "text": "Il n'y a que le cœur qui aille aussi vite que les hirondelles.",
      "author": "Henri Lacordaire, extrait de correspondance \"Lettre à Madame Swetchine - 4 Septembre 1835\"",
      "sourcePage": 27
    },
    {
      "id": 1383,
      "text": "Tout homme a droit à 24 heures de liberté par jour.",
      "author": "René Magritte",
      "sourcePage": 27
    },
    {
      "id": 1384,
      "text": "Qui pardonne aisément invite à l'offenser.",
      "author": "Pierre Corneille, extrait de \"Cinna\"",
      "sourcePage": 27
    },
    {
      "id": 1385,
      "text": "Il n'est de grand amour qu'à l'ombre d'un grand rêve.",
      "author": "Edmond Rostand, extrait de \"Chantecler\"",
      "sourcePage": 27
    },
    {
      "id": 1386,
      "text": "L'amour se nourrit de patience autant que de désir.",
      "author": "Amin Maalouf, extrait de \"Le périple de Baldassare\"",
      "sourcePage": 27
    },
    {
      "id": 1387,
      "text": "L'amour, c'est être toujours inquiet de l'autre.",
      "author": "Marcel Achard, extrait de \"Jean de la Lune\"",
      "sourcePage": 27
    },
    {
      "id": 1388,
      "text": "L'humour est le plus court chemin d'un homme à un autre.",
      "author": "Georges Wolinski",
      "sourcePage": 27
    },
    {
      "id": 1389,
      "text": "L'émeraude ne perd pas de sa valeur faute de louanges.",
      "author": "Marc Aurèle",
      "sourcePage": 27
    },
    {
      "id": 1390,
      "text": "Ne donnez pas votre confiance, prêtez-la.",
      "author": "François Proust, extrait de \"Maximes à l'usage des dirigés et de leurs dirigeants\"",
      "sourcePage": 27
    },
    {
      "id": 1391,
      "text": "Le possible n'est pas loin du nécessaire.",
      "author": "Pythagore",
      "sourcePage": 27
    },
    {
      "id": 1392,
      "text": "Une erreur ne devient une faute que lorsqu'on ne veut pas en démordre.",
      "author": "Ernst Jünger, extrait de \"Sur les falaises de marbre\"",
      "sourcePage": 27
    },
    {
      "id": 1393,
      "text": "Ce qui est juste peut bien être dit même deux fois.",
      "author": "Empédocle",
      "sourcePage": 27
    },
    {
      "id": 1394,
      "text": "Le monde aurait pu être simple comme le ciel et la mer.",
      "author": "André Malraux",
      "sourcePage": 27
    },
    {
      "id": 1395,
      "text": "L'activité fait plus de fortunes que la prudence.",
      "author": "Vauvenargues",
      "sourcePage": 27
    },
    {
      "id": 1396,
      "text": "Croire en quelque chose et ne pas le vivre, c'est malhonnête.",
      "author": "Gandhi",
      "sourcePage": 27
    },
    {
      "id": 1397,
      "text": "Celui qui aime à apprendre est bien près du savoir.",
      "author": "Confucius",
      "sourcePage": 27
    },
    {
      "id": 1398,
      "text": "Ceux qui vivent sont ceux qui luttent.",
      "author": "Victor Hugo, extrait de \"Châtiments\"",
      "sourcePage": 27
    },
    {
      "id": 1399,
      "text": "Si on n'est pas prêt à tout, on n'est prêt à rien.",
      "author": "Paul Auster, extrait de \"Moon Palace\"",
      "sourcePage": 27
    },
    {
      "id": 1400,
      "text": "Quand on aime trop quelque chose, il faut s'en priver.",
      "author": "Daniel Picouly, extrait de \"L'enfant léopard\"",
      "sourcePage": 27
    },
    {
      "id": 1401,
      "text": "On ne peut apprendre au crabe à marcher droit.",
      "author": "Aristophane, extrait de \"La paix\"",
      "sourcePage": 27
    },
    {
      "id": 1402,
      "text": "Dieu a inventé la calvitie pour rendre les hommes plus humbles.",
      "author": "Bruce Willis",
      "sourcePage": 27
    },
    {
      "id": 1403,
      "text": "L'inégalité n'est pas une preuve de l'existence de l'égalité.",
      "author": "Ylipe, extrait de \"Textes sans paroles\"",
      "sourcePage": 27
    },
    {
      "id": 1404,
      "text": "La faiblesse de la force est de ne croire qu'à la force.",
      "author": "Paul Valéry, extrait des \"Mauvaises pensées et autres\"",
      "sourcePage": 27
    },
    {
      "id": 1405,
      "text": "Rien n'est moins raisonnable que de vouloir que les enfants le soient.",
      "author": "Madame de Maintenon",
      "sourcePage": 27
    },
    {
      "id": 1406,
      "text": "L'humanité se prend trop au sérieux ; c'est le péché originel de notre monde.",
      "author": "Oscar Wilde, extrait de \"Le portrait de Dorian Gray\"",
      "sourcePage": 27
    },
    {
      "id": 1407,
      "text": "Ce ne sont pas les heures qui sont précieuses, ce sont les minutes.",
      "author": "Bernard Shaw",
      "sourcePage": 27
    },
    {
      "id": 1408,
      "text": "C'est pas parce qu'on demande rien qu'on sait tout.",
      "author": "Gilles Paris, extrait de \"Autobiographie d'une courgette\"",
      "sourcePage": 27
    },
    {
      "id": 1409,
      "text": "Où finit la paresse, où commence la contemplation ?",
      "author": "Jean Dutourd, extrait de \"Doucin\"",
      "sourcePage": 27
    },
    {
      "id": 1410,
      "text": "L'interdit donne de la saveur, la censure du talent.",
      "author": "Marc Vilrouge, extrait d'une interview pour \"Le Dilettante\"",
      "sourcePage": 27
    },
    {
      "id": 1411,
      "text": "Ne pas se faire de bien, c'est une manière de se faire du mal.",
      "author": "Lisa Carducci, extrait des \"Nouvelles en couleurs\"",
      "sourcePage": 28
    },
    {
      "id": 1412,
      "text": "Le doute et la peur sont les auxiliaires des grandes initiatives.",
      "author": "Amélie Nothomb, extrait d' \"Hygiène de l'assassin\"",
      "sourcePage": 28
    },
    {
      "id": 1413,
      "text": "Vivre tous simplement pour que tous puissent simplement vivre.",
      "author": "Gandhi",
      "sourcePage": 28
    },
    {
      "id": 1414,
      "text": "Nul ne peut atteindre l'aube sans passer par le chemin de la nuit.",
      "author": "Khalil Gibran",
      "sourcePage": 28
    },
    {
      "id": 1415,
      "text": "Il n'y a pas d'homme cultivé ; il n'y a que des hommes qui se cultivent.",
      "author": "Ferdinand Foch",
      "sourcePage": 28
    },
    {
      "id": 1416,
      "text": "On ne cherche pas le bonheur, on l'attend.",
      "author": "Reine Malouin, extrait de \"Profonds destins\"",
      "sourcePage": 28
    },
    {
      "id": 1417,
      "text": "On peut toujours apprendre ce qu'on ne sait pas, non ce qu'on croit savoir.",
      "author": "Gustave Thibon, extrait de \"L'ignorance étoilée\"",
      "sourcePage": 28
    },
    {
      "id": 1418,
      "text": "Il faut apprendre à marcher seul dans l'existence.",
      "author": "Andrée Maillet, extrait de \"Les remparts de Québec\"",
      "sourcePage": 28
    },
    {
      "id": 1419,
      "text": "Qui borne ses désirs est toujours assez riche.",
      "author": "Jacques Delille",
      "sourcePage": 28
    },
    {
      "id": 1420,
      "text": "Je vis de mon désir de vivre.",
      "author": "Miguel de Cervantès",
      "sourcePage": 28
    },
    {
      "id": 1421,
      "text": "Les hommes ont ce don d'avoir des yeux et d'oublier de s'en servir.",
      "author": "David Mitchell, extrait de \"Ecrits fantômes\"",
      "sourcePage": 28
    },
    {
      "id": 1422,
      "text": "J'ai trop le désir qu'on respecte ma liberté pour ne pas respecter celle des autres.",
      "author": "Françoise Sagan, extrait de \"Qui suis-je ?\"",
      "sourcePage": 28
    },
    {
      "id": 1423,
      "text": "La seule manière de protéger sa culture, c'est d'accepter de la mettre en danger.",
      "author": "Paul Andreu",
      "sourcePage": 28
    },
    {
      "id": 1424,
      "text": "La liberté, c'est de n'arriver jamais à l'heure.",
      "author": "Alfred Jarry, extrait de \"Ubu roi\"",
      "sourcePage": 28
    },
    {
      "id": 1425,
      "text": "Lire et être curieux, c'est la même chose.",
      "author": "Pascal Quignard, extrait d'un \"Entretien avec Catherine Argand - Février 1998\"",
      "sourcePage": 28
    },
    {
      "id": 1426,
      "text": "C'est à ce signe qu'on distingue les vrais héros : ils ne se plaignent jamais de leur sort.",
      "author": "Yvan Audouard, extrait de \"Le sabre de mon père\"",
      "sourcePage": 28
    },
    {
      "id": 1427,
      "text": "Le temps de la réflexion est une économie de temps.",
      "author": "Publius Syrus",
      "sourcePage": 28
    },
    {
      "id": 1428,
      "text": "N'essayez pas de devenir un homme qui a du succès. Essayez de devenir un homme qui a de la valeur.",
      "author": "Albert Einstein",
      "sourcePage": 28
    },
    {
      "id": 1429,
      "text": "Le fort fait ses événements, le faible subit ceux que la destinée lui impose.",
      "author": "Alfred de Vigny, extrait de \"Journal d'un poète\"",
      "sourcePage": 28
    },
    {
      "id": 1430,
      "text": "Le vrai bonheur est celui que les autres ne voient pas, et donc n'envient pas.",
      "author": "David Foenkinos, extrait de \"Inversion de l'idiotie\"",
      "sourcePage": 28
    },
    {
      "id": 1431,
      "text": "Les hommes déprécient ce qu'ils ne peuvent comprendre.",
      "author": "Goethe",
      "sourcePage": 28
    },
    {
      "id": 1432,
      "text": "Personne ne réclame ce qu'il désire : chacun réclame ce qu'il croit pouvoir obtenir.",
      "author": "Gilbert Keith Chesterton, extrait de \"Ce qui cloche dans le monde\"",
      "sourcePage": 28
    },
    {
      "id": 1433,
      "text": "Quarante années durant, j'ai vu. Aujourd'hui je regarde.",
      "author": "Pierre Daninos",
      "sourcePage": 28
    },
    {
      "id": 1434,
      "text": "Il faut affronter la réalité avec une pointe d'humour ; autrement, on passe à côté.",
      "author": "Lawrence Durrell",
      "sourcePage": 28
    },
    {
      "id": 1435,
      "text": "L'intelligence est la faculté qui fait que l'on s'abstient.",
      "author": "Henry de Montherlant, extrait des \"Carnets\"",
      "sourcePage": 28
    },
    {
      "id": 1436,
      "text": "Votre vie n'aura jamais que la dimension de vos espérances.",
      "author": "Esther Rochon, extrait d' \"En hommage aux araignées\"",
      "sourcePage": 28
    },
    {
      "id": 1437,
      "text": "Avoir de la considération pour soi vous attire quelquefois celle des autres.",
      "author": "Chamfort",
      "sourcePage": 28
    },
    {
      "id": 1438,
      "text": "Instruction : des pierres dans un sac. Culture : une graine dans un pot.",
      "author": "Maurice Chapelan",
      "sourcePage": 28
    },
    {
      "id": 1439,
      "text": "L'argent ne peut donner le talent, et parfois il peut empêcher d'y atteindre.",
      "author": "François Coppée, extrait de \"Les vrais riches\"",
      "sourcePage": 28
    },
    {
      "id": 1440,
      "text": "La meilleure façon de se venger d'un ennemi, c'est de ne pas lui ressembler.",
      "author": "Marc-Aurèle",
      "sourcePage": 28
    },
    {
      "id": 1441,
      "text": "Les idées sont des graines de lotus, elles ne dorment que pour mieux pousser.",
      "author": "Fatou Diome, extrait de \"Le ventre de l'Atlantique\"",
      "sourcePage": 28
    },
    {
      "id": 1442,
      "text": "Ceux qui se taisent disent plus de choses que ceux qui parlent tout le temps.",
      "author": "Octave Mirbeau, extrait de \"Les affaires sont les affaires\"",
      "sourcePage": 28
    },
    {
      "id": 1443,
      "text": "Choisir le doute comme philosophie de vie c'est comme choisir l'immobilité comme mode de transport.",
      "author": "Yann Martel, extrait de \"L'histoire de Pi\"",
      "sourcePage": 28
    },
    {
      "id": 1444,
      "text": "L'habituel défaut de l'homme est de ne pas prévoir l'orage par beau temps.",
      "author": "Nicholas Machiavel",
      "sourcePage": 28
    },
    {
      "id": 1445,
      "text": "Le pouvoir de l'homme s'est accru dans tous les domaines, excepté sur lui-même.",
      "author": "Winston Churchill",
      "sourcePage": 28
    },
    {
      "id": 1446,
      "text": "Nul homme n'est sans défauts : le meilleur est celui qui en a le moins.",
      "author": "Horace",
      "sourcePage": 28
    },
    {
      "id": 1447,
      "text": "Plus personne, ou presque, ne croit que changer la vie des autres est important pour soi.",
      "author": "Jacques Attali, extrait de \"La voie humaine\"",
      "sourcePage": 28
    },
    {
      "id": 1448,
      "text": "Mieux vaut comprendre peu que comprendre mal.",
      "author": "Anatole France",
      "sourcePage": 28
    },
    {
      "id": 1449,
      "text": "N'allez pas là où le chemin peut mener. Allez là où il n'y a pas de chemin et laissez une trace.",
      "author": "Ralph Waldo Emerson",
      "sourcePage": 28
    },
    {
      "id": 1450,
      "text": "Il ne faut pas lier un navire à une seule ancre, ni une vie à un seul espoir.",
      "author": "Epictète",
      "sourcePage": 28
    },
    {
      "id": 1451,
      "text": "Soyez autodidactes, n'attendez pas que la vie vous donne des leçons.",
      "author": "Stanislaw Jerzy Lec, extrait des \"Nouvelles pensées échevelées\"",
      "sourcePage": 28
    },
    {
      "id": 1452,
      "text": "Ayez surtout le souci de séparer les choses du bruit qu'elles font.",
      "author": "Sénèque",
      "sourcePage": 29
    },
    {
      "id": 1453,
      "text": "La vie est la seule carrière qui m'intéresse.",
      "author": "Erik Orsenna, extrait d'une interview dans \"Lire - Mai 2000\"",
      "sourcePage": 29
    },
    {
      "id": 1454,
      "text": "C'est avoir tort que d'avoir raison trop tôt.",
      "author": "Marguerite Yourcenar, extrait des \"Mémoires d'Hadrien\"",
      "sourcePage": 29
    },
    {
      "id": 1455,
      "text": "Pour réussir, il ne suffit pas de prévoir. Il faut aussi savoir improviser.",
      "author": "Isaac Asimov",
      "sourcePage": 29
    },
    {
      "id": 1456,
      "text": "Si vous croyez savoir, vous ne savez pas.",
      "author": "Lao-Tseu, extrait du \"Tao Te King\"",
      "sourcePage": 29
    },
    {
      "id": 1457,
      "text": "Ce que d'autres ont réussi, on peut toujours le réussir.",
      "author": "Antoine de Saint-Exupéry, extrait de \"Terre des hommes\"",
      "sourcePage": 29
    },
    {
      "id": 1458,
      "text": "Beaucoup devient peu si l'on désire un peu plus encore.",
      "author": "Francisco de Quevedo",
      "sourcePage": 29
    },
    {
      "id": 1459,
      "text": "Le rire, comme les essuie-glaces, permet d'avancer même s'il n'arrête pas la pluie.",
      "author": "Gérard Jugnot",
      "sourcePage": 29
    },
    {
      "id": 1460,
      "text": "Tout avantage a ses inconvénients et réciproquement.",
      "author": "Jacques Rouxel, extrait de la BD \"Les shadoks\"",
      "sourcePage": 29
    },
    {
      "id": 1461,
      "text": "Tu me dis, j'oublie. Tu m'enseignes, je me souviens. Tu m'impliques, j'apprends.",
      "author": "Benjamin Franklin",
      "sourcePage": 29
    },
    {
      "id": 1462,
      "text": "Les grands bonheurs viennent du ciel, les petits bonheurs viennent de l'effort.",
      "author": "Proverbe chinois",
      "sourcePage": 29
    },
    {
      "id": 1463,
      "text": "Avoir l'esprit ouvert n'est pas l'avoir béant à toutes les sottises.",
      "author": "Jean Rostand, extrait de \"Inquiétudes d'un biologiste\"",
      "sourcePage": 29
    },
    {
      "id": 1464,
      "text": "Rien ne sert de penser, il faut réfléchir avant.",
      "author": "Pierre Dac, extrait de \"Y'a du mou dans la corde à nœuds !\"",
      "sourcePage": 29
    },
    {
      "id": 1465,
      "text": "La difficulté de réussir ne fait qu'ajouter à la nécessité d'entreprendre.",
      "author": "Beaumarchais, extrait de \"Le barbier de Séville\"",
      "sourcePage": 29
    },
    {
      "id": 1466,
      "text": "Il est aussi absurde de regretter le passé que d'organiser l'avenir.",
      "author": "Roman Polanski, extrait de \"Roman\"",
      "sourcePage": 29
    },
    {
      "id": 1467,
      "text": "Quand je cesserai de m'indigner, j'aurai commencé ma vieillesse.",
      "author": "André Gide, extrait de \"Nouveaux prétextes\"",
      "sourcePage": 29
    },
    {
      "id": 1468,
      "text": "On ne donne pas la vie. On la transmet.",
      "author": "Françoise Giroud, extrait de \"Ce que je crois\"",
      "sourcePage": 29
    },
    {
      "id": 1469,
      "text": "Les relations sont sûrement le miroir dans lequel on se découvre soi- même.",
      "author": "Krishnamurti",
      "sourcePage": 29
    },
    {
      "id": 1470,
      "text": "Où serait le mérite, si les héros n’avaient jamais peur ?",
      "author": "Alphonse Daudet, extrait de \"Tartarin de Tarascon\"",
      "sourcePage": 29
    },
    {
      "id": 1471,
      "text": "Les lois inutiles affaiblissent les lois nécessaires.",
      "author": "Montesquieu, extrait de \"L’esprit des lois\"",
      "sourcePage": 29
    },
    {
      "id": 1472,
      "text": "Gémir sur un malheur passé, c’est le plus sûr moyen d’en attirer un autre.",
      "author": "William Shakespeare, extrait d’ \"Othello\"",
      "sourcePage": 29
    },
    {
      "id": 1473,
      "text": "L’impossible, nous ne l’atteignons pas, mais il nous sert de lanterne.",
      "author": "René Char",
      "sourcePage": 29
    },
    {
      "id": 1474,
      "text": "Choisissez un travail que vous aimez et vous n’aurez pas à travailler un seul jour de votre vie.",
      "author": "Confucius",
      "sourcePage": 29
    },
    {
      "id": 1475,
      "text": "Aucun journaliste ne sait plus ce qu’est une bonne nouvelle.",
      "author": "Dalaï Lama",
      "sourcePage": 29
    },
    {
      "id": 1476,
      "text": "Les hommes se distinguent par ce qu’ils montrent et se ressemblent par ce qu’ils cachent.",
      "author": "Paul Valéry, extrait de \"Mélange\"",
      "sourcePage": 29
    },
    {
      "id": 1477,
      "text": "Le succès semble plus doux à qui ne réussit jamais.",
      "author": "Emily Dickinson, extrait des \"Poèmes\"",
      "sourcePage": 29
    },
    {
      "id": 1478,
      "text": "Un trésor de belles maximes est préférable à un amas de richesses.",
      "author": "Socrate",
      "sourcePage": 29
    },
    {
      "id": 1479,
      "text": "Ce qui importe ce n'est pas de lire mais de relire.",
      "author": "Jorge Luis Borges, extrait de \"Le livre de sable\"",
      "sourcePage": 29
    },
    {
      "id": 1480,
      "text": "L'homme ordinaire ne se préoccupe que de passer le temps, l'homme de talent que de l'employer.",
      "author": "Arthur Schopenhauer, extrait des \"Aphorismes sur la sagesse dans la vie\"",
      "sourcePage": 29
    },
    {
      "id": 1481,
      "text": "Les passionnés soulèvent le monde, et les sceptiques le laissent retomber.",
      "author": "Albert Guinon",
      "sourcePage": 29
    },
    {
      "id": 1482,
      "text": "Toute connaissance est une réponse à une question.",
      "author": "Gaston Bachelard",
      "sourcePage": 29
    },
    {
      "id": 1483,
      "text": "C'est proprement ne valoir rien que de n'être utile à personne.",
      "author": "René Descartes",
      "sourcePage": 29
    },
    {
      "id": 1484,
      "text": "Il y aurait de quoi faire bien des heureux avec tout le bonheur qui se perd en ce monde.",
      "author": "Duc de Lévis",
      "sourcePage": 29
    },
    {
      "id": 1485,
      "text": "Ça m'est égal d'être laide ou belle. Il faut seulement que je plaise aux gens qui m'intéressent.",
      "author": "Boris Vian, extrait de \"L'herbe rouge\"",
      "sourcePage": 29
    },
    {
      "id": 1486,
      "text": "Les yeux de l’esprit ne commencent à être perçants que quand ceux du corps commencent à baisser.",
      "author": "Platon, extrait de \"Le banquet\"",
      "sourcePage": 29
    },
    {
      "id": 1487,
      "text": "La Terre promise est toujours de l’autre côté du désert.",
      "author": "Henry Havelock Ellis, extrait de \"La danse de la vie\"",
      "sourcePage": 29
    },
    {
      "id": 1488,
      "text": "Les palmes qu'on remporte ne donnent pas toutes des fruits.",
      "author": "Stanislaw Jerzy Lec, extrait des \"Nouvelles pensées échevelées\"",
      "sourcePage": 29
    },
    {
      "id": 1489,
      "text": "La culture, c'est ce qui relie les savoirs et les féconde.",
      "author": "Edgar Morin",
      "sourcePage": 29
    },
    {
      "id": 1490,
      "text": "Quand on me contrarie, on éveille mon attention, non pas ma colère.",
      "author": "Montaigne, extrait des \"Essais\"",
      "sourcePage": 29
    },
    {
      "id": 1491,
      "text": "Point n'est besoin d'espérer pour entreprendre ni de réussir pour persévérer.",
      "author": "Guillaume le Taciturne",
      "sourcePage": 29
    },
    {
      "id": 1492,
      "text": "N’est-il pas honteux que les fanatiques aient du zèle et que les sages n’en aient pas ?",
      "author": "Voltaire, extrait des \"Pensées détachées de M. l’abbé de Saint-Pierre\"",
      "sourcePage": 30
    },
    {
      "id": 1493,
      "text": "Je chante pour mon vallon en souhaitant que dans chaque vallon un coq en fasse autant.",
      "author": "Edmond Rostand, extrait de \"Chantecler\"",
      "sourcePage": 30
    },
    {
      "id": 1494,
      "text": "Pas de chef-d'œuvre dans la paresse !",
      "author": "Salvador Dali",
      "sourcePage": 30
    },
    {
      "id": 1495,
      "text": "Apprends qu’un homme n’est pas plus qu’un autre, s’il ne fait plus qu’un autre.",
      "author": "Miguel de Cervantès, extrait de \"Don Quichotte\"",
      "sourcePage": 30
    },
    {
      "id": 1496,
      "text": "L’aventure est dans chaque souffle de vent.",
      "author": "Charles Lindbergh, extrait de \"The Spirit of St Louis\"",
      "sourcePage": 30
    },
    {
      "id": 1497,
      "text": "L’idéal est pour nous ce qu’est une étoile pour le marin. Il ne peut être atteint mais il demeure un guide.",
      "author": "Albert Schweitzer",
      "sourcePage": 30
    },
    {
      "id": 1498,
      "text": "La confiance en soi est le premier secret du succès.",
      "author": "Ralph Waldo Emerson, extrait de \"La confiance en soi\"",
      "sourcePage": 30
    },
    {
      "id": 1499,
      "text": "Nous cherchons plus à durer que nous n'essayons de vivre.",
      "author": "Andy Warhol",
      "sourcePage": 30
    },
    {
      "id": 1500,
      "text": "Le génie n’est pas celui qui croit mais celui qui saisit la progression des choses.",
      "author": "Laurent Lemire, extrait de la biographie \"Alan Turing\"",
      "sourcePage": 30
    },
    {
      "id": 1501,
      "text": "Il faut juger les sentiments par des actes plus que par des paroles.",
      "author": "George Sand, extrait de \"Le marquis de Villemer\"",
      "sourcePage": 30
    },
    {
      "id": 1502,
      "text": "Si l’homme construit les routes, la femme trace les chemins.",
      "author": "André Lévy, extrait de \"Les femmes\"",
      "sourcePage": 30
    },
    {
      "id": 1503,
      "text": "L'exemple, c'est tout ce qu'un père peut faire pour ses enfants.",
      "author": "Thomas Mann",
      "sourcePage": 30
    },
    {
      "id": 1504,
      "text": "Lire, c'est aller à la rencontre d'une chose qui va exister.",
      "author": "Italo Calvino, extrait de \"Si par une nuit d'hiver un voyageur\"",
      "sourcePage": 30
    },
    {
      "id": 1505,
      "text": "La richesse est un instrument dont on use, et non un dieu que l’on vénère.",
      "author": "Calvin Coolidge",
      "sourcePage": 30
    },
    {
      "id": 1506,
      "text": "On ne croit qu'en ceux qui croient en eux.",
      "author": "Talleyrand",
      "sourcePage": 30
    },
    {
      "id": 1507,
      "text": "A la liberté de provocation, répond la liberté d'objection.",
      "author": "Bernard Pivot, extrait de \"Le métier de lire\"",
      "sourcePage": 30
    },
    {
      "id": 1508,
      "text": "L’artiste est celui qui nous montre du doigt une parcelle du monde.",
      "author": "J.M.G. Le Clézio, extrait de \"L’extase matérielle\"",
      "sourcePage": 30
    },
    {
      "id": 1509,
      "text": "Ce n’est pas la façon dont sa lame est aiguisée qui fait le talent du sabreur.",
      "author": "Yvan Audouard, extrait de \"Le sabre de mon père\"",
      "sourcePage": 30
    },
    {
      "id": 1510,
      "text": "Si ma chaussure est étroite, que m’importe que le monde soit vaste.",
      "author": "Proverbe turc",
      "sourcePage": 30
    },
    {
      "id": 1511,
      "text": "Un défaut qui empêche les hommes d'agir, c'est de ne pas sentir de quoi ils sont capables.",
      "author": "Bossuet",
      "sourcePage": 30
    },
    {
      "id": 1512,
      "text": "L'arbre devient solide sous le vent.",
      "author": "Sénèque",
      "sourcePage": 30
    },
    {
      "id": 1513,
      "text": "Tout le monde voudrait vivre longtemps, mais personne ne voudrait être vieux.",
      "author": "Jonathan Swift, extrait des \"Pensées sur divers sujets moraux et divertissants\"",
      "sourcePage": 30
    },
    {
      "id": 1514,
      "text": "On a toujours le choix. On est même la somme de ses choix.",
      "author": "Joseph O'Connor, extrait de \"Desperados\"",
      "sourcePage": 30
    },
    {
      "id": 1515,
      "text": "Celui qui peut, agit. Celui qui ne peut pas, enseigne.",
      "author": "Bernard Shaw, extrait de \"Maximes pour révolutionnaires\"",
      "sourcePage": 30
    },
    {
      "id": 1516,
      "text": "Pour triompher, le mal n’a besoin que de l’inaction des gens de bien.",
      "author": "Edmund Burke, extrait de \"Attribution\"",
      "sourcePage": 30
    },
    {
      "id": 1517,
      "text": "Personne ne survit au fait d'être estimé au-dessus de sa valeur.",
      "author": "Oscar Wilde",
      "sourcePage": 30
    },
    {
      "id": 1518,
      "text": "L’habitude est une grande sourdine.",
      "author": "Samuel Beckett, extrait d’ \"En attendant Godot\"",
      "sourcePage": 30
    },
    {
      "id": 1519,
      "text": "Il n'y a que ceux qui rêvent qui peuvent espérer se réveiller.",
      "author": "Seumas O'Kelly, extrait de \"La tombe du tisserand\"",
      "sourcePage": 30
    },
    {
      "id": 1520,
      "text": "Ce que beurre et whisky ne peuvent soigner est incurable.",
      "author": "Proverbe irlandais",
      "sourcePage": 30
    },
    {
      "id": 1521,
      "text": "Les circonstances sont les maîtresses des faibles et les outils des sages.",
      "author": "Samuel Lover",
      "sourcePage": 30
    },
    {
      "id": 1522,
      "text": "L’innocence et la beauté n’ont d’ennemi que le temps.",
      "author": "William Butler Yeats",
      "sourcePage": 30
    },
    {
      "id": 1523,
      "text": "Tout ce qui a son prix est de peu de valeur.",
      "author": "Friedrich Nietzsche, extrait de \"Ainsi parlait Zarathoustra\"",
      "sourcePage": 30
    },
    {
      "id": 1524,
      "text": "Il est bien plus difficile de se juger soi-même que de juger autrui.",
      "author": "Antoine de Saint-Exupéry, extrait de \"Le petit prince\"",
      "sourcePage": 30
    },
    {
      "id": 1525,
      "text": "Les cœurs les plus proches ne sont pas ceux qui se touchent.",
      "author": "Proverbe chinois",
      "sourcePage": 30
    },
    {
      "id": 1526,
      "text": "Etre est plus indispensable qu'avoir. Le rêve, c'est d'avoir de quoi être.",
      "author": "Frédéric Dard",
      "sourcePage": 30
    },
    {
      "id": 1527,
      "text": "Le présent n’est pas un passé en puissance, il est le moment du choix et de l’action.",
      "author": "Simone de Beauvoir, extrait de \"Pour une morale de l’ambiguïté\"",
      "sourcePage": 30
    },
    {
      "id": 1528,
      "text": "Faute de but, l’homme devient une cible.",
      "author": "Ylipe, extrait de \"Textes sans paroles\"",
      "sourcePage": 30
    },
    {
      "id": 1529,
      "text": "Un bon maître a ce souci constant : enseigner à se passer de lui.",
      "author": "André Gide, extrait de \"Journal\"",
      "sourcePage": 30
    },
    {
      "id": 1530,
      "text": "Les querelles ne dureraient pas longtemps si le tort n’était que d’un côté.",
      "author": "La Rochefoucauld, extrait de \"Maximes\"",
      "sourcePage": 30
    },
    {
      "id": 1531,
      "text": "Les bonnes idées n’ont pas d’âge, elles ont seulement de l’avenir.",
      "author": "Robert Mallet, extrait des \"Apostilles ou l'utile et le futile\"",
      "sourcePage": 30
    },
    {
      "id": 1532,
      "text": "Il faut avoir déjà beaucoup appris de choses pour savoir demander ce qu’on ne sait pas.",
      "author": "Jean- Jacques Rousseau, extrait de \"Julie ou La nouvelle Héloïse\"",
      "sourcePage": 31
    },
    {
      "id": 1533,
      "text": "Je m’intéresse à l’avenir parce que c’est là que je vais passer le reste de ma vie.",
      "author": "Charles F. Kettering",
      "sourcePage": 31
    },
    {
      "id": 1534,
      "text": "On ne vit pas de ce que l'on mange, mais de ce que l'on digère.",
      "author": "Alexandre Dumas",
      "sourcePage": 31
    },
    {
      "id": 1535,
      "text": "La curiosité mène à tout : parfois à écouter aux portes, parfois à découvrir l'Amérique.",
      "author": "J. M. Eça de Queiros",
      "sourcePage": 31
    },
    {
      "id": 1536,
      "text": "Avoir les yeux fermés ne veut pas toujours dire qu'on dort, ni les avoir ouverts qu'on voit.",
      "author": "Bill Cosby",
      "sourcePage": 31
    },
    {
      "id": 1537,
      "text": "Quelqu'un s'assoit à l'ombre aujourd'hui parce quelqu'un d'autre a planté un arbre il y a longtemps.",
      "author": "Warren Buffett",
      "sourcePage": 31
    },
    {
      "id": 1538,
      "text": "On ne consulte que l'oreille parce qu'on manque de cœur.",
      "author": "Blaise Pascal, extrait des \"Pensées\"",
      "sourcePage": 31
    },
    {
      "id": 1539,
      "text": "La confiture n'est bonne que s'il faut monter sur une chaise pour attraper le pot dans le placard.",
      "author": "Alexandre Vialatte",
      "sourcePage": 31
    },
    {
      "id": 1540,
      "text": "Ce que les hommes veulent en fait, ce n’est pas la connaissance, c’est la certitude.",
      "author": "Bertrand Russell",
      "sourcePage": 31
    },
    {
      "id": 1541,
      "text": "Ce n'est plus souvent que la perte des choses qui en enseigne la valeur.",
      "author": "Arthur Schopenhauer, extrait des \"Aphorismes sur la sagesse dans la vie\"",
      "sourcePage": 31
    },
    {
      "id": 1542,
      "text": "Si la cause est bonne, c’est de la persévérance. Si la cause est mauvaise, c’est de l’obstination.",
      "author": "Lawrence Sterne, extrait de \"Tristam Shandy\"",
      "sourcePage": 31
    },
    {
      "id": 1543,
      "text": "L’avenir est un lieu commode pour y mettre des songes.",
      "author": "Anatole France, extrait de \"Les opinions de M. Jérôme Coignard\"",
      "sourcePage": 31
    },
    {
      "id": 1544,
      "text": "Seul celui qui aime existe.",
      "author": "Ludwig Feuerbach, extrait de \"Manifestes philosophiques\"",
      "sourcePage": 31
    },
    {
      "id": 1545,
      "text": "Chaque âge a ses problèmes. On les résout à l'âge suivant.",
      "author": "Maurice Chapelan",
      "sourcePage": 31
    },
    {
      "id": 1546,
      "text": "La perfection d'une pendule n'est pas d'aller vite, mais d'être réglée.",
      "author": "Vauvenargues, extrait de \"Réflexions et maximes\"",
      "sourcePage": 31
    },
    {
      "id": 1547,
      "text": "N'ayez pas peur de faire un grand pas si c'est indiqué : on ne franchit pas un abîme en deux petits sauts.",
      "author": "David Lloyd George",
      "sourcePage": 31
    },
    {
      "id": 1548,
      "text": "Certains sentent la pluie à l'avance : d'autres se contentent d'être mouillés.",
      "author": "Henry Miller",
      "sourcePage": 31
    },
    {
      "id": 1549,
      "text": "L’air du paradis est celui qui souffle entre les oreilles d’un cheval.",
      "author": "Proverbe arabe",
      "sourcePage": 31
    },
    {
      "id": 1550,
      "text": "Tout ce que les hommes ont fait de beau et de bien, ils l'ont construit avec leurs rêves...",
      "author": "Bernard Moitessier, extrait de \"La longue route\"",
      "sourcePage": 31
    },
    {
      "id": 1551,
      "text": "L’amour est un châtiment. Nous sommes punis de n’avoir pas pu rester seuls.",
      "author": "Marguerite Yourcenar, extrait de \"Feux\"",
      "sourcePage": 31
    },
    {
      "id": 1552,
      "text": "Les proverbes sont de courtes maximes tirées d’une longue expérience.",
      "author": "Miguel de Cervantès",
      "sourcePage": 31
    },
    {
      "id": 1553,
      "text": "Il n'y a que le premier pas qui coûte.",
      "author": "Marie du Deffand",
      "sourcePage": 31
    },
    {
      "id": 1554,
      "text": "On fait tout avec de l'argent, excepté des hommes.",
      "author": "Auguste Detœuf, extrait de \"Propos d’O.L. Barenton, confiseur\"",
      "sourcePage": 31
    },
    {
      "id": 1555,
      "text": "Les arbres aux racines profondes sont ceux qui montent haut.",
      "author": "Frédéric Mistral, extrait de \"Les îles d'or\"",
      "sourcePage": 31
    },
    {
      "id": 1556,
      "text": "Le monde progresse grâce aux choses impossibles qui ont été réalisées.",
      "author": "André Maurois",
      "sourcePage": 31
    },
    {
      "id": 1557,
      "text": "Pour retrouver sa jeunesse, il n'y a qu'à recommencer ses folies.",
      "author": "Oscar Wilde",
      "sourcePage": 31
    },
    {
      "id": 1558,
      "text": "La vie est ton navire et non pas ta demeure.",
      "author": "Alphonse de Lamartine",
      "sourcePage": 31
    },
    {
      "id": 1559,
      "text": "Arrêtez le mal avant qu’il n’existe ; calmez le désordre avant qu’il n’éclate.",
      "author": "Lao-Tseu",
      "sourcePage": 31
    },
    {
      "id": 1560,
      "text": "L'humanité se divise en trois catégories : ceux qui ne peuvent pas bouger, ceux qui peuvent bouger, et ceux qui bougent.",
      "author": "Benjamin Franklin",
      "sourcePage": 31
    },
    {
      "id": 1561,
      "text": "Se connaître soi-même, c'est s'oublier. S'oublier soi-même, c'est s'ouvrir à toutes choses.",
      "author": "Dôgen, extrait de \"GenjoKoan\"",
      "sourcePage": 31
    },
    {
      "id": 1562,
      "text": "Qui s'embarrasse à regretter le passé perd le présent et risque l'avenir.",
      "author": "Francisco de Quevedo",
      "sourcePage": 31
    },
    {
      "id": 1563,
      "text": "Pour qu'un château de cartes s'écroule, il suffit d'en retirer une seule.",
      "author": "Dominique Muller, extrait de \"Les filles prodigues\"",
      "sourcePage": 31
    },
    {
      "id": 1564,
      "text": "Découvrez ce que vous aimeriez faire et faites tout votre possible pour y parvenir.",
      "author": "Richard Bach, extrait de la préface de \"Jonathan Livingstone le goéland\"",
      "sourcePage": 31
    },
    {
      "id": 1565,
      "text": "Heureux celui qui oublie ce qu’on ne peut plus changer.",
      "author": "Proverbe allemand",
      "sourcePage": 31
    },
    {
      "id": 1566,
      "text": "Notre vie est pour une grande part composée de rêves. Il faut les rattacher à l'action.",
      "author": "Anaïs Nin",
      "sourcePage": 31
    },
    {
      "id": 1567,
      "text": "La pensée voyage à la vitesse du désir.",
      "author": "Malcolm de Chazal, extrait de \"Sens plastique\"",
      "sourcePage": 31
    },
    {
      "id": 1568,
      "text": "La meilleure séduction est de n'en employer aucune.",
      "author": "Prince de Ligne, extrait des \"Pensées et fragments\"",
      "sourcePage": 31
    },
    {
      "id": 1569,
      "text": "Il y a de l'espoir pour tout le monde, c'est ce qui fait tourner l'univers.",
      "author": "Paul Auster, extrait de \"Moon Palace\"",
      "sourcePage": 31
    },
    {
      "id": 1570,
      "text": "Il ne faut pas se fier aux choses qui ne peuvent pas arriver, car c'est justement celles-là qui arrivent.",
      "author": "Pierre Dac, extrait de \"Y'a du mou dans la corde à nœuds !\"",
      "sourcePage": 31
    },
    {
      "id": 1571,
      "text": "Il n'est point d'impasse là où on peut faire marche arrière.",
      "author": "Stanislaw Jerzy Lec, extrait des \"Nouvelles pensées échevelées\"",
      "sourcePage": 32
    },
    {
      "id": 1572,
      "text": "Il faut remettre une fois par an son avenir en jeu.",
      "author": "Arthur Cravan",
      "sourcePage": 32
    },
    {
      "id": 1573,
      "text": "Qu’une personne vous manque est moins grave que de ne manquer à personne.",
      "author": "Grégoire Lacroix, extrait de \"Les euphorismes de Grégoire\"",
      "sourcePage": 32
    },
    {
      "id": 1574,
      "text": "Rien n’est constant dans ce monde que l’inconstance.",
      "author": "Jonathan Swift, extrait de \"Essai critique sur les facultés de l’esprit\"",
      "sourcePage": 32
    },
    {
      "id": 1575,
      "text": "Quand il est dur d'avancer, ce sont les durs qui avancent.",
      "author": "John Fitzgerald Kennedy",
      "sourcePage": 32
    },
    {
      "id": 1576,
      "text": "La nature a donné aux grands hommes de faire, et laissé aux autres de juger.",
      "author": "Vauvenargues, extrait de \"Réflexions et maximes\"",
      "sourcePage": 32
    },
    {
      "id": 1577,
      "text": "La coutume est une seconde nature qui détruit la première.",
      "author": "Blaise Pascal, extrait des \"Pensées sur la religion\"",
      "sourcePage": 32
    },
    {
      "id": 1578,
      "text": "L’imagination porte bien plus loin que la vue.",
      "author": "Baltasar Gracian Y Morales",
      "sourcePage": 32
    },
    {
      "id": 1579,
      "text": "Nous sommes automates dans les trois quarts de nos actions.",
      "author": "Leibniz",
      "sourcePage": 32
    },
    {
      "id": 1580,
      "text": "Conservons par la sagesse ce que nous avons acquis par l'enthousiasme.",
      "author": "Condorcet",
      "sourcePage": 32
    },
    {
      "id": 1581,
      "text": "Il ne suffit pas d'avoir les mains propres, il faut avoir l'esprit pur.",
      "author": "Thalès",
      "sourcePage": 32
    },
    {
      "id": 1582,
      "text": "Un beau livre, c'est celui qui sème à foison les points d'interrogation.",
      "author": "Jean Cocteau, extrait de \"Le rappel à l'ordre\"",
      "sourcePage": 32
    },
    {
      "id": 1583,
      "text": "La vie passe, rapide caravane ! Arrête ta monture et cherche à être heureux.",
      "author": "Omar Khayyâm, extrait de \"Rubâ'iyyât\"",
      "sourcePage": 32
    },
    {
      "id": 1584,
      "text": "Nous aurons le destin que nous aurons mérité.",
      "author": "Albert Einstein, extrait de \"Comment je vois le monde\"",
      "sourcePage": 32
    },
    {
      "id": 1585,
      "text": "On n’est jamais si heureux ni si malheureux qu’on s’imagine.",
      "author": "La Rochefoucauld, extrait des \"Maximes\"",
      "sourcePage": 32
    },
    {
      "id": 1586,
      "text": "Il est bien des choses qui ne paraissent impossibles que tant qu’on ne les a pas tentées.",
      "author": "André Gide, extrait de \"Si le grain ne meurt\"",
      "sourcePage": 32
    },
    {
      "id": 1587,
      "text": "Le véritable travail, c'est de savoir attendre.",
      "author": "Jean Rostand, extrait des \"Pages d'un moraliste\"",
      "sourcePage": 32
    },
    {
      "id": 1588,
      "text": "Si le cœur ne contemple pas, l’œil ne verra pas.",
      "author": "Proverbe caucasien",
      "sourcePage": 32
    },
    {
      "id": 1589,
      "text": "La mer est aussi profonde dans le calme que dans la tempête.",
      "author": "John Donne, extrait de \"Sermons\"",
      "sourcePage": 32
    },
    {
      "id": 1590,
      "text": "Tout est possible sauf la paix dans le monde.",
      "author": "Jim Harrison, extrait de \"De Marquette à Veracruz\"",
      "sourcePage": 32
    },
    {
      "id": 1591,
      "text": "Le mensonge des uns est l'antidote aux mensonges des autres.",
      "author": "Bernardo Carvalho, extrait de \"Mongolia\"",
      "sourcePage": 32
    },
    {
      "id": 1592,
      "text": "La force des vrais détours n'est pas d'éloigner mais d'atteindre au but avec plus d'exactitude.",
      "author": "Benjamin Pelletier, extrait de \"La mère des batailles\"",
      "sourcePage": 32
    },
    {
      "id": 1593,
      "text": "Etre rebelle, c'est refuser l'idée que le monde est figé.",
      "author": "Benoît Duteurtre, extrait de \"La rebelle\"",
      "sourcePage": 32
    },
    {
      "id": 1594,
      "text": "Qu’est-ce que créer sinon tenter désespérément de laisser une trace de son passage sur terre ?",
      "author": "Jérôme Garcin, extrait de \"Bartabas, roman\"",
      "sourcePage": 32
    },
    {
      "id": 1595,
      "text": "Il faut écrire pour soi, c’est ainsi que l’on peut arriver aux autres.",
      "author": "Eugène Ionesco, extrait de \"Notes et contre-notes\"",
      "sourcePage": 32
    },
    {
      "id": 1596,
      "text": "Changez vos stratégies et tactiques, mais jamais vos principes.",
      "author": "John Kessel",
      "sourcePage": 32
    },
    {
      "id": 1597,
      "text": "L'essentiel consiste à ne pas s'affliger.",
      "author": "Roberto Bolano, extrait de \"Le gaucho insupportable\"",
      "sourcePage": 32
    },
    {
      "id": 1598,
      "text": "Les scrupules sont contraires au désir et à l'existence.",
      "author": "Pierre Garçonnat, extrait de \"L’orangerie de Meudon\"",
      "sourcePage": 32
    },
    {
      "id": 1599,
      "text": "Posséder, c’est se déposséder.",
      "author": "Fabrice Pliskin, extrait de \"L’agent dormant\"",
      "sourcePage": 32
    },
    {
      "id": 1600,
      "text": "Réclamer le possible, tout le possible, c'est critiquer le monde tel qu'il est.",
      "author": "Erik Orsenna, extrait de \"Les chevaliers du subjonctif\"",
      "sourcePage": 32
    },
    {
      "id": 1601,
      "text": "La rentrée littéraire est une maladie française qu’il ne faut surtout pas soigner.",
      "author": "Frédéric Beigbeder, extrait du magazine \"Lire - Juillet 2004\"",
      "sourcePage": 32
    },
    {
      "id": 1602,
      "text": "La vie est dure, mais elle est belle puisqu’on y tient tellement.",
      "author": "François Truffaut, cité dans le livre de Dominique Auzel \"Paroles de François Truffaut\"",
      "sourcePage": 32
    },
    {
      "id": 1603,
      "text": "Les hommes disent que la vie est courte, et je vois qu’ils s’efforcent de la rendre telle.",
      "author": "Jean- Jacques Rousseau, extrait de \"Emile ou de l’éducation\"",
      "sourcePage": 32
    },
    {
      "id": 1604,
      "text": "L’amour, la seule obsession que tout le monde désire.",
      "author": "Philip Roth, extrait de \"La bête qui meurt\"",
      "sourcePage": 32
    },
    {
      "id": 1605,
      "text": "Les choses ne sont pas ce qu'elles sont mais ce qu'elles doivent être, à nous de tirer sur les rênes.",
      "author": "Gilles Veber, extrait de \"Gauthier\"",
      "sourcePage": 32
    },
    {
      "id": 1606,
      "text": "On peut rater sa vie à cause d'un seul mot.",
      "author": "Amélie Nothomb, extrait de \"Biographie de la faim\"",
      "sourcePage": 32
    },
    {
      "id": 1607,
      "text": "Pour atteindre la vérité, il faut perdre du temps et cesser de travailler.",
      "author": "Montserrat Figueras, extrait de \"La griffe du passé\"",
      "sourcePage": 32
    },
    {
      "id": 1608,
      "text": "Le bonheur, c’est un choix.",
      "author": "David Sandes, extrait de \"La méthode miraculeuse de Félix Bubka\"",
      "sourcePage": 32
    },
    {
      "id": 1609,
      "text": "Plus aucun idéal ne vaut qu'on se sacrifie pour lui, il n'y a rien au- dessus de la vie.",
      "author": "Pascal Bruckner, extrait de \"La tentation de l’innocence\"",
      "sourcePage": 32
    },
    {
      "id": 1610,
      "text": "Rien n’empêche tant d’être naturel que l’envie de le paraître.",
      "author": "La Rochefoucauld, extrait des \"Maximes\"",
      "sourcePage": 33
    },
    {
      "id": 1611,
      "text": "Toutes les fleurs de l'avenir sont dans les semences d'aujourd'hui.",
      "author": "Proverbe chinois",
      "sourcePage": 33
    },
    {
      "id": 1612,
      "text": "Il faut arranger nos souvenirs. Sans ça, la vie n’est pas supportable.",
      "author": "Philippe Besson, extrait de \"Les jours fragiles\"",
      "sourcePage": 33
    },
    {
      "id": 1613,
      "text": "La mémoire est aussi menteuse que l'imagination, et bien plus dangereuse avec ses petits airs studieux.",
      "author": "Françoise Sagan",
      "sourcePage": 33
    },
    {
      "id": 1614,
      "text": "Les vérités qui nous importent le plus ne sont jamais dites qu’à moitié.",
      "author": "Baltasar Gracian Y Morales, extrait de \"L'homme universel\"",
      "sourcePage": 33
    },
    {
      "id": 1615,
      "text": "Pour la plupart des hommes, se corriger consiste à changer de défauts.",
      "author": "Voltaire",
      "sourcePage": 33
    },
    {
      "id": 1616,
      "text": "Je vais bien. Et si tout le monde allait aussi bien que moi, j'irais beaucoup mieux.",
      "author": "Guy Bedos",
      "sourcePage": 33
    },
    {
      "id": 1617,
      "text": "Notre tête est ronde pour permettre à la pensée de changer de direction.",
      "author": "Francis Picabia, extrait de la revue \"La pomme de pins - Février 1922\"",
      "sourcePage": 33
    },
    {
      "id": 1618,
      "text": "Il n'y a pas de vérités, pas de mensonges. Tout est une histoire d'opinions.",
      "author": "Terry Gilliam, dialogue du film américain \"L'armée des douze singes\"",
      "sourcePage": 33
    },
    {
      "id": 1619,
      "text": "Sachons éviter les offenses, puisque nous ne savons pas les supporter.",
      "author": "Sénèque, extrait de \"De la colère\"",
      "sourcePage": 33
    },
    {
      "id": 1620,
      "text": "Découvrir consiste à voir comme tout le monde et à réfléchir comme personne.",
      "author": "Albert Szent Györgyi",
      "sourcePage": 33
    },
    {
      "id": 1621,
      "text": "Faites confiance à votre instinct. Il vaut mieux que les erreurs soient les vôtres, plutôt que celles de quelqu'un d'autre.",
      "author": "Billy Wilder",
      "sourcePage": 33
    },
    {
      "id": 1622,
      "text": "Les hommes n'acceptent le changement que dans la nécessité et ils ne voient la nécessité que dans la crise.",
      "author": "Jean Monnet",
      "sourcePage": 33
    },
    {
      "id": 1623,
      "text": "Rien n'est meilleur à l'âme que de faire une âme moins triste...",
      "author": "Benoît Duteurtre, extrait de \"Le voyage en France\"",
      "sourcePage": 33
    },
    {
      "id": 1624,
      "text": "La vérité est dans l’imaginaire.",
      "author": "Eugène Ionesco",
      "sourcePage": 33
    },
    {
      "id": 1625,
      "text": "Je ne perdrai pas mon temps à essayer de prolonger ma vie.",
      "author": "Claude Pujade Renaud, extrait de \"Chers disparus\"",
      "sourcePage": 33
    },
    {
      "id": 1626,
      "text": "Difficile de dire qui suit le courant de son plein gré.",
      "author": "Stanislaw Jerzy Lec, extrait des \"Nouvelles pensées échevelées\"",
      "sourcePage": 33
    },
    {
      "id": 1627,
      "text": "Insister, c'est exister ! Il faut se battre pour faire aboutir ses idées.",
      "author": "Christian Blachas",
      "sourcePage": 33
    },
    {
      "id": 1628,
      "text": "Nous plantons les graines de la paix, maintenant et pour le futur.",
      "author": "Wangari Maathai",
      "sourcePage": 33
    },
    {
      "id": 1629,
      "text": "Un livre a toujours deux auteurs : celui qui l’écrit et celui qui le lit.",
      "author": "Jacques Salomé, extrait de \"Si je m’écoutais, je m’entendrais\"",
      "sourcePage": 33
    },
    {
      "id": 1630,
      "text": "Un roman est un miroir qui se promène sur une grande route.",
      "author": "Stendhal, extrait de \"Le rouge et le noir\"",
      "sourcePage": 33
    },
    {
      "id": 1631,
      "text": "Il vaut mieux écrire de grandes choses que d’en exécuter de petites.",
      "author": "Denis Diderot, extrait de \"Le neveu de Rameau\"",
      "sourcePage": 33
    },
    {
      "id": 1632,
      "text": "Le talent et le goût ne suffisent pas, seul le style compte.",
      "author": "Pierre Cardin",
      "sourcePage": 33
    },
    {
      "id": 1633,
      "text": "On concède la liberté en gros pour la contraindre dans le détail.",
      "author": "Robert Sabatier, extrait de \"Le livre de la déraison souriante\"",
      "sourcePage": 33
    },
    {
      "id": 1634,
      "text": "Je redoute l'hiver parce que c'est la saison du confort !",
      "author": "Arthur Rimbaud, extrait d’ \"Une saison en enfer\"",
      "sourcePage": 33
    },
    {
      "id": 1635,
      "text": "Le cinéma c’est de l’art de faire faire de jolies choses à de jolies femmes.",
      "author": "François Truffaut",
      "sourcePage": 33
    },
    {
      "id": 1636,
      "text": "La logique mène à tout, à condition d’en sortir.",
      "author": "Alphonse Allais, extrait de \"Pas de bile\"",
      "sourcePage": 33
    },
    {
      "id": 1637,
      "text": "Il y a plus de courage que de talent dans la plupart des réussites.",
      "author": "Félix Leclerc",
      "sourcePage": 33
    },
    {
      "id": 1638,
      "text": "Si tous tiraient dans la même direction, le monde basculerait.",
      "author": "Proverbe yiddish",
      "sourcePage": 33
    },
    {
      "id": 1639,
      "text": "Qui n’a pas les moyens de ses ambitions a tous les soucis.",
      "author": "Talleyrand",
      "sourcePage": 33
    },
    {
      "id": 1640,
      "text": "On peut réduire une œuvre d’art à son seul prix, mais cela ne représentera jamais sa valeur réelle.",
      "author": "Isabelle Jarry, extrait de \"J’ai nom sans bruit\"",
      "sourcePage": 33
    },
    {
      "id": 1641,
      "text": "Nous avons si peu l'habitude de la bonté que nous la confondons, en général, avec l'idiotie.",
      "author": "Rosa Montero, extrait de \"Le territoires des barbares\"",
      "sourcePage": 33
    },
    {
      "id": 1642,
      "text": "Le bien est dans le bon usage que l'on fait de n'importe quoi.",
      "author": "Marcel Jouhandeau",
      "sourcePage": 33
    },
    {
      "id": 1643,
      "text": "Pour désirer laisser des traces dans le monde, il faut en être solidaire.",
      "author": "Simone de Beauvoir, extrait de \"L'invitée\"",
      "sourcePage": 33
    },
    {
      "id": 1644,
      "text": "Point n'est besoin d'écrire pour avoir de la poésie dans ses poches.",
      "author": "Léon-Paul Fargue, extrait de \"Le piéton de Paris\"",
      "sourcePage": 33
    },
    {
      "id": 1645,
      "text": "Le temps n'épargne pas ce qu'on a fait sans lui.",
      "author": "François Fayolle",
      "sourcePage": 33
    },
    {
      "id": 1646,
      "text": "Toute opinion est indifférente aux ambitieux, pourvu qu'ils gouvernent.",
      "author": "Jacques-Henri Bernardin de Saint-Pierre, extrait de \"Paul et Virginie\"",
      "sourcePage": 33
    },
    {
      "id": 1647,
      "text": "La terre s'est imposée l'homme pour châtiment.",
      "author": "Pablo Neruda, extrait de \"Canto General\"",
      "sourcePage": 33
    },
    {
      "id": 1648,
      "text": "Le futur appartient à celui qui a la plus longue mémoire.",
      "author": "Friedrich Nietzsche",
      "sourcePage": 33
    },
    {
      "id": 1649,
      "text": "Dans \"connaître\", il y a \"naître\".",
      "author": "Victor Hugo, extrait de \"Carnet\"",
      "sourcePage": 34
    },
    {
      "id": 1650,
      "text": "Seule la paresse fatigue le cerveau.",
      "author": "Louis Pauwels, extrait de \"L'apprentissage de la sérénité\"",
      "sourcePage": 34
    },
    {
      "id": 1651,
      "text": "Le Génie est comme le diamant : il brille dans l’ombre.",
      "author": "Xavier Forneret, extrait de \"Sans titre\"",
      "sourcePage": 34
    },
    {
      "id": 1652,
      "text": "Personne ne croit aux experts, mais tout le monde les écoute.",
      "author": "Auguste Detœuf",
      "sourcePage": 34
    },
    {
      "id": 1653,
      "text": "Il y a dans la vie tellement de choses susceptibles de nous rendre heureux.",
      "author": "Arthur Rubinstein",
      "sourcePage": 34
    },
    {
      "id": 1654,
      "text": "Dans la balance de la destinée, le muscle ne pèse jamais autant que le cerveau.",
      "author": "James Russel Lowell",
      "sourcePage": 34
    },
    {
      "id": 1655,
      "text": "S’il n’y avait pas de montagnes, les plaines n’apparaîtraient pas.",
      "author": "Proverbe chinois",
      "sourcePage": 34
    },
    {
      "id": 1656,
      "text": "La mémoire est l'avenir du passé.",
      "author": "Paul Valéry, extrait de \"Cahiers I\"",
      "sourcePage": 34
    },
    {
      "id": 1657,
      "text": "Si tu veux comprendre le mot bonheur, il faut l’entendre comme récompense et non comme but.",
      "author": "Antoine de Saint-Exupéry, extrait de \"Carnets\"",
      "sourcePage": 34
    },
    {
      "id": 1658,
      "text": "Ce n'est pas seulement le monde qu'il s'agit de changer ; mais l'homme.",
      "author": "André Gide, extrait de \"Les nouvelles nourritures\"",
      "sourcePage": 34
    },
    {
      "id": 1659,
      "text": "Efforce-toi de ne pas être de ton temps.",
      "author": "Georg Christoph Lichtenberg, extrait de \"Le miroir de l'âme\"",
      "sourcePage": 34
    },
    {
      "id": 1660,
      "text": "Savoir écouter, c'est posséder, outre le sien, le cerveau des autres.",
      "author": "Léonard de Vinci",
      "sourcePage": 34
    },
    {
      "id": 1661,
      "text": "On n'est jamais aussi vainqueur ni aussi vaincu qu'on se l'imagine.",
      "author": "Charles de Montalembert",
      "sourcePage": 34
    },
    {
      "id": 1662,
      "text": "Les haines de races ne sont jamais au fond, que des haines de places.",
      "author": "Edmond Rostand, extrait de \"Chantecler\"",
      "sourcePage": 34
    },
    {
      "id": 1663,
      "text": "La vie puise dans l’écriture et les livres s’inspirent de la réalité.",
      "author": "Enrique Vila-Matas",
      "sourcePage": 34
    },
    {
      "id": 1664,
      "text": "Les hommes peuvent atteindre un but commun sans emprunter les mêmes voies.",
      "author": "Amadou Hampâté Bâ",
      "sourcePage": 34
    },
    {
      "id": 1665,
      "text": "C'est d'âme qu'il faut changer, non de climat.",
      "author": "Sénèque, extrait des \"Lettres à Lucilius\"",
      "sourcePage": 34
    },
    {
      "id": 1666,
      "text": "Seules les femmes voient vraiment les choses. Les hommes n'ont jamais qu'une idée.",
      "author": "Marcel Aymé, extrait de \"Uranus\"",
      "sourcePage": 34
    },
    {
      "id": 1667,
      "text": "La vie, c’est comme une bicyclette, il faut avancer pour ne pas perdre l’équilibre.",
      "author": "Albert Einstein",
      "sourcePage": 34
    },
    {
      "id": 1668,
      "text": "On dit que les nouvelles générations sont difficiles à gouverner. Je l’espère bien.",
      "author": "Alain, extrait des \"Propos sur l’éducation\"",
      "sourcePage": 34
    },
    {
      "id": 1669,
      "text": "Il est difficile de vaincre ses passions, et impossible de les satisfaire.",
      "author": "Marguerite de La Sablière, cité dans les \"Réflexions ou sentences et maximes morales\"",
      "sourcePage": 34
    },
    {
      "id": 1670,
      "text": "Peu de livres changent une vie. Quand ils la changent c'est pour toujours.",
      "author": "Christian Bobin, extrait de \"La plus que vive\"",
      "sourcePage": 34
    },
    {
      "id": 1671,
      "text": "Ce n'est pas la force, mais la persévérance, qui fait les grandes œuvres.",
      "author": "Samuel Johnson",
      "sourcePage": 34
    },
    {
      "id": 1672,
      "text": "Pour être simple, il faut beaucoup apprendre.",
      "author": "Olga Sedakova",
      "sourcePage": 34
    },
    {
      "id": 1673,
      "text": "On n'a pas besoin de gravir une montagne pour savoir si elle est élevée.",
      "author": "Paulo Coelho, extrait de \"Le pèlerin de Compostelle\"",
      "sourcePage": 34
    },
    {
      "id": 1674,
      "text": "Ce sont les échecs bien supportés qui donnent le droit de réussir.",
      "author": "Jean Mermoz",
      "sourcePage": 34
    },
    {
      "id": 1675,
      "text": "Il vaut mieux fortifier ses points forts que combler ses points faibles.",
      "author": "Bernard Werber, extrait de \"L'empire des anges\"",
      "sourcePage": 34
    },
    {
      "id": 1676,
      "text": "Le véritable trésor, c'est de pouvoir compter sur les autres.",
      "author": "Massa Makan Diabaté, extrait de \"Kala Jata\"",
      "sourcePage": 34
    },
    {
      "id": 1677,
      "text": "Il faut oser ou se résigner à tout.",
      "author": "Tite-Live",
      "sourcePage": 34
    },
    {
      "id": 1678,
      "text": "Si un arc-en-ciel dure un quart d'heure, on ne le regarde plus.",
      "author": "Goethe, extrait des \"Maximes et pensées\"",
      "sourcePage": 34
    },
    {
      "id": 1679,
      "text": "On ne donne la parole qu'à ceux qui veulent la prendre.",
      "author": "Guy Bedos, extrait de \"Inconsolable et gai\"",
      "sourcePage": 34
    },
    {
      "id": 1680,
      "text": "Il vaut mieux ne pas faire le voyage que s’arrêter en chemin.",
      "author": "Michel Polac, extrait d’ \"Hors de soi\"",
      "sourcePage": 34
    },
    {
      "id": 1681,
      "text": "On ne peut poser les pieds sur le sol tant qu'on n’a pas touché le ciel.",
      "author": "Paul Auster, extrait de \"Moon Palace\"",
      "sourcePage": 34
    },
    {
      "id": 1682,
      "text": "Ceux qui ne connaissent pas leur histoire s'exposent à ce qu'elle recommence...",
      "author": "Elie Wiesel",
      "sourcePage": 34
    },
    {
      "id": 1683,
      "text": "La persuasion n’annule pas définitivement le doute.",
      "author": "Denis Guedj, extrait de \"Le théorème du perroquet\"",
      "sourcePage": 34
    },
    {
      "id": 1684,
      "text": "Le travail de la jeunesse fait le repos de la vieillesse.",
      "author": "Proverbe grec antique",
      "sourcePage": 34
    },
    {
      "id": 1685,
      "text": "Dire oui à tout et à tout le monde, c'est comme si on n'existait pas.",
      "author": "Tahar Ben Jelloun, extrait de \"L'auberge des pauvres\"",
      "sourcePage": 34
    },
    {
      "id": 1686,
      "text": "Il faut être prudent, mais non pas timide.",
      "author": "Voltaire",
      "sourcePage": 34
    },
    {
      "id": 1687,
      "text": "Recommencer, ce n’est pas refaire.",
      "author": "César, extrait d'une interview dans \"Opus International\"",
      "sourcePage": 34
    },
    {
      "id": 1688,
      "text": "Les leçons ne servent généralement qu'à ceux qui les donnent.",
      "author": "Pierre Dac, extrait de \"Y'a du mou dans la corde à nœuds !\"",
      "sourcePage": 34
    },
    {
      "id": 1689,
      "text": "Le monde m'est nouveau à mon réveil, chaque matin.",
      "author": "Colette",
      "sourcePage": 34
    },
    {
      "id": 1690,
      "text": "Vous devez toujours savoir distinguer l'essentiel de la futilité.",
      "author": "David Ben Gourion",
      "sourcePage": 34
    },
    {
      "id": 1691,
      "text": "J’ai besoin du bonheur de tous pour être heureux.",
      "author": "André Gide",
      "sourcePage": 34
    },
    {
      "id": 1692,
      "text": "Prévoir consiste à projeter dans l'avenir ce qu'on a perçu dans le passé.",
      "author": "Henri Bergson",
      "sourcePage": 35
    },
    {
      "id": 1693,
      "text": "Il faut mettre son génie dans sa vie et son talent dans ses œuvres.",
      "author": "Oscar Wilde",
      "sourcePage": 35
    },
    {
      "id": 1694,
      "text": "Il y a plus de choses dans le ciel et sur la terre que n'en rêve votre philosophie.",
      "author": "William Shakespeare, extrait de \"Hamlet\"",
      "sourcePage": 35
    },
    {
      "id": 1695,
      "text": "A quoi bon soulever des montagnes quand il est si simple de passer par dessus ?",
      "author": "Boris Vian",
      "sourcePage": 35
    },
    {
      "id": 1696,
      "text": "Quelle flamme pourrait égaler le rayon de soleil d’un jour d’hiver ?",
      "author": "Henry David Thoreau",
      "sourcePage": 35
    },
    {
      "id": 1697,
      "text": "Délaisse les grandes routes, prends les sentiers.",
      "author": "Pythagore",
      "sourcePage": 35
    },
    {
      "id": 1698,
      "text": "Il faut que l'idée naisse de la vision comme l'étincelle du caillou.",
      "author": "Charles-Ferdinand Ramuz",
      "sourcePage": 35
    },
    {
      "id": 1699,
      "text": "Noël n’est pas un jour ni une saison, c’est un état d’esprit.",
      "author": "Calvin Coolidge",
      "sourcePage": 35
    },
    {
      "id": 1700,
      "text": "Avec un morceau de pain, on trouve son paradis sous un sapin.",
      "author": "Proverbe russe",
      "sourcePage": 35
    },
    {
      "id": 1701,
      "text": "L'amour se passe de cadeaux, mais pas de présence.",
      "author": "Félix Leclerc",
      "sourcePage": 35
    },
    {
      "id": 1702,
      "text": "La culture... ce qui a fait de l'homme autre chose qu'un accident de l'univers.",
      "author": "André Malraux",
      "sourcePage": 35
    },
    {
      "id": 1703,
      "text": "Les mots justes trouvés au bon moment sont de l'action.",
      "author": "Hannah Arendt",
      "sourcePage": 35
    },
    {
      "id": 1704,
      "text": "Cœur insouciant vit longtemps.",
      "author": "William Shakespeare",
      "sourcePage": 35
    },
    {
      "id": 1705,
      "text": "Je me presse de rire de tout, de peur d’être obligé d’en pleurer.",
      "author": "Beaumarchais, extrait de \"Le barbier de Séville\"",
      "sourcePage": 35
    },
    {
      "id": 1706,
      "text": "De la musique avant toute chose.",
      "author": "Paul Verlaine, extrait de \"L’art poétique\"",
      "sourcePage": 35
    },
    {
      "id": 1707,
      "text": "Et comme ton bonheur dépend tout de tes vœux, songes-y bien avant que de les faire.",
      "author": "Charles Perrault, extrait du conte \"Les souhaits ridicules\"",
      "sourcePage": 35
    },
    {
      "id": 1708,
      "text": "Ignorant d’où je viens, incertain où je vais.",
      "author": "Alphonse de Lamartine, extrait du poème \"L’homme\"",
      "sourcePage": 35
    },
    {
      "id": 1709,
      "text": "Plus on connaît, plus on aime.",
      "author": "Léonard de Vinci, extrait des \"Carnets\"",
      "sourcePage": 35
    },
    {
      "id": 1710,
      "text": "Celui qui sait aimer peut seul savoir combien on l'aime.",
      "author": "Alfred de Musset",
      "sourcePage": 35
    },
    {
      "id": 1711,
      "text": "Change de ciel, tu changeras d’étoile.",
      "author": "Proverbe corse",
      "sourcePage": 35
    },
    {
      "id": 1712,
      "text": "On ne peut aimer que dans la sérénité, autrement on s'égare.",
      "author": "Marie-Claire Blais",
      "sourcePage": 35
    },
    {
      "id": 1713,
      "text": "Le sentiment de nos forces les augmente.",
      "author": "Vauvenargues",
      "sourcePage": 35
    },
    {
      "id": 1714,
      "text": "L'amitié double les joies et réduit de moitié les peines.",
      "author": "Francis Bacon",
      "sourcePage": 35
    },
    {
      "id": 1715,
      "text": "Ce n'est pas parce que les choses sont difficiles que nous n'osons pas, c'est parce que nous n'osons pas qu'elles sont difficiles.",
      "author": "Sénèque",
      "sourcePage": 35
    },
    {
      "id": 1716,
      "text": "Se vouloir libre, c'est aussi vouloir les autres libres.",
      "author": "Simone de Beauvoir, extrait de \"Pour une morale de l'ambiguïté\"",
      "sourcePage": 35
    },
    {
      "id": 1717,
      "text": "Penser, c'est chercher des clairières dans une forêt.",
      "author": "Jules Renard, extrait de son \"Journal\"",
      "sourcePage": 35
    },
    {
      "id": 1718,
      "text": "Même la petite rosée fait prospérer le champ.",
      "author": "Christian Jacq, extrait de \"La pierre de lumière\"",
      "sourcePage": 35
    },
    {
      "id": 1719,
      "text": "Avoir fait plus pour le monde que le monde n’a fait pour vous : c’est ça, le succès.",
      "author": "Henry Ford",
      "sourcePage": 35
    },
    {
      "id": 1720,
      "text": "Rien de tel que d’aller au bout du monde pour trouver des gens qui vont encore plus loin.",
      "author": "Pierre Daninos, extrait de \"Vacances à tous prix\"",
      "sourcePage": 35
    },
    {
      "id": 1721,
      "text": "Il faut tenir à une résolution parce qu'elle est bonne, et non parce qu'on l'a prise.",
      "author": "La Rochefoucauld",
      "sourcePage": 35
    },
    {
      "id": 1722,
      "text": "L'enthousiasme est une maladie qui se gagne.",
      "author": "Voltaire, extrait de \"Lettres philosophiques\"",
      "sourcePage": 35
    },
    {
      "id": 1723,
      "text": "Tout le monde croit savoir exactement comment nous devrions vivre.",
      "author": "Paulo Coelho, extrait de \"L'alchimiste\"",
      "sourcePage": 35
    },
    {
      "id": 1724,
      "text": "Un livre est une fenêtre par laquelle on s’évade.",
      "author": "Julien Green",
      "sourcePage": 35
    },
    {
      "id": 1725,
      "text": "Le seul mauvais choix est l’absence de choix.",
      "author": "Amélie Nothomb, extrait de la \"Métaphysique des tubes\"",
      "sourcePage": 35
    },
    {
      "id": 1726,
      "text": "La fatalité triomphe dès que l'on croit en elle.",
      "author": "Simone de Beauvoir",
      "sourcePage": 35
    },
    {
      "id": 1727,
      "text": "Je veux être tout ce que je suis capable de devenir.",
      "author": "Katherine Mansfield",
      "sourcePage": 35
    },
    {
      "id": 1728,
      "text": "Bien dire fait rire, bien faire fait taire.",
      "author": "André Dacier",
      "sourcePage": 35
    },
    {
      "id": 1729,
      "text": "Au tamis de la vie, je n’ai gardé que les paillettes et tout le sable est parti au fil de l’eau.",
      "author": "Yvan Audouard, extrait de \"Les nouveaux contes de ma Provence\"",
      "sourcePage": 35
    },
    {
      "id": 1730,
      "text": "D’un œil, observer le monde extérieur, de l’autre regarder au fond de soi-même.",
      "author": "Amedeo Modigliani",
      "sourcePage": 35
    },
    {
      "id": 1731,
      "text": "Tous les hommes font la même erreur, de s'imaginer que bonheur veut dire que tous les vœux se réalisent.",
      "author": "Léon Tolstoï",
      "sourcePage": 35
    },
    {
      "id": 1732,
      "text": "Un grain de poésie suffit à parfumer tout un siècle.",
      "author": "José Marti, extrait de \"Pages choisies\"",
      "sourcePage": 35
    },
    {
      "id": 1733,
      "text": "La moitié du monde ne sait comment l'autre vit.",
      "author": "François Rabelais",
      "sourcePage": 35
    },
    {
      "id": 1734,
      "text": "Celui qui se perd dans sa passion perd moins que celui qui perd sa passion.",
      "author": "Saint Augustin",
      "sourcePage": 35
    },
    {
      "id": 1735,
      "text": "A qui sait attendre, le temps ouvre ses portes.",
      "author": "Proverbe chinois",
      "sourcePage": 35
    },
    {
      "id": 1736,
      "text": "Tout nuage n'enfante pas une tempête.",
      "author": "William Shakespeare",
      "sourcePage": 35
    },
    {
      "id": 1737,
      "text": "Il y a toujours dans notre enfance, un moment où la porte s'ouvre et laisse entrer l'avenir.",
      "author": "Graham Greene",
      "sourcePage": 35
    },
    {
      "id": 1738,
      "text": "La vie ressemble à un conte ; ce qui importe, ce n'est pas sa longueur, mais sa valeur.",
      "author": "Sénèque",
      "sourcePage": 35
    },
    {
      "id": 1739,
      "text": "La vraie sagesse est de ne pas sembler sage.",
      "author": "Eschyle, extrait de \"Prométhée enchaîné\"",
      "sourcePage": 35
    },
    {
      "id": 1740,
      "text": "Il est dit que tout homme doit découvrir quelque chose qui justifie sa vie.",
      "author": "Luis Sepulveda, extrait de \"Une sale histoire\"",
      "sourcePage": 36
    },
    {
      "id": 1741,
      "text": "Maison de paille où l’on rit vaut mieux qu’un palais où l’on pleure.",
      "author": "Proverbe chinois",
      "sourcePage": 36
    },
    {
      "id": 1742,
      "text": "On rencontre sa destinée souvent par les chemins qu’on prend pour l’éviter.",
      "author": "Jean de La Fontaine, extrait des \"Fables\"",
      "sourcePage": 36
    },
    {
      "id": 1743,
      "text": "La liberté, c'est un cadeau qu'on se fait à soi-même.",
      "author": "Louis Gauthier, extrait de \"Souvenir de San Chiquita\"",
      "sourcePage": 36
    },
    {
      "id": 1744,
      "text": "L’espoir est une bulle irisée qui colore fugitivement la vie.",
      "author": "Jean Mauduit",
      "sourcePage": 36
    },
    {
      "id": 1745,
      "text": "La bonne humeur a quelque chose de généreux : elle donne plutôt qu’elle ne reçoit.",
      "author": "Alain, extrait de \"Propos\"",
      "sourcePage": 36
    },
    {
      "id": 1746,
      "text": "Créer, c’est vivre deux fois.",
      "author": "Albert Camus, extrait de \"Le mythe de Sisyphe\"",
      "sourcePage": 36
    },
    {
      "id": 1747,
      "text": "Sur les flots, sur les grands chemins, nous poursuivons le bonheur. Mais il est ici, le bonheur.",
      "author": "Horace, extrait de \"Epîtres\"",
      "sourcePage": 36
    },
    {
      "id": 1748,
      "text": "La faculté de rire aux éclats est preuve d'une âme excellente.",
      "author": "Jean Cocteau",
      "sourcePage": 36
    },
    {
      "id": 1749,
      "text": "Les choses de l’enfance ne meurent pas, elles se répètent comme les saisons.",
      "author": "Eleanor Farjeon",
      "sourcePage": 36
    },
    {
      "id": 1750,
      "text": "La victoire sur soi est la plus grande des victoires.",
      "author": "Platon",
      "sourcePage": 36
    },
    {
      "id": 1751,
      "text": "On n'est heureux que par l'amour.",
      "author": "Pierre Choderlos de Laclos, extrait de \"Les liaisons dangereuses\"",
      "sourcePage": 36
    },
    {
      "id": 1752,
      "text": "S'il a de la chance, l'écrivain peut changer le monde.",
      "author": "Arthur Miller, extrait d’une interview dans \"L’Express - 12 septembre 2002\"",
      "sourcePage": 36
    },
    {
      "id": 1753,
      "text": "C'est par le travail que l'homme se transforme.",
      "author": "Louis Aragon, extrait de \"Article dans l'Humanité\"",
      "sourcePage": 36
    },
    {
      "id": 1754,
      "text": "Se demander sérieusement tous les soirs ce que le jour nous a fait apprendre de neuf.",
      "author": "Georg Christoph Lichtenberg, extrait de \"Le miroir de l'âme\"",
      "sourcePage": 36
    },
    {
      "id": 1755,
      "text": "Le bonheur, c’est de continuer à désirer ce qu’on possède.",
      "author": "Saint Augustin",
      "sourcePage": 36
    },
    {
      "id": 1756,
      "text": "Ce qu’il faut chercher et trouver c’est la douceur sereine d’une inébranlable paix.",
      "author": "Alexandra David- Neel",
      "sourcePage": 36
    },
    {
      "id": 1757,
      "text": "L'heure de la fin des découvertes ne sonne jamais.",
      "author": "Colette",
      "sourcePage": 36
    },
    {
      "id": 1758,
      "text": "La beauté plaît aux yeux, la douceur charme l'âme.",
      "author": "Voltaire",
      "sourcePage": 36
    },
    {
      "id": 1759,
      "text": "La patience vient mieux à bout des entreprises que la force.",
      "author": "Plutarque, extrait de \"Vie des hommes illustres\"",
      "sourcePage": 36
    },
    {
      "id": 1760,
      "text": "Quand on suit une mauvaise route, plus on marche vite, plus on s'égare.",
      "author": "Denis Diderot",
      "sourcePage": 36
    },
    {
      "id": 1761,
      "text": "Peu importe le succès, il s’agit d’être grand, non de le paraître.",
      "author": "Romain Rolland",
      "sourcePage": 36
    },
    {
      "id": 1762,
      "text": "A vaincre sans péril on triomphe sans gloire.",
      "author": "Pierre Corneille, extrait de \"Le Cid\"",
      "sourcePage": 36
    },
    {
      "id": 1763,
      "text": "Nous ne vivons pas seulement à notre époque. Nous portons toute notre histoire avec nous.",
      "author": "Jostein Gaarder, extrait de \"Le monde de Sophie\"",
      "sourcePage": 36
    },
    {
      "id": 1764,
      "text": "Il n'y a qu'une façon d'apprendre, c'est par l'action.",
      "author": "Paulo Coelho, extrait de \"L'alchimiste\"",
      "sourcePage": 36
    },
    {
      "id": 1765,
      "text": "Le grand talent accepte les critiques.",
      "author": "Marin Karmitz, extrait du magazine \"Les Inrocks - 31 Juillet 2002\"",
      "sourcePage": 36
    },
    {
      "id": 1766,
      "text": "Le destin n'est pas une chaîne mais un envol.",
      "author": "Alessandro Baricco, extrait d’ \"Océan Mer\"",
      "sourcePage": 36
    },
    {
      "id": 1767,
      "text": "Sans imagination, l’amour n’a aucune chance.",
      "author": "Romain Gary",
      "sourcePage": 36
    },
    {
      "id": 1768,
      "text": "Le plus dur, c'est pas d'arriver au sommet, c'est d'y être.",
      "author": "Coluche",
      "sourcePage": 36
    },
    {
      "id": 1769,
      "text": "L'hymne de la haine ne profite pas à l'humanité.",
      "author": "Gandhi, extrait de \"Discours et écrits\"",
      "sourcePage": 36
    },
    {
      "id": 1770,
      "text": "Les histoires sont la chose la plus importante au monde. Sans les histoires, nous ne serions pas humains.",
      "author": "Philip Pullman",
      "sourcePage": 36
    },
    {
      "id": 1771,
      "text": "La plus grande difficulté n'est pas tant de prendre des décisions que de les assumer.",
      "author": "Serge Uzzan",
      "sourcePage": 36
    },
    {
      "id": 1772,
      "text": "Le chemin est long du projet à la chose.",
      "author": "Molière",
      "sourcePage": 36
    },
    {
      "id": 1773,
      "text": "Quand tout se fait petit, femmes vous restez grandes.",
      "author": "Victor Hugo, extrait de \"Châtiments\"",
      "sourcePage": 36
    },
    {
      "id": 1774,
      "text": "Une pièce sans livres, c’est comme un corps sans âme.",
      "author": "Cicéron",
      "sourcePage": 36
    },
    {
      "id": 1775,
      "text": "Tout ce qui est exquis mûrit lentement.",
      "author": "Arthur Schopenhauer, extrait des \"Aphorismes sur la sagesse dans la vie\"",
      "sourcePage": 36
    },
    {
      "id": 1776,
      "text": "La culture est ce qui fait d'une journée de travail une journée de vie.",
      "author": "Georges Duhamel",
      "sourcePage": 36
    },
    {
      "id": 1777,
      "text": "Le succès fut toujours un enfant de l'audace.",
      "author": "Prosper Crébillon, extrait de \"Catilina\"",
      "sourcePage": 36
    },
    {
      "id": 1778,
      "text": "Règle d'optique : tout semble plus grand de loin.",
      "author": "Stanislaw Jerzy Lec, extrait des \"Nouvelles pensées échevelées\"",
      "sourcePage": 36
    },
    {
      "id": 1779,
      "text": "Créer ce que jamais nous ne verrons, c’est cela la Poésie.",
      "author": "Gerardo Diego",
      "sourcePage": 36
    },
    {
      "id": 1780,
      "text": "Ce qui est facile n’a pas de saveur.",
      "author": "Nicolas Hulot, extrait de \"Etats d’âme\"",
      "sourcePage": 36
    },
    {
      "id": 1781,
      "text": "L’enfance est le sol sur lequel nous marcherons toute notre vie.",
      "author": "Lya Luft, extrait de \"Pertes et profits\"",
      "sourcePage": 36
    },
    {
      "id": 1782,
      "text": "Ne désespérez jamais. Faites infuser davantage.",
      "author": "Henri Michaux, extrait de \"Tranches de savoir\"",
      "sourcePage": 36
    },
    {
      "id": 1783,
      "text": "Curieuse langue française, et prophétique, qui fait commencer l'amour comme la guerre par une déclaration !",
      "author": "Jean Simard, extrait de l’ \"Hôtel de la reine\"",
      "sourcePage": 36
    },
    {
      "id": 1784,
      "text": "La vérité doit s'imposer sans violence.",
      "author": "Léon Tolstoï, extrait de \"Guerre et paix\"",
      "sourcePage": 37
    },
    {
      "id": 1785,
      "text": "Le bonheur est quelque chose qui se multiplie quand il se divise.",
      "author": "Paulo Coelho, extrait de \"Sur le bord de la rivière Piedra je me suis assise et j'ai pleuré\"",
      "sourcePage": 37
    },
    {
      "id": 1786,
      "text": "Plus on prête attention aux coïncidences, plus elles se produisent.",
      "author": "Vladimir Nabokov, extrait de \"L'enchanteur\"",
      "sourcePage": 37
    },
    {
      "id": 1787,
      "text": "Il faut toujours semer derrière soi un prétexte pour revenir, quand on part.",
      "author": "Alessandro Baricco, extrait d’ \"Océan Mer\"",
      "sourcePage": 37
    },
    {
      "id": 1788,
      "text": "On court après le bonheur, et l'on oublie d'être heureux.",
      "author": "François Cavanna",
      "sourcePage": 37
    },
    {
      "id": 1789,
      "text": "Il y a du plaisir à rencontrer les yeux de celui à qui l'on vient de donner.",
      "author": "Jean de La Bruyère",
      "sourcePage": 37
    },
    {
      "id": 1790,
      "text": "Ce que je cherche dans la parole, c'est la réponse de l'autre.",
      "author": "Jacques Lacan, extrait de \"Ecrits\"",
      "sourcePage": 37
    },
    {
      "id": 1791,
      "text": "Un travail réglé et des victoires après des victoires, voilà sans doute la formule du bonheur.",
      "author": "Alain, extrait des \"Propos sur le bonheur\"",
      "sourcePage": 37
    },
    {
      "id": 1792,
      "text": "Naître, c'est recevoir tout un univers en cadeau.",
      "author": "Jostein Gaarder, extrait de \"Dans un miroir, obscur\"",
      "sourcePage": 37
    },
    {
      "id": 1793,
      "text": "Rester, c’est exister : mais voyager, c’est vivre.",
      "author": "Gustave Nadaud, extrait de \"Contes, scènes et récits\"",
      "sourcePage": 37
    },
    {
      "id": 1794,
      "text": "La poésie se fait dans un lit comme l'amour. Ses draps défaits sont l'aurore des choses.",
      "author": "André Breton",
      "sourcePage": 37
    },
    {
      "id": 1795,
      "text": "Le venin et le parfum sont toujours dans de petits flacons.",
      "author": "Luis Sepulveda, extrait de \"Une sale histoire\"",
      "sourcePage": 37
    },
    {
      "id": 1796,
      "text": "On se voit d'un autre œil qu'on ne voit son prochain.",
      "author": "Jean de La Fontaine, extrait de la fable \"La besace\"",
      "sourcePage": 37
    },
    {
      "id": 1797,
      "text": "Parler juste, c'est comme chanter juste, c'est un don. Mais ça étonne moins.",
      "author": "Jean Piat, extrait de \"Les plumes de paon\"",
      "sourcePage": 37
    },
    {
      "id": 1798,
      "text": "La littérature ne bégaie pas l'existence, elle l'invente, elle l'a provoque, elle la dépasse.",
      "author": "Eric- Emmanuel Schmitt, extrait de \"Variations énigmatiques\"",
      "sourcePage": 37
    },
    {
      "id": 1799,
      "text": "Misérable est l'amour qui se laisserait mesurer.",
      "author": "William Shakespeare, extrait de \"Antoine et Cléopâtre\"",
      "sourcePage": 37
    },
    {
      "id": 1800,
      "text": "Les idées, c’est comme les gosses. Il ne suffit pas de les avoir, il faut les élever.",
      "author": "Daniel Picouly",
      "sourcePage": 37
    },
    {
      "id": 1801,
      "text": "Prenez le temps comme il vient, le vent comme il souffle, la femme comme elle est.",
      "author": "Alfred de Musset",
      "sourcePage": 37
    },
    {
      "id": 1802,
      "text": "Quand on ne pense pas à ce que l’on dit, c’est qu’on dit ce que l’on pense.",
      "author": "Jacinto Benavente",
      "sourcePage": 37
    },
    {
      "id": 1803,
      "text": "On cesse toujours d’être le numéro 1 mais on ne cesse jamais d’avoir été le premier.",
      "author": "Frédéric Dard, extrait du journal \"France-Soir - 11 Décembre 1975\"",
      "sourcePage": 37
    },
    {
      "id": 1804,
      "text": "Il vaut mieux suivre le bon chemin en boitant que le mauvais d'un pas ferme.",
      "author": "Saint Augustin",
      "sourcePage": 37
    },
    {
      "id": 1805,
      "text": "Il est plus difficile de désagréger un préjugé qu'un atome.",
      "author": "Albert Einstein",
      "sourcePage": 37
    },
    {
      "id": 1806,
      "text": "J’ai trouvé ma devise - deux verbes auxiliaires : être vaut mieux qu’avoir.",
      "author": "Marina Tsvetaeva, extrait de \"Vivre dans le feu\"",
      "sourcePage": 37
    },
    {
      "id": 1807,
      "text": "Ce n’est pas ce que l’on dit qui compte, mais ce qu’on entend.",
      "author": "Philippe Delerm",
      "sourcePage": 37
    },
    {
      "id": 1808,
      "text": "La grande ruse, c’est que les choses soient comme elles sont.",
      "author": "Friedrich Hegel",
      "sourcePage": 37
    },
    {
      "id": 1809,
      "text": "L'avenir est quelque chose qui se surmonte. On ne subit pas l'avenir, on le fait.",
      "author": "Georges Bernanos, extrait de \"La liberté pour quoi faire ?\"",
      "sourcePage": 37
    },
    {
      "id": 1810,
      "text": "L'essentiel pour le bonheur de la vie, c'est ce que l'on a en soi-même.",
      "author": "Arthur Schopenhauer, extrait des \"Aphorismes sur la sagesse dans la vie\"",
      "sourcePage": 37
    },
    {
      "id": 1811,
      "text": "Toutes les batailles de la vie nous enseignent quelque chose, même celles que nous perdons.",
      "author": "Paulo Coelho, extrait de \"La cinquième montagne\"",
      "sourcePage": 37
    },
    {
      "id": 1812,
      "text": "L’amour, c’est la plus belle invention pour tenir les gens debout.",
      "author": "Cali",
      "sourcePage": 37
    },
    {
      "id": 1813,
      "text": "Mon objectif, ce n'est pas de construire la société de demain, c'est de montrer qu'elle ne doit pas ressembler à celle d'aujourd'hui.",
      "author": "Albert Jacquard",
      "sourcePage": 37
    },
    {
      "id": 1814,
      "text": "La gloire des grands hommes est comme les ombres : elle s'allonge avec leur couchant.",
      "author": "Henry de Montherlant, extrait de \"La reine morte\"",
      "sourcePage": 37
    },
    {
      "id": 1815,
      "text": "Ce qui est terrible sur cette terre, c’est que tout le monde a ses raisons.",
      "author": "Jean Renoir, dialogue du film français \"La règle du jeu\"",
      "sourcePage": 37
    },
    {
      "id": 1816,
      "text": "Bénissons nos désirs insatisfaits, chérissons nos rêves inaccessibles : l’envie nous maintient en vie.",
      "author": "Frédéric Beigbeder, extrait de \"L’égoïste romantique\"",
      "sourcePage": 37
    },
    {
      "id": 1817,
      "text": "Il n’y a de certain que le passé, mais on ne travaille qu’avec l’avenir.",
      "author": "Auguste Detœuf",
      "sourcePage": 37
    },
    {
      "id": 1818,
      "text": "Pour qu’une chose soit intéressante, il suffit de la regarder longtemps.",
      "author": "Gustave Flaubert",
      "sourcePage": 37
    },
    {
      "id": 1819,
      "text": "Si l’on passait l’année entière en vacances ; s’amuser serait aussi épuisant que travailler.",
      "author": "William Shakespeare, extrait de \"Henry IV\"",
      "sourcePage": 37
    },
    {
      "id": 1820,
      "text": "Chaque homme doit inventer son chemin.",
      "author": "Jean-Paul Sartre, extrait de \"Les mouches\"",
      "sourcePage": 37
    },
    {
      "id": 1821,
      "text": "Une des grandes règles de l’art : ne pas s’attarder !",
      "author": "André Gide, extrait de \"Le journal\"",
      "sourcePage": 37
    },
    {
      "id": 1822,
      "text": "La richesse est pareille à l'eau de mer : plus on en boit, plus on a soif.",
      "author": "Arthur Schopenhauer",
      "sourcePage": 37
    },
    {
      "id": 1823,
      "text": "L’amour est un art, une acrobatie, c’est parfois de l’héroïsme.",
      "author": "Lya Luft, extrait de \"Pertes et profits\"",
      "sourcePage": 38
    },
    {
      "id": 1824,
      "text": "Plus on va dans l'infime, plus on a de chances de trouver l'universel.",
      "author": "Philippe Delerm, extrait d'une interview sur \"Evene.fr - Mars 2005\"",
      "sourcePage": 38
    },
    {
      "id": 1825,
      "text": "L’honnêteté intellectuelle, voilà la qualité dont doit s’enorgueillir un travailleur de l’esprit.",
      "author": "Gary Victor, extrait de \"Je sais quand Dieu vient se promener dans mon jardin\"",
      "sourcePage": 38
    },
    {
      "id": 1826,
      "text": "Les seuls amis dignes d’intérêt sont ceux que l’on peut appeler à quatre heures du matin.",
      "author": "Marlène Dietrich",
      "sourcePage": 38
    },
    {
      "id": 1827,
      "text": "Le chemin le plus court d'un point à un autre c'est de ne pas y aller.",
      "author": "Philippe Geluck, extrait de \"L'excellent du chat\"",
      "sourcePage": 38
    },
    {
      "id": 1828,
      "text": "Inventer, c’est penser à côté.",
      "author": "Albert Einstein",
      "sourcePage": 38
    },
    {
      "id": 1829,
      "text": "Dans la plupart des pays, les citoyens possèdent la liberté de parole. Mais dans une démocratie, ils possèdent encore la liberté après avoir parlé.",
      "author": "André Guillois, extrait de \"Liberté, égalité, hilarité\"",
      "sourcePage": 38
    },
    {
      "id": 1830,
      "text": "Il y a de l'espoir pour tout le monde, c'est ce qui fait tourner l'univers.",
      "author": "Paul Auster, extrait de \"Moon Palace\"",
      "sourcePage": 38
    },
    {
      "id": 1831,
      "text": "Effacer le temps et surfer sur le présent.",
      "author": "Charlélie Couture",
      "sourcePage": 38
    },
    {
      "id": 1832,
      "text": "L'amour est la seule chose que le partage grandit.",
      "author": "Massa Makan Diabaté, extrait d’ \"A la mémoire de David Diop\"",
      "sourcePage": 38
    },
    {
      "id": 1833,
      "text": "Croire au soleil quand tombe l'eau.",
      "author": "Louis Aragon, extrait de \"Le fou d’Elsa\"",
      "sourcePage": 38
    },
    {
      "id": 1834,
      "text": "Le monde dans lequel chacun vit dépend de la façon de le concevoir.",
      "author": "Arthur Schopenhauer, extrait des \"Aphorismes sur la sagesse dans la vie\"",
      "sourcePage": 38
    },
    {
      "id": 1835,
      "text": "L’amour, comme un disque du destin qui n’en finit pas de passer...",
      "author": "Ludmila Oulitskaïa, extrait de \"Sincèrement vôtre, Chourik\"",
      "sourcePage": 38
    },
    {
      "id": 1836,
      "text": "Pour être subversif, il faut être subjectif.",
      "author": "Frédéric Beigbeder, extrait de \"L’égoïste romantique\"",
      "sourcePage": 38
    },
    {
      "id": 1837,
      "text": "Les vers de terre s'enfoncent dans le sol pour ne pas tomber amoureux des étoiles.",
      "author": "Yvan Audouard",
      "sourcePage": 38
    },
    {
      "id": 1838,
      "text": "Le cinéma, c'est un stylo, du papier et des heures à observer le monde et les gens.",
      "author": "Jacques Tati",
      "sourcePage": 38
    },
    {
      "id": 1839,
      "text": "A l'envers des nuages, il y a toujours un ciel.",
      "author": "Mûhammad Al-Faytûry, extrait de \"Norin et Tarabay\"",
      "sourcePage": 38
    },
    {
      "id": 1840,
      "text": "Le point de vue le plus simple est toujours le meilleur.",
      "author": "Charlie Chaplin, extrait de \"Ma vie\"",
      "sourcePage": 38
    },
    {
      "id": 1841,
      "text": "La vie a plus d'imagination que n'en portent nos rêves.",
      "author": "Ridley Scott, dialogue du film franco- britannique \"1492, Christophe Colomb\"",
      "sourcePage": 38
    },
    {
      "id": 1842,
      "text": "Il vaut mieux faire des conneries que s'économiser.",
      "author": "Gérard Depardieu, extrait d'une interview dans \"L’Humanité - 21 août 1999\"",
      "sourcePage": 38
    },
    {
      "id": 1843,
      "text": "La notoriété c’est lorsqu’on remarque votre présence, la célébrité c’est lorsqu’on note votre absence.",
      "author": "Georges Wolinski",
      "sourcePage": 38
    },
    {
      "id": 1844,
      "text": "La liberté n’est pas l’absence d’engagement, mais la capacité de choisir.",
      "author": "Paulo Coelho, extrait de \"Le Zahir\"",
      "sourcePage": 38
    },
    {
      "id": 1845,
      "text": "La pensée a des ailes. Nul ne peut arrêter son envol.",
      "author": "Youssef Chahine, dialogue du film \"Le destin\"",
      "sourcePage": 38
    },
    {
      "id": 1846,
      "text": "Les plats se lisent et les livrent se mangent.",
      "author": "Marcel Proust",
      "sourcePage": 38
    },
    {
      "id": 1847,
      "text": "Aucune femme n'est pareille. Chacune a quelque chose d'unique et d'irremplaçable.",
      "author": "François Truffaut, dialogue du film \"L'homme qui aimait les femmes\"",
      "sourcePage": 38
    },
    {
      "id": 1848,
      "text": "Ce que l'on fait dans sa vie résonne dans l'éternité.",
      "author": "Ridley Scott, dialogue du film américain \"Gladiator\"",
      "sourcePage": 38
    },
    {
      "id": 1849,
      "text": "C’est l'angoisse du temps qui passe nous fait tant parler du temps qu'il fait.",
      "author": "Jean-Pierre Jeunet, dialogue du film \"Le fabuleux destin d’Amélie Poulain\"",
      "sourcePage": 38
    },
    {
      "id": 1850,
      "text": "La jeunesse, comme la verdure, pare la terre ; mais l'éducation la couvre de moissons.",
      "author": "Rivarol, extrait du discours \"De l'homme intellectuel et moral\"",
      "sourcePage": 38
    },
    {
      "id": 1851,
      "text": "Vous pouvez tout faire, penser ou croire, posséder toute la science du monde, si vous n'aimez pas, vous n'êtes rien.",
      "author": "Marcelle Sauvageot, extrait de \"Laissez-moi\"",
      "sourcePage": 38
    },
    {
      "id": 1852,
      "text": "Si la matière grise était plus rose, le monde aurait moins les idées noires.",
      "author": "Pierre Dac",
      "sourcePage": 38
    },
    {
      "id": 1853,
      "text": "La poésie est un engagement à aller vers l’autre.",
      "author": "Jean-Pierre Siméon, extrait d'une interview sur \"Evene - Mars 2005\"",
      "sourcePage": 38
    },
    {
      "id": 1854,
      "text": "Il y a beaucoup de gens dont la facilité de parler ne vient que de l'impuissance de se taire.",
      "author": "Cyrano de Bergerac",
      "sourcePage": 38
    },
    {
      "id": 1855,
      "text": "Le plus difficile n’est pas de faire son devoir, c’est de savoir où il se place.",
      "author": "Jean de La Varende, extrait de \"Cœur pensif\"",
      "sourcePage": 38
    },
    {
      "id": 1856,
      "text": "Ecrire c'est traverser une saison qui n'est sur aucun calendrier.",
      "author": "Françoise Lefèvre, extrait de \"Souliers d'automne\"",
      "sourcePage": 38
    },
    {
      "id": 1857,
      "text": "J’aime ce qui me nourrit : le boire, le manger, les livres.",
      "author": "Etienne de La Boétie",
      "sourcePage": 38
    },
    {
      "id": 1858,
      "text": "Il est bien malaisé de régler ses désirs.",
      "author": "Jean de La Fontaine, extrait de \"Elégie\"",
      "sourcePage": 38
    },
    {
      "id": 1859,
      "text": "On ne sait jamais pourquoi on tombe amoureux de quelqu'un : c'est même à cela qu'on reconnaît qu'on aime.",
      "author": "Francis de Croisset",
      "sourcePage": 39
    },
    {
      "id": 1860,
      "text": "Le luxe n'est pas un plaisir, mais le plaisir est un luxe.",
      "author": "Francis Picabia, extrait de la revue \"Le Pilhaou Thibaou - Juillet 1921\"",
      "sourcePage": 39
    },
    {
      "id": 1861,
      "text": "Ce qu'un homme pense de lui-même, voilà ce qui règle ou plutôt indique son destin.",
      "author": "Henry David Thoreau : \"Walden\"",
      "sourcePage": 39
    },
    {
      "id": 1862,
      "text": "Votre véritable ami est celui qui ne vous passe rien et qui vous pardonne tout.",
      "author": "Diane de Beausacq",
      "sourcePage": 39
    },
    {
      "id": 1863,
      "text": "Pour juger le monde, il faut le voir de loin et l'avoir beaucoup vu de près.",
      "author": "La Rochefoucauld",
      "sourcePage": 39
    },
    {
      "id": 1864,
      "text": "La seule vraie tristesse est dans l’absence de désir.",
      "author": "Charles-Ferdinand Ramuz : \"Journal\"",
      "sourcePage": 39
    },
    {
      "id": 1865,
      "text": "Rien ne résume un homme, pas même ses idées.",
      "author": "Mourad Bourboune : \"Le mont des genêts\"",
      "sourcePage": 39
    },
    {
      "id": 1866,
      "text": "Les maux sont moins néfastes au bonheur que l'ennui.",
      "author": "Giacomo Leopardi : \"Zibaldone\"",
      "sourcePage": 39
    },
    {
      "id": 1867,
      "text": "L’histoire ne fait rien, c’est l’homme, réel et vivant, qui fait tout.",
      "author": "Karl Marx",
      "sourcePage": 39
    },
    {
      "id": 1868,
      "text": "Nous croyons conduire le destin, mais c’est toujours lui qui nous mène.",
      "author": "Denis Diderot : \"Jacques le fataliste et son maître\"",
      "sourcePage": 39
    },
    {
      "id": 1869,
      "text": "Il y a dans la jalousie plus d’amour-propre que d’amour.",
      "author": "La Rochefoucauld",
      "sourcePage": 39
    },
    {
      "id": 1870,
      "text": "J’ai toujours préféré la folie des passions à la sagesse de l’indifférence.",
      "author": "Anatole France : \"Le crime de Sylvestre Bonnard\"",
      "sourcePage": 39
    },
    {
      "id": 1871,
      "text": "L'enfance est ce que nous passons notre existence à essayer de retrouver.",
      "author": "Forest Whitaker, dialogue du film américain \"Ainsi va la vie\"",
      "sourcePage": 39
    },
    {
      "id": 1872,
      "text": "Combien de luttes a dû mener l’Humanité pour rendre l’homme plus humain ?",
      "author": "Marek Halter",
      "sourcePage": 39
    },
    {
      "id": 1873,
      "text": "Savoir pour prévoir, afin de pouvoir.",
      "author": "Auguste Comte",
      "sourcePage": 39
    },
    {
      "id": 1874,
      "text": "Les femmes ne sont jamais plus fortes que lorsqu'elles s'arment de leur faiblesse.",
      "author": "Marie du Deffand : \"Correspondance\"",
      "sourcePage": 39
    },
    {
      "id": 1875,
      "text": "On n'est pas un homme quand on n'aime que soi.",
      "author": "Fénelon",
      "sourcePage": 39
    },
    {
      "id": 1876,
      "text": "Le cœur d’un père s’agrandit avec chaque enfant.",
      "author": "Jean Basile Bezroudnoff : \"La jument des Mongols\"",
      "sourcePage": 39
    },
    {
      "id": 1877,
      "text": "L’idée que la vie est un bien et que nous méritons la liberté et le bonheur se transmet en y croyant.",
      "author": "Lya Luft : \"Pertes et profits\"",
      "sourcePage": 39
    },
    {
      "id": 1878,
      "text": "Pour bien aimer un pays il faut le manger, le boire et l’entendre chanter.",
      "author": "Michel Déon",
      "sourcePage": 39
    },
    {
      "id": 1879,
      "text": "L'instruction est le seul moyen de libération.",
      "author": "Ngugi : \"Enfant, ne pleure pas\"",
      "sourcePage": 39
    },
    {
      "id": 1880,
      "text": "La jeunesse a cela de beau qu’elle peut admirer sans comprendre.",
      "author": "Anatole France : \"La vie littéraire\"",
      "sourcePage": 39
    },
    {
      "id": 1881,
      "text": "Quand on est aimé, on ne doute de rien. Quand on aime, on doute de tout.",
      "author": "Colette",
      "sourcePage": 39
    },
    {
      "id": 1882,
      "text": "Tirons notre courage de notre désespoir même.",
      "author": "Sénèque : \"Questions naturelles\"",
      "sourcePage": 39
    },
    {
      "id": 1883,
      "text": "C'est le propre de l'homme de se tromper ; seul l'insensé persiste dans son erreur.",
      "author": "Cicéron",
      "sourcePage": 39
    },
    {
      "id": 1884,
      "text": "Le seul temps vraiment perdu est celui qu’on passe à regretter les occasions manquées.",
      "author": "Grégoire Lacroix : \"Les euphorismes de Grégoire - 2\"",
      "sourcePage": 39
    },
    {
      "id": 1885,
      "text": "Ce n’est pas seulement l’endroit où l’on va qui donne un sens à la vie, mais aussi la façon dont on s’y rend.",
      "author": "Marc Levy, extrait de \"Vous revoir\"",
      "sourcePage": 39
    },
    {
      "id": 1886,
      "text": "Une chambre d’enfant à ranger, c’est une vie à construire.",
      "author": "Daniel Pennac : \"Messieurs les enfants\"",
      "sourcePage": 39
    },
    {
      "id": 1887,
      "text": "Il ne faut pas avoir peur du bonheur. C'est seulement un bon moment à passer.",
      "author": "Romain Gary",
      "sourcePage": 39
    },
    {
      "id": 1888,
      "text": "La liberté consiste moins à faire sa volonté qu'à ne pas être soumis à celle d'autrui.",
      "author": "Jean-Jacques Rousseau : \"Discours sur l'inégalité\"",
      "sourcePage": 39
    },
    {
      "id": 1889,
      "text": "C'est plein de disputes, un bonheur.",
      "author": "Jean Anouilh : \"Antigone\"",
      "sourcePage": 39
    },
    {
      "id": 1890,
      "text": "Ce qu’on ne peut pas dire, il ne faut surtout pas le taire, mais l’écrire.",
      "author": "Jacques Derrida",
      "sourcePage": 39
    },
    {
      "id": 1891,
      "text": "La tolérance est un exercice et une conquête sur soi.",
      "author": "Albert Memmi : \"Exercice du bonheur\"",
      "sourcePage": 39
    },
    {
      "id": 1892,
      "text": "Seuls les yeux ne vieillissent jamais : l'âge passe et ne touche pas le regard.",
      "author": "Tahar Ben Jelloun : \"L'auberge des pauvres\"",
      "sourcePage": 39
    },
    {
      "id": 1893,
      "text": "Le bonheur est un rêve d'enfant réalisé dans l'âge adulte.",
      "author": "Sigmund Freud",
      "sourcePage": 39
    },
    {
      "id": 1894,
      "text": "On n'est jamais abouti. Il y aura toujours quelque chose à faire, une autre couleur à visiter.",
      "author": "Jean Reno, extrait du magazine \"Ciné Live - Novembre 2001\"",
      "sourcePage": 39
    },
    {
      "id": 1895,
      "text": "Pour bien s'entendre, il faut avoir les mêmes défauts et des qualités différentes.",
      "author": "Massa Makan Diabaté : \"Le coiffeur de Kouta\"",
      "sourcePage": 39
    },
    {
      "id": 1896,
      "text": "Ce qu'on n'a jamais mis en question n'a point été prouvé.",
      "author": "Denis Diderot, extrait des \"Pensées philosophiques\"",
      "sourcePage": 39
    },
    {
      "id": 1897,
      "text": "Même pour le simple envol d'un papillon tout le ciel est nécessaire.",
      "author": "Paul Claudel",
      "sourcePage": 39
    },
    {
      "id": 1898,
      "text": "Le but de la société humaine doit être le progrès des hommes, non celui des choses.",
      "author": "Léonard Sismonde de Sismondi",
      "sourcePage": 39
    },
    {
      "id": 1899,
      "text": "L’homme n’invente l’éternité de son existence que dans les sentiments qu’il partage.",
      "author": "Marc Levy, extrait de \"Vous revoir\"",
      "sourcePage": 39
    },
    {
      "id": 1900,
      "text": "Un baiser légal ne vaut jamais un baiser volé.",
      "author": "Guy de Maupassant : \"Confession d’une femme\"",
      "sourcePage": 39
    },
    {
      "id": 1901,
      "text": "La vie offre toujours deux pentes. On grimpe ou on se laisse glisser.",
      "author": "Pierre Hebey : \"Deux amis de toujours\"",
      "sourcePage": 40
    },
    {
      "id": 1902,
      "text": "Un homme n'est vieux que quand les regrets ont pris chez lui la place des rêves.",
      "author": "John Barrymore",
      "sourcePage": 40
    },
    {
      "id": 1903,
      "text": "Ayant médité la douceur et la compassion, j'ai oublié la différence entre moi et les autres.",
      "author": "Milarepa",
      "sourcePage": 40
    },
    {
      "id": 1904,
      "text": "C'est le devoir qui crée le droit et non le droit qui crée le devoir.",
      "author": "François René de Chateaubriand, extrait d’un \"Discours à la Chambre des Pairs\"",
      "sourcePage": 40
    },
    {
      "id": 1905,
      "text": "Le passé et le présent sont nos moyens ; le seul avenir est notre fin.",
      "author": "Blaise Pascal, extrait des \"Pensées sur la religion\"",
      "sourcePage": 40
    },
    {
      "id": 1906,
      "text": "C'est la confrontation avec les autres qui vous permet de dévoiler toutes vos facettes.",
      "author": "Björk",
      "sourcePage": 40
    },
    {
      "id": 1907,
      "text": "Malgré sa fragilité, la liane résiste au poids de la calebasse.",
      "author": "Proverbe indien",
      "sourcePage": 40
    },
    {
      "id": 1908,
      "text": "Un sourire coûte moins cher que l'électricité, mais donne autant de lumière.",
      "author": "Abbé Pierre",
      "sourcePage": 40
    },
    {
      "id": 1909,
      "text": "La vertu est le triomphe de la générosité sur l'intérêt.",
      "author": "Duc de Lévis : \"Maximes, préceptes et réflexions\"",
      "sourcePage": 40
    },
    {
      "id": 1910,
      "text": "Nous passons chaque jour et chaque nuit à nous perdre et toute notre vie à nous chercher.",
      "author": "Hafid Aggoune : \"Quelle nuit sommes-nous ?\"",
      "sourcePage": 40
    },
    {
      "id": 1911,
      "text": "Il faut savoir joindre l’agréable à l’agréable et se contenter de beaucoup.",
      "author": "Jean-Claude Carrière : \"Détails de ce monde\"",
      "sourcePage": 40
    },
    {
      "id": 1912,
      "text": "Ce n'est pas dans ses effets qu'on attaque un mal, c'est dans sa cause.",
      "author": "François Guizot",
      "sourcePage": 40
    },
    {
      "id": 1913,
      "text": "On finit toujours par mépriser ceux qui sont trop facilement de notre avis.",
      "author": "Jules Renard, extrait de son \"Journal\"",
      "sourcePage": 40
    },
    {
      "id": 1914,
      "text": "Il faut toujours se réserver le droit de rire le lendemain de ses idées de la veille.",
      "author": "Napoléon Bonaparte",
      "sourcePage": 40
    },
    {
      "id": 1915,
      "text": "Il n’y a que deux conduites avec la vie : ou on la rêve ou on l’accomplit.",
      "author": "René Char",
      "sourcePage": 40
    },
    {
      "id": 1916,
      "text": "Tous les moyens sont bons quand ils sont efficaces.",
      "author": "Jean-Paul Sartre : \"Les mains sales\"",
      "sourcePage": 40
    },
    {
      "id": 1917,
      "text": "Les chemins qui vont droit devant s'escaladent.",
      "author": "Gilles Vigneault : \"La petite heure\"",
      "sourcePage": 40
    },
    {
      "id": 1918,
      "text": "La vie s’arrête lorsque la peur de l’inconnu est plus forte que l’élan.",
      "author": "Hafid Aggoune : \"Quelle nuit sommes-nous ?\"",
      "sourcePage": 40
    },
    {
      "id": 1919,
      "text": "Rien n'est jamais perdu tant qu'il reste quelque chose à trouver.",
      "author": "Pierre Dac",
      "sourcePage": 40
    },
    {
      "id": 1920,
      "text": "Il n’y a point de génie sans un grain de folie.",
      "author": "Aristote : \"Poétique\"",
      "sourcePage": 40
    },
    {
      "id": 1921,
      "text": "Si vous fermez la porte à toutes les erreurs, la vérité restera dehors.",
      "author": "Rabindranàth Tagore",
      "sourcePage": 40
    },
    {
      "id": 1922,
      "text": "C'est cela l'amour, tout donner, tout sacrifier sans espoir de retour.",
      "author": "Albert Camus : \"Les justes\"",
      "sourcePage": 40
    },
    {
      "id": 1923,
      "text": "Ce qui m'intéresse, ce n'est pas le bonheur de tous les hommes, c'est celui de chacun.",
      "author": "Boris Vian : \"L'écume des jours\"",
      "sourcePage": 40
    },
    {
      "id": 1924,
      "text": "Ce que la voix peut cacher, le regard le livre.",
      "author": "Georges Bernanos : \"Dialogues des Carmélites\"",
      "sourcePage": 40
    },
    {
      "id": 1925,
      "text": "On devient son pire ennemi en essayant de donner du sens à ce qui n'en a pas.",
      "author": "Hubert Selby Junior",
      "sourcePage": 40
    },
    {
      "id": 1926,
      "text": "Il est dans la nature humaine de penser sagement et d'agir d'une façon absurde.",
      "author": "Anatole France",
      "sourcePage": 40
    },
    {
      "id": 1927,
      "text": "Il n'y a que deux sortes de gens attrayants ; ceux qui savent absolument tout et ceux qui ne savent absolument rien.",
      "author": "Oscar Wilde",
      "sourcePage": 40
    },
    {
      "id": 1928,
      "text": "La plume est l’interprète de l’âme : ce que l’une pense, l’autre l’exprime.",
      "author": "Miguel de Cervantès : \"Don Quichotte\"",
      "sourcePage": 40
    },
    {
      "id": 1929,
      "text": "L'important n'est pas de convaincre, mais de donner à réfléchir.",
      "author": "Bernard Werber : \"Le père de nos pères\"",
      "sourcePage": 40
    },
    {
      "id": 1930,
      "text": "Le monde déteste le changement, c’est pourtant la seule chose qui lui a permis de progresser.",
      "author": "Charles F. Kettering",
      "sourcePage": 40
    },
    {
      "id": 1931,
      "text": "Un livre a toujours deux auteurs : celui qui l’écrit et celui qui le lit.",
      "author": "Jacques Salomé : \"Si je m’écoutais, je m’entendrais\"",
      "sourcePage": 40
    },
    {
      "id": 1932,
      "text": "Un rêve est la moitié d'une réalité.",
      "author": "Joseph Joubert, extrait des \"Pensées\"",
      "sourcePage": 40
    },
    {
      "id": 1933,
      "text": "Il n’y a pas de hasard... il n’y a que des rendez-vous qu’on ne sait pas lire.",
      "author": "Jérôme Touzalin : \"Le Pommier\"",
      "sourcePage": 40
    },
    {
      "id": 1934,
      "text": "Le sort fait les parents, le choix fait les amis.",
      "author": "Jacques Delille : \"Malheur et pitié\"",
      "sourcePage": 40
    },
    {
      "id": 1935,
      "text": "La force sans l’intelligence s’effondre sous sa propre masse.",
      "author": "Horace : \"Odes\"",
      "sourcePage": 40
    },
    {
      "id": 1936,
      "text": "Il est bon de lire entre les lignes, cela fatigue moins les yeux.",
      "author": "Sacha Guitry",
      "sourcePage": 40
    },
    {
      "id": 1937,
      "text": "Les femmes des uns font le bonheur des autres.",
      "author": "Gustave Flaubert",
      "sourcePage": 40
    },
    {
      "id": 1938,
      "text": "Les livres que le monde appelle immoraux sont ceux qui lui montrent sa propre ignominie.",
      "author": "Oscar Wilde : \"Le portrait de Dorian Gray\"",
      "sourcePage": 40
    },
    {
      "id": 1939,
      "text": "Crois en toi, mais ne doute pas toujours des autres.",
      "author": "Joachim Maria Machado de Assis",
      "sourcePage": 40
    },
    {
      "id": 1940,
      "text": "Celui qui se perd dans sa passion a moins perdu que celui qui perd sa passion.",
      "author": "Alexandre Jardin : \"Le roman des Jardin\"",
      "sourcePage": 40
    },
    {
      "id": 1941,
      "text": "Que sait du désert celui qui ne regarde qu'un grain de sable ?",
      "author": "Erik Orsenna : \"Madame Bâ\"",
      "sourcePage": 40
    },
    {
      "id": 1942,
      "text": "Un livre, c'est un détonateur qui sert à faire réagir les gens.",
      "author": "Amélie Nothomb : \"Les combustibles\"",
      "sourcePage": 40
    },
    {
      "id": 1943,
      "text": "Un cœur qui bat c’est une âme qui respire.",
      "author": "Laurent Sagalovitsch : \"Loin de quoi\"",
      "sourcePage": 41
    },
    {
      "id": 1944,
      "text": "Les maîtres d'école sont des jardiniers en intelligences humaines.",
      "author": "Victor Hugo, extrait des \"Faits et croyances\"",
      "sourcePage": 41
    },
    {
      "id": 1945,
      "text": "J’aime penser que la lune est là même si je ne la regarde pas.",
      "author": "Albert Einstein",
      "sourcePage": 41
    },
    {
      "id": 1946,
      "text": "Eternité est l’anagramme d’étreinte.",
      "author": "Henry de Montherlant : \"Les jeunes filles\"",
      "sourcePage": 41
    },
    {
      "id": 1947,
      "text": "Il faut affronter la réalité avec une pointe d’humour ; autrement, on passe à côté.",
      "author": "Lawrence Durrell",
      "sourcePage": 41
    },
    {
      "id": 1948,
      "text": "Le premier ennemi à combattre est à l’intérieur de soi. Souvent, c’est le seul.",
      "author": "Christine Orban : \"Deux fois par semaine\"",
      "sourcePage": 41
    },
    {
      "id": 1949,
      "text": "Un problème prévu est un problème en moins.",
      "author": "Maurice Dantec : \"La sirène rouge\"",
      "sourcePage": 41
    },
    {
      "id": 1950,
      "text": "Seule l’obscurité a le pouvoir d’ouvrir au monde le cœur d’un homme.",
      "author": "Paul Auster : \"La chambre dérobée\"",
      "sourcePage": 41
    },
    {
      "id": 1951,
      "text": "Il n'y a pas de réussite facile ni d'échecs définitifs.",
      "author": "Marcel Proust",
      "sourcePage": 41
    },
    {
      "id": 1952,
      "text": "L'écriture a ceci de mystérieux qu'elle parle.",
      "author": "Paul Claudel : \"Connaissance de l'Est\"",
      "sourcePage": 41
    },
    {
      "id": 1953,
      "text": "Y penser sans cesse ne labourera pas le champ.",
      "author": "Proverbe irlandais",
      "sourcePage": 41
    },
    {
      "id": 1954,
      "text": "Les biens superflus rendent la vie superflue.",
      "author": "Pier Paolo Pasolini, cité dans le livre de Davide Toffolo \"Pasolini, une rencontre\"",
      "sourcePage": 41
    },
    {
      "id": 1955,
      "text": "Il faut du courage pour avoir du talent.",
      "author": "Georg Brandes : \"H. C. Andersen, auteur de contes\"",
      "sourcePage": 41
    },
    {
      "id": 1956,
      "text": "Il ne faut pas avoir peur des vagues qui agitent votre âme. C'est ça, la vie.",
      "author": "Hwang Sok-Yong : \"Le vieux jardin\"",
      "sourcePage": 41
    },
    {
      "id": 1957,
      "text": "On ne va jamais si loin que lorsque l'on ne sait pas où l'on va.",
      "author": "Rivarol",
      "sourcePage": 41
    },
    {
      "id": 1958,
      "text": "Le destin est ce qui nous arrive au moment où on ne s'y attend pas.",
      "author": "Tahar Ben Jelloun, extrait d’ \"Eloge de l'amitié\"",
      "sourcePage": 41
    },
    {
      "id": 1959,
      "text": "Certains livres se lisent à la cuisine, d’autres au salon. Un vrai bon livre se lit n’importe où.",
      "author": "Thomas Chandler Haliburton : \"Les bons mots de Sam Slick\"",
      "sourcePage": 41
    },
    {
      "id": 1960,
      "text": "Il ne s'agit pas de beaucoup lire, mais de bien lire.",
      "author": "Aristippe",
      "sourcePage": 41
    },
    {
      "id": 1961,
      "text": "L'erreur agite ; la vérité repose.",
      "author": "Joseph Joubert, extrait des \"Pensées\"",
      "sourcePage": 41
    },
    {
      "id": 1962,
      "text": "S'irriter d'un reproche, c'est reconnaître qu'on l'a mérité.",
      "author": "Tacite : \"Annales\"",
      "sourcePage": 41
    },
    {
      "id": 1963,
      "text": "Nous créons notre propre réalité par la manière dont nous choisissons de percevoir le monde extérieur.",
      "author": "Elliot Perlman : \"Ambiguïtés\"",
      "sourcePage": 41
    },
    {
      "id": 1964,
      "text": "La peur bloque la compréhension intelligente de la vie.",
      "author": "Jiddu Krishnamurti : \"La connaissance de soi\"",
      "sourcePage": 41
    },
    {
      "id": 1965,
      "text": "Ne jugez pas le grain de poivre d'après sa petite taille, goûtez-le et vous sentirez comme il pique.",
      "author": "Proverbe arabe",
      "sourcePage": 41
    },
    {
      "id": 1966,
      "text": "Le courage est la première des qualités humaines car elle garantit toutes les autres.",
      "author": "Aristote",
      "sourcePage": 41
    },
    {
      "id": 1967,
      "text": "Rien ne s’est fait de grand qui ne soit une espérance exagérée.",
      "author": "Jules Verne",
      "sourcePage": 41
    },
    {
      "id": 1968,
      "text": "Un rêve sans étoiles est un rêve oublié.",
      "author": "Paul Eluard",
      "sourcePage": 41
    },
    {
      "id": 1969,
      "text": "Chaque homme est une histoire qui n'est identique à aucune autre.",
      "author": "Alexis Carrel : \"L'homme, cet inconnu\"",
      "sourcePage": 41
    },
    {
      "id": 1970,
      "text": "Une rose d'automne est plus qu'une autre exquise.",
      "author": "Agrippa d'Aubigné",
      "sourcePage": 41
    },
    {
      "id": 1971,
      "text": "Une armée de fourmis peut triompher d’un serpent venimeux.",
      "author": "Proverbe chinois",
      "sourcePage": 41
    },
    {
      "id": 1972,
      "text": "A l’échelle d’une carte, le monde est un jeu d’enfant.",
      "author": "Laurent Graff : \"Voyage, voyages\"",
      "sourcePage": 41
    },
    {
      "id": 1973,
      "text": "L’ignorant affirme, le savant doute, le sage réfléchit.",
      "author": "Aristote",
      "sourcePage": 41
    },
    {
      "id": 1974,
      "text": "C'est l'incertitude qui nous charme. Tout devient merveilleux dans la brume.",
      "author": "Oscar Wilde : \"Le portrait de Dorian Gray\"",
      "sourcePage": 41
    },
    {
      "id": 1975,
      "text": "Bien des hommes pourraient voir, s'ils enlevaient leurs lunettes.",
      "author": "Friedrich Hebbel, extrait des \"Aphorismes et réflexions\"",
      "sourcePage": 41
    },
    {
      "id": 1976,
      "text": "Le seul conseiller qui plaise, c'est le temps.",
      "author": "Francis Bacon",
      "sourcePage": 41
    },
    {
      "id": 1977,
      "text": "L'univers nous appartient dans la proportion où nous lui appartenons.",
      "author": "Jean Giono : \"Le poids du ciel\"",
      "sourcePage": 41
    },
    {
      "id": 1978,
      "text": "Le poète épouse la nature, et la nature lui offre ses fruits, qu’il met en mots.",
      "author": "Marie Darrieussecq : \"Le pays\"",
      "sourcePage": 41
    },
    {
      "id": 1979,
      "text": "Entendre une phrase qui tombe juste, c'est voir son âme dans un miroir.",
      "author": "Christine Orban : \"Deux fois par semaine\"",
      "sourcePage": 41
    },
    {
      "id": 1980,
      "text": "De bons amis, de bons livres et la conscience somnolente, voilà le secret du bonheur.",
      "author": "Mark Twain",
      "sourcePage": 41
    },
    {
      "id": 1981,
      "text": "Porter des lunettes ne veut pas dire savoir lire.",
      "author": "Proverbe guadeloupéen",
      "sourcePage": 41
    },
    {
      "id": 1982,
      "text": "A vaincre sans péril, on évite des ennuis !",
      "author": "René Goscinny, extrait de la bande dessinée \"Astérix chez les Bretons\"",
      "sourcePage": 41
    },
    {
      "id": 1983,
      "text": "On n'échappe pas au ridicule par une affectation de gravité.",
      "author": "Georges Bernanos : \"Les grands cimetières sous la lune\"",
      "sourcePage": 41
    },
    {
      "id": 1984,
      "text": "Celui qui dit qu’il est arrivé, c’est qu’il n’est pas allé bien loin.",
      "author": "Jean Carmet",
      "sourcePage": 41
    },
    {
      "id": 1985,
      "text": "La vérité est une ligne tracée entre les erreurs.",
      "author": "Franz Anton Mesmer",
      "sourcePage": 41
    },
    {
      "id": 1986,
      "text": "Il est souvent nécessaire d'entreprendre pour espérer et de persévérer pour réussir.",
      "author": "Gilbert Cesbron",
      "sourcePage": 42
    },
    {
      "id": 1987,
      "text": "Si vous voulez que la vie vous sourie, apportez-lui d'abord votre bonne humeur.",
      "author": "Baruch Spinoza",
      "sourcePage": 42
    },
    {
      "id": 1988,
      "text": "La gloire suit ordinairement ceux qui la fuient.",
      "author": "Charles Rollin",
      "sourcePage": 42
    },
    {
      "id": 1989,
      "text": "La gourmandise commence quand on n’a plus faim.",
      "author": "Alphonse Daudet, extrait des \"Lettres de mon moulin\"",
      "sourcePage": 42
    },
    {
      "id": 1990,
      "text": "Qui n’est jamais tombé n’a pas une juste idée de l’effort à faire pour se tenir debout.",
      "author": "Multatuli : \"Idées\"",
      "sourcePage": 42
    },
    {
      "id": 1991,
      "text": "Il ne sert de rien à l’homme de gagner la Lune s’il vient à perdre la Terre.",
      "author": "François Mauriac : \"Bloc- notes\"",
      "sourcePage": 42
    },
    {
      "id": 1992,
      "text": "On ne peut répondre de son courage quand on n’a jamais été dans le péril.",
      "author": "La Rochefoucauld : \"Maximes\"",
      "sourcePage": 42
    },
    {
      "id": 1993,
      "text": "La puissance ne consiste pas à frapper fort ou souvent, mais à frapper juste.",
      "author": "Honoré de Balzac : \"Physiologie du mariage\"",
      "sourcePage": 42
    },
    {
      "id": 1994,
      "text": "Il faut de l’esprit pour bien parler, de l’intelligence suffit pour bien écouter.",
      "author": "André Gide : \"Journal\"",
      "sourcePage": 42
    },
    {
      "id": 1995,
      "text": "Changer d’air, c’est salutaire !",
      "author": "Jean-Pierre Jeunet, dialogue du film \"Le fabuleux destin d’Amélie Poulain\"",
      "sourcePage": 42
    },
    {
      "id": 1996,
      "text": "C’est la nuit qu’il est beau de croire à la lumière.",
      "author": "Edmond Rostand : \"Chantecler\"",
      "sourcePage": 42
    },
    {
      "id": 1997,
      "text": "On peut feindre d’avoir du cœur, pas d’avoir de l’esprit.",
      "author": "Paul Morand",
      "sourcePage": 42
    },
    {
      "id": 1998,
      "text": "En buvant l’eau du puits, n’oubliez pas ceux qui l’ont creusé.",
      "author": "Proverbe chinois",
      "sourcePage": 42
    },
    {
      "id": 1999,
      "text": "La vraie liberté est celle qui se dérobe sans bruit au cours trop bien huilé des choses.",
      "author": "Martine Mairal : \"Loin de moi\"",
      "sourcePage": 42
    },
    {
      "id": 2000,
      "text": "Mieux vaut réaliser son souhait que souhaiter l'avoir fait.",
      "author": "Woody Allen",
      "sourcePage": 42
    },
    {
      "id": 2001,
      "text": "Tout le bonheur du monde est dans l'inattendu.",
      "author": "Jean d'Ormesson, extrait d'une interview dans \"Libération - 23 Décembre 2000\"",
      "sourcePage": 42
    },
    {
      "id": 2002,
      "text": "Paresse : habitude prise de se reposer avant la fatigue.",
      "author": "Jules Renard, extrait de son \"Journal\"",
      "sourcePage": 42
    },
    {
      "id": 2003,
      "text": "Le monde appartient aux optimistes, les pessimistes ne sont que des spectateurs.",
      "author": "François Guizot",
      "sourcePage": 42
    },
    {
      "id": 2004,
      "text": "La seule façon d’être suivi, c’est de courir plus vite que les autres.",
      "author": "Francis Picabia : \"Ecrits\"",
      "sourcePage": 42
    },
    {
      "id": 2005,
      "text": "Le tact dans l’audace, c’est de savoir jusqu’où on peut aller trop loin.",
      "author": "Jean Cocteau : \"Le coq et l’arlequin\"",
      "sourcePage": 42
    },
    {
      "id": 2006,
      "text": "Il faut tout prendre au sérieux, mais rien au tragique.",
      "author": "Adolphe Thiers, extrait d’un discours à l’ \"Assemblée Nationale - 24 Mai 1873\"",
      "sourcePage": 42
    },
    {
      "id": 2007,
      "text": "Un homme est bien fort quand il s’avoue sa faiblesse.",
      "author": "Honoré de Balzac : \"La peau de chagrin\"",
      "sourcePage": 42
    },
    {
      "id": 2008,
      "text": "La fleur de l'illusion produit le fruit de la réalité.",
      "author": "Paul Claudel, extrait du \"Journal\"",
      "sourcePage": 42
    },
    {
      "id": 2009,
      "text": "Il vaut mieux débattre d’une question sans la régler que la régler sans en avoir débattu.",
      "author": "Joseph Joubert, extrait des \"Pensées, essais et maximes\"",
      "sourcePage": 42
    },
    {
      "id": 2010,
      "text": "Si l’on jugeait les choses sur les apparences, personne n’aurait jamais voulu manger un oursin.",
      "author": "Marcel Pagnol",
      "sourcePage": 42
    },
    {
      "id": 2011,
      "text": "Personne n’est plus redoutable que celui qui n’a jamais de doutes.",
      "author": "Jacques Sternberg",
      "sourcePage": 42
    },
    {
      "id": 2012,
      "text": "On ne fait pas ce qu'on veut et cependant on est responsable de ce qu'on est.",
      "author": "Jean-Paul Sartre",
      "sourcePage": 42
    },
    {
      "id": 2013,
      "text": "Les amis sont ceux qui vous forcent au bonheur.",
      "author": "Denys Gagnon",
      "sourcePage": 42
    },
    {
      "id": 2014,
      "text": "Les choses se déforment facilement quand on regarde en arrière.",
      "author": "Hermann Hesse : \"Biographie indienne\"",
      "sourcePage": 42
    },
    {
      "id": 2015,
      "text": "Quand un arbre tombe, on l'entend ; quand la forêt pousse, pas un bruit.",
      "author": "Proverbe africain",
      "sourcePage": 42
    },
    {
      "id": 2016,
      "text": "Mieux vaut une conscience tranquille qu'une destinée prospère. J'aime mieux un bon sommeil qu'un bon lit.",
      "author": "Victor Hugo : \"Littérature et philosophie mêlées\"",
      "sourcePage": 42
    },
    {
      "id": 2017,
      "text": "La moindre chose contient un peu d'inconnu. Trouvons-le.",
      "author": "Guy de Maupassant : \"Pierre et Jean\"",
      "sourcePage": 42
    },
    {
      "id": 2018,
      "text": "Tout homme est utile à l’humanité par cela seul qu’il existe.",
      "author": "Jean-Jacques Rousseau : \"Julie ou La nouvelle Héloïse\"",
      "sourcePage": 42
    },
    {
      "id": 2019,
      "text": "Le bon sens, tout le monde en a besoin, peu l'ont, et chacun croit l'avoir.",
      "author": "Benjamin Franklin",
      "sourcePage": 42
    },
    {
      "id": 2020,
      "text": "Il faut avoir besoin d'esprit pour arriver à avoir de l'esprit.",
      "author": "Friedrich Nietzsche : \"Le crépuscule des idoles\"",
      "sourcePage": 42
    },
    {
      "id": 2021,
      "text": "L'hymne de la haine ne profite pas à l'humanité.",
      "author": "Gandhi : \"Discours et écrits\"",
      "sourcePage": 42
    },
    {
      "id": 2022,
      "text": "L’amour dans l’œil de l’autre est un cadeau que l’on se fait à soi.",
      "author": "Christophe Renauld : \"Elles, une affaire\"",
      "sourcePage": 42
    },
    {
      "id": 2023,
      "text": "L’amour dans l’œil de l’autre est un cadeau que l’on se fait à soi.",
      "author": "Christophe Renauld : \"Elles, une affaire\"",
      "sourcePage": 42
    },
    {
      "id": 2024,
      "text": "Le talent, c'est la hardiesse, l'esprit libre, les idées larges.",
      "author": "Anton Tchekhov : \"Oncle Vania\"",
      "sourcePage": 42
    },
    {
      "id": 2025,
      "text": "La rigueur vient toujours à bout de l’obstacle.",
      "author": "Léonard de Vinci",
      "sourcePage": 42
    },
    {
      "id": 2026,
      "text": "Tout ce qui se ressemble n'est pas identique.",
      "author": "William Shakespeare : \"Jules Cesar\"",
      "sourcePage": 42
    },
    {
      "id": 2027,
      "text": "De petites occasions sont souvent à l'origine de grandes entreprises.",
      "author": "Démosthène",
      "sourcePage": 42
    },
    {
      "id": 2028,
      "text": "L'important, c'est de savoir ce qu'il faut observer.",
      "author": "Edgar Allan Poe, extrait des \"Histoires extraordinaires\"",
      "sourcePage": 43
    },
    {
      "id": 2029,
      "text": "C'est dans ce que les hommes ont de plus commun qu'ils se différencient le plus.",
      "author": "Blaise Cendrars, extrait d' \"Aujourd'hui\"",
      "sourcePage": 43
    },
    {
      "id": 2030,
      "text": "L'intelligence, c'est de prévoir celle de l'autre.",
      "author": "Georges Perros, extrait des \"Papiers collés\"",
      "sourcePage": 43
    },
    {
      "id": 2031,
      "text": "'Se souvenir', voilà le premier pas vers 'comprendre'.",
      "author": "Arnold Schönberg",
      "sourcePage": 43
    },
    {
      "id": 2032,
      "text": "Face à une œuvre d'art, on ne doit pas rêver, mais s'attacher à en percer la signification.",
      "author": "Arnold Schönberg",
      "sourcePage": 43
    },
    {
      "id": 2033,
      "text": "Il faut exiger de chacun ce que chacun peut donner.",
      "author": "Antoine de Saint-Exupéry : \"Le petit prince\"",
      "sourcePage": 43
    },
    {
      "id": 2034,
      "text": "J’ai assez d’idées pour qu’on puisse me voler sans me nuire.",
      "author": "André Malraux",
      "sourcePage": 43
    },
    {
      "id": 2035,
      "text": "Une erreur originale vaut mieux qu'une vérité banale.",
      "author": "Fiodor Dostoïevski",
      "sourcePage": 43
    },
    {
      "id": 2036,
      "text": "Quand vous êtes très jeune, l’humour est une défense. Par la suite, il peut devenir une arme.",
      "author": "René Goscinny, cité dans le livre de \"René Goscinny dessinateur\"",
      "sourcePage": 43
    },
    {
      "id": 2037,
      "text": "Les prévisions sont difficiles, surtout lorsqu’elles concernent l’avenir.",
      "author": "Pierre Dac",
      "sourcePage": 43
    },
    {
      "id": 2038,
      "text": "Il est temps de vivre la vie que tu t'es imaginée.",
      "author": "Henry James",
      "sourcePage": 43
    },
    {
      "id": 2039,
      "text": "Demain est moins à découvrir qu’à inventer.",
      "author": "Gaston Berger : \"Phénoménologie du temps et prospective\"",
      "sourcePage": 43
    },
    {
      "id": 2040,
      "text": "Un changement en prépare un autre.",
      "author": "Nicolas Machiavel",
      "sourcePage": 43
    },
    {
      "id": 2041,
      "text": "Un lac réfléchit mieux les étoiles qu'une rivière.",
      "author": "Théodore Jouffroy",
      "sourcePage": 43
    },
    {
      "id": 2042,
      "text": "Le souvenir des peines passées est agréable.",
      "author": "Euripide",
      "sourcePage": 43
    },
    {
      "id": 2043,
      "text": "Le projet est le brouillon de l'avenir. Parfois, il faut à l'avenir des centaines de brouillons.",
      "author": "Jules Renard, extrait de son \"Journal\"",
      "sourcePage": 43
    },
    {
      "id": 2044,
      "text": "Vouloir le vrai, c'est s'avouer impuissant à le créer.",
      "author": "Friedrich Nietzsche",
      "sourcePage": 43
    },
    {
      "id": 2045,
      "text": "Tout ce qui peut être fait un autre jour, le peut être aujourd'hui.",
      "author": "Montaigne",
      "sourcePage": 43
    },
    {
      "id": 2046,
      "text": "La vérité de demain se nourrit de l'erreur d'hier.",
      "author": "Antoine de Saint-Exupéry : \"Pilote de guerre\"",
      "sourcePage": 43
    },
    {
      "id": 2047,
      "text": "Patience ! Avec le temps, l'herbe devient du lait.",
      "author": "Proverbe chinois",
      "sourcePage": 43
    },
    {
      "id": 2048,
      "text": "Ne jamais se hâter ni tarder.",
      "author": "Marc-Aurèle",
      "sourcePage": 43
    },
    {
      "id": 2049,
      "text": "Tout le genre humain n'est qu'une famille dispersée sur la face de toute la terre.",
      "author": "Fénelon : \"Les aventures de Télémaque\"",
      "sourcePage": 43
    },
    {
      "id": 2050,
      "text": "C'est bon de ne pas regarder à la dépense de son énergie !",
      "author": "Jules Renard, extrait de son \"Journal\"",
      "sourcePage": 43
    },
    {
      "id": 2051,
      "text": "La vérité sort plus facilement de l’erreur que de la confusion.",
      "author": "Francis Bacon",
      "sourcePage": 43
    },
    {
      "id": 2052,
      "text": "Ne jamais se hâter ni tarder.",
      "author": "Marc-Aurèle",
      "sourcePage": 43
    },
    {
      "id": 2053,
      "text": "A voir marcher quelqu'un, on connaît sa pensée.",
      "author": "Pétrone",
      "sourcePage": 43
    },
    {
      "id": 2054,
      "text": "La crise d'hier est la blague de demain.",
      "author": "Herbert George Wells",
      "sourcePage": 43
    },
    {
      "id": 2055,
      "text": "Ouvrir les yeux est un antidote au désespoir.",
      "author": "Sylvain Tesson : \"Petit traité sur l’immensité du monde\"",
      "sourcePage": 43
    },
    {
      "id": 2056,
      "text": "Les jeunes gens voudraient être fidèles et ne le sont pas. Les vieux voudraient être infidèles et ne le peuvent plus.",
      "author": "Oscar Wilde",
      "sourcePage": 43
    },
    {
      "id": 2057,
      "text": "La sève du feuillage ne s'élucide qu'au secret des racines.",
      "author": "Patrick Chamoiseau, extrait de \"Texaco\"",
      "sourcePage": 43
    },
    {
      "id": 2058,
      "text": "L'homme qui déplace une montagne commence par déplacer les petites pierres.",
      "author": "Confucius",
      "sourcePage": 43
    },
    {
      "id": 2059,
      "text": "L’élégance est de se comporter dans la solitude comme en société.",
      "author": "Sylvain Tesson : \"Petit traité sur l’immensité du monde\"",
      "sourcePage": 43
    },
    {
      "id": 2060,
      "text": "Si haut que parvienne une chose lancée, c’est à terre qu’elle retourne.",
      "author": "Proverbe africain",
      "sourcePage": 43
    },
    {
      "id": 2061,
      "text": "J'avance dans l'hiver à force de printemps.",
      "author": "Prince de Ligne : \"Almanach de Bruxelles\"",
      "sourcePage": 43
    },
    {
      "id": 2062,
      "text": "L’homme libre est celui qui n’a pas peur d’aller jusqu’au bout de sa pensée.",
      "author": "Léon Blum",
      "sourcePage": 43
    },
    {
      "id": 2063,
      "text": "Lorsque tu ne sais pas où tu vas, regarde d’où tu viens.",
      "author": "Proverbe africain",
      "sourcePage": 43
    },
    {
      "id": 2064,
      "text": "On ne peut pas résoudre les difficultés en jouant à cache-cache avec elles.",
      "author": "Taslima Nasreen : \"Vent en rafales\"",
      "sourcePage": 43
    },
    {
      "id": 2065,
      "text": "J'avais mis mes souliers devant la cheminée, le père Noël m'a apporté des pieds.",
      "author": "Philippe Geluck, extrait de \"Le Chat\"",
      "sourcePage": 43
    },
    {
      "id": 2066,
      "text": "L'homme généreux invente même des raisons de donner.",
      "author": "Publius Syrus",
      "sourcePage": 43
    },
    {
      "id": 2067,
      "text": "Porter la liberté est la seule charge qui redresse bien le dos.",
      "author": "Patrick Chamoiseau, extrait de \"Texaco\"",
      "sourcePage": 43
    },
    {
      "id": 2068,
      "text": "Aucune vérité ne mérite de demeurer exemplaire.",
      "author": "André Breton : \"Les pas perdus\"",
      "sourcePage": 43
    },
    {
      "id": 2069,
      "text": "Les émotions sont faites pour être partagées.",
      "author": "Marc Levy : \"Et si c’était vrai...\"",
      "sourcePage": 43
    },
    {
      "id": 2070,
      "text": "Quel vin est aussi pétillant, savoureux, enivrant, que l’infini des possibles !",
      "author": "Sören Kierkegaard",
      "sourcePage": 43
    },
    {
      "id": 2071,
      "text": "Demain du ventre du temps surgira une année nouvelle.",
      "author": "Njabulo S. Ndebele : \"Portrait de l'amour\"",
      "sourcePage": 43
    },
    {
      "id": 2072,
      "text": "Les bonnes résolutions ne gagnent pas à être différées.",
      "author": "Jules Romains : \"Monsieur le Trouhadec saisi par la débauche\"",
      "sourcePage": 43
    },
    {
      "id": 2073,
      "text": "Qu'importent les trésors ! Plutôt qu'argent entasser, mieux vaut amis posséder.",
      "author": "Nikolaï Gogol : \"Les âmes mortes\"",
      "sourcePage": 43
    },
    {
      "id": 2074,
      "text": "La joie des autres est une grande part de la nôtre.",
      "author": "Ernest Renan",
      "sourcePage": 44
    },
    {
      "id": 2075,
      "text": "L’homme de culture doit être un inventeur d’âmes.",
      "author": "Aimé Césaire",
      "sourcePage": 44
    },
    {
      "id": 2076,
      "text": "Les spectateurs ne trouvent pas ce qu'ils désirent, ils désirent ce qu'ils trouvent.",
      "author": "Guy Debord, extrait du documentaire \"Refutation de tous les jugements tant élogieux qu'hostiles...\"",
      "sourcePage": 44
    },
    {
      "id": 2077,
      "text": "Ce que nous jouons, c’est la vie.",
      "author": "Louis Armstrong",
      "sourcePage": 44
    },
    {
      "id": 2078,
      "text": "Nos élèves cherchent en nous ce qu'ils espèrent de l'avenir.",
      "author": "Denys Gagnon",
      "sourcePage": 44
    },
    {
      "id": 2079,
      "text": "Un homme sans culture ressemble à un zèbre sans rayures.",
      "author": "Proverbe africain",
      "sourcePage": 44
    },
    {
      "id": 2080,
      "text": "Lorsque l'art entre dans une maison, la violence en sort.",
      "author": "Fernando Botero",
      "sourcePage": 44
    },
    {
      "id": 2081,
      "text": "La vie est trop courte pour être petite.",
      "author": "Benjamin Disraeli",
      "sourcePage": 44
    },
    {
      "id": 2082,
      "text": "L'homme le plus heureux est celui qui fait le bonheur d'un plus grand nombre d'autres.",
      "author": "Denis Diderot : \"Dictionnaire des hommes\"",
      "sourcePage": 44
    },
    {
      "id": 2083,
      "text": "L'amitié n'exige rien en échange, que de l'entretien.",
      "author": "Georges Brassens",
      "sourcePage": 44
    },
    {
      "id": 2084,
      "text": "Traitez les gens comme s'ils étaient ce qu'ils doivent être et vous les aiderez à devenir ce qu'ils sont capables d'être.",
      "author": "Goethe",
      "sourcePage": 44
    },
    {
      "id": 2085,
      "text": "La poésie ne doit pas périr. Car alors, où serait l’espoir du Monde ?",
      "author": "Léopold Sédar Senghor",
      "sourcePage": 44
    },
    {
      "id": 2086,
      "text": "Rien de pire qu’un mur pour bloquer les idées.",
      "author": "Annie Lemoine : \"Vue sur mer\"",
      "sourcePage": 44
    },
    {
      "id": 2087,
      "text": "Si vous ne pouvez expliquer un concept à un enfant de six ans, c'est que vous ne le comprenez pas complètement.",
      "author": "Albert Einstein",
      "sourcePage": 44
    },
    {
      "id": 2088,
      "text": "La parole n'a pas été donnée à l'homme : il l'a prise.",
      "author": "Louis Aragon : \"Le libertinage\"",
      "sourcePage": 44
    },
    {
      "id": 2089,
      "text": "Combien fécond le plus petit domaine, quand on sait bien le cultiver.",
      "author": "Goethe",
      "sourcePage": 44
    },
    {
      "id": 2090,
      "text": "La nécessité de rechercher le véritable bonheur est le fondement de notre liberté.",
      "author": "John Locke : \"Essai sur l'entendement humain\"",
      "sourcePage": 44
    },
    {
      "id": 2091,
      "text": "Tout le plaisir de l'amour est dans le changement.",
      "author": "Molière",
      "sourcePage": 44
    },
    {
      "id": 2092,
      "text": "Tout le monde peut être important car tout le monde peut servir à quelque chose.",
      "author": "Martin Luther King",
      "sourcePage": 44
    },
    {
      "id": 2093,
      "text": "Si l'on m'apprenait que la fin du monde est pour demain, je planterais quand même un pommier.",
      "author": "Martin Luther",
      "sourcePage": 44
    },
    {
      "id": 2094,
      "text": "Le seul moyen de guérir, c’est de se considérer comme guéri.",
      "author": "Gustave Flaubert, extrait d’une \"Lettre\"",
      "sourcePage": 44
    },
    {
      "id": 2095,
      "text": "Pour avoir du talent, il faut être convaincu qu’on en possède.",
      "author": "Gustave Flaubert, extrait d’une \"Lettre\"",
      "sourcePage": 44
    },
    {
      "id": 2096,
      "text": "Une route peut prendre mille directions, la vérité n’en connaît qu’une.",
      "author": "Proverbe chinois",
      "sourcePage": 44
    },
    {
      "id": 2097,
      "text": "Si l'on peut trouver moins que rien, c'est que rien vaut déjà quelque chose.",
      "author": "Raymond Devos, extrait du sketch \"Parler pour ne rien dire\"",
      "sourcePage": 44
    },
    {
      "id": 2098,
      "text": "On peut toujours faire quelque chose de ce qu'on a fait de nous.",
      "author": "Jean-Paul Sartre : \"L'existentialisme est un humanisme\"",
      "sourcePage": 44
    },
    {
      "id": 2099,
      "text": "Il faut rêver très haut pour ne pas réaliser trop bas.",
      "author": "Alfred Capus",
      "sourcePage": 44
    },
    {
      "id": 2100,
      "text": "Ne juge pas chaque jour à la récolte que tu fais mais aux graines que tu sèmes.",
      "author": "Robert Louis Stevenson",
      "sourcePage": 44
    },
    {
      "id": 2101,
      "text": "Il faut commencer par éprouver ce qu'on veut exprimer.",
      "author": "Vincent Van Gogh",
      "sourcePage": 44
    },
    {
      "id": 2102,
      "text": "La vie est magnifique aussi longtemps qu’elle vous consume.",
      "author": "David Herbert Lawrence : \"Ile, mon île\"",
      "sourcePage": 44
    },
    {
      "id": 2103,
      "text": "Il faudrait naître vieux, débuter par la sagesse puis décider de son destin.",
      "author": "Ana Blandiana : \"Il faudrait\"",
      "sourcePage": 44
    },
    {
      "id": 2104,
      "text": "Choisissez un travail que vous aimez et vous n’aurez pas à travailler un seul jour de votre vie.",
      "author": "Confucius",
      "sourcePage": 44
    },
    {
      "id": 2105,
      "text": "Les gens heureux n’ont pas besoin de se presser.",
      "author": "Proverbe chinois",
      "sourcePage": 44
    },
    {
      "id": 2106,
      "text": "Tout ce qu'on ne connaît pas paraît magnifique.",
      "author": "Tacite",
      "sourcePage": 44
    },
    {
      "id": 2107,
      "text": "La seule vraie rébellion est la recherche du bonheur.",
      "author": "Henrik Ibsen",
      "sourcePage": 44
    },
    {
      "id": 2108,
      "text": "Il faut que la volonté imagine trop pour réaliser assez.",
      "author": "Gaston Bachelard",
      "sourcePage": 44
    },
    {
      "id": 2109,
      "text": "Le monde est un endroit magnifique pour lequel il vaut la peine de se battre.",
      "author": "Ernest Hemingway : \"Pour qui sonne le glas\"",
      "sourcePage": 44
    },
    {
      "id": 2110,
      "text": "L’Homme a cru qu’il importait d’avoir ignorant qu’il importe d’être.",
      "author": "Oscar Wilde : \"L’Âme Humaine\"",
      "sourcePage": 44
    },
    {
      "id": 2111,
      "text": "J'aime mieux un vice commode qu'une fatigante vertu.",
      "author": "Molière : \"Amphitryon\"",
      "sourcePage": 44
    },
    {
      "id": 2112,
      "text": "Un bien acquis sans peine est un trésor en l'air.",
      "author": "Pierre Corneille : \"Le menteur\"",
      "sourcePage": 44
    },
    {
      "id": 2113,
      "text": "C'est une très belle histoire que nous vivons, puisque nous la vivons.",
      "author": "Yves Navarre : \"Le temps voulu\"",
      "sourcePage": 44
    },
    {
      "id": 2114,
      "text": "Formule de mon bonheur : un \"oui\", un \"non\", une ligne droite, un but...",
      "author": "Friedrich Nietzsche : \"Le crépuscule des idoles\"",
      "sourcePage": 44
    },
    {
      "id": 2115,
      "text": "L'amour, c'est rencontrer quelqu'un qui vous donne des nouvelles de vous.",
      "author": "André Breton",
      "sourcePage": 44
    },
    {
      "id": 2116,
      "text": "Il n’y a jamais un sommet d’où la vue ne soit pas belle.",
      "author": "Sylvain Tesson",
      "sourcePage": 44
    },
    {
      "id": 2117,
      "text": "Dans la vie on ne fait pas ce que l’on veut mais on est responsable de ce que l’on est.",
      "author": "Jean-Paul Sartre",
      "sourcePage": 45
    },
    {
      "id": 2118,
      "text": "Pourquoi un miracle n’en serait pas un seulement parce qu’un autre ne le voit pas ?",
      "author": "Arthur Japin, cité dans le livre de \"Un charmant défaut\"",
      "sourcePage": 45
    },
    {
      "id": 2119,
      "text": "On se livre d'autant plus vivement aux plaisirs qu'on se sent près de les perdre.",
      "author": "François René de Chateaubriand, extrait de ses \"Mémoires d’outre-tombe\"",
      "sourcePage": 45
    },
    {
      "id": 2120,
      "text": "La bonne volonté raccourcit le chemin.",
      "author": "Proverbe brésilien",
      "sourcePage": 45
    },
    {
      "id": 2121,
      "text": "A vouloir étouffer les révolutions pacifiques, on rend inévitables les révolutions violentes.",
      "author": "John Fitzgerald Kennedy",
      "sourcePage": 45
    },
    {
      "id": 2122,
      "text": "Souvent on entend mal ce qu'on croit bien entendre.",
      "author": "Molière : \"Dom Garcie de Navare\"",
      "sourcePage": 45
    },
    {
      "id": 2123,
      "text": "La vérité tient sa lumière en elle-même, non dans celui qui la dit.",
      "author": "Christian Bobin: \"Le Très-Bas\"",
      "sourcePage": 45
    },
    {
      "id": 2124,
      "text": "Il n'y a personne qui soit née sous une mauvaise étoile, il n'y a que des gens qui ne savent pas lire le ciel.",
      "author": "Dalaï Lama",
      "sourcePage": 45
    },
    {
      "id": 2125,
      "text": "En amour, celui qui est guéri le premier est toujours le mieux guéri.",
      "author": "François de La Rochefoucauld : \"Maximes\"",
      "sourcePage": 45
    },
    {
      "id": 2126,
      "text": "Toute accession à une haute fonction emprunte un escalier tortueux.",
      "author": "Francis Bacon, extrait des \"Essais\"",
      "sourcePage": 45
    },
    {
      "id": 2127,
      "text": "Avec les enfants, quoi qu’on fasse, on se trompe toujours.",
      "author": "Maria Mercè Roca : \"Le Dernier Train\"",
      "sourcePage": 45
    },
    {
      "id": 2128,
      "text": "La jalousie est le tyran du royaume de l'amour.",
      "author": "Miguel de Cervantès",
      "sourcePage": 45
    },
    {
      "id": 2129,
      "text": "Le vice, c’est le mal qu’on fait sans plaisir.",
      "author": "Colette : \"Claudine en ménage\"",
      "sourcePage": 45
    },
    {
      "id": 2130,
      "text": "C'est une merveille d'ignorer l'avenir.",
      "author": "Marguerite Duras : \"Des journées dans les arbres\"",
      "sourcePage": 45
    },
    {
      "id": 2131,
      "text": "Je me sens très optimiste quant à l’avenir du pessimisme.",
      "author": "Jean Rostand : \"Carnet d’un biologiste\"",
      "sourcePage": 45
    },
    {
      "id": 2132,
      "text": "Malheur aux détails, la postérité les néglige tous.",
      "author": "Voltaire : \"Correspondance\"",
      "sourcePage": 45
    },
    {
      "id": 2133,
      "text": "‘On’ n’est pas indéfini, c’est ‘je’ qui manque de précision.",
      "author": "Tania de Montaigne : \"Tokyo c’est loin\"",
      "sourcePage": 45
    },
    {
      "id": 2134,
      "text": "Ne restreins pas le champ du possible aux limites de ton imaginaire.",
      "author": "Antony Bouchardon, extrait de la \"Lettre à Bernard de Milleville\"",
      "sourcePage": 45
    },
    {
      "id": 2135,
      "text": "Les ampoules aux mains sont plus honorables que les bagues.",
      "author": "Proverbe estonien",
      "sourcePage": 45
    },
    {
      "id": 2136,
      "text": "La vie, c’est comme la mer, elle ne porte que ceux qui remuent.",
      "author": "Hervé Bazin",
      "sourcePage": 45
    },
    {
      "id": 2137,
      "text": "Un coup de dés jamais n'abolira le hasard.",
      "author": "Stéphane Mallarmé",
      "sourcePage": 45
    },
    {
      "id": 2138,
      "text": "La seule manière de protéger sa culture, c'est d'accepter de la mettre en danger.",
      "author": "Paul Andreu",
      "sourcePage": 45
    },
    {
      "id": 2139,
      "text": "Le doute est un hommage que l'on rend à la vérité.",
      "author": "Ernest Renan",
      "sourcePage": 45
    },
    {
      "id": 2140,
      "text": "L’empreinte d’un homme sur un autre est éternelle, aucun destin n’a traversé le nôtre impunément.",
      "author": "François Mauriac",
      "sourcePage": 45
    },
    {
      "id": 2141,
      "text": "L'expérience, ce n'est pas ce qui arrive à quelqu'un, c'est ce que quelqu'un fait avec ce qui lui arrive.",
      "author": "Aldous Huxley : \"Le meilleur des mondes\"",
      "sourcePage": 45
    },
    {
      "id": 2142,
      "text": "La vie ne se comprend que par un retour en arrière, mais on ne la vit qu’en avant.",
      "author": "Søren Kierkegaard",
      "sourcePage": 45
    },
    {
      "id": 2143,
      "text": "Autrui, pièce maîtresse de mon univers.",
      "author": "Michel Tournier : \"Vendredi ou les limbes du Pacifique\"",
      "sourcePage": 45
    },
    {
      "id": 2144,
      "text": "Toute âme est une mélodie qu’il s’agit de renouer.",
      "author": "Stéphane Mallarmé",
      "sourcePage": 45
    },
    {
      "id": 2145,
      "text": "Ma vie est une énigme dont ton nom est le mot.",
      "author": "Victor Hugo",
      "sourcePage": 45
    },
    {
      "id": 2146,
      "text": "Un livre est une fenêtre par laquelle on s’évade.",
      "author": "Julien Green",
      "sourcePage": 45
    },
    {
      "id": 2147,
      "text": "Le fait que les hommes tirent peu de profit des leçons de l’Histoire est la leçon la plus importante que l’Histoire nous enseigne.",
      "author": "Aldous Huxley : \"Collected essays\"",
      "sourcePage": 45
    },
    {
      "id": 2148,
      "text": "Le divorce est un ourlet au bas du cœur avant qu’il ne s’effiloche.",
      "author": "Dominique Sampiero : \"La Petite Présence\"",
      "sourcePage": 45
    },
    {
      "id": 2149,
      "text": "Le monde ne mourra jamais par manque de merveilles mais uniquement par manque d’émerveillement.",
      "author": "Gilbert Keith Chesterton",
      "sourcePage": 45
    },
    {
      "id": 2150,
      "text": "La route qui mène chez un ami n’est jamais longue.",
      "author": "Proverbe danois",
      "sourcePage": 45
    },
    {
      "id": 2151,
      "text": "L’être humain a besoin d’inscrire le moindre de ses gestes dans un devenir afin de ne pas sombrer dans le désespoir.",
      "author": "Rajae Benchemsi : \"Marrakech, lumière d’exil\"",
      "sourcePage": 45
    },
    {
      "id": 2152,
      "text": "\"L’avenir de l’homme, c'est la femme. Elle est la couleur de son âme.\" Louis Aragon",
      "author": "\"Le fou d’Elsa\"",
      "sourcePage": 45
    },
    {
      "id": 2153,
      "text": "La politique est le premier des arts et le dernier des métiers.",
      "author": "Voltaire",
      "sourcePage": 45
    },
    {
      "id": 2154,
      "text": "Ni l’ignorance n’est défaut d’esprit, ni le savoir n’est preuve de génie.",
      "author": "Vauvenargues : \"Réflexions et maximes\"",
      "sourcePage": 45
    },
    {
      "id": 2155,
      "text": "L’égoïsme et la haine ont seuls une patrie ; la fraternité n’en a pas !",
      "author": "Alphonse de Lamartine : \"La Marseillaise de la paix\"",
      "sourcePage": 45
    },
    {
      "id": 2156,
      "text": "Les choses n'ont pas de signification : elles ont une existence.",
      "author": "Fernando Pessoa : \"Le gardeur de troupeaux et autres poèmes\"",
      "sourcePage": 45
    },
    {
      "id": 2157,
      "text": "Il n'est pas de plaisir plus doux que de surprendre un homme en lui donnant plus qu'il n'espère.",
      "author": "Charles Baudelaire : \"Le spleen de Paris\"",
      "sourcePage": 45
    },
    {
      "id": 2158,
      "text": "La peinture ne saisira le mystère de la réalité que si le peintre ne sait pas comment s'y prendre.",
      "author": "Francis Bacon, extrait des \"Entretiens avec David Sylvester\"",
      "sourcePage": 46
    },
    {
      "id": 2159,
      "text": "Il est bien plus divertissant d'être ennuyeux que d'être intéressant.",
      "author": "Amélie Nothomb : \"Les catilinaires\"",
      "sourcePage": 46
    },
    {
      "id": 2160,
      "text": "Rien n'est trop difficile pour la jeunesse.",
      "author": "Socrate",
      "sourcePage": 46
    },
    {
      "id": 2161,
      "text": "Quand on ne sait rien faire, il faut avoir de l'ambition.",
      "author": "Georges Wolinski",
      "sourcePage": 46
    },
    {
      "id": 2162,
      "text": "Le désespoir, c’est quand l’intelligence prend la souffrance à son compte.",
      "author": "Georges Perros : \"En vue d’un éloge de la paresse\"",
      "sourcePage": 46
    },
    {
      "id": 2163,
      "text": "Le début ne laisse pas présager la fin.",
      "author": "Hérodote : \"Histoires\"",
      "sourcePage": 46
    },
    {
      "id": 2164,
      "text": "L'avenir n'existe qu'au présent.",
      "author": "Louis Scutenaire : \"Mes inscriptions\"",
      "sourcePage": 46
    },
    {
      "id": 2165,
      "text": "Donner aux uns, ça veut dire prendre aux autres.",
      "author": "Georges Wolinski",
      "sourcePage": 46
    },
    {
      "id": 2166,
      "text": "Aucune culture n'est l'entière vérité.",
      "author": "Richard Hoggart, extrait du journal \"The Listener - 1971\"",
      "sourcePage": 46
    },
    {
      "id": 2167,
      "text": "La politique de l’autruche est respectable : tout dépend de ce qu’il y a dans le sable.",
      "author": "Didier van Cauwelaert : \"Cloner le christ ?\"",
      "sourcePage": 46
    },
    {
      "id": 2168,
      "text": "Si tu te sers de la liberté en échange d'autre chose, comme l'oiseau, elle s'envolera.",
      "author": "Gao Xingjian, extrait du discours de \"Réception du Prix Nobel - Décembre 2000\"",
      "sourcePage": 46
    },
    {
      "id": 2169,
      "text": "La plume est la langue de l’âme.",
      "author": "Miguel de Cervantès : \"Don Quichotte\"",
      "sourcePage": 46
    },
    {
      "id": 2170,
      "text": "Sans l'ironie, le monde serait comme une forêt sans oiseaux.",
      "author": "Anatole France",
      "sourcePage": 46
    },
    {
      "id": 2171,
      "text": "La route de l’excès mène au palais de la sagesse.",
      "author": "William Blake : \"Le mariage du Ciel et de l'Enfer\"",
      "sourcePage": 46
    },
    {
      "id": 2172,
      "text": "Que d'hommes se pressent vers la lumière non pas pour voir mieux, mais pour mieux briller.",
      "author": "Friedrich Nietzsche",
      "sourcePage": 46
    },
    {
      "id": 2173,
      "text": "Jusqu’à présent, les hommes n’ont trouvé d’autre chemin vers la vérité que l’erreur.",
      "author": "Nicolae Iorga, extrait des \"Pensées\"",
      "sourcePage": 46
    },
    {
      "id": 2174,
      "text": "L’encre d’autrui conduit vite au sommet, mais il ne faut pas attendre qu’elle sèche.",
      "author": "David Gilbert : \"Les Normaux\"",
      "sourcePage": 46
    },
    {
      "id": 2175,
      "text": "Le cœur le plus sensible à la beauté des fleurs est toujours le premier blessé par les épines.",
      "author": "Thomas Moore",
      "sourcePage": 46
    },
    {
      "id": 2176,
      "text": "Avant d’aimer avec le cœur et avec son corps, on aime d’abord avec des mots.",
      "author": "Pascal Martin : \"Le Bonsaï de Brocéliande\"",
      "sourcePage": 46
    },
    {
      "id": 2177,
      "text": "\"Le mensonge, comme l’huile, flotte à la surface de la vérité.\" Henryk Sienkiewicz",
      "author": "\"Quo vadis\"",
      "sourcePage": 46
    },
    {
      "id": 2178,
      "text": "Il faut retenir son cœur, car si on le laissait aller, combien vite, alors, on perdrait la tête !",
      "author": "Friedrich Nietzsche, extrait d’ \"Ainsi parlait Zarathoustra\"",
      "sourcePage": 46
    },
    {
      "id": 2179,
      "text": "La perfection des moyens et la confusion des buts semblent caractériser notre époque.",
      "author": "Albert Einstein",
      "sourcePage": 46
    },
    {
      "id": 2180,
      "text": "Quand on a du caractère, il est toujours mauvais.",
      "author": "Georges Clemenceau",
      "sourcePage": 46
    },
    {
      "id": 2181,
      "text": "La victoire obtenue par la violence équivaut à une défaite, car elle est momentanée.",
      "author": "Gandhi",
      "sourcePage": 46
    },
    {
      "id": 2182,
      "text": "Quand tu donnes tu perçois plus que tu ne donnes, car tu n'étais rien et tu deviens.",
      "author": "Antoine de Saint-Exupéry",
      "sourcePage": 46
    },
    {
      "id": 2183,
      "text": "Il ne faut pas attendre d’être parfait pour commencer quelque chose de bien.",
      "author": "Abbé Pierre : \"Servir\"",
      "sourcePage": 46
    },
    {
      "id": 2184,
      "text": "Il n'y a pas d'acte qui soit tout à fait gratuit ; même pas le don de soi-même.",
      "author": "Emmanuel Boundzéki Dongala : \"Un fusil dans la main, un poème dans la poche\"",
      "sourcePage": 46
    },
    {
      "id": 2185,
      "text": "Il y a de la vérité, même s'il n'y a pas de vraisemblance, dans tout ce qu'un homme rêve.",
      "author": "José Eduardo Agualusa : \"Le Marchand de passés\"",
      "sourcePage": 46
    },
    {
      "id": 2186,
      "text": "Celui qui n'a qu'un désir ou qu'une opinion est un homme à caractère.",
      "author": "Rivarol, extrait des \"Maximes, pensées et paradoxes\"",
      "sourcePage": 46
    },
    {
      "id": 2187,
      "text": "La vie est plus belle que la prudence.",
      "author": "Abbé Pierre : \"Servir\"",
      "sourcePage": 46
    },
    {
      "id": 2188,
      "text": "Seule la chaussure sait si la chaussette a des trous.",
      "author": "Proverbe créole",
      "sourcePage": 46
    },
    {
      "id": 2189,
      "text": "Le progrès nait de la diversité des cultures et de l'affirmation des personnalités.",
      "author": "Pierre Joliot : \"La recherche passionnément\"",
      "sourcePage": 46
    },
    {
      "id": 2190,
      "text": "Ce n'est pas en enfermant son voisin qu'on se convainc de son propre bon sens.",
      "author": "Fiodor Dostoïevski",
      "sourcePage": 46
    },
    {
      "id": 2191,
      "text": "La vie est la seule carrière qui m'intéresse.",
      "author": "Erik Orsenna, extrait d'une interview dans \"Lire - Mai 2000\"",
      "sourcePage": 46
    },
    {
      "id": 2192,
      "text": "Ce qui est nécessaire n'est jamais ridicule.",
      "author": "Cardinal de Retz, extrait de ses \"Mémoires\"",
      "sourcePage": 46
    },
    {
      "id": 2193,
      "text": "Il faut plus de force et de talent pour conserver que pour acquérir.",
      "author": "Jean Pucelle : \"Le temps\"",
      "sourcePage": 46
    },
    {
      "id": 2194,
      "text": "Ce ne sont pas ceux qui courent le plus vite qui sont les plus pressés.",
      "author": "Coluche, extrait du sketch \"Si j’ai bien tout lu Freud - 1980\"",
      "sourcePage": 46
    },
    {
      "id": 2195,
      "text": "Avec le mot \"si\" on peut faire tout ce qu'on ne peut pas faire.",
      "author": "Pierre Dac : \"Y'a du mou dans la corde à nœuds !\"",
      "sourcePage": 46
    },
    {
      "id": 2196,
      "text": "L'humour est la forme la plus saine de la lucidité.",
      "author": "Jacques Brel",
      "sourcePage": 47
    },
    {
      "id": 2197,
      "text": "Se cogner à la réalité ne peut pas faire de mal.",
      "author": "Smaïn : \"Sur la vie de ma mère\"",
      "sourcePage": 47
    },
    {
      "id": 2198,
      "text": "La nature des choses se livre davantage à travers les tourments de l’art que dans sa liberté propre.",
      "author": "Francis Bacon, extrait d’ \"Instauratio Magna\"",
      "sourcePage": 47
    },
    {
      "id": 2199,
      "text": "Il faut emprunter les idées du peuple si l'on veut le diriger.",
      "author": "Eric-Emmanuel Schmitt : \"L'évangile selon Pilate\"",
      "sourcePage": 47
    },
    {
      "id": 2200,
      "text": "Je m'avance vers celui qui me contredit.",
      "author": "Montaigne",
      "sourcePage": 47
    },
    {
      "id": 2201,
      "text": "La fortune ne devrait être possédée que par les gens d'esprit : autrement, elle représente un danger public.",
      "author": "Friedrich Nietzsche, extrait d' \"Humain, trop humain\"",
      "sourcePage": 47
    },
    {
      "id": 2202,
      "text": "Pour rouler au hasard, il faut être seul. Dès qu'on est deux, on va toujours quelque part.",
      "author": "Alfred Hitchcock, dialogue du film \"Sueurs froides\"",
      "sourcePage": 47
    },
    {
      "id": 2203,
      "text": "Mieux vaut lire un homme que dix livres.",
      "author": "Charles-Augustin Sainte-Beuve : \"Causeries du lundi\"",
      "sourcePage": 47
    },
    {
      "id": 2204,
      "text": "Le rôle de tout être humain, c’est de faire la preuve que le monde n’est pas sans raison.",
      "author": "Abbé Pierre : \"Servir\"",
      "sourcePage": 47
    },
    {
      "id": 2205,
      "text": "Travailler en ne faisant rien, c’est une approche du bonheur de notre époque.",
      "author": "Denys Colomb de Daunant : \"Le Séquoia\"",
      "sourcePage": 47
    },
    {
      "id": 2206,
      "text": "La meilleure façon de tuer un artiste est sûrement de lui donner tout ce dont il a besoin.",
      "author": "Henry Miller : \"Peindre c'est aimer à nouveau\"",
      "sourcePage": 47
    },
    {
      "id": 2207,
      "text": "Etre, c'est être différent, c'est n'avoir pas de sosie, pas même dans la glace.",
      "author": "Louis Pauwels : \"Les dernières chaînes\"",
      "sourcePage": 47
    },
    {
      "id": 2208,
      "text": "La moitié d'une orange goûte aussi sucrée qu'une orange entière.",
      "author": "Johann Wolfgang von Goethe",
      "sourcePage": 47
    },
    {
      "id": 2209,
      "text": "Rien de plus sale que l’amour-propre.",
      "author": "Marguerite Yourcenar : \"Feux\"",
      "sourcePage": 47
    },
    {
      "id": 2210,
      "text": "On fait tout pour gagner un cœur et bien peu pour le garder.",
      "author": "Jacques Deval",
      "sourcePage": 47
    },
    {
      "id": 2211,
      "text": "Frapper l'ennemi, c'est bien. Frapper l'imagination, c'est mieux.",
      "author": "Jean de Lattre de Tassigny",
      "sourcePage": 47
    },
    {
      "id": 2212,
      "text": "J’aimerais pouvoir m’exprimer avec mes sens. Les mots sont parfois très handicapants.",
      "author": "Björk, extrait d'une interview \"Tracks - 19 décembre 1997\"",
      "sourcePage": 47
    },
    {
      "id": 2213,
      "text": "Ce n'est pas que je suis si intelligent, c'est que je reste plus longtemps avec les problèmes.",
      "author": "Albert Einstein",
      "sourcePage": 47
    },
    {
      "id": 2214,
      "text": "Mieux vaut tomber de très haut que de voler comme un moineau.",
      "author": "Dimitri T. Analis : \"L’Autre royaume\"",
      "sourcePage": 47
    },
    {
      "id": 2215,
      "text": "L'homme est parfois assez fou pour préférer le chagrin à l'oubli.",
      "author": "Maurice Chapelan",
      "sourcePage": 47
    },
    {
      "id": 2216,
      "text": "La défense la plus sûre contre la tentation, c'est la lâcheté.",
      "author": "Mark Twain",
      "sourcePage": 47
    },
    {
      "id": 2217,
      "text": "Il y a une chose plus terrible que la calomnie, c'est la vérité.",
      "author": "Talleyrand",
      "sourcePage": 47
    },
    {
      "id": 2218,
      "text": "La volonté de condamner emploie toujours l'arme qu'elle a sous la main.",
      "author": "Gaston Bachelard : \"La psychanalyse du feu\"",
      "sourcePage": 47
    },
    {
      "id": 2219,
      "text": "On parle bien plus volontiers de ce qu'on ignore. Car c'est à quoi l'on pense.",
      "author": "Paul Valéry : \"Tel quel\"",
      "sourcePage": 47
    },
    {
      "id": 2220,
      "text": "Tout mouvement politique est fondé sur le kitsch, sur la volonté de séduire.",
      "author": "Milan Kundera, extrait d'un \"Entretien avec Antoine de Gaudemar - Février 1984\"",
      "sourcePage": 47
    },
    {
      "id": 2221,
      "text": "Peu de gens sont faits pour l'indépendance, c'est le privilège des puissants.",
      "author": "Friedrich Nietzsche",
      "sourcePage": 47
    },
    {
      "id": 2222,
      "text": "Seul le fantastique a des chances d'être vrai.",
      "author": "Pierre Teilhard de Chardin",
      "sourcePage": 47
    },
    {
      "id": 2223,
      "text": "Les citoyens ne devraient pas craindre leur gouvernement, c'est le gouvernement qui devrait craindre ses citoyens.",
      "author": "Alan Moore",
      "sourcePage": 47
    },
    {
      "id": 2224,
      "text": "Quand on renie le passé on perd l’avenir.",
      "author": "Dulce Maria Cardoso : \"Les Anges, Violeta\"",
      "sourcePage": 47
    },
    {
      "id": 2225,
      "text": "Dans la communication, le plus compliqué n'est ni le message, ni la technique, mais le récepteur.",
      "author": "Dominique Wolton",
      "sourcePage": 47
    },
    {
      "id": 2226,
      "text": "Ce n'est pas la récompense qui élève l'âme, mais le labeur qui lui valu cette récompense.",
      "author": "Multatuli : \"Max Havelaar\"",
      "sourcePage": 47
    },
    {
      "id": 2227,
      "text": "Qui s’est brûlé la langue n’oublie plus de souffler sur sa soupe.",
      "author": "Proverbe allemand",
      "sourcePage": 47
    },
    {
      "id": 2228,
      "text": "Sans la liberté de blâmer, il n’est point d’éloge flatteur.",
      "author": "Beaumarchais : \"Le Mariage de Figaro\"",
      "sourcePage": 47
    },
    {
      "id": 2229,
      "text": "Tant de mains pour transformer ce monde, et si peu de regards pour le contempler !",
      "author": "Julien Gracq : \"Lettrines\"",
      "sourcePage": 47
    },
    {
      "id": 2230,
      "text": "On mesure l’intelligence d’un individu à la quantité d’incertitudes qu’il est capable de supporter.",
      "author": "Emmanuel Kant",
      "sourcePage": 47
    },
    {
      "id": 2231,
      "text": "Ils ont échoué parce qu’ils n’avaient pas commencé par le rêve.",
      "author": "William Shakespeare",
      "sourcePage": 47
    },
    {
      "id": 2232,
      "text": "S'il fallait étudier toutes les lois, on n'aurait pas le temps de les transgresser.",
      "author": "Johann Wolfgang von Goethe",
      "sourcePage": 47
    },
    {
      "id": 2233,
      "text": "La vie est une chose trop importante pour être prise au sérieux.",
      "author": "Gilbert Keith Chesterton",
      "sourcePage": 47
    },
    {
      "id": 2234,
      "text": "Quand les sages sont au bout de leur sagesse, il convient d'écouter les enfants.",
      "author": "Georges Bernanos : \"Dialogues de Carmélites\"",
      "sourcePage": 47
    },
    {
      "id": 2235,
      "text": "Il faut que l'idée naisse de la vision comme l'étincelle du caillou.",
      "author": "Charles-Ferdinand Ramuz",
      "sourcePage": 47
    },
    {
      "id": 2236,
      "text": "Le rire est le meilleur cadeau que nous puissions faire aux autres.",
      "author": "Dulce Maria Cardoso : \"Les Anges, Violeta\"",
      "sourcePage": 48
    },
    {
      "id": 2237,
      "text": "Les caresses n'ont jamais transformé un tigre en chaton.",
      "author": "Franklin Delano Roosevelt",
      "sourcePage": 48
    },
    {
      "id": 2238,
      "text": "Le cinéma est fait pour tous ceux dont la curiosité est le plus grand défaut.",
      "author": "Claude Lelouch : \"Itinéraire d'un enfant très gâté\"",
      "sourcePage": 48
    },
    {
      "id": 2239,
      "text": "En même temps, si on était mort, on ne pourrait pas se plaindre de la vie.",
      "author": "Frédéric Beigbeder : \"L’égoïste romantique\"",
      "sourcePage": 48
    },
    {
      "id": 2240,
      "text": "La musique, c’est du bruit qui pense.",
      "author": "Victor Hugo, extrait des \"Fragments\"",
      "sourcePage": 48
    },
    {
      "id": 2241,
      "text": "Il ne suffit pas de parler, il faut parler juste.",
      "author": "William Shakespeare : \"Le songe d'une nuit d'été\"",
      "sourcePage": 48
    },
    {
      "id": 2242,
      "text": "On transforme sa main en la mettant dans une autre.",
      "author": "Paul Eluard",
      "sourcePage": 48
    },
    {
      "id": 2243,
      "text": "Avec du temps et de la patience, les feuilles de mûrier se transforment en robe de soie.",
      "author": "Proverbe chinois",
      "sourcePage": 48
    },
    {
      "id": 2244,
      "text": "L’éducation nous apprend les règles de la vie. L’expérience nous apprend les exceptions.",
      "author": "Mina Guillois : \"A l’école du rire\"",
      "sourcePage": 48
    },
    {
      "id": 2245,
      "text": "Les hommes naissent égaux, dès le lendemain, ils ne le sont plus.",
      "author": "Jules Renard, extrait de son \"Journal 1905 - 1910\"",
      "sourcePage": 48
    },
    {
      "id": 2246,
      "text": "La douleur est toujours moins forte que la plainte.",
      "author": "Jean de La Fontaine : \"La matrone d’Ephèse\"",
      "sourcePage": 48
    },
    {
      "id": 2247,
      "text": "Nos bonnes actions sont souvent plus troubles que nos péchés.",
      "author": "Marcel Aymé : \"Vogue la galère\"",
      "sourcePage": 48
    },
    {
      "id": 2248,
      "text": "Les jours sont peut-être égaux pour une horloge, mais pas pour un homme.",
      "author": "Marcel Proust, extrait des \"Chroniques\"",
      "sourcePage": 48
    },
    {
      "id": 2249,
      "text": "Les plus jolies choses du monde ne sont que des ombres.",
      "author": "Charles Dickens",
      "sourcePage": 48
    },
    {
      "id": 2250,
      "text": "Ce qui constitue l'essence d'être un être humain, c'est de ne pas rechercher la perfection.",
      "author": "George Orwell",
      "sourcePage": 48
    },
    {
      "id": 2251,
      "text": "Il faut avoir bien du jugement pour sentir que nous n'en avons point.",
      "author": "Pierre Carlet de Chamblain de Marivaux : \"L'île de la raison\"",
      "sourcePage": 48
    },
    {
      "id": 2252,
      "text": "L’art, mes enfants, c’est d’être absolument soi-même.",
      "author": "Paul Verlaine",
      "sourcePage": 48
    },
    {
      "id": 2253,
      "text": "Vivre, c’est changer du temps en expérience.",
      "author": "Caleb Gattegno",
      "sourcePage": 48
    },
    {
      "id": 2254,
      "text": "La vie est perdue contre la mort, mais la mémoire gagne dans son combat contre le néant.",
      "author": "Tzvetan Todorov : \"Les abus de la mémoire\"",
      "sourcePage": 48
    },
    {
      "id": 2255,
      "text": "Sans la parole, le plaisir de l'amour diminue au moins de deux tiers.",
      "author": "Giovanni Casanova : \"Histoire de ma vie\"",
      "sourcePage": 48
    },
    {
      "id": 2256,
      "text": "La réalité n’est qu’un point de vue.",
      "author": "Philip K. Dick",
      "sourcePage": 48
    },
    {
      "id": 2257,
      "text": "L’écriture et l’amour procèdent de la même tension, de la même joie, de la même perdition.",
      "author": "Nina Bouraoui : \"Poupée Bella\"",
      "sourcePage": 48
    },
    {
      "id": 2258,
      "text": "Celui qui plante la vertu ne doit pas oublier de l'arroser souvent.",
      "author": "Confucius : \"Chou-King\"",
      "sourcePage": 48
    },
    {
      "id": 2259,
      "text": "A trop s’accrocher au superflu, le nécessaire fait défaut.",
      "author": "Jean Guilaine : \"Pourquoi j’ai construit une maison carrée\"",
      "sourcePage": 48
    },
    {
      "id": 2260,
      "text": "Si vous voulez vraiment rêver, réveillez-vous...",
      "author": "Daniel Pennac : \"Au bonheur des ogres\"",
      "sourcePage": 48
    },
    {
      "id": 2261,
      "text": "Les performances individuelles, ce n’est pas le plus important. On gagne et on perd en équipe.",
      "author": "Zinédine Zidane, extrait d’un article sur \"Sport24.com - 18 Novembre 2001\"",
      "sourcePage": 48
    },
    {
      "id": 2262,
      "text": "Il ne faut pas toujours avoir raison pour plaire.",
      "author": "Charles Joseph : \"Prince de Ligne\"",
      "sourcePage": 48
    },
    {
      "id": 2263,
      "text": "Les fous ouvrent des voies qu’empruntent ensuite les sages.",
      "author": "Carlo Dossi, extrait des \"Notes d’azur\"",
      "sourcePage": 48
    },
    {
      "id": 2264,
      "text": "La chance d'avoir du talent ne suffit pas ; il faut encore le talent d'avoir de la chance.",
      "author": "Hector Berlioz",
      "sourcePage": 48
    },
    {
      "id": 2265,
      "text": "Il n'est pire servitude que l'espoir d'être heureux.",
      "author": "Carlos Fuentes : \"Diane ou La chasseresse solitaire\"",
      "sourcePage": 48
    },
    {
      "id": 2266,
      "text": "Rêve de grandes choses : cela te permettra d'en faire au moins de toutes petites.",
      "author": "Jules Renard, extrait de son \"Journal\"",
      "sourcePage": 48
    },
    {
      "id": 2267,
      "text": "Le silence est l'élément dans lequel se façonnent les grandes choses.",
      "author": "Thomas Carlyle : \"Sartor Resartus\"",
      "sourcePage": 48
    },
    {
      "id": 2268,
      "text": "Ne pas se rendre au théâtre, c'est comme faire sa toilette sans miroir.",
      "author": "Arthur Schopenhauer, extrait des \"Observations psychologiques\"",
      "sourcePage": 48
    },
    {
      "id": 2269,
      "text": "Les grandes œuvres sont celles qui réveillent notre génie.",
      "author": "Louis-Ferdinand Céline : \"Semmelweis\"",
      "sourcePage": 48
    },
    {
      "id": 2270,
      "text": "Rêver pour vous réveiller ! De rêveurs vous deviendrez des éveilleurs !",
      "author": "Gitta Mallasz",
      "sourcePage": 48
    },
    {
      "id": 2271,
      "text": "Avoir conscience qu'on fait une bêtise et la faire tout de même, c'est une volupté !",
      "author": "André Birabeau",
      "sourcePage": 48
    },
    {
      "id": 2272,
      "text": "Le plus beau sommeil ne vaut pas le moment où l'on se réveille.",
      "author": "André Gide",
      "sourcePage": 48
    },
    {
      "id": 2273,
      "text": "L’art ne veut pas la représentation d’une chose belle mais la belle représentation d’une chose.",
      "author": "Emmanuel Kant, extrait de la \"Critique du jugement\"",
      "sourcePage": 48
    },
    {
      "id": 2274,
      "text": "La liberté, c'est de pouvoir choisir celui dont on sera l'esclave.",
      "author": "Jeanne Moreau",
      "sourcePage": 48
    },
    {
      "id": 2275,
      "text": "L'art de savoir ne rien faire est une discipline extrêmement laborieuse.",
      "author": "Pierre Léger, extrait d’ \"Embarke mon amour, c'est pas une joke\"",
      "sourcePage": 48
    },
    {
      "id": 2276,
      "text": "Les hommes sont comme les animaux : les gros mangent les petits et les petits les piquent.",
      "author": "Voltaire",
      "sourcePage": 49
    },
    {
      "id": 2277,
      "text": "Laissez-vous entraîner par le courant de la vie... sans arme ni bagage.",
      "author": "Anthony de Mello : \"Sans arme ni bagage\"",
      "sourcePage": 49
    },
    {
      "id": 2278,
      "text": "Il ne faut pas laisser croître l’herbe sur le chemin de l’amitié.",
      "author": "Proverbe français",
      "sourcePage": 49
    },
    {
      "id": 2279,
      "text": "L’art de la vie publique, c’est de savoir exactement où il faut s’arrêter, et d’aller un peu plus loin.",
      "author": "Saki : \"L’Insupportable Bassington\"",
      "sourcePage": 49
    },
    {
      "id": 2280,
      "text": "Le sang noble est un accident de la fortune, les actions nobles caractérisent les grands.",
      "author": "Carlo Goldoni : \"Paméla\"",
      "sourcePage": 49
    },
    {
      "id": 2281,
      "text": "Conquérir sa joie vaut mieux que de s’abandonner à sa tristesse.",
      "author": "André Gide : \"Journal 1889-1939\"",
      "sourcePage": 49
    },
    {
      "id": 2282,
      "text": "Le faire est révélateur de l'être.",
      "author": "Jean-Paul Sartre",
      "sourcePage": 49
    },
    {
      "id": 2283,
      "text": "La terre est devenue trop petite pour la méchanceté des hommes.",
      "author": "Maurice Chapelan, extrait d' \"Amours, amour\"",
      "sourcePage": 49
    },
    {
      "id": 2284,
      "text": "C'est à partir de toi que j'ai dit oui au monde.",
      "author": "Paul Eluard",
      "sourcePage": 49
    },
    {
      "id": 2285,
      "text": "Qui veut faire quelque chose trouve un moyen, qui ne veut rien faire trouve une excuse.",
      "author": "Proverbe arabe",
      "sourcePage": 49
    },
    {
      "id": 2286,
      "text": "Si tu pleures de joie, ne sèche pas tes larmes : tu les voles à la douleur.",
      "author": "Paul-Jean Toulet : \"Les trois impostures\"",
      "sourcePage": 49
    },
    {
      "id": 2287,
      "text": "L’éternité, c’est long, surtout vers la fin.",
      "author": "Woody Allen",
      "sourcePage": 49
    },
    {
      "id": 2288,
      "text": "Les hommes croient ce qu'ils désirent.",
      "author": "Jules César",
      "sourcePage": 49
    },
    {
      "id": 2289,
      "text": "Le bonheur est une petite chose que l'on grignote, assis par terre, au soleil.",
      "author": "Jean Giraudoux",
      "sourcePage": 49
    },
    {
      "id": 2290,
      "text": "Echouer, c'est avoir la possibilité de recommencer de manière plus intelligente.",
      "author": "Henry Ford",
      "sourcePage": 49
    },
    {
      "id": 2291,
      "text": "Il faut, de temps en temps, se conduire comme des enfants : ça n'empêche pas de vieillir.",
      "author": "Francis Blanche",
      "sourcePage": 49
    },
    {
      "id": 2292,
      "text": "Vivre c'est inventer.",
      "author": "Maurice Blanchard : \"Journal de poètes\"",
      "sourcePage": 49
    },
    {
      "id": 2293,
      "text": "L’imagination vaut bien des voyages et elle coûte moins cher.",
      "author": "George William Curtis, extrait des \"Aphorismes\"",
      "sourcePage": 49
    },
    {
      "id": 2294,
      "text": "La connaissance parle, mais la sagesse écoute.",
      "author": "Jimi Hendrix",
      "sourcePage": 49
    },
    {
      "id": 2295,
      "text": "Les plus belles choses de ce monde sont les plus inutiles : par exemple les paons et les lys.",
      "author": "John Ruskin : \"Les Pierres de Venise\"",
      "sourcePage": 49
    },
    {
      "id": 2296,
      "text": "La peur a détruit plus de choses en ce monde que la joie n’en a créées.",
      "author": "Paul Morand : \"Eloge du repos\"",
      "sourcePage": 49
    },
    {
      "id": 2297,
      "text": "Réfléchis avec lenteur, mais exécute rapidement tes décisions.",
      "author": "Isocrate, extrait d’ \"A Démonicos\"",
      "sourcePage": 49
    },
    {
      "id": 2298,
      "text": "De l’éducation de son peuple dépend le destin d’un pays.",
      "author": "Benjamin Disraeli",
      "sourcePage": 49
    },
    {
      "id": 2299,
      "text": "Changer de souci fait autant de bien que prendre des vacances.",
      "author": "David Lloyd George",
      "sourcePage": 49
    },
    {
      "id": 2300,
      "text": "Les enfants sont à ceux qui les rendent meilleurs.",
      "author": "Massa Makan Diabaté : \"Le Lieutenant de Kouta\"",
      "sourcePage": 49
    },
    {
      "id": 2301,
      "text": "Ayez surtout le souci de séparer les choses du bruit qu'elles font.",
      "author": "Sénèque",
      "sourcePage": 49
    },
    {
      "id": 2302,
      "text": "N’oublions pas que les enfants suivent les exemples mieux qu’ils n’écoutent les conseils.",
      "author": "Roy Lemon Smith",
      "sourcePage": 49
    },
    {
      "id": 2303,
      "text": "Chose que l'on dédaigne vaut bien mieux qu'on ne le croit.",
      "author": "Chrétien de Troyes",
      "sourcePage": 49
    },
    {
      "id": 2304,
      "text": "Le temps de l’âme échappe à celui du corps, même si l’esprit s’ingénie à les concilier.",
      "author": "Henry Bonnier : \"Les Amants de Bruges\"",
      "sourcePage": 49
    },
    {
      "id": 2305,
      "text": "La différence est une beauté qu’il faut apprendre à voir.",
      "author": "Ingrid Naour : \"Un fils dans la tête\"",
      "sourcePage": 49
    },
    {
      "id": 2306,
      "text": "Les rêves sont la littérature du sommeil.",
      "author": "Jean Cocteau : \"Le Mystère laïc\"",
      "sourcePage": 49
    },
    {
      "id": 2307,
      "text": "La décision est souvent l’art d’être cruel à temps.",
      "author": "Henry Becque",
      "sourcePage": 49
    },
    {
      "id": 2308,
      "text": "Il n’y a point de forêt sans arbres tordus.",
      "author": "Proverbe bulgare",
      "sourcePage": 49
    },
    {
      "id": 2309,
      "text": "Chaque être naît seul, à son jour, à son heure, et vient au monde les mains vides.",
      "author": "Paulina Chiziane : \"Le Parlement conjugal\"",
      "sourcePage": 49
    },
    {
      "id": 2310,
      "text": "A tout repas, la faim est la meilleure et la plus piquante des sauces.",
      "author": "Chrétien de Troyes",
      "sourcePage": 49
    },
    {
      "id": 2311,
      "text": "On n’est jamais si heureux que quand on a trouvé le moyen de se perdre.",
      "author": "Amélie Nothomb : \"Journal d’hirondelle\"",
      "sourcePage": 49
    },
    {
      "id": 2312,
      "text": "Le meilleur et le pire ne sont que le recto et le verso du même.",
      "author": "Christiane Singer : \"Seul ce qui brûle\"",
      "sourcePage": 49
    },
    {
      "id": 2313,
      "text": "Un maître est en lui-même un enseignement : chacun de ses gestes, de ses regards est une leçon.",
      "author": "Mark Fisher : \"Le millionnaire\"",
      "sourcePage": 49
    },
    {
      "id": 2314,
      "text": "Les grandes personnes ne sont que des enfants déguisés.",
      "author": "Pierre Daninos : \"Vacances à tous prix\"",
      "sourcePage": 49
    },
    {
      "id": 2315,
      "text": "Commettre au moins une folie par an pour ne pas devenir fou.",
      "author": "Vicente Huidobro, extrait d’ \"Altazor\"",
      "sourcePage": 49
    },
    {
      "id": 2316,
      "text": "Au bout de la patience, il y a le ciel.",
      "author": "Proverbe africain",
      "sourcePage": 49
    },
    {
      "id": 2317,
      "text": "Tout âge porte ses fruits, il faut savoir les cueillir.",
      "author": "Raymond Radiguet : \"Le bal du comte d’Orgel\"",
      "sourcePage": 50
    },
    {
      "id": 2318,
      "text": "La blessure cicatrisée, on oublie la douleur.",
      "author": "Proverbe chinois",
      "sourcePage": 50
    },
    {
      "id": 2319,
      "text": "L’erreur est humaine, le pardon divin.",
      "author": "Alexander Pope : \"Essai sur la critique\"",
      "sourcePage": 50
    },
    {
      "id": 2320,
      "text": "Chaque pomme est une fleur qui a connu l'amour.",
      "author": "Félix Leclerc : \"Le calepin d'un flâneur\"",
      "sourcePage": 50
    },
    {
      "id": 2321,
      "text": "L’amitié est l’amour sans ailes.",
      "author": "George Gordon, Lord Byron",
      "sourcePage": 50
    },
    {
      "id": 2322,
      "text": "Le voyage est un retour vers l'essentiel.",
      "author": "Proverbe tibétain",
      "sourcePage": 50
    },
    {
      "id": 2323,
      "text": "Les conseils de la vieillesse éclairent sans réchauffer comme le soleil d'hiver.",
      "author": "Vauvenargues : \"Réflexions et maximes\"",
      "sourcePage": 50
    },
    {
      "id": 2324,
      "text": "Si vous aimez la vie, elle vous aimera en retour.",
      "author": "Arthur Rubinstein",
      "sourcePage": 50
    },
    {
      "id": 2325,
      "text": "Si l'homme des cavernes avait su rire, le cours de l'histoire eut été changé.",
      "author": "Oscar Wilde",
      "sourcePage": 50
    },
    {
      "id": 2326,
      "text": "On ne peut être heureux si l’on ne désire rien.",
      "author": "Henri Laborit, extrait de l' \"Eloge de la fuite\"",
      "sourcePage": 50
    },
    {
      "id": 2327,
      "text": "L’amour est un rêve pour deux.",
      "author": "Björk : Paroles de la chanson \"Bachelorette\"",
      "sourcePage": 50
    },
    {
      "id": 2328,
      "text": "Les corps sont étranges. Ce qui est à l’extérieur ne correspond pas toujours à ce qu’il y a à l’intérieur.",
      "author": "Kitty Fitzgerald : \"Le Palais des cochons\"",
      "sourcePage": 50
    },
    {
      "id": 2329,
      "text": "Mieux vaut vivre un jour comme un lion que cent ans comme un mouton.",
      "author": "Proverbe italien",
      "sourcePage": 50
    },
    {
      "id": 2330,
      "text": "Il est plus nécessaire d’étudier les hommes que les livres.",
      "author": "François de La Rochefoucauld : \"Maximes\"",
      "sourcePage": 50
    },
    {
      "id": 2331,
      "text": "S'éloigner de tout rapproche un peu de l'essentiel.",
      "author": "Loïck Peyron, extrait du magazine \"Marie-Claire - Avril 2000\"",
      "sourcePage": 50
    },
    {
      "id": 2332,
      "text": "L'esprit c'est comme un parachute : s'il reste fermé, on s'écrase.",
      "author": "Frank Zappa",
      "sourcePage": 50
    },
    {
      "id": 2333,
      "text": "Le silence de la nuit est le lac le plus profond de la terre.",
      "author": "Dominique Rolin",
      "sourcePage": 50
    },
    {
      "id": 2334,
      "text": "Le baiser est la plus sûre façon de se taire en disant tout.",
      "author": "Guy de Maupassant",
      "sourcePage": 50
    },
    {
      "id": 2335,
      "text": "La connaissance de la vie est comme le sable : elle ne salit pas.",
      "author": "Elsa Triolet : \"Luna-Park\"",
      "sourcePage": 50
    },
    {
      "id": 2336,
      "text": "Le malheur peut être un pas vers le bonheur.",
      "author": "Proverbe japonais",
      "sourcePage": 50
    },
    {
      "id": 2337,
      "text": "L'oreille est le chemin du cœur.",
      "author": "Voltaire",
      "sourcePage": 50
    },
    {
      "id": 2338,
      "text": "Les dieux jettent les dés et ne demandent pas si nous avons envie de jouer.",
      "author": "Paulo Coelho : \"Sur le bord de la rivière Piedra je me suis assise et j'ai pleuré\"",
      "sourcePage": 50
    },
    {
      "id": 2339,
      "text": "Au-dessus des nuages, il y a toujours du soleil.",
      "author": "Pierre Dudan : \"Les Cent pas dans ma tête\"",
      "sourcePage": 50
    },
    {
      "id": 2340,
      "text": "Même pour jouer son propre rôle, il faut se maquiller.",
      "author": "Stanislaw Jerzy Lec, extrait des \"Nouvelles Pensées échevelées\"",
      "sourcePage": 50
    },
    {
      "id": 2341,
      "text": "Qui vit sans folie n’est pas si sage qu’on croit.",
      "author": "François de La Rochefoucauld : \"Maximes\"",
      "sourcePage": 50
    },
    {
      "id": 2342,
      "text": "Il y a de l’or dans l’erreur.",
      "author": "Mathieu Chedid : \"Qui de nous deux\"",
      "sourcePage": 50
    },
    {
      "id": 2343,
      "text": "Au royaume de l’espoir, il n’y a pas d’hiver.",
      "author": "Proverbe russe",
      "sourcePage": 50
    },
    {
      "id": 2344,
      "text": "On peut aussi bâtir quelque chose de beau avec les pierres qui entravent le chemin.",
      "author": "Johann Wolfgang von Goethe",
      "sourcePage": 50
    },
    {
      "id": 2345,
      "text": "La chance est un hasard, le bonheur une vocation.",
      "author": "Alexandru Vlahuta, extrait des \"Pensées\"",
      "sourcePage": 50
    },
    {
      "id": 2346,
      "text": "Ce qui ne peut être évité, il faut l'embrasser.",
      "author": "William Shakespeare",
      "sourcePage": 50
    },
    {
      "id": 2347,
      "text": "Le silence est pour les oreilles ce que la nuit est pour les yeux.",
      "author": "Pascal Quignard : \"La Haine de la musique\"",
      "sourcePage": 50
    },
    {
      "id": 2348,
      "text": "L’amour est aveugle et sa canne est rose.",
      "author": "Serge Gainsbourg",
      "sourcePage": 50
    },
    {
      "id": 2349,
      "text": "On se sert des couleurs, mais on peint avec le sentiment.",
      "author": "Jean Chardin",
      "sourcePage": 50
    },
    {
      "id": 2350,
      "text": "Nous devons dormir pour donner assez de place au rêve.",
      "author": "Erik Orsenna : \"Les Chevaliers du subjonctif\"",
      "sourcePage": 50
    },
    {
      "id": 2351,
      "text": "Les âmes se rencontrent sur les lèvres des amants.",
      "author": "Percy Bysshe Shelley",
      "sourcePage": 50
    },
    {
      "id": 2352,
      "text": "Etre écrivain, c’est errer dans l’espace avec un crayon.",
      "author": "Pascal Quignard, extrait de la série documentaire TV \"A Mi-mots\"",
      "sourcePage": 50
    },
    {
      "id": 2353,
      "text": "L’échec est l’épice qui donne sa saveur au succès.",
      "author": "Truman Capote",
      "sourcePage": 50
    },
    {
      "id": 2354,
      "text": "La musique commence là où s'arrête le pouvoir des mots.",
      "author": "Richard Wagner",
      "sourcePage": 50
    },
    {
      "id": 2355,
      "text": "En fuyant la pluie, on rencontre la grêle.",
      "author": "Proverbe turc",
      "sourcePage": 50
    },
    {
      "id": 2356,
      "text": "Me réveiller chaque jour et jouer de mon mieux les cartes qui m’ont été distribuées.",
      "author": "Rebecca Wells",
      "sourcePage": 50
    },
    {
      "id": 2357,
      "text": "Le cœur perçoit ce que l'œil ne voit pas.",
      "author": "Al-Gazal",
      "sourcePage": 50
    },
    {
      "id": 2358,
      "text": "La femme est la poésie, l'homme la prose.",
      "author": "Alphonse Toussenel",
      "sourcePage": 50
    },
    {
      "id": 2359,
      "text": "Un sourire est une clef secrète qui ouvre bien des cœurs.",
      "author": "Baden-Powell",
      "sourcePage": 50
    },
    {
      "id": 2360,
      "text": "La perfection est un chemin, non une fin.",
      "author": "Proverbe coréen",
      "sourcePage": 50
    },
    {
      "id": 2361,
      "text": "Celui qui n'ose pas regarder le soleil en face ne sera jamais une étoile.",
      "author": "William Blake",
      "sourcePage": 50
    },
    {
      "id": 2362,
      "text": "Il faut jouer pour devenir sérieux.",
      "author": "Aristote",
      "sourcePage": 50
    },
    {
      "id": 2363,
      "text": "Il faut s'endurcir, sans jamais se départir de sa tendresse.",
      "author": "Ernesto \"Che\" Guevara",
      "sourcePage": 50
    },
    {
      "id": 2364,
      "text": "Nous avons besoin d’hommes qui sachent rêver à des choses inédites.",
      "author": "John Fitzgerald Kennedy, extrait d'un discours à \"Dublin - 28 Juin 1963\"",
      "sourcePage": 50
    },
    {
      "id": 2365,
      "text": "Le plaisir est le bonheur des fous, le bonheur est le plaisir des sages.",
      "author": "Jules Barbey d’Aurevilly",
      "sourcePage": 50
    },
    {
      "id": 2366,
      "text": "La beauté n'est qu'un piège tendu par la nature à la raison.",
      "author": "Voltaire",
      "sourcePage": 50
    },
    {
      "id": 2367,
      "text": "Quand le soleil s'éclipse on en voit la grandeur.",
      "author": "Sénèque",
      "sourcePage": 51
    },
    {
      "id": 2368,
      "text": "Rêve ta vie en couleur, c'est le secret du bonheur.",
      "author": "Walt Disney",
      "sourcePage": 51
    },
    {
      "id": 2369,
      "text": "Le vase donne une forme au vide, et la musique au silence.",
      "author": "Georges Braque : \"Le Jour et la nuit\"",
      "sourcePage": 51
    },
    {
      "id": 2370,
      "text": "Si le problème a une solution, il ne sert à rien de s'inquiéter. Mais s'il n'en a pas, alors s'inquiéter ne change rien.",
      "author": "Proverbe tibétain",
      "sourcePage": 51
    },
    {
      "id": 2371,
      "text": "Il y a des fleurs partout pour qui veut bien les voir.",
      "author": "Henri Matisse",
      "sourcePage": 51
    },
    {
      "id": 2372,
      "text": "Aucun chemin de fleurs ne conduit à la gloire.",
      "author": "Jean de La Fontaine : \"Les Deux Aventuriers et le talisman\"",
      "sourcePage": 51
    },
    {
      "id": 2373,
      "text": "Imaginer, c'est hausser le réel d'un ton.",
      "author": "Gaston Bachelard : \"L'Air et les songes\"",
      "sourcePage": 51
    },
    {
      "id": 2374,
      "text": "Tant que le cœur conserve des souvenirs, l'esprit garde des illusions.",
      "author": "François René de Chateaubriand",
      "sourcePage": 51
    },
    {
      "id": 2375,
      "text": "Le feu qui semble éteint souvent dort sous la cendre.",
      "author": "Pierre Corneille",
      "sourcePage": 51
    },
    {
      "id": 2376,
      "text": "Le moment donné par le hasard vaut mieux que le moment choisi.",
      "author": "Proverbe chinois",
      "sourcePage": 51
    },
    {
      "id": 2377,
      "text": "Rien de grand ne se fait sans chimères.",
      "author": "Ernest Renan : \"L'Avenir de la science\"",
      "sourcePage": 51
    },
    {
      "id": 2378,
      "text": "Se passionner pour tout et ne tenir à rien.",
      "author": "Jean-Louis Barrault",
      "sourcePage": 51
    },
    {
      "id": 2379,
      "text": "Même quand l'oiseau marche on sent qu'il a des ailes.",
      "author": "Antoine-Marin Lemierre : \"Fragments du poème des fastes\"",
      "sourcePage": 51
    },
    {
      "id": 2380,
      "text": "L'obstacle nous fait grands.",
      "author": "André Chénier : \"Le Jeu de paume\"",
      "sourcePage": 51
    },
    {
      "id": 2381,
      "text": "Le souvenir est le parfum de l'âme.",
      "author": "George Sand",
      "sourcePage": 51
    },
    {
      "id": 2382,
      "text": "Les belles nuits font les beaux jours !",
      "author": "Eugène Scribe : \"Le Domino noir\"",
      "sourcePage": 51
    },
    {
      "id": 2383,
      "text": "L'homme est une prison où l'âme reste libre.",
      "author": "Victor Hugo : \"Les Contemplations\"",
      "sourcePage": 51
    },
    {
      "id": 2384,
      "text": "La culture c’est ce qui fait l’humain.",
      "author": "Monica Bellucci",
      "sourcePage": 51
    },
    {
      "id": 2385,
      "text": "Sous le mot prudence, il y a le rire des dieux.",
      "author": "Pierre Albert Jourdan, extrait des \"Fragments\"",
      "sourcePage": 51
    },
    {
      "id": 2386,
      "text": "Le sourire est le baiser de l'âme.",
      "author": "Michel Bouthot : \"Chemins parsemés d'immortelles pensées\"",
      "sourcePage": 51
    },
    {
      "id": 2387,
      "text": "C'est l'incertitude qui nous charme. Tout devient merveilleux dans la brume.",
      "author": "Oscar Wilde : \"Le Portrait de Dorian Gray\"",
      "sourcePage": 51
    },
    {
      "id": 2388,
      "text": "Les mots sans les pensées ne vont jamais au ciel.",
      "author": "William Shakespeare : \"Hamlet\"",
      "sourcePage": 51
    },
    {
      "id": 2389,
      "text": "Les projets sont les promesses que l'imagination fait au cœur.",
      "author": "Jean-Louis Vaudoyer",
      "sourcePage": 51
    },
    {
      "id": 2390,
      "text": "La terre est ronde pour ceux qui s'aiment.",
      "author": "Jean Giraudoux : \"Electre\"",
      "sourcePage": 51
    },
    {
      "id": 2391,
      "text": "Un secret a toujours la forme d'une oreille.",
      "author": "Jean Cocteau : \"Le Rappel à l'ordre\"",
      "sourcePage": 51
    },
    {
      "id": 2392,
      "text": "L'amitié est une âme en deux corps.",
      "author": "Aristote : \"Ethique à Nicomaque\"",
      "sourcePage": 51
    },
    {
      "id": 2393,
      "text": "Rien ne sèche plus vite qu’une larme.",
      "author": "Apollonios de Rhodes : \"Les Argonautiques\"",
      "sourcePage": 51
    },
    {
      "id": 2394,
      "text": "Le visage est le miroir du cœur.",
      "author": "Proverbe français",
      "sourcePage": 51
    },
    {
      "id": 2395,
      "text": "Peu importe ce qu’on pourra vous dire, les mots et les idées peuvent changer le monde.",
      "author": "Peter Weir, dialogue du film américain \"Le Cercle des poètes disparus\"",
      "sourcePage": 51
    },
    {
      "id": 2396,
      "text": "Le mystère est le meilleur artisan du merveilleux.",
      "author": "Ursula Le Guin : \"La Main gauche de la nuit\"",
      "sourcePage": 51
    },
    {
      "id": 2397,
      "text": "Il est d'étranges soirs où les fleurs ont une âme.",
      "author": "Albert Samain, extrait d’\"Au Jardin de l'infante\"",
      "sourcePage": 51
    },
    {
      "id": 2398,
      "text": "Personne ne peut fuir son cœur. C'est pourquoi il vaut mieux écouter ce qu'il dit.",
      "author": "Paulo Coelho : \"L’Alchimiste\"",
      "sourcePage": 51
    },
    {
      "id": 2399,
      "text": "Qu’importe de quoi parlent les lèvres, lorsqu’on écoute les cœurs se répondre.",
      "author": "Alfred de Musset : \"La Confession d’un enfant du siècle\"",
      "sourcePage": 51
    },
    {
      "id": 2400,
      "text": "Chaque homme doit inventer son chemin.",
      "author": "Jean-Paul Sartre : \"Les Mouches\"",
      "sourcePage": 51
    },
    {
      "id": 2401,
      "text": "La connaissance seule ne suffit pas ; elle n'a pas de cœur.",
      "author": "Dan Millman : \"Le Guerrier pacifique\"",
      "sourcePage": 51
    },
    {
      "id": 2402,
      "text": "L'écriture a ceci de mystérieux qu'elle parle.",
      "author": "Paul Claudel : \"Connaissance de l'Est\"",
      "sourcePage": 51
    },
    {
      "id": 2403,
      "text": "Que sait du désert celui qui ne regarde qu'un grain de sable ?",
      "author": "Erik Orsenna : \"Madame Bâ\"",
      "sourcePage": 51
    },
    {
      "id": 2404,
      "text": "Ce qui est beau, c'est ce qu'on aime.",
      "author": "Jean Anouilh : \"Colombe\"",
      "sourcePage": 51
    },
    {
      "id": 2405,
      "text": "N'est vaincu que celui qui croit l'être.",
      "author": "Fernando de Rojas : \"La Célestine\"",
      "sourcePage": 51
    },
    {
      "id": 2406,
      "text": "Seul un regard peut créer l'univers.",
      "author": "Christian Morgenstern : \"Borne kilométrique\"",
      "sourcePage": 51
    },
    {
      "id": 2407,
      "text": "La seule amitié qui vaille est celle qui naît sans raison.",
      "author": "Arthur Van Schendel : \"Un Vagabond amoureux\"",
      "sourcePage": 51
    },
    {
      "id": 2408,
      "text": "Le monde est un livre et ceux qui ne voyagent pas n’en lisent qu’une page.",
      "author": "Saint Augustin",
      "sourcePage": 51
    },
    {
      "id": 2409,
      "text": "Rien n’est réel sauf le hasard.",
      "author": "Paul Auster : \"Cité de verre\"",
      "sourcePage": 51
    },
    {
      "id": 2410,
      "text": "Le cœur fait tout, le reste est inutile.",
      "author": "Jean de La Fontaine : \"Belphégor\"",
      "sourcePage": 51
    },
    {
      "id": 2411,
      "text": "L'âme a des illusions comme l'oiseau a des ailes ; c'est ce qui la soutient.",
      "author": "Victor Hugo",
      "sourcePage": 51
    },
    {
      "id": 2412,
      "text": "Sans la musique, la vie serait une erreur.",
      "author": "Friedrich Nietzsche : \"Le Crépuscule des idoles\"",
      "sourcePage": 51
    },
    {
      "id": 2413,
      "text": "L'amour est immense, il n'est pas infini.",
      "author": "Etienne de Senancour, extrait d' \"Oberman\"",
      "sourcePage": 51
    },
    {
      "id": 2414,
      "text": "Dans un voyage, le plus long est d'arriver à la porte.",
      "author": "Varron",
      "sourcePage": 51
    },
    {
      "id": 2415,
      "text": "La vie est un ballet ; on ne le danse qu’une fois.",
      "author": "Proverbe malinké",
      "sourcePage": 51
    },
    {
      "id": 2416,
      "text": "Le bonheur est un ange au visage grave.",
      "author": "Amedeo Modigliani",
      "sourcePage": 51
    },
    {
      "id": 2417,
      "text": "Il y a des étoiles mortes qui brillent encore parce que leur éclat est pris au piège du temps.",
      "author": "Don Delillo : \"Cosmopolis\"",
      "sourcePage": 51
    },
    {
      "id": 2418,
      "text": "Ne crois pas que tu t’es trompé de route quand tu n’es pas allé assez loin.",
      "author": "Claude Aveline : \"Avec toi-même\"",
      "sourcePage": 52
    },
    {
      "id": 2419,
      "text": "Si les anges volent, c'est parce qu'ils se prennent eux-mêmes à la légère.",
      "author": "Gilbert Keith Chesterton",
      "sourcePage": 52
    },
    {
      "id": 2420,
      "text": "Le hasard sait toujours trouver ceux qui savent s'en servir.",
      "author": "Romain Rolland : \"Jean-Christophe\"",
      "sourcePage": 52
    },
    {
      "id": 2421,
      "text": "La plus grande chute est celle qu’on fait du haut de l’innocence.",
      "author": "Heiner Müller, cité dans le livre de \"Nous sommes cruels\"",
      "sourcePage": 52
    },
    {
      "id": 2422,
      "text": "Le voyage est court. Essayons de le faire en première classe.",
      "author": "Philippe Noiret",
      "sourcePage": 52
    },
    {
      "id": 2423,
      "text": "La beauté n’est pas dans les choses, elle est dans nos yeux.",
      "author": "Bernard Noël : \"Le Nu\"",
      "sourcePage": 52
    },
    {
      "id": 2424,
      "text": "Devenir adulte, c'est reconnaître, sans trop souffrir, que le \"Père Noël\" n'existe pas.",
      "author": "Hubert Reeves : \"L'Espace prend la forme de mon regard\"",
      "sourcePage": 52
    },
    {
      "id": 2425,
      "text": "Sans les cadeaux, Noël ne serait pas Noël.",
      "author": "Louisa May Alcott : \"Little Women\"",
      "sourcePage": 52
    },
    {
      "id": 2426,
      "text": "La littérature est la preuve que la vie ne suffit pas.",
      "author": "Fernando Pessoa",
      "sourcePage": 52
    },
    {
      "id": 2427,
      "text": "L’amour a son instinct, il sait trouver le chemin du cœur.",
      "author": "Honoré de Balzac",
      "sourcePage": 52
    },
    {
      "id": 2428,
      "text": "Le monde est plein de mystères, et il n’est pas nécessaire que nous les percions tous.",
      "author": "Rachid El- Daïf : \"Fais voir tes jambes, Leïla !\"",
      "sourcePage": 52
    },
    {
      "id": 2429,
      "text": "Quand on sait entendre, on parle toujours bien.",
      "author": "Molière : \"Les Femmes savantes\"",
      "sourcePage": 52
    },
    {
      "id": 2430,
      "text": "La possibilité de vivre commence dans le regard de l’autre.",
      "author": "Michel Houellebecq : \"Les Particules élémentaires\"",
      "sourcePage": 52
    },
    {
      "id": 2431,
      "text": "Demain du ventre du temps surgira une année nouvelle.",
      "author": "Njabulo S. Ndebele : \"Portrait de l'amour\"",
      "sourcePage": 52
    },
    {
      "id": 2432,
      "text": "Il est aussi absurde de regretter le passé que d’organiser l’avenir.",
      "author": "Roman Polanski : \"Roman\"",
      "sourcePage": 52
    },
    {
      "id": 2433,
      "text": "La vérité est comme le soleil. Elle fait tout voir et ne se laisse pas regarder.",
      "author": "Victor Hugo : \"Tas de pierres\"",
      "sourcePage": 52
    },
    {
      "id": 2434,
      "text": "La vie est comme un instrument de musique ; il faut la tendre et la relâcher, pour la rendre agréable.",
      "author": "Démophile",
      "sourcePage": 52
    },
    {
      "id": 2435,
      "text": "Un maître n’est pas celui qui sans cesse enseigne, mais celui qui soudain apprend.",
      "author": "Joao Guimaraes Rosa : \"Diadorim\"",
      "sourcePage": 52
    },
    {
      "id": 2436,
      "text": "La vie c'est ça, un bout de lumière qui finit dans la nuit.",
      "author": "Louis-Ferdinand Céline, extrait du \"Voyage au bout de la nuit\"",
      "sourcePage": 52
    },
    {
      "id": 2437,
      "text": "La mesure de l'amour, c'est d'aimer sans mesure.",
      "author": "Saint Augustin, extrait d’un \"Sermon\"",
      "sourcePage": 52
    },
    {
      "id": 2438,
      "text": "Les fleurs du printemps sont les rêves de l'hiver racontés, le matin, à la table des anges.",
      "author": "Khalil Gibran",
      "sourcePage": 52
    },
    {
      "id": 2439,
      "text": "Chaque jour il faut danser, fût-ce seulement par la pensée.",
      "author": "Nahman de Braslaw",
      "sourcePage": 52
    },
    {
      "id": 2440,
      "text": "L’oiseau a son nid, l’araignée sa toile, et l’homme l’amitié.",
      "author": "William Blake : \"Le Mariage du Ciel et de l'Enfer\"",
      "sourcePage": 52
    },
    {
      "id": 2441,
      "text": "Ecrire, c’est une façon de parler sans être interrompu.",
      "author": "Jules Renard, extrait de son \"Journal\"",
      "sourcePage": 52
    },
    {
      "id": 2442,
      "text": "La pensée est l'esclave de la vie, et la vie est le fou du temps...",
      "author": "William Shakespeare : \"Henry IV\"",
      "sourcePage": 52
    },
    {
      "id": 2443,
      "text": "Aimer c'est la moitié de croire.",
      "author": "Victor Hugo : \"Les Chants du crépuscule\"",
      "sourcePage": 52
    },
    {
      "id": 2444,
      "text": "L'horizon est dans les yeux et non dans la réalité.",
      "author": "Angel Ganivet : \"Lettre\"",
      "sourcePage": 52
    },
    {
      "id": 2445,
      "text": "Comme ça lave, un bon rire !",
      "author": "Daniel Picouly : \"L'Enfant léopard\"",
      "sourcePage": 52
    },
    {
      "id": 2446,
      "text": "En amour, quand deux yeux se rencontrent, ils se tutoient.",
      "author": "Alphonse Karr",
      "sourcePage": 52
    },
    {
      "id": 2447,
      "text": "On se souvient du baiser promis, on oublie les baisers reçus.",
      "author": "Proverbe scandinave",
      "sourcePage": 52
    },
    {
      "id": 2448,
      "text": "Effacer le temps et surfer sur le présent.",
      "author": "Charlélie Couture",
      "sourcePage": 52
    },
    {
      "id": 2449,
      "text": "Il fait froid, parce que l’on regarde là où il n’y a pas de chaleur.",
      "author": "Alexandra David-Neel",
      "sourcePage": 52
    },
    {
      "id": 2450,
      "text": "La sagesse, c'est d'avoir des rêves suffisamment grands pour ne pas les perdre de vue lorsqu'on les poursuit.",
      "author": "Oscar Wilde",
      "sourcePage": 52
    },
    {
      "id": 2451,
      "text": "On n'oublie rien de rien, on s'habitue, c'est tout.",
      "author": "Jacques Brel",
      "sourcePage": 52
    },
    {
      "id": 2452,
      "text": "Dormir à deux rend la nuit moins opaque.",
      "author": "Malcolm de Chazal",
      "sourcePage": 52
    },
    {
      "id": 2453,
      "text": "Une pensée est une idée de passage.",
      "author": "Pythagore",
      "sourcePage": 52
    },
    {
      "id": 2454,
      "text": "Espérer, c'est être heureux.",
      "author": "Alain, extrait des \"Propos sur le bonheur\"",
      "sourcePage": 52
    },
    {
      "id": 2455,
      "text": "Quand deux blessures se rencontrent elles se referment l'une sur l'autre.",
      "author": "Mona Latif-Ghattas : \"Les Voix du jour et de la nuit\"",
      "sourcePage": 52
    },
    {
      "id": 2456,
      "text": "Quand le cœur est chaud, on n'a pas froid au corps.",
      "author": "Lao She : \"Quatre générations sous un même toit\"",
      "sourcePage": 52
    },
    {
      "id": 2457,
      "text": "Le monde semble sombre quand on a les yeux fermés.",
      "author": "Proverbe indien",
      "sourcePage": 52
    },
    {
      "id": 2458,
      "text": "La certitude de l’amour est absolue et n’a plus besoin de preuves.",
      "author": "Vincent Delcroix : \"Ce qui est perdu\"",
      "sourcePage": 52
    },
    {
      "id": 2459,
      "text": "Après tout, ce qui doit venir n’est pas tant à découvrir qu’à inventer...",
      "author": "Hélène Grimaud : \"Variations Sauvages\"",
      "sourcePage": 52
    },
    {
      "id": 2460,
      "text": "S’aimer c’est plus facile à faire, c’est beaucoup plus difficile à vivre.",
      "author": "Camille de Peretti : \"Nous sommes cruels\"",
      "sourcePage": 52
    },
    {
      "id": 2461,
      "text": "Le rivage est plus sûr, mais j’aime me battre avec les flots.",
      "author": "Emily Dickinson",
      "sourcePage": 52
    },
    {
      "id": 2462,
      "text": "Sans imagination il ne pourrait y avoir création.",
      "author": "Albert Jacquard : \"Petite Philosophie à l'usage des non-philosophes\"",
      "sourcePage": 53
    },
    {
      "id": 2463,
      "text": "L’oiseau en cage rêvera des nuages.",
      "author": "Proverbe japonais",
      "sourcePage": 53
    },
    {
      "id": 2464,
      "text": "L’art est le plus beau des mensonges.",
      "author": "Claude Debussy : \"Monsieur Croche, antidilettante\"",
      "sourcePage": 53
    },
    {
      "id": 2465,
      "text": "Le temps adoucit tout.",
      "author": "Voltaire : \"L'Ingénu\"",
      "sourcePage": 53
    },
    {
      "id": 2466,
      "text": "Vivre, c'est lutter contre les démons du cœur et du cerveau.",
      "author": "Henrik Ibsen : \"Lettre à Passarge\"",
      "sourcePage": 53
    },
    {
      "id": 2467,
      "text": "Ce n'est que quand il fait nuit que les étoiles brillent.",
      "author": "Winston Churchill",
      "sourcePage": 53
    },
    {
      "id": 2468,
      "text": "C’est tellement mystérieux, le pays des larmes.",
      "author": "Antoine de Saint-Exupéry : \"Le Petit Prince\"",
      "sourcePage": 53
    },
    {
      "id": 2469,
      "text": "Il n’y a pas de vrai bonheur dans l’égoïsme.",
      "author": "George Sand : \"Le Marquis de Villemer\"",
      "sourcePage": 53
    },
    {
      "id": 2470,
      "text": "Aimer un être, c'est accepter de vieillir avec lui.",
      "author": "Albert Camus : \"Caligula\"",
      "sourcePage": 53
    },
    {
      "id": 2471,
      "text": "La musique fait danser les consciences.",
      "author": "Enzo Cormann, cité dans le \"Petit Dictionnaire du théâtre\"",
      "sourcePage": 53
    },
    {
      "id": 2472,
      "text": "Il n'y a point de recette pour embellir la nature. Il ne s'agit que de voir.",
      "author": "Auguste Rodin, extrait d’ \"Art\"",
      "sourcePage": 53
    },
    {
      "id": 2473,
      "text": "Etre pompette, c’était sentir tourner le monde et en être le roi.",
      "author": "Erwin Mortier : \"Temps de pose\"",
      "sourcePage": 53
    },
    {
      "id": 2474,
      "text": "Un visage est-il un masque de comédie posé sur la tragédie de l’âme ?",
      "author": "Shan Sa : \"Alexandre et Alestria\"",
      "sourcePage": 53
    },
    {
      "id": 2475,
      "text": "Il te restera toujours tes rêves pour réinventer le monde que l’on t’a confisqué.",
      "author": "Yasmina Khadra : \"L’Attentat\"",
      "sourcePage": 53
    },
    {
      "id": 2476,
      "text": "L'amour consiste à être bête ensemble.",
      "author": "Paul Valéry : \"Monsieur Teste\"",
      "sourcePage": 53
    },
    {
      "id": 2477,
      "text": "Le soleil ne se lève que pour celui qui va à sa rencontre.",
      "author": "Henri Le Saux",
      "sourcePage": 53
    },
    {
      "id": 2478,
      "text": "La tête, le cœur font mille bêtises. Les mains se trompent rarement.",
      "author": "Jean Anouilh",
      "sourcePage": 53
    },
    {
      "id": 2479,
      "text": "Rien ne rime, mais tout dépend de l'esprit dans lequel on l'accomplit.",
      "author": "Camara Laye : \"L'Enfant noir\"",
      "sourcePage": 53
    },
    {
      "id": 2480,
      "text": "Le souvenir est un poète, n'en fais pas un historien.",
      "author": "Paul Géraldy",
      "sourcePage": 53
    },
    {
      "id": 2481,
      "text": "La pensée de la mort nous trompe, car elle nous fait oublier de vivre.",
      "author": "Vauvenargues : \"Réflexions et maximes\"",
      "sourcePage": 53
    },
    {
      "id": 2482,
      "text": "Les souvenirs du bonheur passé sont les rides de l'âme.",
      "author": "Xavier de Maistre, extrait d' \"Expédition nocturne autour de ma chambre\"",
      "sourcePage": 53
    },
    {
      "id": 2483,
      "text": "Les mouettes naissent des mouchoirs que l'on agite au départ du bateau.",
      "author": "Ramon Gomez de la Serna : \"Greguerias\"",
      "sourcePage": 53
    },
    {
      "id": 2484,
      "text": "Nous cherchons plus à durer que nous n'essayons de vivre.",
      "author": "Andy Warhol",
      "sourcePage": 53
    },
    {
      "id": 2485,
      "text": "Vivre, c'est se cogner au présent.",
      "author": "Max : \"Le Blog de Max\"",
      "sourcePage": 53
    },
    {
      "id": 2486,
      "text": "La poésie en dit long et c’est vite fait. La prose ne va pas très loin et prend du temps.",
      "author": "Charles Bukowski",
      "sourcePage": 53
    },
    {
      "id": 2487,
      "text": "La peinture vient de l'endroit où les mots ne peuvent plus s'exprimer.",
      "author": "Gao Xingjian : \"La Montagne de l'âme\"",
      "sourcePage": 53
    },
    {
      "id": 2488,
      "text": "Il suffit d'un baiser pour apprendre l'amour.",
      "author": "Max-Pol Fouchet",
      "sourcePage": 53
    },
    {
      "id": 2489,
      "text": "Il faut oublier les folies d’un jour pour faire place à celles du lendemain.",
      "author": "David Hume",
      "sourcePage": 53
    },
    {
      "id": 2490,
      "text": "Celui qui n'est pas occupé à naître est occupé à mourir.",
      "author": "Bob Dylan",
      "sourcePage": 53
    },
    {
      "id": 2491,
      "text": "Si vous fermez la porte à toutes les erreurs, la vérité restera dehors.",
      "author": "Rabindranàth Tagore",
      "sourcePage": 53
    },
    {
      "id": 2492,
      "text": "La seule arme des enfants contre le monde, c’est l’imaginaire.",
      "author": "Claude Miller : \"Studio Magazine - Octobre 1998\"",
      "sourcePage": 53
    },
    {
      "id": 2493,
      "text": "Le beau est toujours bizarre.",
      "author": "Charles Baudelaire",
      "sourcePage": 53
    },
    {
      "id": 2494,
      "text": "Pour être aimé, soyez discret, la clé des cœurs, c'est le secret.",
      "author": "Jean-Pierre Florian",
      "sourcePage": 53
    },
    {
      "id": 2495,
      "text": "L'amour est un tyran qui n'épargne personne.",
      "author": "Pierre Corneille : \"Le Cid\"",
      "sourcePage": 53
    },
    {
      "id": 2496,
      "text": "Allons sagement et doucement : trébuche qui court vite.",
      "author": "William Shakespeare : \"Roméo et Juliette\"",
      "sourcePage": 53
    },
    {
      "id": 2497,
      "text": "La sagesse est d'être fou lorsque les circonstances en valent la peine.",
      "author": "Jean Cocteau : \"Opium\"",
      "sourcePage": 53
    },
    {
      "id": 2498,
      "text": "On ne naît pas femme : on le devient.",
      "author": "Simone de Beauvoir : \"Le Deuxième Sexe\"",
      "sourcePage": 53
    },
    {
      "id": 2499,
      "text": "La douleur passe, la beauté reste.",
      "author": "Pierre-Auguste Renoir",
      "sourcePage": 53
    },
    {
      "id": 2500,
      "text": "Les hasards de notre vie nous ressemblent.",
      "author": "Elsa Triolet : \"Camouflages\"",
      "sourcePage": 53
    },
    {
      "id": 2501,
      "text": "Nos cauchemars, c'est notre âme qui balaye devant sa porte.",
      "author": "Jacques Deval, extrait d' \"Afin de vivre bel et bien\"",
      "sourcePage": 53
    },
    {
      "id": 2502,
      "text": "Il faut toujours un coup de folie pour bâtir un destin.",
      "author": "Marguerite Yourcenar : \"Les Yeux ouverts\"",
      "sourcePage": 53
    },
    {
      "id": 2503,
      "text": "Quand le cœur n’y est pas, les mains ne sont pas habiles.",
      "author": "Proverbe chinois",
      "sourcePage": 53
    },
    {
      "id": 2504,
      "text": "Tous les hommes craignent de se faire posséder par une sirène.",
      "author": "Paule Constant : \"La Bête à chagrin\"",
      "sourcePage": 53
    },
    {
      "id": 2505,
      "text": "L'aventure c'est le trésor que l'on découvre à chaque matin.",
      "author": "Jacques Brel, paroles de la chanson \"L’Aventure\"",
      "sourcePage": 53
    },
    {
      "id": 2506,
      "text": "Mieux vaut mourir d'amour que d'aimer sans regrets.",
      "author": "Paul Eluard",
      "sourcePage": 53
    },
    {
      "id": 2507,
      "text": "L’amour, c’est quand on rencontre quelqu’un qui vous donne de vos nouvelles.",
      "author": "André Breton",
      "sourcePage": 53
    },
    {
      "id": 2508,
      "text": "C'est dans la rosée des petites choses que le cœur trouve son matin et se rafraîchit.",
      "author": "Khalil Gibran",
      "sourcePage": 54
    }
  ]
};
const DAILY_QUOTES = QUOTE_DATASET.quotes;
